#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

/*
 * Config word:
 *   Bit 15    OS        = 1  (begin single conversion)
 *   Bits 14:12 MUX      = 100 (AIN0 single-ended)
 *   Bits 11:9  PGA      = 001 (±4.096 V)
 *   Bit  8     MODE     = 1  (single-shot)
 *   Bits 7:5   DR       = 100 (128 SPS)
 *   Bit  4     COMP_MODE = 0
 *   Bit  3     COMP_POL  = 0
 *   Bit  2     COMP_LAT  = 0
 *   Bits 1:0   COMP_QUE  = 11 (disable comparator)
 * => 0xC183
 */
#define ADS1115_CONFIG_WORD 0xC183

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_write_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) < 0) {
        return -1;
    }
    return 0;
}

static int ads1115_read_conversion(int handle, int16_t *raw) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        return -1;
    }
    *raw = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ads1115_write_config(i2c_handle, ADS1115_CONFIG_WORD) < 0) {
        fprintf(stderr, "Failed to write ADS1115 config\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Reading current from MLX91219 via ADS1115 (I2C 0x%02X)\n", ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw;
        if (ads1115_read_conversion(i2c_handle, &raw) < 0) {
            fprintf(stderr, "I2C read error: %d\n", raw);
            break;
        }

        /*
         * ADS1115 in single-shot mode at 128 SPS takes ~7.8 ms for a conversion.
         * We wait 10 ms to be safe.
         */
        gpioDelay(10000);

        float voltage = (raw * 4.096) / 32768.0;
        float current = voltage / 1000.0; /* 1 mV/A */

        printf("Current: %.3f A\n", current);
        fflush(stdout);

        usleep(500000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

