#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "flame_data.csv"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then don't-care */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_flame_sensor(void) {
    return (gpioRead(FLAME_SENSOR_PIN) == 1) ? 1 : 0;
}

static float approximate_temperature(int adc_value) {
    /* Placeholder linear approximation; replace with calibrated curve */
    return (float)adc_value * 0.1f;
}

static int log_data(time_t timestamp, int flame_detected, float temperature) {
    struct tm *timeinfo = localtime(&timestamp);
    if (!timeinfo) {
        fprintf(stderr, "localtime() failed\n");
        return -1;
    }

    char timestamp_str[32];
    if (strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d,%.2f\n", timestamp_str, flame_detected, temperature) < 0) {
        fprintf(stderr, "fprintf() to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,flame_detected,temperature\n");
        fflush(log_file);
    }

    printf("Flame detection system started. Logging to %s every %d s. Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        time_t current_time = time(NULL);
        if (current_time == (time_t)-1) {
            perror("time()");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        int flame_detected = read_flame_sensor();
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        float temperature = 0.0f;

        if (adc_value >= 0) {
            temperature = approximate_temperature(adc_value);
        } else {
            fprintf(stderr, "ADC read failed; skipping entry.\n");
        }

        if (log_data(current_time, flame_detected, temperature) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

