#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128_SPS 0x0080
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 100
#define BUZZER_DURATION_MS 2000
#define TEMP_THRESHOLD_C 60.0
#define LOG_FILE_NAME "fire_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_flame_sensor(void) {
    int flame_value = gpioRead(FLAME_SENSOR_PIN);
    gpioDelay(DEBOUNCE_DELAY_MS * 1000);
    int debounced_value = gpioRead(FLAME_SENSOR_PIN);
    return (flame_value == debounced_value) ? flame_value : 0;
}

static int read_temperature(float *temperature) {
    if (i2c_handle < 0) return -1;

    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
