#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <linux/gpiochip.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP_NAME  "gpiochip4"
#define FAN_GPIO        18
#define CURRENT_THRESHOLD 1.0f
#define LOG_FILE        "current_log.txt"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define SAMPLE_INTERVAL 1

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int fan_gpio_line = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    struct gpiochip *chip = NULL;
    struct gpio_line *line = NULL;

    chip = gpiochip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        chip = gpiochip_open_by_number(0);
    }
    if (!chip) {
        perror("gpiochip_open");
        return -1;
    }

    line = gpio_chip_get_line(chip, FAN_GPIO);
    if (!line) {
        perror("gpio_chip_get_line");
        gpiochip_close(chip);
        return -1;
    }

    if (gpio_line_request_output(line, "mlx91219-fan", 0) < 0) {
        perror("gpio_line_request_output");
        gpiochip_close(chip);
        return -1;
    }

    fan_gpio_line = line;
    return 0;
}

static int read_adc(uint8_t channel) {
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    if (value == 0x0000 || value == 0xFFFF) {
        fprintf(stderr, "ADC channel %u: sensor absent or bus error (0x%04X)\n", channel, value);
        return -1;
    }
    return value;
}

static float adc_to_current(int adc_value) {
    return (float)adc_value * 0.001f;
}

static int log_current(float current) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.3f\n", timestamp, current) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static void control_fan(float current) {
    int val = (current > CURRENT_THRESHOLD) ? 1 : 0;
    if (gpio_line_set_value(fan_gpio_line, val) < 0) {
        perror("gpio_line_set_value");
    }
}

static void cleanup(void) {
    if (fan_gpio_line >= 0) {
        gpio_line_set_value(fan_gpio_line, 0);
        gpio_line_release(fan_gpio_line);
        fan_gpio_line = -1;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring current on MCP3008 channel 0. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            float current = adc_to_current(adc_value);
            if (log_current(current) < 0) {
                fprintf(stderr, "Failed to log current\n");
            }
            control_fan(current);
            printf("Current: %.3f A\n", current);
        }
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

