#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

/*
 * MICS-4514 CO sensor (dual-element MOS, NO2/CO)
 * I2C address 0x33, 16-bit ADC output (simulated raw value).
 * Conversion: raw_16 = log10(CO_ppm) / slope + intercept
 */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_co_raw(int handle, uint16_t *raw_out) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "I2C read failed (got %d bytes, expected 2)\n", bytes_read);
        return -1;
    }
    *raw_out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static double calculate_ppm(uint16_t raw) {
    /*
     * Logarithmic calibration curve:
     *   raw_16 = log10(CO_ppm) / slope + intercept
     * Rearranged: CO_ppm = 10^((raw_16 - intercept) / slope)
     */
    const double intercept = 0.0;
    const double slope = 1.0;
    return pow(10.0, ((double)raw - intercept) / slope);
}

static int log_data(FILE *fp, double ppm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, %.2f\n", timestamp, ppm) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CO sensor logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t raw = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
            if (read_co_raw(i2c_handle, &raw) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "I2C read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                sleep(1);
            }
        }

        if (!success) {
            fprintf(stderr, "Sensor not responding after %d attempts. Skipping sample.\n", MAX_RETRIES);
        } else {
            double ppm = calculate_ppm(raw);
            if (log_data(log_file, ppm) != 0) {
                fprintf(stderr, "Failed to log data\n");
            } else {
                printf("CO: %.2f ppm\n", ppm);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL_SEC && !terminate; s++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

