    result = i2cReadDevice(handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading I2C device: %d\n", result);
        return -1;
    }

    uint16_t ox_raw = (buf[0] << 8) | buf[1];
    uint16_t red_raw = (buf[2] << 8) | buf[3];

    *co_ppm = (float)ox_raw * 0.1;
    return 0;
}

int log_co_data(float co_ppm) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening CO log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, co_ppm);
    fclose(fp);
    return 0;
}

int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening alert log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f ppm - CO ALERT\n", timestamp, co_ppm);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float co_ppm;
    while (running) {
        if (read_mics4514(i2c_handle, &co_ppm) == 0) {
            if (log_co_data(co_ppm) != 0) {
                fprintf(stderr, "Error logging CO data\n");
            }

            if (co_ppm >= CO_THRESHOLD) {
                if (log_alert(co_ppm) != 0) {
                    fprintf(stderr, "Error logging alert\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

