#include <pigpio.h>

#define I2C_BUS 1
#define MIC1_PIN 2
#define MIC2_PIN 3
#define LOG_FILE "audio_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define ERROR_VALUE -999.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mic(int pin, float *level) {
    int data = 0;
    int timeout = 0;

    /* Start bit-banged I2C read: drive SDA low, then sample */
    if (gpioSetMode(pin, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(pin, 0) < 0) return -1;
    gpioDelay(1);

    /* Release SDA: switch to input (external pull-up brings it high) */
    if (gpioSetMode(pin, PI_INPUT) < 0) return -1;

    /* Sample: measure how long SDA stays low */
    timeout = SAMPLE_INTERVAL_US;
    while (gpioRead(pin) == 0) {
        if (--timeout <= 0) return -1;
        gpioDelay(1);
    }

    /* Read the data bit: measure how long SDA stays high */
    timeout = SAMPLE_INTERVAL_US;
    while (gpioRead(pin) == 1) {
        if (--timeout <= 0) return -1;
        gpioDelay(1);
    }

    /* Decode: if SDA was high for >= 2/3 of the interval, it is a '1' */
    if (timeout > 0 && timeout >= (SAMPLE_INTERVAL_US * 2) / 3) {
        data = 1;
    }

    *level = (float)data;
    return 0;
}

static float calculate_average(float v1, float v2) {
    return (v1 + v2) / 2.0f;
}

static int log_data(float avg_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, avg_level);
    } else {
        fprintf(fp, "timestamp_error, %.2f\n", avg_level);
    }

    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_PIN, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for mic1 (pin %d): %s\n",
                MIC1_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_PIN, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for mic2 (pin %d): %s\n",
                MIC2_PIN, strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Audio level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float level1 = ERROR_VALUE, level2 = ERROR_VALUE;
        int rc1 = read_mic(MIC1_PIN, &level1);
        int rc2 = read_mic(MIC2_PIN, &level2);

        if (rc1 != 0 || rc2 != 0) {
            fprintf(stderr, "Error reading microphone data (rc1=%d, rc2=%d)\n", rc1, rc2);
        }

        float avg = calculate_average(level1, level2);
        if (log_data(avg) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

