#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_PIN 27
#define HIGH_THRESHOLD 1000.0
#define WINDOW_MS 100
#define SAMPLE_DELAY_US 1000
#define LED_ON_MS 500

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static double calculate_rms(int *samples, int num_samples) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double val = (double)samples[i];
        sum_sq += val * val;
    }
    return sqrt(sum_sq / num_samples);
}

static void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int mic1_samples[WINDOW_MS];
    int mic2_samples[WINDOW_MS];
    int sample_idx = 0;

    while (running) {
        int mic1_val = read_mcp3008(0);
        int mic2_val = read_mcp3008(1);

        if (mic1_val < 0 || mic2_val < 0) {
            fprintf(stderr, "Error reading ADC values, skipping sample\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        mic1_samples[sample_idx] = mic1_val;
        mic2_samples[sample_idx] = mic2_val;
        sample_idx++;

        if (sample_idx >= WINDOW_MS) {
            double mic1_rms = calculate_rms(mic1_samples, WINDOW_MS);
            double mic2_rms = calculate_rms(mic2_samples, WINDOW_MS);
            log_data(mic1_rms, mic2_rms);

            if (mic1_rms > HIGH_THRESHOLD || mic2_rms > HIGH_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
                gpioDelay(LED_ON_MS * 1000);
                gpioWrite(LED_PIN, 0);
            }

            sample_idx = 0;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

