#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <string.h>

/* Configuration */
#define I2C_BUS 1
#define LED_PIN 17
#define CURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_A0_GND (0x4000)
#define ADS1115_CONFIG_PGA_4_096V (0x0200)
#define ADS1115_CONFIG_MODE_SINGLE (0x0100)
#define ADS1115_CONFIG_DR_128_SPS (0x0080)
#define ADS1115_CONFIG_CQUE_NONE (0x0003)

/* Globals */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static double current_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Initialize ADS1115 ADC for single-ended A0, 4.096V gain, 128 SPS */
static int ads1115_init(int handle) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_A0_GND |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128_SPS | ADS1115_CONFIG_CQUE_NONE;

    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(handle, config_buf, 3) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config register.\n");
        return -1;
    }
    return 0;
}

/* Read raw 16-bit ADC value from ADS1115 channel A0 */
static int ads1115_read_raw(int handle, int16_t *raw_out) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion register pointer.\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion data.\n");
        return -1;
    }

    *raw_out = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

/* Convert raw ADC value to current (A) using 4.096V full-scale, 16-bit signed */
static double raw_to_current(int16_t raw) {
    const double full_scale_voltage = 4.096;
    const double adc_resolution = 32768.0;
    return (raw * full_scale_voltage) / adc_resolution;
}

/* Store current in circular buffer */
static void buffer_store(double current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

/* Calculate average of buffered currents */
static double buffer_average(void) {
    if (buffer_count == 0) {
        return 0.0;
    }
    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += current_buffer[i];
    }
    return sum / buffer_count;
}

/* Control warning LED based on average current */
static void control_led(double average_current) {
    if (average_current > CURRENT_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: ADS1115 initialization failed. Check wiring and sensor presence.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler.\n");
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (running) {
        int16_t raw_value = 0;
        if (ads1115_read_raw(i2c_handle, &raw_value) < 0) {
            fprintf(stderr, "Warning: Failed to read ADC value. Retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double current = raw_to_current(raw_value);
        buffer_store(current);
        double average_current = buffer_average();
        control_led(average_current);

        printf("Raw: %d, Current: %.3f A, Avg: %.3f A\n", raw_value, current, average_current);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

