#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TCS34725_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A
#define TCS34725_EXPECTED_ID 0x44
#define LOG_FILE "color_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(i2c_handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static int init_tcs34725(void) {
    uint8_t id = 0;
    if (read_reg(TCS34725_ID, &id) < 0) {
        return -1;
    }
    if (id != TCS34725_EXPECTED_ID) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x%02X)\n", id, TCS34725_EXPECTED_ID);
        return -1;
    }

    if (write_reg(TCS34725_ENABLE, 0x03) < 0) return -1;
    if (write_reg(TCS34725_ATIME, 0xFF) < 0) return -1;
    if (write_reg(TCS34725_CONTROL, 0x03) < 0) return -1;

    return 0;
}

static int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_word(TCS34725_CDATAL, clear) < 0) return -1;
    if (read_word(TCS34725_RDATAL, red) < 0) return -1;
    if (read_word(TCS34725_GDATAL, green) < 0) return -1;
    if (read_word(TCS34725_BDATAL, blue) < 0) return -1;
    return 0;
}

static int log_color_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_tcs34725() < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(log_file);
    }

    int consecutive_errors = 0;

    while (running) {
        uint16_t clear, red, green, blue;

        if (read_color_data(&clear, &red, &green, &blue) == 0) {
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors, exiting.\n");
                break;
            }
        }

        if (log_color_data(clear, red, green, blue) < 0) {
            fprintf(stderr, "Logging failed, continuing.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

