#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90817_ADDR 0x48
#define LOG_FILE "pressure_log.csv"
#define READ_INTERVAL_SEC 1
#define MAX_RETRIES 3

/* MLX90817 register addresses (datasheet) */
#define MLX90817_REG_PRESSURE_MSB 0x00
#define MLX90817_REG_PRESSURE_LSB 0x01
#define MLX90817_REG_TEMP_MSB    0x02
#define MLX90817_REG_TEMP_LSB    0x03
#define MLX90817_REG_CONFIG      0x04

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, MLX90817_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_pressure(float *pressure)
{
    uint8_t msb, lsb;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read_register(MLX90817_REG_PRESSURE_MSB, &msb) != 0) {
            retries++;
            continue;
        }
        if (read_register(MLX90817_REG_PRESSURE_LSB, &lsb) != 0) {
            retries++;
            continue;
        }

        uint16_t raw = ((uint16_t)msb << 8) | lsb;
        *pressure = (float)raw * 0.01f; /* kPa */
        return 0;
    }

    fprintf(stderr, "Failed to read pressure after %d retries.\n", MAX_RETRIES);
    return -1;
}

static int log_pressure(float pressure)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "Error converting time to UTC.\n");
        return -1;
    }

    char timestamp[32];
