#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_CONV_REG     0x00
#define ADS1115_CONFIG_REG   0x01

/* AIN0 = pressure, AIN1 = temperature */
#define ADS1115_AIN0_SINGLE  0x4000  /* AIN0 single-ended, gain=1, 128 SPS */
#define ADS1115_AIN1_SINGLE  0x5000  /* AIN1 single-ended, gain=1, 128 SPS */

#define WARNING_LED_GPIO     17
#define PRESSURE_THRESHOLD   105.0f
#define SAMPLE_PERIOD_US     1000000  /* 1 second */
#define MAX_RETRIES          3

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static int  ads1115_init(void);
static int  ads1115_read_channel(uint16_t config, uint16_t *raw);
static float raw_to_pressure_kpa(uint16_t raw);
static float raw_to_temperature_c(uint16_t raw);
static void set_warning_led(bool on);
static void signal_handler(int sig);

/* ----------------------------- ADS1115 ----------------------------------- */

/*
 * Write a 16-bit value to an ADS1115 register.
 * Returns 0 on success, -1 on failure.
 */
static int ads1115_write_reg(uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] ADS1115 write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * Returns 0 on success, -1 on failure.
 */
static int ads1115_read_reg(uint8_t reg, uint16_t *value)
{
    char buf[2];

    if (i2cWriteDevice(g_i2c_handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "[ERROR] ADS1115 reg select 0x%02X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] ADS1115 read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int ads1115_init(void)
{
    /*
     * Config word:
     *   OS=1 (start single conversion)
     *   MUX[2:0]=000 (AIN0 single-ended)
     *   PGA[2:0]=001 (gain=1)
     *   MODE=1 (single-shot)
     *   DR[2:0]=100 (128 SPS)
     *   COMP_MODE=0, COMP_POL=0, COMP_LAT=0, COMP_QUE=11 (disabled)
     */
    uint16_t config = 0x8483;
    if (ads1115_write_reg(ADS1115_CONFIG_REG, config) != 0)
        return -1;

    /* Allow first conversion to complete (128 SPS -> ~7.8 ms) */
    gpioDelay(10000);
    return 0;
}

static int ads1115_read_channel(uint16_t config, uint16_t *raw)
{
    if (ads1115_write_reg(ADS1115_CONFIG_REG, config) != 0)
        return -1;

    /* Wait for conversion to finish (~7.8 ms at 128 SPS) */
    gpioDelay(10000);

    uint16_t val;
    if (ads1115_read_reg(ADS1115_CONV_REG, &val) != 0)
        return -1;

    *raw = val;
    return 0;
}

/* ----------------------------- Sensor Conversion -------------------------- */

static float raw_to_pressure_kpa(uint16_t raw)
{
    /*
     * MLX90834 pressure channel:
     *   0.5 V -> 0 kPa, 4.5 V -> 105 kPa
     * 16-bit signed, 0.5 V resolution.
     */
    float voltage = (float)raw * 0.0000625f;
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > 4.5f) voltage = 4.5f;
    return (voltage - 0.5f) * 100.0f;
}

static float raw_to_temperature_c(uint16_t raw)
{
    /*
     * MLX90834 temperature channel:
     *   0.5 V -> 25 C, 2.5 V -> 25 C (NTC compensation)
     * 16-bit signed, 0.5 V resolution.
     */
    float voltage = (float)raw * 0.0000625f;
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > 2.5f) voltage = 2.5f;
    return (voltage - 0.5f) * 25.0f;
}

/* ----------------------------- LED Control -------------------------------- */

static void set_warning_led(bool on)
{
    if (gpioWrite(WARNING_LED_GPIO, on ? 1 : 0) != 0)
        fprintf(stderr, "[WARN] Failed to write GPIO%d\n", WARNING_LED_GPIO);
}

/* ----------------------------- Signal Handling ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init() != 0) {
        fprintf(stderr, "[FATAL] ADS1115 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure warning LED */
    if (gpioSetMode(WARNING_LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d) failed\n", WARNING_LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    set_warning_led(false);

    /* Install signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 via ADS1115 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw_p = 0, raw_t = 0;
        bool ok = false;

        /* Read pressure channel with retries */
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (ads1115_read_channel(ADS1115_AIN0_SINGLE, &raw_p) == 0) {
                ok = true;
                break;
            }
            fprintf(stderr, "[WARN] Pressure read failed (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(10000);
        }
        if (!ok) {
            fprintf(stderr, "[FATAL] Pressure read failed after %d attempts\n",
                    MAX_RETRIES);
            break;
        }

        /* Read temperature channel with retries */
        ok = false;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (ads1115_read_channel(ADS1115_AIN1_SINGLE, &raw_t) == 0) {
                ok = true;
                break;
            }
            fprintf(stderr, "[WARN] Temperature read failed (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(10000);
        }
        if (!ok) {
            fprintf(stderr, "[FATAL] Temperature read failed after %d attempts\n",
                    MAX_RETRIES);
            break;
        }

        float pressure = raw_to_pressure_kpa(raw_p);
        float temperature = raw_to_temperature_c(raw_t);

        printf("Pressure: %.2f kPa | Temperature: %.2f C\n",
               pressure, temperature);

        /* Control warning LED */
        set_warning_led(pressure > PRESSURE_THRESHOLD);

        /* Sleep for sample period (interruptible by signals) */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* Cleanup */
    set_warning_led(false);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

