#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128_SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128_SPS | ADS1115_CONFIG_CQUE_NONE)
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_ads1115(int fd, int16_t *pressure) {
    uint16_t config = ADS1115_CONFIG_DEFAULT;
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }

    uint16_t prev_config = config;
    for (int i = 0; i < MAX_RETRIES; i++) {
        usleep(10000);
        uint16_t curr_config;
        if (i2c_read_reg16(fd, ADS1115_REG_CONFIG, &curr_config) < 0) {
            return -1;
        }
        if (curr_config == config) {
            break;
        }
        config = curr_config;
    }

    if (config != prev_config) {
        return -1;
    }

    uint16_t conversion;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &conversion) < 0) {
        return -1;
    }

    *pressure = (int16_t)conversion;
    return 0;
}

static int convert_to_kpa(int16_t adc_value, float *pressure) {
    float voltage = (adc_value * 4.096) / 32768.0;
    *pressure = (voltage - 0.2) / 0.005;
    return 0;
}

static int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t adc_value;
        float pressure;

        if (read_ads1115(i2c_fd, &adc_value) < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        if (convert_to_kpa(adc_value, &pressure) < 0) {
            fprintf(stderr, "Error converting ADC value to pressure\n");
            break;
        }

        if (pressure < 0.0 || pressure > 100.0) {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
            break;
        }

        if (log_pressure(pressure) < 0) {
            fprintf(stderr, "Error logging pressure\n");
            break;
        }

        printf("Pressure: %.2f kPa\n", pressure);
        usleep(SAMPLE_INTERVAL_US);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpioTerminate();

    printf("Pressure monitoring stopped.\n");
    return 0;
}

