#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3208_CS_PIN 8
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3];
    unsigned char rx[3];

    tx[0] = 0x01;
    tx[1] = (0x08 | channel) << 4;
    tx[2] = 0x00;

    gpioWrite(MCP3208_CS_PIN, 0);
    int result = spiXfer(spi_handle, tx, rx, 3);
    gpioWrite(MCP3208_CS_PIN, 1);

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx[1] & 0x0F) << 8) | rx[2];
    return adc_value;
}

float adc_to_humidity(int adc_value) {
    float humidity = 100.0 * (float)adc_value / 1023.0;
    return humidity;
}

float adc_to_temperature(int adc_value) {
    float temperature = 100.0 * (float)adc_value / 1023.0;
    return temperature;
}

void log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

void send_email_alert(float humidity) {
