#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Si1172-A30-GMR Optical Heart Rate Sensor – I2C driver library
 *
 * NOTE: The Si1172 is a complex sensor that requires a proprietary
 * algorithm to convert raw PPG samples into true Heart Rate (HR) and
 * SpO2.  This program logs the raw 16-bit IR and RED ADC values as proxy
 * values for HR and SpO2, and sets the error flag to 2 when the sensor
 * appears absent or uninitialized.  A full implementation would
 * require the Silicon Labs Si117x driver library (libsi117x) and the
 * proprietary Si117x firmware.
 */

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define LOG_FILE       "biometric_log.csv"
#define SAMPLE_PERIOD  1.0

/* Si1172 register addresses (example subset) */
#define REG_PART_ID    0x00
#define REG_HW_KEY     0x07
#define REG_MEAS_RATE  0x08
#define REG_DATA_RATE  0x09
#define REG_IR_ADC_DATA0 0x22
#define REG_RED_ADC_DATA0 0x24

#define HW_KEY_VALUE   0x17

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write one byte to an 8-bit register.
 * Returns 0 on success, -1 on failure.
 */
static int reg_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/*
 * Read one byte from an 8-bit register.
 * Returns the byte value (0–255) on success, or -1 on failure.
 */
static int reg_read_byte(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    return rc;
}

/*
 * Read a 16-bit little-endian value from two consecutive registers.
 * Returns 0 on success and stores the value in *out; returns -1 on
 * failure.
 */
static int reg_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int lo = reg_read_byte(handle, reg);
    if (lo < 0)
        return -1;
    int hi = reg_read_byte(handle, reg + 1);
    if (hi < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/*
 * Initialise the Si1172 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int init_sensor(int handle)
{
    int part_id = reg_read_byte(handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Sensor not responding on I2C bus %d, addr 0x%02X\n",
                I2C_BUS, I2C_ADDR);
        return -1;
    }
    fprintf(stderr, "Si1172 Part ID: 0x%02X\n", part_id);

    if (reg_write_byte(handle, REG_HW_KEY, HW_KEY_VALUE) < 0)
        return -1;

    /*
     * Set measurement rate to 100 ms (0x0A).
     * Set data rate to 100 ms (0x0A).
     * These values are typical; a full implementation would use
     * the Si117x driver library to configure the sensor per the
     * application's requirements.
     */
    if (reg_write_byte(handle, REG_MEAS_RATE, 0x0A) < 0)
        return -1;
    if (reg_write_byte(handle, REG_DATA_RATE, 0x0A) < 0)
        return -1;

    return 0;
}

/*
 * Read HR and SpO2 proxy values from the Si1172.
 * Returns 0 on success, -1 on failure.
 */
static int read_sensor_data(int handle, uint16_t *hr_proxy, uint16_t *spo2_proxy)
{
    if (reg_read_word(handle, REG_IR_ADC_DATA0, hr_proxy) < 0)
        return -1;
    if (reg_read_word(handle, REG_RED_ADC_DATA0, spo2_proxy) < 0)
        return -1;
    return 0;
}

/*
 * Log one sample to the CSV file.
 * timestamp: Unix epoch seconds
 * hr: proxy HR value (raw ADC)
 * spo2: proxy SpO2 value (raw ADC)
 * error: 0 = OK, 1 = I2C read error, 2 = sensor absent/uninitialized
 */
static void log_data(FILE *fp, time_t timestamp, uint16_t hr_proxy,
                     uint16_t spo2_proxy, int error)
{
    fprintf(fp, "%ld,%u,%u,%d\n", (long)timestamp, hr_proxy, spo2_proxy, error);
    fflush(fp);
}

int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise sensor --- */
    if (init_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialisation failed (sensor absent or uninitialized)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,hr_proxy,spo2_proxy,error_flag\n");
        fflush(g_log_file);
    }

    /* --- Install signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Logging to %s. Press Ctrl-C to stop.\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        time_t now = time(NULL);
        uint16_t hr_proxy = 0, spo2_proxy = 0;
        int error = 0;

        if (read_sensor_data(g_i2c_handle, &hr_proxy, &spo2_proxy) < 0) {
            error = 1;
        }

        log_data(g_log_file, now, hr_proxy, spo2_proxy, error);

        /* Sleep for the sample period, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++)
            time_sleep(0.1);
    }

    /* --- Graceful shutdown --- */
    fprintf(stderr, "\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

