#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define ADC_CHANNEL    0
#define ADC_MAX        1023
#define FLOW_MIN       0.0
#define FLOW_MAX       5.0
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_PERIOD  1000000  /* microseconds */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (value stored in *out), -1 on SPI error,
 * -2 if the ADC value is 0 or full-scale (sensor absent / wiring fault).
 */
static int read_mcp3008(int handle, int channel, int *out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result:
     *   rx[1] bits 1..0  -> bits 9..8 of 10-bit result
     *   rx[2]           -> bits 7..0 of 10-bit result
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d): %s\n", ret, strerror(errno));
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];

    if (adc == 0 || adc == ADC_MAX) {
        fprintf(stderr, "ADC value %d at channel %d: sensor absent or wiring fault\n",
                adc, channel);
        return -2;
    }

    *out = adc;
    return 0;
}

static float calculate_flow_rate(int adc_value)
{
    /*
     * Placeholder linear mapping.
     * Replace with the actual calibration curve from the SpiroQuant A+ datasheet.
     */
    return (float)adc_value * 0.1f;
}

static int log_flow_rate(FILE *fp, float flow_rate)
{
    struct timeval tv;
    if (gettimeofday(&tv, NULL) != 0) {
        fprintf(stderr, "gettimeofday failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&tv.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%06ld,%.2f\n", timestamp, (long)tv.tv_usec, flow_rate) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
