#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x5C
#define MEASURE_CMD 0x3600
#define CONVERSION_DELAY_MS 10
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "environmental_data.csv"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_cmd: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            perror("i2c_read_bytes: read failed");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "i2c_read_bytes: unexpected EOF\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int read_icp10125(int fd, float *temperature, float *pressure) {
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) {
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    uint8_t data[6];
    if (i2c_read_bytes(fd, data, 6) < 0) {
        return -1;
    }

    uint16_t raw_pressure = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_temp = ((uint16_t)data[3] << 8) | data[4];

    *pressure = (100.0f * raw_pressure) / 65536.0f;
    *temperature = (100.0f * raw_temp) / 65536.0f;

    return 0;
}

static void log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_data: localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, pressure);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float temperature, pressure;
        if (read_icp10125(i2c_fd, &temperature, &pressure) == 0) {
            log_data(log_fp, temperature, pressure);
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_S);
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    if (log_fp) {
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("\nExiting gracefully.\n");
    return 0;
}

