#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define NUM_SAMPLES 100
#define GAIN_MIN 0
#define GAIN_MAX 10

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain_mic1> <gain_mic2>\n", argv[0]);
        return 1;
    }

    int gain_mic1 = atoi(argv[1]);
    int gain_mic2 = atoi(argv[2]);

    if (gain_mic1 < GAIN_MIN || gain_mic1 > GAIN_MAX ||
        gain_mic2 < GAIN_MIN || gain_mic2 > GAIN_MAX) {
        fprintf(stderr, "Gain values must be between %d and %d\n", GAIN_MIN, GAIN_MAX);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return 1;
    }

    printf("Sampling audio from MP23ABS1 microphones via MCP3008...\n");
    printf("Gain for mic1: %d, Gain for mic2: %d\n", gain_mic1, gain_mic2);
    printf("Press Ctrl+C to exit.\n");

    int samples_mic1[NUM_SAMPLES];
    int samples_mic2[NUM_SAMPLES];
    int samples_mic1_denoised[NUM_SAMPLES];
    int samples_mic2_denoised[NUM_SAMPLES];

    while (running) {
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int val_mic1 = read_mcp3008(spi_fd, 0);
            int val_mic2 = read_mcp3008(spi_fd, 1);

            if (val_mic1 < 0 || val_mic2 < 0) {
                fprintf(stderr, "Error reading MCP3008 channels. Retrying...\n");
                sleep(1);
                continue;
            }

            samples_mic1[i] = val_mic1;
            samples_mic2[i] = val_mic2;
        }

        for (int i = 0; i < NUM_SAMPLES; i++) {
            samples_mic1_denoised[i] = samples_mic1[i] - (gain_mic2 * samples_mic2[i] / 100);
            samples_mic2_denoised[i] = samples_mic2[i] - (gain_mic1 * samples_mic1[i] / 100);
        }

        printf("Mic1: %d, Mic2: %d, DenoisedMic1: %d, DenoisedMic2: %d\n",
               samples_mic1[0], samples_mic2[0], samples_mic1_denoised[0], samples_mic2_denoised[0]);
    }

    printf("\nExiting gracefully...\n");
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return 0;
}

