#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define ADC_CHANNEL 0
#define LOG_FILE    "moisture_log.txt"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 */
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static int log_data(int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", ts, moisture_level) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting VH400 moisture logging (MCP3008 CH%d, %d s interval)...\n",
           ADC_CHANNEL, SAMPLE_INTERVAL);

    while (g_running) {
        int moisture = read_mcp3008(ADC_CHANNEL);
        if (moisture < 0) {
            fprintf(stderr, "ADC read error; retrying in %d s\n", SAMPLE_INTERVAL);
        } else if (moisture < 0 || moisture > 1023) {
            fprintf(stderr, "ADC value out of range: %d\n", moisture);
        } else {
            if (log_data(moisture) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            } else {
                printf("Logged: %d\n", moisture);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

