#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define BUZZER_GPIO 18
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define FLAME_LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float read_ambient_temperature(void) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open ambient temperature file: %s. Using default 25.0 C.\n", strerror(errno));
        return 25.0f;
    }

    char buffer[256];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Warning: Could not read ambient temperature from file. Using default 25.0 C.\n");
        fclose(fp);
        return 25.0f;
    }
    fclose(fp);

    char *endptr;
    float temperature = strtof(buffer, &endptr);
    if (*endptr != '\0' || temperature < -50.0f || temperature > 100.0f) {
        fprintf(stderr, "Warning: Invalid temperature value '%s'. Using default 25.0 C.\n", buffer);
        return 25.0f;
    }
    return temperature;
}

static float compensate_voltage(int raw_adc, float ambient_temperature) {
    float voltage = (float)raw_adc * 3.3f / 1024.0f;
    float compensated_voltage = voltage - (ambient_temperature / 100.0f) * 0.1f;
    return compensated_voltage;
}

static void log_data(int raw_adc, float voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%s\n", timestamp, raw_adc, voltage, temperature, flame_detected, flame_detected ? "Flame Detected" : "No Flame");
    fflush(log_file);
}

static void control_buzzer(int gpio_pin, int state) {
    if (gpio_pin < 0 || gpio_pin > 31) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return;
    }
    if (state != 0 && state != 1) {
        fprintf(stderr, "Invalid buzzer state: %d\n", state);
        return;
    }

    if (gpio_pin == BUZZER_GPIO) {
        if (state == 1) {
            if (gpioWrite(BUZZER_GPIO, 1) < 0) {
                fprintf(stderr, "Error turning buzzer ON: %s\n", strerror(errno));
            }
        } else {
            if (gpioWrite(BUZZER_GPIO, 0) < 0) {
                fprintf(stderr, "Error turning buzzer OFF: %s\n", strerror(errno));
            }
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting buzzer GPIO %d as output: %s\n", BUZZER_GPIO, strerror(errno));
        close(spi_fd);
        return 1;
    }

    log_file = fopen(FLAME_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", FLAME_LOG_FILE, strerror(errno));
        close(spi_fd);
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_adc = -1;
        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            raw_adc = read_mcp3008(ADC_CHANNEL);
            if (raw_adc >= 0 && raw_adc <= 1023) {
                break;
            }
            if (retry < MAX_RETRIES - 1) {
                fprintf(stderr, "ADC read failed, retrying... (%d/%d)\n", retry + 1, MAX_RETRIES);
                usleep(100000);
            }
        }

        if (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "Failed to read valid ADC value after %d retries. Skipping iteration.\n", MAX_RETRIES);
            control_buzzer(BUZZER_GPIO, 0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float voltage = (float)raw_adc * 3.3f / 1024.0f;
        float ambient_temperature = read_ambient_temperature();
        float compensated_voltage = compensate_voltage(raw_adc, ambient_temperature);
        int flame_detected = (compensated_voltage > 0.5f) ? 1 : 0;

        control_buzzer(BUZZER_GPIO, flame_detected);
        log_data(raw_adc, voltage, ambient_temperature, flame_detected);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    control_buzzer(BUZZER_GPIO, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return 0;
}

