#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define LED_PIN     17
#define WATER_LEVEL_THRESHOLD_HIGH  75.0
#define WATER_LEVEL_THRESHOLD_LOW   70.0
#define JSON_FILE "water_levels.json"
#define SAMPLE_INTERVAL_US 5000000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then don't-care */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_water_level(float percentage) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(json_file, "  {\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, percentage);
    fflush(json_file);
}

static void control_led(float percentage) {
    if (percentage > WATER_LEVEL_THRESHOLD_HIGH) {
        gpioWrite(LED_PIN, 1);
    } else if (percentage < WATER_LEVEL_THRESHOLD_LOW) {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    json_file = fopen(JSON_FILE, "w");
    if (json_file == NULL) {
        perror("Error opening JSON file");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(json_file, "[\n");
    fflush(json_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(json_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping this sample\n");
        } else {
            float percentage = (float)adc_value / 1023.0f * 100.0f;
            printf("Water level: %.2f%%\n", percentage);
            log_water_level(percentage);
            control_led(percentage);
        }

        /* Sleep in ~100 ms increments so signals are caught promptly */
        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(LOOP_DELAY_US);
        }
    }

    /* Clean shutdown */
    fprintf(json_file, "]\n");
    fflush(json_file);
    fclose(json_file);
    json_file = NULL;

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    spi_handle = -1;
    gpioTerminate();

    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

