#include <errno.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_VALUE 0
#define DEFAULT_MAX_VALUE 1000
#define DEFAULT_THRESHOLD 30
#define DEFAULT_INTERVAL 60
#define DEFAULT_EMAIL_RECIPIENT "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "/etc/msmtprc"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 500000
#define SPI_BITS 8
#define SPI_MODE 0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static char *email_recipient = DEFAULT_EMAIL_RECIPIENT;
static char *msmtp_config = DEFAULT_MSMTP_CONFIG;

typedef struct {
    int min_value;
    int max_value;
    int threshold;
    int interval;
} Config;

static Config config = {DEFAULT_MIN_VALUE, DEFAULT_MAX_VALUE, DEFAULT_THRESHOLD, DEFAULT_INTERVAL};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
