    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI device: %s, channel: %d, interval: %d s\n", SPI_DEVICE, ADC_CHANNEL, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int adc_value = read_adc(g_spi_fd, ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
        } else {
            float pressure = adc_to_pressure(adc_value);

            if (pressure < 0.0f) {
                fprintf(stderr, "Invalid pressure reading (ADC: %d, Voltage: %.3f V).\n", adc_value, (float)adc_value / (float)ADC_MAX_VALUE * VREF);
            } else {
                log_data(pressure, adc_value);
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    return EXIT_SUCCESS;
}

