#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define PUMP_GPIO        17
#define MOISTURE_LOW     300
#define MOISTURE_HIGH    600
#define BUFFER_SIZE      20
#define SAMPLE_INTERVAL  5

#define MCP3008_CHANNEL  0

typedef struct {
    time_t timestamp;
    int    moisture_level;
    int    pump_state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static int      buffer_count = 0;
static volatile sig_atomic_t running = 1;
static int      spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(time_t ts, int moisture, int pump) {
    log_buffer[buffer_index].timestamp = ts;
    log_buffer[buffer_index].moisture_level = moisture;
    log_buffer[buffer_index].pump_state = pump;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer ---\n");
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char tbuf[32];
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S",
                 localtime(&log_buffer[idx].timestamp));
        printf("[%s] Moisture: %d, Pump: %s\n",
               tbuf, log_buffer[idx].moisture_level,
               log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End Log Buffer ---\n\n");
    fflush(stdout);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1 + channel, then don't-care */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d): %s\n", ret, strerror(errno));
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static void control_pump(int moisture) {
    static int pump_on = 0;

    if (moisture < MOISTURE_LOW && !pump_on) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_on = 1;
            printf("Pump ON (Moisture: %d)\n", moisture);
        } else {
            fprintf(stderr, "Failed to turn pump ON: %s\n", strerror(errno));
        }
    } else if (moisture > MOISTURE_HIGH && pump_on) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_on = 0;
            printf("Pump OFF (Moisture: %d)\n", moisture);
        } else {
            fprintf(stderr, "Failed to turn pump OFF: %s\n", strerror(errno));
        }
    }
}

static void timer_callback(void *user) {
    (void)user;
    time_t now = time(NULL);
    int   moisture = read_mcp3008(MCP3008_CHANNEL);
    int   pump     = gpioRead(PUMP_GPIO);

    if (moisture < 0) {
        fprintf(stderr, "Error reading moisture sensor\n");
        return;
    }

    log_data(now, moisture, pump);
    control_pump(moisture);

    if (pump != gpioRead(PUMP_GPIO)) {
        fprintf(stderr, "Warning: pump GPIO read mismatch (expected %d, got %d)\n",
                pump, gpioRead(PUMP_GPIO));
    }

    print_log_buffer();
}

static int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise pump GPIO state\n");
        gpioTerminate();
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize() != 0) {
        return 1;
    }

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(1000000); /* 1 s */
    }

    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    cleanup();
    return 0;
}

