#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_INTR_ENABLE_2 0x03
#define REG_FIFO_WR_PTR 0x04
#define REG_OVERFLOW_CTR 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED_PA_1 0x0C
#define REG_LED_PA_2 0x0D
#define REG_LED_VIS_1 0x0E
#define REG_LED_VIS_2 0x10
#define REG_TEMP_INTR_THRESH 0x11
#define REG_TEMP_INTR_CONFIG 0x12
#define REG_TEMP_INTR_STATUS 0x13
#define REG_TEMP_DATA 0x14
#define REG_TEMP_CONFIG 0x15
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x50

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    FILE *fp = fopen(HEALTH_LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s - ERROR: %s\n", timestamp, message);
        fclose(fp);
    }
    fprintf(stderr, "%s - ERROR: %s\n", timestamp, message);
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        log_error("Failed to read register");
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        log_error("Failed to write register");
        return -1;
    }
    return 0;
}

static int read_spo2(int handle, float *spo2) {
    uint8_t spo2_data[3];
    uint8_t spo2_config = 0x00;
    uint8_t spo2_config_val;
    int result;

    if (write_register(handle, REG_SPO2_CONFIG, spo2_config) < 0) return -1;

    result = i2cReadI2CBlockData(handle, REG_FIFO_DATA, (char *)spo2_data, 3);
    if (result != 3) {
        log_error("Failed to read SPO2 data");
        return -1;
    }

    spo2_config_val = spo2_data[2];
    if (spo2_config_val & 0x01) {
        *spo2 = (float)((spo2_data[0] << 8) | spo2_data[1]) / 100.0;
    } else {
        *spo2 = (float)((spo2_data[1] << 8) | spo2_data[0]) / 100.0;
    }
    return 0;
}

static int read_heart_rate(int handle, int *heart_rate) {
    uint8_t heart_rate_data[2];
    uint8_t heart_rate_config = 0x00;
    int result;

