#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CE 0
#define NUM_CHANNELS 3
#define LOG_FILE "analog_log.csv"
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    float voltage = (float)adc_value * 3.3f / 1024.0f;
    return (int)voltage;
}

static void log_data(int channel, float voltage) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, channel, voltage);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | (SPI_MODE & 3));
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging MCP3008 channels 0-2 to %s every 500ms. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        for (int ch = 0; ch < NUM_CHANNELS; ch++) {
            int voltage = read_mcp3008(ch);
            if (voltage >= 0) {
                log_data(ch, (float)voltage);
            } else {
                fprintf(stderr, "Error reading channel %d\n", ch);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

