#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define BUZZER_PIN 24
#define THRESHOLD 500
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then don't-care */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed: returned %d\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int set_buzzer(int state) {
    int rc = gpioWrite(BUZZER_PIN, state);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(%d) failed: %d\n", state, rc);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    /* Safe state: buzzer off, GPIOs released */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register cleanup on normal exit paths */
    atexit(cleanup);

    /* Install signal handler for SIGINT (Ctrl-C) */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        return EXIT_FAILURE;
    }

    /* Configure buzzer pin as output and ensure it is off */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", BUZZER_PIN);
        return EXIT_FAILURE;
    }
    if (set_buzzer(0) < 0) {
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        return EXIT_FAILURE;
    }

    printf("MQ-2 gas sensor monitoring started. Press Ctrl-C to exit.\n");

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "ADC read error; continuing\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        printf("ADC: %d\n", adc);

        if (adc >= THRESHOLD) {
            if (set_buzzer(1) < 0) {
                break;
            }
        } else {
            if (set_buzzer(0) < 0) {
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

