    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        return EXIT_FAILURE;
    }

    printf("MQ-2 gas sensor monitoring started. Press Ctrl-C to exit.\n");

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "ADC read error; continuing\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        printf("ADC: %d\n", adc);

        if (adc >= THRESHOLD) {
            if (set_buzzer(1) < 0) {
                break;
            }
        } else {
            if (set_buzzer(0) < 0) {
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

