#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_CONV   0x00
#define ADS1115_CONFIG 0x01

#define RELAY_GPIO     17
#define REED_GPIO      27

#define DISTANCE_THRESHOLD 500
#define RELAY_PULSE_MS     3000
#define SAMPLE_INTERVAL_MS 200
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_MS 50

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    if (i2c_write_reg16(fd, ADS1115_CONFIG, 0x8000) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg16(fd, ADS1115_CONFIG, 0x4000) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_distance(int fd) {
    uint16_t raw;
    if (i2c_read_reg16(fd, ADS1115_CONV, &raw) < 0) return -1;
    return (int)raw;
}

static int calibrate_distance(int fd, int *threshold) {
    int sum = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int v = read_distance(fd);
        if (v < 0) return -1;
        sum += v;
        usleep(CALIBRATION_DELAY_MS * 1000);
    }
    *threshold = sum / CALIBRATION_SAMPLES;
    return 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen("/var/log/door_events.log", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, event);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        close(i2c_fd);
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0 || gpioSetMode(REED_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        close(i2c_fd);
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioSetPullUpDown(REED_GPIO, PI_PUD_UP);

    int threshold = 0;
    if (calibrate_distance(i2c_fd, &threshold) < 0) {
        fprintf(stderr, "Calibration failed\n");
        close(i2c_fd);
        return 1;
    }
    printf("Calibration complete. Threshold: %d\n", threshold);

    while (running) {
        int dist = read_distance(i2c_fd);
        if (dist < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        if (dist < threshold) {
            printf("Distance below threshold (%d < %d)\n", dist, threshold);
            if (gpioWrite(RELAY_GPIO, 1) < 0) {
                fprintf(stderr, "Failed to energize relay\n");
            } else {
                log_event("Door lock released");
                usleep(RELAY_PULSE_MS * 1000);
                if (gpioWrite(RELAY_GPIO, 0) < 0) {
                    fprintf(stderr, "Failed to de-energize relay\n");
                } else {
                    int reed = gpioRead(REED_GPIO);
                    if (reed < 0) {
                        fprintf(stderr, "Failed to read reed sensor\n");
                    } else if (reed == 0) {
                        log_event("Door opened");
                    } else {
                        log_event("Door not opened");
                    }
                }
            }
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpioWrite(RELAY_GPIO, 0);
    if (i2c_fd >= 0) close(i2c_fd);
    printf("Exiting cleanly.\n");
    return 0;
}

