            if (log_event(value) == 0) {
                printf("Peak detected: %d\n", value);
            } else {
                fprintf(stderr, "Failed to log event.\n");
            }
            peak_detected = 1;
        } else if (value <= PEAK_THRESHOLD && peak_detected) {
            peak_detected = 0;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

