#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR    0x00
#define SAMPLE_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown on Ctrl-C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 slave address */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Error: ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * Dummy write: the PCF8591 returns the result of the *previous*
     * conversion on the first read after a write.  We write 0x00 to
     * clear any stale result and ensure we start with a fresh sample.
     */
    uint8_t dummy = 0x00;
    if (write(fd, &dummy, 1) != 1) {
        fprintf(stderr, "Error: dummy write failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Monitoring PCF8591 AIN0 on %s (addr 0x%02X) every %d ms...\n",
           I2C_BUS, PCF8591_ADDR, SAMPLE_DELAY_US / 1000);
    fflush(stdout);

    while (g_running) {
        uint8_t value = 0;
        ssize_t n = read(fd, &value, 1);
        if (n != 1) {
            fprintf(stderr, "Error: I2C read failed (returned %zd): %s\n",
                    n, n < 0 ? strerror(errno) : "short read");
            goto cleanup;
        }

        printf("AIN0: %u\n", (unsigned)value);
        fflush(stdout);

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

