#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128_SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define GPIO_SHUTDOWN 27
#define THRESHOLD_GAUSS 500.0
#define SAMPLE_INTERVAL_US 1000000
#define BUFFER_SIZE 10
#define VREF 3.3
#define ADC_MAX 32767.0
#define ADC_VREF_4_096V 4.096

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static CircularBuffer gauss_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    memset(cb->buffer, 0, sizeof(cb->buffer));
}

static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float calculate_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / cb->count;
}

static int read_ads1115(int handle, float *voltage) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128_SPS | ADS1115_CONFIG_CQUE_NONE;
    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;
    if (i2cWriteDevice(handle, cfg, 3) < 0) return -1;

    gpioDelay(10000);

    char reg[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(handle, reg, 1) < 0) return -1;

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;

    int16_t raw = (data[0] << 8) | data[1];
    *voltage = (raw / ADC_MAX) * VREF;
    return 0;
}

static float voltage_to_gauss(float v) {
    if (v < 0.0f || v > VREF) return 0.0f;
    return (v / VREF) * 100.0f;
}

static void shutdown_motor(void) {
    gpioWrite(GPIO_SHUTDOWN, 1);
    syslog(LOG_INFO, "Motor shutdown triggered!");
}

int main(void) {
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", GPIO_SHUTDOWN);
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);

    init_circular_buffer(&gauss_buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Starting Hall sensor monitoring...");

    while (running) {
        float voltage = 0.0f;
        if (read_ads1115(i2c_handle, &voltage) < 0) {
            syslog(LOG_ERR, "I2C/ADC read error: %s", strerror(errno));
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (voltage < 0.0f || voltage > VREF) {
            syslog(LOG_ERR, "Voltage out of range: %.3f V", voltage);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        add_to_buffer(&gauss_buffer, gauss);
        float avg = calculate_average(&gauss_buffer);

        if (avg > THRESHOLD_GAUSS) {
            shutdown_motor();
        }

        syslog(LOG_INFO, "Voltage: %.3f V, Gauss: %.2f, Avg: %.2f", voltage, gauss, avg);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down...");
    gpioWrite(GPIO_SHUTDOWN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return 0;
}

