#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define MOISTURE_THRESHOLD 300
#define PUMP_GPIO 18
#define WATERING_DURATION 10
#define LOG_FILE "watering_events.txt"
#define SAMPLE_INTERVAL 60
#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0
#define ADC_INVALID -1

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return ADC_INVALID;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return ADC_INVALID;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d\n", PUMP_GPIO);
        return -1;
    }
    return 0;
}

static int log_event(int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s - Moisture level: %d\n", timestamp, moisture_level) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    control_pump(0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        cleanup();
        return 1;
    }

    if (control_pump(0) != 0) {
        fprintf(stderr, "Error: Failed to initialize pump GPIO to OFF\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_adc(ADC_CHANNEL);

        if (moisture_level == ADC_INVALID) {
            fprintf(stderr, "Error: Invalid ADC reading, skipping cycle\n");
        } else if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold (%d < %d). Watering...\n",
                   moisture_level, MOISTURE_THRESHOLD);

            if (control_pump(1) != 0) {
                fprintf(stderr, "Error: Failed to activate pump\n");
                break;
            }

            for (int i = 0; i < WATERING_DURATION && running; i++) {
                sleep(1);
            }

            if (control_pump(0) != 0) {
                fprintf(stderr, "Error: Failed to deactivate pump\n");
                break;
            }

            if (log_event(moisture_level) != 0) {
                fprintf(stderr, "Error: Failed to log event\n");
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

