static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    control_pump(0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        cleanup();
        return 1;
    }

    if (control_pump(0) != 0) {
        fprintf(stderr, "Error: Failed to initialize pump GPIO to OFF\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_adc(ADC_CHANNEL);

        if (moisture_level == ADC_INVALID) {
            fprintf(stderr, "Error: Invalid ADC reading, skipping cycle\n");
        } else if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold (%d < %d). Watering...\n",
                   moisture_level, MOISTURE_THRESHOLD);

            if (control_pump(1) != 0) {
                fprintf(stderr, "Error: Failed to activate pump\n");
                break;
            }

            for (int i = 0; i < WATERING_DURATION && running; i++) {
                sleep(1);
            }

            if (control_pump(0) != 0) {
                fprintf(stderr, "Error: Failed to deactivate pump\n");
                break;
            }

            if (log_event(moisture_level) != 0) {
                fprintf(stderr, "Error: Failed to log event\n");
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

