#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 / GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 channel 0 */
#define PWM_GPIO       18         /* GPIO18 (BCM) */
#define PWM_FREQUENCY  1000       /* 1 kHz */
#define PWM_RANGE      1024       /* 0–1023 duty */
#define SAMPLE_US      100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI transfer failure.
 */
static int read_adc(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
}

static int set_pwm(int gpio, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "gpioPWM failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on GPIO18 --- */
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on GPIO %d\n", PWM_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed on GPIO %d\n", PWM_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed on GPIO %d\n", PWM_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MCP3008 + PWM control running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc = read_adc(g_spi_handle, ADC_CHANNEL);
        if (adc < 0) {
            /* SPI error: stop PWM and back off briefly before retry */
            set_pwm(PWM_GPIO, 0);
            gpioDelay(10000);  /* 10 ms */
            continue;
        }

        int pwm = (int)((float)adc / 1023.0f * PWM_RANGE);
        if (set_pwm(PWM_GPIO, pwm) < 0) {
            /* Non-fatal: continue sampling */
        }

        printf("ADC: %4d  PWM: %4d\n", adc, pwm);
        gpioDelay(SAMPLE_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    set_pwm(PWM_GPIO, 0);
    spiClose(g_spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

