#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CLIENT_ID "rpi_soil_monitor"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define SAMPLE_INTERVAL_SEC 60
#define SPI_READ_RETRIES 3
#define SPI_RETRY_DELAY_US 10000
#define SENSOR_ABSENT_THRESHOLD 0
#define SENSOR_ABSENT_TIMEOUT_SEC 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < SPI_READ_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        syslog(LOG_WARNING, "SPI transfer failed (attempt %d/%d): %s",
               attempt + 1, SPI_READ_RETRIES, strerror(errno));
        if (attempt < SPI_READ_RETRIES - 1) {
            gpioDelay(SPI_RETRY_DELAY_US);
        }
    }
    syslog(LOG_ERR, "SPI read failed after %d retries", SPI_READ_RETRIES);
    return -1;
}

static void control_relay(int state) {
    if (state == relay_state) {
        return;
    }
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write relay GPIO %d: %s", RELAY_GPIO, strerror(errno));
        return;
    }
    relay_state = state;
    syslog(LOG_INFO, "Relay %s", state ? "activated" : "deactivated");
}

static void publish_moisture(int moisture_level) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%d", moisture_level);

    if (mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture level: %s", mosquitto_strerror(mosq_errno()));
    } else {
        syslog(LOG_INFO, "Published moisture level: %d", moisture_level);
    }
}

static void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to broker %s:%d", MQTT_BROKER, MQTT_PORT);
        if (mosquitto_subscribe(mosq, NULL, "pump_control", 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to pump_control: %s", mosquitto_strerror(mosq_errno()));
        } else {
            syslog(LOG_INFO, "Subscribed to pump_control");
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    (void)mosq;
    (void)userdata;
    if (rc == 0) {
        syslog(LOG_INFO, "MQTT disconnected cleanly");
    } else {
        syslog(LOG_WARNING, "MQTT disconnected unexpectedly: %s", mosquitto_strerror(rc));
    }
}

static void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    (void)mosq;
    (void)userdata;
    if (message->payloadlen > 0) {
        char payload[32];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';

        if (strcmp(payload, "pump_on") == 0) {
            control_relay(1);
        } else if (strcmp(payload, "pump_off") == 0) {
            control_relay(0);
        } else {
            syslog(LOG_WARNING, "Unknown MQTT command: %s", payload);
        }
    }
}

static void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up resources...");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (mosq != NULL) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog(MQTT_CLIENT_ID, LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting soil moisture monitor...");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO %d as output", RELAY_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", strerror(spi_handle));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mosq == NULL) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", strerror(MOSQUITTO_ERR));
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Soil moisture monitoring started. Press Ctrl+C to exit.");

    while (running) {
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            syslog(LOG_ERR, "Failed to read moisture level. Retrying in %d seconds.", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (moisture_level < SENSOR_ABSENT_THRESHOLD) {
            syslog(LOG_WARNING, "Sensor absent or disconnected (level=%d). Ensuring pump is off.", moisture_level);
            control_relay(0);
        } else if (moisture_level > SENSOR_ABSENT_THRESHOLD) {
            syslog(LOG_INFO, "Sensor present (level=%d). Monitoring thresholds.", moisture_level);
        } else {
            syslog(LOG_WARNING, "Sensor reading at threshold (%d). Monitoring thresholds.", moisture_level);
        }

        if (moisture_level < MOISTURE_THRESHOLD_LOW) {
            if (relay_state == 0) {
                control_relay(1);
            }
        } else if (moisture_level > MOISTURE_THRESHOLD_HIGH) {
            if (relay_state == 1) {
                control_relay(0);
            }
        }

        publish_moisture(moisture_level);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    syslog(LOG_INFO, "Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

