    uint32_t period = PWM_RANGE;

    if (gpioSetPWMfrequency(gpio, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d: %s\n", gpio, strerror(errno));
        return;
