    if (gpioSetPWMrange(gpio, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d: %s\n", gpio, strerror(errno));
        return;
    }

    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle on GPIO %d: %s\n", gpio, strerror(errno));
