    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Vibration detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int noise_level = read_mcp3008(0);
        if (noise_level < 0) {
            fprintf(stderr, "Error reading noise level. Skipping iteration.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (noise_level > NOISE_THRESHOLD) {
            set_motor_pwm(MOTOR_GPIO_1, 50);
            set_motor_pwm(MOTOR_GPIO_2, 50);
            log_vibration_event(1);
        } else {
            set_motor_pwm(MOTOR_GPIO_1, 0);
            set_motor_pwm(MOTOR_GPIO_2, 0);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

