    if (adc_value < 0 || adc_value > 1023) {
        return -1.0f;
    }
    return (float)adc_value / 1023.0f * 100.0f;
}

static void control_pump(int state) {
    if (g_pigpio_initialized) {
        gpioWrite(PUMP_GPIO, state);
    }
}

static void cleanup(void) {
    control_pump(0);
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_pigpio_initialized) {
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
}

