        fprintf(stderr, "Error: Failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }

    printf("Door sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        int distance = distance_to_adc(adc_value);

        if (distance < DISTANCE_THRESHOLD) {
            printf("Distance: %d cm - Door detected!\n", distance);
            log_event(distance);

            if (gpioWrite(RELAY_PIN, 1) != 0) {
                fprintf(stderr, "Error: Failed to activate relay\n");
            } else {
                gpioDelay(DEBOUNCE_DELAY * 1000000);
                if (gpioWrite(RELAY_PIN, 0) != 0) {
                    fprintf(stderr, "Error: Failed to deactivate relay\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

