        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int calculate_average(int values[], int count) {
    if (count <= 0) return 0;
    int sum = 0;
    for (int i = 0; i < count; i++) sum += values[i];
    return sum / count;
}

