    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int values[SAMPLE_COUNT];
    int valid_count = 0;

    while (running) {
        for (int i = 0; i < SAMPLE_COUNT; i++) {
            int v = read_mcp3008(i);
            if (v < 0) {
                fprintf(stderr, "Skipping sample %d due to read error\n", i);
                continue;
            }
            values[valid_count++] = v;
        }

        if (valid_count == 0) {
            fprintf(stderr, "No valid samples in this cycle\n");
        } else {
            int avg = calculate_average(values, valid_count);
            int position = 0;
            if (valid_count == SAMPLE_COUNT) {
                position = (avg * PWM_RANGE) / 1023;
            }
            if (set_valve_position(position) != 0) {
                fprintf(stderr, "Failed to set valve position\n");
            }
            log_data(values, avg, position);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

