                }
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    gpioDelay(RETRY_DELAY_BASE / (1 << retries));
                }
            }
        }

        if (success) {
            int moisture_percentage = convert_to_moisture_percentage(adc_value);
