                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            log_error("SPI communication failed after retries");
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL * 1000000);
        }
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

