#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <sys/stat.h>

#define CONFIG_FILE "theremin_config.txt"

#define SPI_DEVICE "/dev/spidev0.0"
#define PWM_CHIP "/sys/class/pwm/pwmchip0"
#define PWM_EXPORT "/sys/class/pwm/pwmchip0/export"
#define PWM_UNEXPORT "/sys/class/pwm/pwmchip0/unexport"
#define PWM_PERIOD_PATH "/sys/class/pwm/pwmchip0/pwm0/period"
#define PWM_DUTY_CYCLE_PATH "/sys/class/pwm/pwmchip0/pwm0/duty_cycle"
#define PWM_ENABLE_PATH "/sys/class/pwm/pwmchip0/pwm0/enable"

#define TRIG_PIN 23
#define ECHO_PIN 24
#define LDR_CHANNEL 0

#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 2.0
#define MAX_FREQUENCY 2000.0
#define MIN_FREQUENCY 20.0
#define MAX_LDR_VALUE 1023
#define MIN_LDR_VALUE 0
#define PWM_RANGE 1000000
#define TIMEOUT_US 30000

volatile sig_atomic_t program_running = 1;

typedef struct {
    float distance_calibration;
    float volume_calibration;
} CalibrationData;

CalibrationData calibration_data = {200.0, 500.0};

int spi_fd = -1;
int pwm_exported = 0;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int read_mcp3008(int channel) {
    if (spi_fd < 0) return -1;

    uint8_t tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    uint8_t rx_buf[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
