{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Alcohol monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && g_running) {
            adc_value = read_mcp3008(ADC_CHANNEL);
            if (adc_value >= 0 && adc_value <= ADC_MAX)
                break;

            fprintf(stderr, "ADC read failed (attempt %d/%d)\n",
                    retries + 1, MAX_RETRIES);
            retries++;
            if (retries < MAX_RETRIES)
                usleep(RETRY_DELAY_MS * 1000);
        }

        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "Error: Failed to read ADC after %d retries.\n",
                    MAX_RETRIES);
            if (log_data(0, "Error: ADC read failure") < 0)
                fprintf(stderr, "Error logging ADC failure.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (adc_value == ADC_MIN || adc_value == ADC_MAX) {
            fprintf(stderr,
                    "Warning: Sensor may be absent or disconnected (ADC at rail).\n");
            if (log_data(adc_value, "Warning: Sensor absent or rail reading") < 0)
                fprintf(stderr, "Error logging sensor-absent warning.\n");
        } else {
            const char *msg = classify_alcohol(adc_value);
            if (log_data(adc_value, msg) < 0)
                fprintf(stderr, "Error logging data.\n");
            printf("ADC: %d, %s\n", adc_value, msg);
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

