            fprintf(stderr, "Error reading moisture sensor\n");
            log_data(-1, -1);
        } else {
            int pump_status = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;
            gpioWrite(PUMP_GPIO, pump_status);
            log_data(moisture, pump_status);
            printf("Moisture: %d, Pump: %s\n", moisture, pump_status ? "ON" : "OFF");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

