#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_PWM_PIN 18
#define MOTOR1_DIR_PIN 23
#define MOTOR2_PWM_PIN 24
#define MOTOR2_DIR_PIN 25

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

#define ACCELERATION_TIME 2.0
#define HOLD_TIME 2.0
#define REVERSE_DELAY_MS 100
#define PAUSE_TIME 5.0

#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_potentiometer(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int map_value(int x, int in_min, int in_max, int out_min, int out_max) {
    if (in_max == in_min) return out_min;
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

static void set_motor_speed(int motor_pin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    gpioPWM(motor_pin, speed);
}

static void set_motor_direction(int dir_pin, int direction) {
    if (direction < 0) direction = 0;
    if (direction > 1) direction = 1;
    gpioWrite(dir_pin, direction);
}

static void accelerate_motor(int motor_pin, int target_speed, double duration) {
    double step_time = duration / 100.0;
    for (double t = 0.0; t < duration && running; t += step_time) {
        int current_speed = (int)(map_value(t, 0.0, duration, 0, target_speed));
        set_motor_speed(motor_pin, current_speed);
        gpioDelay((uint32_t)(step_time * 1000000));
    }
}

static void decelerate_motor(int motor_pin, double duration) {
    double step_time = duration / 100.0;
    for (double t = 0.0; t < duration && running; t += step_time) {
        int current_speed = (int)(map_value(t, 0.0, duration, target_speed, 0));
        set_motor_speed(motor_pin, current_speed);
        gpioDelay((uint32_t)(step_time * 1000000));
    }
}

static void reverse_direction(int motor1_dir_pin, int motor2_dir_pin) {
    set_motor_direction(motor1_dir_pin, 1);
    set_motor_direction(motor2_dir_pin, 0);
    gpioDelay(REVERSE_DELAY_MS * 1000);
}

