        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR1_PWM_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PWM_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR_PIN, PI_OUTPUT);

    gpioSetPWMrange(MOTOR1_PWM_PIN, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_PWM_PIN, PWM_RANGE);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (running) {
        int pot1_value = read_potentiometer(POT1_CHANNEL);
        int pot2_value = read_potentiometer(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Potentiometer read failed, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        int speed1 = map_value(pot1_value, 0, 1023, 0, PWM_RANGE);
        int speed2 = map_value(pot2_value, 0, 1023, 0, PWM_RANGE);

        printf("Pot1: %d, Pot2: %d, Speed1: %d, Speed2: %d\n", pot1_value, pot2_value, speed1, speed2);

        set_motor_speed(MOTOR1_PWM_PIN, speed1);
        set_motor_speed(MOTOR2_PWM_PIN, speed2);
        set_motor_direction(MOTOR1_DIR_PIN, 1);
        set_motor_direction(MOTOR2_DIR_PIN, 1);

        accelerate_motor(MOTOR1_PWM_PIN, speed1, ACCELERATION_TIME);
        accelerate_motor(MOTOR2_PWM_PIN, speed2, ACCELERATION_TIME);

        if (!running) break;
        gpioDelay((uint32_t)(HOLD_TIME * 1000000));

        decelerate_motor(MOTOR1_PWM_PIN, ACCELERATION_TIME);
        decelerate_motor(MOTOR2_PWM_PIN, ACCELERATION_TIME);

        if (!running) break;
        gpioDelay((uint32_t)(PAUSE_TIME * 1000000));

        reverse_direction(MOTOR1_DIR_PIN, MOTOR2_DIR_PIN);
        if (!running) break;
        gpioDelay((uint32_t)(REVERSE_DELAY_MS * 1000));
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

