#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_PIN 17
#define SOUND_THRESHOLD 500
#define DEBOUNCE_DELAY_US 10000
#define CALIBRATION_DURATION 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int calibrate_sound_level(int *baseline) {
    int sum = 0;
    int valid_samples = 0;

    printf("Calibrating sound level for %d seconds...\n", CALIBRATION_DURATION);

    for (int i = 0; i < CALIBRATION_DURATION * 10 && running; i++) {
        int level = read_mcp3008(0);
        if (level < 0) {
            fprintf(stderr, "Error reading sound level during calibration\n");
            return -1;
        }
        sum += level;
        valid_samples++;
        usleep(100000);
    }

    if (valid_samples == 0) {
        fprintf(stderr, "No valid samples collected during calibration\n");
        return -1;
    }

    *baseline = sum / valid_samples;
    printf("Calibrated sound level: %d\n", *baseline);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int baseline = 0;
    if (calibrate_sound_level(&baseline) != 0) {
        fprintf(stderr, "Calibration failed, exiting\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting sound level monitoring...\n");

    while (running) {
        int level = read_mcp3008(0);
        if (level < 0) {
            fprintf(stderr, "Error reading sound level\n");
            usleep(100000);
            continue;
        }

        if (level > SOUND_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            usleep(DEBOUNCE_DELAY_US);
            if (!running) {
                gpioWrite(LED_PIN, 0);
                break;
            }
            gpioWrite(LED_PIN, 0);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        usleep(100000);
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

