#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_PIN          8
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)
#define LOG_FILE        "audio_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_log_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = 1000000;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    int ret;

    ret = ioctl(g_spi_fd, SPI_IOC_WR_MODE, &0);
    if (ret < 0) {
        fprintf(stderr, "Error setting SPI to alt mode: %s\n", strerror(errno));
        return -1;
    }

    int cs_line = CS_PIN;
    struct gpio_chip *chip = NULL;
    chip = gpio_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n",
                GPIO_CHIP, strerror(errno));
        return -1;
    }

    struct gpio_line *line = NULL;
    line = gpio_chip_get_line(chip, cs_line);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                cs_line, strerror(errno));
        gpio_close(chip);
        return -1;
    }

    ret = gpio_request_output(line, "mcp3008-cs", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n",
                cs_line, strerror(errno));
        gpio_close(chip);
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error sending SPI message: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void log_data(long timestamp_ns, int adc_value)
{
    char buffer[64];
    int len = snprintf(buffer, sizeof(buffer), "%ld|%d\n",
                       timestamp_ns, adc_value);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "Error formatting log line\n");
        return;
    }

    if (fputs(buffer, g_log_fd) == EOF) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fd) == EOF) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    g_log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (g_log_fd < 0) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE, strerror(errno));
        gpio_release(g_spi_fd, CS_PIN);
        close(g_spi_fd);
        return 1;
    }

    struct timespec next_deadline;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next_deadline);

    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);

        long timestamp_ns = (long)now.tv_sec * 1000000000L + now.tv_nsec;
        log_data(timestamp_ns, adc_value);

        next_deadline.tv_nsec += SAMPLE_PERIOD_NS;
        if (next_deadline.tv_nsec >= 1000000000L) {
            next_deadline.tv_sec += 1;
            next_deadline.tv_nsec -= 1000000000L;
        }

        struct timespec sleep_ts;
        sleep_ts.tv_sec = next_deadline.tv_sec;
        sleep_ts.tv_nsec = next_deadline.tv_nsec;

        while (nanosleep(&sleep_ts, &sleep_ts) < 0 && errno == EINTR) {
            if (!g_running) {
                break;
            }
        }
    }

    if (g_log_fd >= 0) {
        close(g_log_fd);
        g_log_fd = -1;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpio_release(g_spi_fd, CS_PIN);

    return 0;
}

