#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2

#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

#define PROCESS_NOISE_X 0.01
#define PROCESS_NOISE_Y 0.01
#define PROCESS_NOISE_Z 0.01

#define MEASUREMENT_NOISE_X 0.1
#define MEASUREMENT_NOISE_Y 0.1
#define MEASUREMENT_NOISE_Z 0.1

#define INITIAL_ERROR_COVARIANCE_X 0.1
#define INITIAL_ERROR_COVARIANCE_Y 0.1
#define INITIAL_ERROR_COVARIANCE_Z 0.1

#define INITIAL_STATE_ESTIMATE_X 0.0
#define INITIAL_STATE_ESTIMATE_Y 0.0
#define INITIAL_STATE_ESTIMATE_Z 0.0

#define VREF 3.3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

typedef struct {
    double x;
    double y;
    double z;
} AccelerationData;

typedef struct {
    double x;
    double y;
    double z;
    double covariance_xx;
    double covariance_xy;
    double covariance_xz;
    double covariance_yy;
    double covariance_yz;
    double covariance_zz;
} KalmanState;

static KalmanState kf_x = {INITIAL_STATE_ESTIMATE_X, 0, 0, INITIAL_ERROR_COVARIANCE_X, 0, 0, 0, 0, 0};
static KalmanState kf_y = {INITIAL_STATE_ESTIMATE_Y, 0, 0, INITIAL_ERROR_COVARIANCE_Y, 0, 0, 0, 0, 0};
static KalmanState kf_z = {INITIAL_STATE_ESTIMATE_Z, 0, 0, INITIAL_ERROR_COVARIANCE_Z, 0, 0, 0, 0, 0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n", SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int read_mcp3008_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int result = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d: %s\n", channel, pigpio_error(result));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static AccelerationData read_acceleration(void) {
    AccelerationData data = {0, 0, 0};
    int x_raw = read_mcp3008_channel(X_CHANNEL);
    int y_raw = read_mcp3008_channel(Y_CHANNEL);
    int z_raw = read_mcp3008_channel(Z_CHANNEL);

    if (x_raw < 0 || y_raw < 0 || z_raw < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return data;
    }

    data.x = ((double)x_raw / 1023.0) * VREF;
    data.y = ((double)y_raw / 1023.0) * VREF;
    data.z = ((double)z_raw / 1023.0) * VREF;
    return data;
}

static void kalman_filter_update(KalmanState *state, double measurement) {
    double x_diff = measurement - state->x;
    double y_diff = 0.0;
    double z_diff = 0.0;

    state->x += x_diff;
    state->y += y_diff;
    state->z += z_diff;

    state->covariance_xx += PROCESS_NOISE_X;
    state->covariance_yy += PROCESS_NOISE_Y;
    state->covariance_zz += PROCESS_NOISE_Z;

    state->covariance_xy += -state->x * PROCESS_NOISE_X;
    state->covariance_xz += -state->x * PROCESS_NOISE_Z;
    state->covariance_yz += -state->y * PROCESS_NOISE_Z;

    state->covariance_yx += -state->y * PROCESS_NOISE_X;
    state->covariance_zx += -state->z * PROCESS_NOISE_X;
    state->covariance_zy += -state->z * PROCESS_NOISE_Y;

    state->covariance_zz += -state->z * PROCESS_NOISE_Z;

    double s_x = state->covariance_xx + MEASUREMENT_NOISE_X;
    double s_y = state->covariance_yy + MEASUREMENT_NOISE_Y;
    double s_z = state->covariance_zz + MEASUREMENT_NOISE_Z;

    double k_x = state->covariance_xx / s_x;
    double k_y = state->covariance_yy / s_y;
    double k_z = state->covariance_zz / s_z;

    state->x += k_x * x_diff;
    state->y += k_y * y_diff;
    state->z += k_z * z_diff;

    state->covariance_xx -= k_x * state->covariance_xx;
    state->covariance_yy -= k_y * state->covariance_yy;
    state->covariance_zz -= k_z * state->covariance_zz;

    state->covariance_xy -= k_x * state->covariance_xy;
    state->covariance_xz -= k_x * state->covariance_xz;
    state->covariance_yz -= k_y * state->covariance_yz;

    state->covariance_yx -= k_y * state->covariance_yx;
    state->covariance_zx -= k_z * state->covariance_zx;
    state->covariance_zy -= k_z * state->covariance_zy;
}

static void print_acceleration(AccelerationData data) {
    printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", data.x, data.y, data.z);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting ADXL335 acceleration monitoring via MCP3008...\n");

    while (running) {
        AccelerationData raw_data = read_acceleration();
        if (raw_data.x != 0.0) {
            KalmanFilterData filtered_data;
            filtered_data.x = kf_x.x;
            filtered_data.y = kf_y.y;
            filtered_data.z = kf_z.z;
            print_acceleration(filtered_data);
        } else {
            fprintf(stderr, "Error reading acceleration data, skipping filter update\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

