#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "watering.log"
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 3) < 0) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void control_pump(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        log_event("ERROR: Failed to write pump GPIO");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Pump set to %s", state ? "ON" : "OFF");
    log_event(msg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        log_event("ERROR: Failed to set pump GPIO mode");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_event("ERROR: Failed to open SPI channel");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int pump_state = 0;
    int consecutive_errors = 0;

    while (running) {
        int moisture = read_adc(spi_handle, ADC_CHANNEL);
        if (moisture < 0) {
            log_event("ERROR: Failed to read ADC value");
            consecutive_errors++;
            if (consecutive_errors > 10) {
                log_event("ERROR: Too many consecutive ADC read failures, aborting");
                break;
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        consecutive_errors = 0;

        float moisture_level = (float)moisture / 1023.0 * 100.0;
        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture level: %.2f%%", moisture_level);
        log_event(msg);

        if (moisture_level < MOISTURE_THRESHOLD && pump_state == 0) {
            control_pump(PUMP_GPIO, 1);
            pump_state = 1;
        } else if (moisture_level >= MOISTURE_THRESHOLD && pump_state == 1) {
            control_pump(PUMP_GPIO, 0);
            pump_state = 0;
        }

        sleep(SAMPLE_INTERVAL);
    }

    log_event("Program terminating");
    control_pump(PUMP_GPIO, 0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

