#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define CSV_FILENAME    "sensor_data.csv"
#define NUM_CHANNELS    3
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008 on the given channel (0-7).
 * Returns 0-1023 on success, or -1 on error.
 */
static int mcp3008_read(int spi_fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read frame (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed on channel %u: %s\n",
                channel, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

int main(void)
{
    int spi_fd = -1;
    FILE *csv_fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure SPI mode --- */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Cannot set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Configure bits per word --- */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Cannot set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Configure max speed --- */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Cannot set SPI speed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open CSV file --- */
    csv_fp = fopen(CSV_FILENAME, "w");
    if (csv_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header */
    if (fprintf(csv_fp, "Channel0,Channel1,Channel2\n") < 0) {
        fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
        goto cleanup;
    }
    if (fflush(csv_fp) != 0) {
        fprintf(stderr, "Failed to flush CSV header: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Logging MCP3008 channels 0-2 to %s every %d second(s). Press Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_PERIOD_S);

    /* --- Main sampling loop --- */
    while (g_running) {
        int values[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = mcp3008_read(spi_fd, (uint8_t)(i));
            if (v < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                error = 1;
                break;
            }
            values[i] = v;
        }

        if (error) {
            break;
        }

        if (fprintf(csv_fp, "%d,%d,%d\n", values[0], values[1], values[2]) < 0) {
            fprintf(stderr, "Failed to write CSV row: %s\n", strerror(errno));
            break;
        }
        if (fflush(csv_fp) != 0) {
            fprintf(stderr, "Failed to flush CSV file: %s\n", strerror(errno));
            break;
        }

        sleep(SAMPLE_PERIOD_S);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (csv_fp != NULL) {
        if (fclose(csv_fp) != 0) {
            fprintf(stderr, "Error closing CSV file: %s\n", strerror(errno));
        }
    }
    if (spi_fd >= 0) {
        if (close(spi_fd) != 0) {
            fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
        }
    }
    return rc;
}

