#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60
#define JSON_BUFFER_SIZE 256

static volatile sig_atomic_t running = 1;
static MQTTClient client;
static int led_state = 0;
static int reconnect_delay = 1;

typedef struct {
    char *topic;
    char *payload;
} mqtt_message_t;

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s (errno: %d - %s)\n", timestamp, message, errno, strerror(errno));
}

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int connect_mqtt(void) {
    int rc;

    rc = MQTTClient_create(&client, MQTT_HOST, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        log_error("MQTTClient_create failed");
        return -1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        log_error("MQTTClient_connect failed");
        MQTTClient_destroy(&client);
        return -1;
    }

    rc = MQTTClient_subscribe(client, MQTT_TOPIC, 0);
    if (rc != MQTTCLIENT_SUCCESS) {
        log_error("MQTTClient_subscribe failed");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return -1;
    }

    printf("Connected to MQTT broker.\n");
    return 0;
}

void on_connect(void *context, char *reason, int result) {
    (void)context;
    (void)reason;
    if (result == MQTTCLIENT_SUCCESS) {
        printf("Connected to MQTT broker.\n");
    } else {
        fprintf(stderr, "Connection failed: %s\n", reason);
    }
}

void on_disconnect(void *context, int reason_code) {
    (void)context;
    (void)reason_code;
