#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN    18
#define POLL_DELAY_US    100000  /* 100 ms */
#define ALARM_DURATION_US 1000000 /* 1 s */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int rc;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return EXIT_FAILURE;
    }

    /* Configure sound sensor pin as input */
    rc = gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", SOUND_SENSOR_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alarm LED pin as output and ensure it starts OFF */
    rc = gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %d\n", ALARM_LED_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioWrite(ALARM_LED_PIN, 0);
    if (rc != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d to LOW: %d\n", ALARM_LED_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_level = gpioRead(SOUND_SENSOR_PIN);
        if (sound_level < 0) {
            fprintf(stderr, "Error reading GPIO%d: %d\n", SOUND_SENSOR_PIN, sound_level);
            break;
        }

        printf("Sound level: %d\n", sound_level);

        /* KY-038 DO goes LOW when sound exceeds threshold */
        if (sound_level == 0) {
            printf("Sound event detected!\n");
            rc = gpioWrite(ALARM_LED_PIN, 1);
            if (rc != 0) {
                fprintf(stderr, "Error turning on alarm LED: %d\n", rc);
                break;
            }
            gpioDelay(ALARM_DURATION_US);
            rc = gpioWrite(ALARM_LED_PIN, 0);
            if (rc != 0) {
                fprintf(stderr, "Error turning off alarm LED: %d\n", rc);
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown: turn off LED and release pigpio resources */
    gpioWrite(ALARM_LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

