#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5
#define ADC_CHANNEL 0

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01;
    tx_buffer[1] = (0x08 | channel) << 4;
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

static float adc_to_temperature(int adc_value) {
    return (float)adc_value * 0.01;
}

static void store_temperature_to_file(float temperature) {
    FILE *fp = fopen("temp_log.dat", "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temp_log.dat for writing\n");
        return;
    }

    size_t elements_written = fwrite(temperature_buffer, sizeof(float), buffer_index, fp);
    if (elements_written != buffer_index) {
        fprintf(stderr, "Error: Failed to write all buffer elements to file\n");
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: Failed to flush temp_log.dat\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close temp_log.dat\n");
    }
}

static void print_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Temperature: %.2f °C (timestamp: %s)\n", temperature, timestamp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Could not register SIGINT handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Could not register SIGTERM handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(SAMPLE_INTERVAL * 1000000);
            continue;
        }

        float temperature = adc_to_temperature(adc_value);
        print_temperature(temperature);
        store_temperature_to_file(temperature);

        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        gpioDelay(SAMPLE_INTERVAL * 1000000);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

