#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define MCP3008_CHANNEL 0
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_sensor(int fd, int addr, unsigned char cmd, unsigned int *value) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    unsigned char buf[2];
    buf[0] = cmd;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error: Failed to write command 0x%02X to I2C device: %s\n", cmd, strerror(errno));
        return -1;
    }
    usleep(10000);
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int spi_read_adc(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_data(const char *filename, int light_level, int sound_level) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Light: %d, Sound: %d\n", timestamp, light_level, sound_level);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    int spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Failed to open SPI bus %s: %s\n", SPI_BUS, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    unsigned int light_level = 0;
    int sound_level = 0;
    while (running) {
        if (i2c_read_sensor(i2c_fd, BH1750_ADDR, BH1750_CONT_HIGH_RES_MODE, &light_level) < 0) {
            fprintf(stderr, "Warning: BH1750 read failed, using 0 lux\n");
            light_level = 0;
        }
        sound_level = spi_read_adc(spi_fd, MCP3008_CHANNEL);
        if (sound_level < 0) {
            fprintf(stderr, "Warning: MCP3008 read failed, using 0\n");
            sound_level = 0;
        }
        if (log_data(LOG_FILE, light_level, sound_level) < 0) {
            fprintf(stderr, "Warning: Failed to log data\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }
    close(i2c_fd);
    close(spi_fd);
    return 0;
}

