#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define LOG_FILE "temperature_log.txt"
#define SPI_SPEED_HZ 500000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define MCP4725_ADDR 0x48
#define DAC_MAX_VALUE 4095
#define VREF 3.3
#define ADC_MAX_VALUE 1023.0
#define TMP36_OFFSET_VOLTS 0.5
#define TMP36_SCALE_VOLTS_PER_C 0.001
#define SAMPLE_INTERVAL_SEC 0.5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MCP4725_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MCP4725_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int write_dac(int value) {
    if (value < 0 || value > DAC_MAX_VALUE) {
        fprintf(stderr, "Invalid DAC value: %d (must be 0-%d)\n", value, DAC_MAX_VALUE);
        return -1;
    }

    uint8_t buf[3];
    buf[0] = 0x40;
    buf[1] = (uint8_t)((value & 0xFF) >> 8);
    buf[2] = (uint8_t)((value & 0xFF) << 2);

    if (write(i2c_fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to DAC failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static float adc_to_celsius(int adc_value) {
    float voltage = (float)adc_value * VREF / ADC_MAX_VALUE;
    return voltage - (TMP36_OFFSET_VOLTS * 100.0);
}

static int log_data(int adc_value, float temperature, int dac_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, ADC: %d, Temperature: %.2f C, DAC: %d\n",
                timestamp, adc_value, temperature, dac_value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (i2c_init() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                usleep(100000);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries. Skipping sample.\n", MAX_RETRIES);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);
        int dac_value = (int)(temperature * 100.0);
        if (dac_value < 0) dac_value = 0;
        if (dac_value > DAC_MAX_VALUE) dac_value = DAC_MAX_VALUE;

        if (write_dac(dac_value) < 0) {
            fprintf(stderr, "Failed to write DAC value. Continuing.\n");
        }

        if (log_data(adc_value, temperature, dac_value) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        printf("ADC: %d, Temperature: %.2f C, DAC: %d\n", adc_value, temperature, dac_value);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Temperature monitoring stopped.\n");

    return 0;
}

