#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

#define NUM_RELAYS 4

#define ACTIVATE_DURATION_US 1000000  /* 1 second in microseconds */
#define DEACTIVATE_DELAY_US 1000000   /* 1 second between relays */

static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown (Ctrl+C, SIGTERM) */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Activate a relay (set pin HIGH) and wait for the specified duration.
   Returns 0 on success, -1 on error. */
static int activate_relay(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, 1) failed\n", pin);
        return -1;
    }
    gpioDelay(ACTIVATE_DURATION_US);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, 0) failed\n", pin);
        return -1;
    }
    return 0;
}

/* Deactivate all relays and release all GPIO lines. */
static void cleanup(void) {
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(pins[i], 0);
        gpioSetMode(pins[i], PI_INPUT);
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay pins as outputs and ensure they start inactive (LOW) */
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(pin=%d, PI_OUTPUT) failed\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioWrite(pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioWrite(pin=%d, 0) failed\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Light sequencer started. Press Ctrl+C to exit.\n");

    /* Main loop: activate each relay sequentially, wait, then repeat */
    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (!running) break;
            if (activate_relay(pins[i]) != 0) {
                fprintf(stderr, "Error activating relay %d (pin %d)\n", i + 1, pins[i]);
                cleanup();
                return EXIT_FAILURE;
            }
            if (i < NUM_RELAYS - 1) {
                gpioDelay(DEACTIVATE_DELAY_US);
            }
        }
    }

    /* Graceful shutdown: deactivate all relays and release resources */
    cleanup();
    printf("Light sequencer stopped.\n");
    return EXIT_SUCCESS;
}

