#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define RAIN_THRESHOLD 5
#define MOTOR_PIN 17
#define MOTOR_REVERSE_PIN 18
#define MOTOR_ENABLE_PIN 27
#define MOTOR_PWM_RANGE 255
#define MOTOR_PWM_DUTY 150
#define MOTOR_RUN_TIME 3
#define LOG_FILE "rain_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int control_motor(int direction) {
    if (gpioWrite(MOTOR_PIN, direction) < 0) {
        fprintf(stderr, "Error: Failed to set motor pin %d\n", MOTOR_PIN);
        return -1;
    }
    if (gpioWrite(MOTOR_REVERSE_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set reverse pin %d\n", MOTOR_REVERSE_PIN);
        return -1;
    }
    if (gpioPWM(MOTOR_ENABLE_PIN, MOTOR_PWM_DUTY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM on pin %d\n", MOTOR_ENABLE_PIN);
        return -1;
    }
    return 0;
}

static void stop_motor(void) {
    gpioPWM(MOTOR_ENABLE_PIN, 0);
    gpioWrite(MOTOR_PIN, 0);
    gpioWrite(MOTOR_REVERSE_PIN, 0);
}

static int log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    stop_motor();
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int rain_level;
    int motor_direction;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetMode(MOTOR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set motor pin %d as output\n", MOTOR_PIN);
        cleanup();
        return 1;
    }
    if (gpioSetMode(MOTOR_REVERSE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set reverse pin %d as output\n", MOTOR_REVERSE_PIN);
        cleanup();
        return 1;
    }
    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set enable pin %d as output\n", MOTOR_ENABLE_PIN);
        cleanup();
        return 1;
    }

