#define SAMPLE_RATE_HZ 100
#define SAMPLE_DELAY_US (1000000 / SAMPLE_RATE_HZ)
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define THRESHOLD 100
#define NUM_SAMPLES 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(ADC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set ADC pin %d as input.\n", ADC_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set LED pin %d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize LED pin %d to LOW.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_adc(void) {
    int sum = 0;
    for (int i = 0; i < NUM_SAMPLES; i++) {
        sum += gpioRead(ADC_PIN);
        gpioDelay(SAMPLE_DELAY_US);
    }
    return sum;
}

static bool detect_clap(int sum) {
    return sum > THRESHOLD;
}

static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Clap detected!\n", timestamp);
    fflush(stdout);
}

static void cleanup(void) {
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    uint32_t last_detection_time = 0;

    while (running) {
        int sum = read_adc();

        if (detect_clap(sum)) {
            uint32_t current_time = gpioTick();
            if (current_time - last_detection_time > DEBOUNCE_MS * 1000) {
                log_detection();
                gpioWrite(LED_PIN, 1);
                gpioDelay(LED_ON_MS * 1000);
                gpioWrite(LED_PIN, 0);
                last_detection_time = current_time;
            }
        }

        gpioDelay(10000);
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

