    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write pump GPIO\n");
        return -1;
    }
    return 0;
}

static void log_data(int moisture_level, int pump_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Moisture: %d%%, Pump: %s\n",
            timestamp, moisture_level, pump_state ? "ON" : "OFF");
