#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define MCP3008_CHANNEL 0
#define LOG_FILE        "magnetic_log.txt"
#define SAMPLE_PERIOD_US 500000

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    g_spi_fd = fd;
    return 0;
}

static int mcp3008_read(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 */
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_magnetic_field(int adc_value)
{
    /*
     * DRV5055-A1 transfer function (simplified):
     *   VOUT = VCC * (1 - (B_max / B_sat) * (B / B_max))
     *   B = (VOUT / VCC) * (1 - (B_max / B_sat) * (VOUT / VCC))
     *
     * With VCC = VREF = 3.3 V, B_max = 1.0 Gauss, B_sat = 1.5 Gauss:
     *   B = (adc / 1023.0) * (1 - (1.0 / 1.5) * (adc / 1023.0))
     */
    double vout = (double)adc_value / 1023.0;
    double b = vout * (1.0 - (1.0 / 1.5) * vout);
    return b * 1000.0;
}

static void log_data(FILE *fp, time_t timestamp, double magnetic_field)
{
    if (fp == NULL) {
        fprintf(stderr, "Log file not open\n");
        return;
    }
    fprintf(fp, "%ld,%.2f\n", (long)timestamp, magnetic_field);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(g_spi_fd);
        return 1;
    }

    printf("Starting DRV5055-A1 magnetic field logging...\n");
    printf("SPI: %s @ %d Hz, mode %d, channel %d\n",
           SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE, MCP3008_CHANNEL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc_value = mcp3008_read(g_spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
        } else {
            double magnetic_field = calculate_magnetic_field(adc_value);
            time_t now = time(NULL);
            log_data(g_log_fp, now, magnetic_field);
            printf("ADC: %4d  B: %7.2f nT\n", adc_value, magnetic_field);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            usleep(SAMPLE_PERIOD_US / 10);
        }
    }

    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    return 0;
}

