#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 2000
#define LOG_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a sensor with hardware debounce: read DEBOUNCE_READINGS times
 * with DEBOUNCE_DELAY_US between reads, and return the majority value.
 * Returns 0 (object present) or 1 (no object) on success, -1 on error.
 */
static int read_sensor_debounced(int gpio) {
    int count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int level = gpioRead(gpio);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d\n", gpio);
            return -1;
        }
        if (level == 0) count++;
        if (i < DEBOUNCE_READINGS - 1)
            gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (count > DEBOUNCE_READINGS / 2) ? 0 : 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * B5W-DB01 has an internal pull-up; disable pigpio pull-up/down
     * to avoid interfering with the sensor's open-collector output.
     */
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_OFF);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring B5W-DB01 sensors on GPIO %d and %d. Press Ctrl+C to exit.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);

    while (running) {
        int s1 = read_sensor_debounced(SENSOR_1_GPIO);
        int s2 = read_sensor_debounced(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: sensor read failure, exiting\n");
            break;
        }

        printf("Sensor 1: %s, Sensor 2: %s\n",
               s1 ? "object present" : "no object",
               s2 ? "object present" : "no object");

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        sleep(LOG_INTERVAL_S);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

