#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <pigpio.h>
#include <syslog.h>

#define PIR_GPIO 17
#define POLL_INTERVAL_US 50000
#define DEBOUNCE_DELAY_US 200000
#define CAPTURE_DIR "/home/pi/security_cam/"
#define CAPTURE_CMD "libcamera-still -o %s --timeout 1000 --nopreview"
#define LOG_FILE "/var/log/security_cam.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);
    return 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm;
        localtime_r(&t, &tm);
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm);
        fprintf(fp, "%s: %s\n", ts, msg);
        fclose(fp);
    } else {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
    }
}

static int capture_image(const char *filename) {
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork failed: %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        char command[512];
        snprintf(command, sizeof(command), CAPTURE_CMD, filename);
        execvp("sh", {"sh", "-c", command});
        _exit(127);
    }
    int status;
    if (waitpid(pid, &status, 0) < 0) {
        syslog(LOG_ERR, "waitpid failed: %s", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 0;
    }
    syslog(LOG_ERR, "libcamera-still failed (status=%d)", WEXITSTATUS(status));
    return -1;
}

int main(void) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (init_gpio() != 0) {
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Security camera started on GPIO%d", PIR_GPIO);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    while (running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead failed");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirm = gpioRead(PIR_GPIO);
            if (confirm < 0) {
                syslog(LOG_ERR, "gpioRead failed during debounce");
                continue;
            }
            if (confirm == current_state) {
                time_t rawtime = time(NULL);
                struct tm tm;
                localtime_r(&rawtime, &tm);
                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", &tm);
                char filename[256];
                snprintf(filename, sizeof(filename), "%smotion_%s.jpg", CAPTURE_DIR, timestamp);

                if (capture_image(filename) == 0) {
                    syslog(LOG_INFO, "Motion detected, image saved: %s", filename);
                } else {
                    syslog(LOG_ERR, "Failed to capture image");
                }
                last_state = current_state;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Security camera shutting down");
    gpioTerminate();
    closelog();
    return 0;
}

