static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_device(int *fd, struct v4l2_capability *cap, struct v4l2_format *fmt) {
    *fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd < 0) {
        perror("open");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(*fd);
        return -1;
    }

    if (!(cap->capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    if (!(cap->capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    memset(fmt, 0, sizeof(*fmt));
    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->fmt.pix.width = 640;
    fmt->fmt.pix.height = 480;
    fmt->fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(*fd);
        return -1;
    }

    if (fmt->fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device does not support MJPEG format\n");
        close(*fd);
        return -1;
    }

    if (xioctl(*fd, VIDIOC_STREAMOFF, &fmt->type) < 0) {
        perror("VIDIOC_STREAMOFF");
        close(*fd);
        return -1;
    }

    return 0;
}

static int init_mmap(int fd, struct v4l2_requestbuffers *req, struct v4l2_buffer *buf, unsigned char **frames, int *frame_count) {
    *frame_count = 0;
    memset(req, 0, sizeof(*req));
    memset(buf, 0, sizeof(*buf));

    if (xioctl(fd, VIDIOC_REQBUFS, req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req->count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    *frame_count = req->count;
    *frames = calloc(req->count, sizeof(unsigned char));
    if (*frames == NULL) {
        perror("calloc");
        return -1;
    }

    for (int i = 0; i < *frame_count; i++) {
        memset(&buf[i], 0, sizeof(buf[i]));
        buf[i].index = i;
        buf[i].length = BUFFER_SIZE;
    }

    if (xioctl(fd, VIDIOC_QBUF, buf) < 0) {
        perror("VIDIOC_QBUF");
        free(*frames);
        *frames = NULL;
        return -1;
    }

    if (xioctl(fd, VIDIOC_STREAMON, &req->type) < 0) {
        perror("VIDIOC_STREAMON");
        free(*frames);
        *frames = NULL;
        return -1;
    }

    return 0;
}

static void log_timestamp(FILE *fp, struct timespec ts) {
    fprintf(fp, "%ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);
    fflush(fp);
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *frames = NULL;
    int frame_count = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_device(&fd, &cap, &fmt) < 0) {
        return EXIT_FAILURE;
    }

    if (init_mmap(fd, &req, &buf, &frames, &frame_count) < 0) {
        goto cleanup;
    }

    FILE *fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        perror("fopen");
        goto cleanup;
    }

    printf("Capturing MJPEG frames from %s. Press Ctrl+C to stop.\n", DEVICE_NAME);

    while (running) {
        fd_set fds;
        struct timeval tv;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        int sel = select(fd + 1, &fds, NULL, NULL, &tv);

        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("select");
            break;
        }

        if (sel == 0) {
            continue;
        }

        ssize_t bytes_read = read(fd, frames[0], BUFFER_SIZE);
        if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("read");
            break;
        }

        if (bytes_read == 0) {
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        log_timestamp(fp, ts);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        xioctl(fd, VIDIOC_STREAMOFF, &req.type);
        close(fd);
    }
    if (frames != NULL) {
        free(frames);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    return ret;
}

