#define DEVICE_NAME "/dev/video0"
#define TARGET_IP "127.0.0.1"
#define TARGET_PORT 5000
#define MAX_PACKET_SIZE 65000
#define NUM_BUFFERS 4
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        perror("open");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(*fd);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        close(*fd);
        return -1;
    }

    if (buf.length < (size_t)(FRAME_WIDTH * FRAME_HEIGHT * 2)) {
        fprintf(stderr, "Buffer too small for YUYV\n");
        close(*fd);
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        close(*fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        close(*fd);
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, unsigned char **frame_data, size_t *frame_size) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *frame_data = (unsigned char *)mmap(NULL, buf.length, PROT_READ, MAP_SHARED, fd, buf.m.offset);
    if (MAP_FAILED == *frame_data) {
        perror("mmap");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    *frame_size = buf.length;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        munmap((void *)*frame_data, buf.length);
        return -1;
    }

    return 0;
}

static int fragment_and_send(int sock, int frame_index, unsigned char *frame, size_t frame_size, int total_frames, int total_fragments) {
    size_t packet_size = 0;
    unsigned char *packet = NULL;
    int retries = 0;

    while (packet_size < MAX_PACKET_SIZE && retries < 10) {
        packet_size += 16;
        packet = (unsigned char *)malloc(packet_size);
        if (!packet) {
            fprintf(stderr, "malloc failed\n");
            return -1;
        }

        int idx = frame_index * total_fragments + frame_index;
        int frag = frame_index;
        int plen = frame_size;

        memcpy(packet, &idx, 4);
        memcpy(packet + 4, &frag, 4);
        memcpy(packet + 8, &total_fragments, 4);
        memcpy(packet + 12, &plen, 4);
        memcpy(packet + 16, frame, frame_size);

        if (sendto(sock, packet, packet_size, 0, (struct sockaddr *)NULL, 0) < 0) {
            perror("sendto");
            free(packet);
            return -1;
        }

        free(packet);
        return 0;
    }

    fprintf(stderr, "Packet too large after retries\n");
    return -1;
}

int main(int argc, char *argv[]) {
    int fd = -1;
    int sock = -1;
    unsigned char *frame = NULL;
    size_t frame_size = 0;
    int frame_index = 0;
    int total_frames = 0;
    int total_fragments = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <open> <ioctl> <socket> <bind> <connect> <sendto>\n", argv[0]);
        return 1;
    }

    if (init_camera(&fd) < 0) return 1;

    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        xioctl(fd, VIDIOC_STREAMOFF, &VIDIOC_STREAM_OFF);
        close(fd);
        return 1;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(TARGET_PORT);
    if (inet_pton(AF_INET, TARGET_IP, &servaddr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sock);
        xioctl(fd, VIDIOC_STREAMOFF, &VIDIOC_STREAM_OFF);
        close(fd);
        return 1;
    }

    if (connect(sock, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("connect");
        close(sock);
        xioctl(fd, VIDIOC_STREAMOFF, &VIDIOC_STREAM_OFF);
        close(fd);
        return 1;
    }

    while (running) {
        if (capture_frame(fd, &frame, &frame_size) < 0) {
            fprintf(stderr, "Capture failed\n");
            break;
        }

        total_fragments = frame_size / (FRAME_WIDTH * FRAME_HEIGHT * 2);
        if (total_fragments == 0) total_fragments = 1;

        for (int i = 0; i < total_fragments; i++) {
            if (!running) break;
            if (fragment_and_send(sock, frame_index, frame, frame_size, total_frames, total_fragments) < 0) {
                fprintf(stderr, "Send failed\n");
                running = 0;
                break;
            }
            frame_index++;
        }

        total_frames++;
    }

    if (frame) munmap((void *)frame, frame_size);
    if (sock >= 0) close(sock);
    if (fd >= 0) xioctl(fd, VIDIOC_STREAMOFF, &VIDIOC_STREAM_OFF);
    if (fd >= 0) close(fd);

    return 0;
}

