#define PWM_PERIOD_US    (1000000 / PWM_FREQUENCY)
#define SERVO_MIN_US     1000
#define SERVO_MAX_US     2000
#define SERVO_MID_INDEX  75

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_servo_angle(int pin, int angle) {
    if (angle < 25) angle = 25;
    if (angle > 125) angle = 125;
    int pulse_width = SERVO_MIN_US + (angle * (SERVO_MAX_US - SERVO_MIN_US) / 100);
    if (gpioServo(pin, PWM_RANGE, pulse_width) < 0) {
        fprintf(stderr, "gpioServo failed on pin %d: %s\n", pin, pigpio_error(0));
        return -1;
    }
    return 0;
}

