    int current = gpioRead(button);
    if (current < 0) {
        fprintf(stderr, "gpioRead failed on button pin %d: %s\n", button, pigpio_error(current));
        return -1;
    }
    if (current == 0) {
        int current_angle = gpioRead(TILT_SERVO_PIN);
        if (current_angle < 0) {
            fprintf(stderr, "gpioRead failed on tilt servo pin %d: %s\n", TILT_SERVO_PIN, pigpio_error(current_angle));
            return -1;
        }
        int new_angle = current_angle + 5;
        if (set_servo_angle(TILT_SERVO_PIN, new_angle) != 0) return -1;
        printf("Tilt adjusted to %d\n", new_angle);
    }
    return 0;
}

static int adjust_pan(int button) {
    int current = gpioRead(button);
    if (current < 0) {
        fprintf(stderr, "gpioRead failed on button pin %d: %s\n", button, pigpio_error(current));
        return -1;
    }
    if (current == 0) {
        int current_angle = gpioRead(TILT_SERVO_PIN);
        if (current_angle < 0) {
            fprintf(stderr, "gpioRead failed on tilt servo pin %d: %s\n", TILT_SERVO_PIN, pigpio_error(current_angle));
            return -1;
        }
        int new_angle = current_angle - 5;
        if (set_servo_angle(TILT_SERVO_PIN, new_angle) != 0) return -1;
        printf("Pan adjusted to %d\n", new_angle);
    }
    return 0;
}

