        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on tilt servo pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_UP_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(PAN_LEFT_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(PAN_RIGHT_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TILT_UP_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(TILT_DOWN_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(PAN_LEFT_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(PAN_RIGHT_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioServo(PAN_SERVO_PIN, PWM_RANGE, SERVO_MID_INDEX * (SERVO_MAX_US - SERVO_MIN_US) / 100) < 0) {
        fprintf(stderr, "Initial pan servo setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioServo(TILT_SERVO_PIN, PWM_RANGE, SERVO_MID_INDEX * (SERVO_MAX_US - SERVO_MIN_US) / 100) < 0) {
        fprintf(stderr, "Initial tilt servo setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt mount control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (adjust_tilt(TILT_UP_BUTTON) != 0 ||
            adjust_tilt(TILT_DOWN_BUTTON) != 0 ||
            adjust_pan(PAN_LEFT_BUTTON) != 0 ||
            adjust_pan(PAN_RIGHT_BUTTON) != 0) {
            fprintf(stderr, "Button adjustment error encountered\n");
            break;
        }
        gpioDelay(50000);
    }

    gpioServo(PAN_SERVO_PIN, 0, 0);
    gpioServo(TILT_SERVO_PIN, 0, 0);
    gpioTerminate();
    printf("Pan-tilt mount control stopped.\n");
    return EXIT_SUCCESS;
}

