#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>

#define VIDEO_DEVICE "/dev/video0"
#define NUM_BUFFERS 4
#define CAPTURE_TIMEOUT_SEC 2
#define JPEG_QUALITY 75

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd_out) {
    int fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", VIDEO_DEVICE, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Warning: device did not accept YUYV format, using %s\n",
                fmt.fmt.pix.pixelformat);
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    size_t length = buf.length;
    void *start = buf.m.start;

    for (int i = 0; i < NUM_BUFFERS; i++) {
        buf.index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            close(fd);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static void convert_yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x += 2) {
            int y1 = y * width + x;
            int y2 = y1 + 1;
            int u = yuyv[y1 * 2 + 1];
            int v = yuyv[y1 * 2 + 2];
            int y0 = yuyv[y1 * 2];
            int y3 = y1 + width;

            int r = y0 + (1.370705 * (v - 128));
            int g = y0 - (0.344136 * (u - 128)) - (0.714136 * (v - 128));
            int b = y0 + (1.772025 * (u - 128));

            if (r < 0) r = 0; if (r > 255) r = 255;
            if (g < 0) g = 0; if (g > 255) g = 255;
            if (b < 0) b = 0; if (b > 255) b = 255;

            rgb[y1 * 3] = r;
            rgb[y1 * 3 + 1] = g;
            rgb[y1 * 3 + 2] = b;

            r = y3 + (1.370705 * (v - 128));
            g = y3 - (0.344136 * (u - 128)) - (0.714136 * (v - 128));
            b = y3 + (1.772025 * (u - 128));

            if (r < 0) r = 0; if (r > 255) r = 255;
            if (g < 0) g = 0; if (g > 255) g = 255;
            if (b < 0) b = 0; if (b > 255) b = 255;

            rgb[y3 * 3] = r;
            rgb[y3 * 3 + 1] = g;
            rgb[y3 * 3 + 2] = b;
        }
    }
}

static void apply_blur(unsigned char *rgb, int width, int height) {
    unsigned char new_rgb[width * height * 3];
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int sum_r = 0, sum_g = 0, sum_b = 0;
            for (int dy = -1; dy <= 1; dy++) {
                for (int dx = -1; dx <= 1; dx++) {
                    if (x + dx >= 0 && x + dx < width && y + dy >= 0 && y + dy < height) {
                        int offset = (y + dy) * width + (x + dx);
                        sum_r += rgb[offset * 3];
                        sum_g += rgb[offset * 3 + 1];
                        sum_b += rgb[offset * 3 + 2];
                    }
                }
            }
            int avg_r = sum_r / 9;
            int avg_g = sum_g / 9;
            int avg_b = sum_b / 9;
            new_rgb[y * width * 3 + x * 3] = avg_r;
            new_rgb[y * width * 3 + x * 3 + 1] = avg_g;
            new_rgb[y * width * 3 + x * 3 + 2] = avg_b;
        }
    }
    memcpy(rgb, new_rgb, width * height * 3);
}

static int encode_jpeg(const unsigned char *rgb, int width, int height, const char *filename, int quality) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_mem_dest(&cinfo, fp);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    int row_stride = width * 3;
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = -1;
    if (init_camera(&fd) < 0) {
        return 1;
    }

    unsigned char *rgb = NULL;
    unsigned char *yuyv = NULL;
    int width = 640, height = 480;
    int ret = 1;

    while (!g_stop) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        struct timeval tv;
        tv.tv_sec = CAPTURE_TIMEOUT_SEC;
        tv.tv_usec = 0;

        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            goto cleanup;
        }
        if (r == 0) {
            fprintf(stderr, "select() timeout\n");
            goto cleanup;
        }

        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            continue;
        }

        if (buf.bytesused < 4) {
            fprintf(stderr, "Buffer too small\n");
            continue;
        }

        if (buf.index >= NUM_BUFFERS) {
            fprintf(stderr, "Buffer index out of range\n");
            continue;
        }

        if (buf.index == 0) {
            size_t total = buf.length;
            if (total < buf.bytesused) {
                fprintf(stderr, "Buffer length mismatch\n");
                continue;
            }
            yuyv = malloc(total);
            if (!yuyv) {
                fprintf(stderr, "Memory allocation failed\n");
                continue;
            }
            memcpy(yuyv, buf.m.start, buf.bytesused);
        }

        if (buf.index > 0) {
            free(rgb);
            rgb = malloc(width * height * 3);
            if (!rgb) {
                fprintf(stderr, "Memory allocation failed\n");
                continue;
            }
        }

        convert_yuyv_to_rgb24(yuyv, rgb, width, height);
        apply_blur(rgb, width, height);

        time_t rawtime;
        time(&rawtime);
        struct tm *timeinfo = localtime(&rawtime);
        char filename[64];
        strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

        if (encode_jpeg(rgb, width, height, filename, JPEG_QUALITY) < 0) {
            fprintf(stderr, "JPEG encoding failed\n");
            continue;
        }

        printf("Saved %s\n", filename);

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            continue;
        }
    }

    ret = 0;

cleanup:
    if (yuyv) free(yuyv);
    if (rgb) free(rgb);
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }
    return ret;
}

