static int enumerate_frame_sizes(int fd, int *count, struct v4l2_frmsizeenum *enums)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    struct v4l2_frmsizeenum enum_info;
    int ret;

    enums = calloc(1, sizeof(*enums));
    if (!enums) {
        fprintf(stderr, "Failed to allocate memory for frame sizes: %s\n", strerror(errno));
        return -1;
