    enum_info.index = 0;

    ret = xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &enum_info);
    if (ret == -1) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n", strerror(errno));
        free(enums);
        return -1;
    }
    if (ret == 0) {
        fprintf(stderr, "No frame sizes available on %s\n", DEVICE_NAME);
        free(enums);
        return -1;
    }

    *count = ret;
    enums->count = ret;
    enums->frame_size = calloc(ret, sizeof(*enums->frame_size));
    if (!enums->frame_size) {
        fprintf(stderr, "Failed to allocate memory for frame sizes: %s\n", strerror(errno));
        free(enums);
        return -1;
    }

    for (int i = 0; i < ret; i++) {
        enums->frame_size[i].width = enum_info.pixel_format;
        enums->frame_size[i].height = enum_info.pixel_format;
        enums->frame_size[i].pixel_format = enum_info.pixel_format;
        enums->frame_size[i].size_index = i;
        enums->frame_size[i].type = V4L2_FRAME_TYPE_CONTINUOUS;
        enums->frame_size[i].field = V4L2_FIELD_NONE;
    }

    return 0;
}

static int enumerate_frame_intervals(int fd, int count,
                                     struct v4l2_frmsizeenum *enums)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    struct v4l2_frmivalenum enum_info;
