{
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum *enums = NULL;
    struct v4l2_frmivalenum *enums_i = NULL;
    int count = 0;
    int focus_supported = 0;
    int focus_ret = 0;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    print_capability(&cap);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s does not support video capture\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (enumerate_frame_sizes(fd, &count, &enums) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (enumerate_frame_rates(fd, count, &enums_i) == -1) {
        free(enums);
        close(fd);
        return EXIT_FAILURE;
    }

    print_resolutions(enums, count);
    print_frame_rates(enums_i, count);

    focus_ret = xioctl(fd, VIDIOC_QUERYCTRL, &focus_supported);
    if (focus_ret == -1) {
        fprintf(stderr, "VIDIOC_QUERYCTRL failed: %s\n", strerror(errno));
        free(enums);
        free(enums_i);
        close(fd);
        return EXIT_FAILURE;
    }

    focus_supported &= V4L2_CID_FOCUS_AUTO;

    if (focus_supported) {
        focus_auto_supported = 1;
        printf("Autofocus:\n");
        print_autofocus(1);
    } else {
        printf("Autofocus:\n");
        print_autofocus(0);
    }

    free(enums);
    free(enums_i);
    close(fd);

    return EXIT_SUCCESS;
}

