#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define IMAGE_QUALITY 85
#define CAPTURE_DIR "motion_captures"
#define HTTP_ENDPOINT_ARG_COUNT 2
#define HTTP_ENDPOINT_ARG_DESC "HTTP endpoint IP:port"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int create_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) {
            return 0;
        }
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        fprintf(stderr, "Error creating directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "raspistill -o %s -q %d -t 1 2>/dev/null",
             filename, IMAGE_QUALITY);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspistill: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspistill exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

static int upload_image(const char *filename, const char *endpoint) {
    char command[1024];
    snprintf(command, sizeof(command),
             "curl -F 'image=@%s' -F 'filename=%s' -F 'timestamp=%ld' -F 'motion_detected=true' -F 'gpio_pin=%d' %s",
             filename, filename, (long)time(NULL), PIR_GPIO, endpoint);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing curl: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "curl exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != HTTP_ENDPOINT_ARG_COUNT + 1) {
        fprintf(stderr, "Usage: %s <IP> <port> <image_path>\n", argv[0]);
        fprintf(stderr, "  IP: IP address of the HTTP server\n");
        fprintf(stderr, "  port: port number of the HTTP server\n");
        fprintf(stderr, "  image_path: path to the image file (optional, will use current capture)\n");
        return EXIT_FAILURE;
    }

    const char *ip_address = argv[1];
    int port = atoi(argv[2]);
    const char *image_path = (argc >= 3) ? argv[3] : NULL;

    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Invalid port number: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (create_directory(CAPTURE_DIR) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring PIR sensor on GPIO %d. Press Ctrl+C to exit.\n", PIR_GPIO);

    time_t last_motion_time = 0;

    while (g_running) {
        int motion_detected = gpioRead(PIR_GPIO);
        if (motion_detected < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", PIR_GPIO);
            break;
        }

        if (motion_detected) {
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) >= DEBOUNCE_SEC) {
                printf("Motion detected on GPIO %d\n", PIR_GPIO);

                if (image_path != NULL) {
                    if (capture_image(image_path) == 0) {
                        char filename[256];
                        snprintf(filename, sizeof(filename), "%s/%s", CAPTURE_DIR, image_path);
                        if (upload_image(filename, ip_address, port) == 0) {
                            printf("Image uploaded successfully.\n");
                        } else {
                            fprintf(stderr, "Failed to upload image.\n");
                        }
                    } else {
                        fprintf(stderr, "Failed to capture image.\n");
                    }
                } else {
                    char filename[256];
                    snprintf(filename, sizeof(filename), "%s/capture_%ld.jpg", CAPTURE_DIR, (long)time(NULL));
                    if (capture_image(filename) == 0) {
                        if (upload_image(filename, ip_address, port) == 0) {
                            printf("Image captured and uploaded.\n");
                        } else {
                            fprintf(stderr, "Failed to upload image.\n");
                        }
                    } else {
                        fprintf(stderr, "Failed to capture image.\n");
                    }
                }

                last_motion_time = now;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

