#define IMAGES_DIR "/home/pi/images"
#define CAPTURE_CMD "raspistill -o %s -w 640 -h 480 -q 85 -t 2000 -n"
#define TIMESTAMP_LEN 32
#define FILENAME_LEN 128

static volatile sig_atomic_t running = 1;
static int pigpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[TIMESTAMP_LEN];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "[%s] %s\n", timestamp, message);
    } else {
        fprintf(fp, "[unknown] %s\n", message);
    }
    fsync(fileno(fp));
    fclose(fp);
}

static void generate_filename(char *filename, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, len, "%Y%m%d_%H%M%S", timeinfo);
    char ext[8];
    strftime(ext, sizeof(ext), "%03d", timeinfo);
    snprintf(filename + strlen(filename), len - strlen(filename), ".%s.jpg", ext);
}

static int capture_image(const char *filename) {
    char command[FILENAME_LEN + 64];
    snprintf(command, sizeof(command), CAPTURE_CMD, IMAGES_DIR, filename);
    int status = system(command);
    if (status == -1) {
        log_message("Error: system() failed to execute capture command.");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        char msg[FILENAME_LEN + 128];
        snprintf(msg, sizeof(msg), "Error: raspistill exited with status %d.", WEXITSTATUS(status));
        log_message(msg);
        return -1;
    }
    if (WIFSIGNALED(status)) {
        char msg[FILENAME_LEN + 128];
        snprintf(msg, sizeof(msg), "Error: raspistill killed by signal %d.", WTERMSIG(status));
        log_message(msg);
        return -1;
    }
    return 0;
}

static void motion_detected(void) {
    char filename[FILENAME_LEN];
    generate_filename(filename, sizeof(filename));
    char log_msg[FILENAME_LEN + 128];
    snprintf(log_msg, sizeof(log_msg), "Motion detected! Capturing image: %s", filename);
    log_message(log_msg);
    if (capture_image(filename) != 0) {
        log_message("Error: Failed to capture image.");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", PIR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d\n", PIR_GPIO);
    }

    if (gpioSetAlertFunc(PIR_GPIO, motion_detected) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO%d\n", PIR_GPIO);
        gpioTerminate();
        return 1;
    }

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);
    log_message("Motion detection started.");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFunc(PIR_GPIO, NULL);
    gpioTerminate();
    log_message("Motion detection stopped.");
    return 0;
}

