#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define NUM_BUFFERS 1
#define CROP_X 120
#define CROP_Y 60

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    void *buffer_start = NULL;
    size_t buffer_length = 0;
    FILE *fp = NULL;
    unsigned char *yuyv_data = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV format\n");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    buffer_length = buf.length;
    buffer_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        perror("mmap");
        buffer_start = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    printf("Capturing %dx%d YUYV frame...\n", WIDTH, HEIGHT);

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "select interrupted by signal\n");
            goto cleanup;
        }
        perror("select");
        goto cleanup;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }

    if (buf.bytesused < (WIDTH * HEIGHT * 2) / 2) {
        fprintf(stderr, "Frame too small: %u bytes\n", buf.bytesused);
        goto cleanup;
    }

    if (buf.index != 0) {
        fprintf(stderr, "Unexpected buffer index %u\n", buf.index);
        goto cleanup;
    }

    if (buf.bytesused != (WIDTH * HEIGHT * 2) / 2) {
        fprintf(stderr, "Frame size mismatch: %u bytes, expected %u\n", buf.bytesused, (WIDTH * HEIGHT * 2) / 2);
        goto cleanup;
    }

    if (buf.format != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Pixel format mismatch: %u, expected YUYV\n", buf.format);
        goto cleanup;
    }

    if (buf.width != WIDTH || buf.height != HEIGHT) {
        fprintf(stderr, "Crop dimensions mismatch: %ux%u, expected %ux%u\n", buf.width, buf.height, WIDTH, HEIGHT);
        goto cleanup;
    }

    yuyv_data = malloc((size_t)buf.bytesused);
    if (!yuyv_data) {
        perror("malloc");
        goto cleanup;
    }

    memcpy(yuyv_data, buffer_start, buf.bytesused);

    unsigned char *dst = malloc((size_t)(CROP_WIDTH * CROP_HEIGHT * 2));
    if (!dst) {
        perror("malloc");
        goto cleanup;
    }

    for (int y = 0; y < CROP_HEIGHT; y++) {
        for (int x = 0; x < CROP_WIDTH; x++) {
            int src_y = y + CROP_Y;
            int src_x = x + CROP_X;
            int src_idx = (src_y * WIDTH + src_x) * 2;
            int dst_idx = (y * CROP_WIDTH + x) * 2;
            dst[dst_idx] = yuyv_data[src_idx];
            dst[dst_idx + 1] = yuyv_data[src_idx + 1];
        }
    }

    fp = fopen("cropped.yuv", "wb");
    if (!fp) {
        perror("fopen");
        goto cleanup;
    }

    size_t written = fwrite(dst, 1, (size_t)(CROP_WIDTH * CROP_HEIGHT * 2), fp);
    if (written != (size_t)(CROP_WIDTH * CROP_HEIGHT * 2)) {
        fprintf(stderr, "Short write: %zu of %d\n", written, (size_t)(CROP_WIDTH * CROP_HEIGHT * 2));
        goto cleanup;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        goto cleanup;
    }
    fp = NULL;

    printf("Cropped frame written to cropped.yuv\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (buffer_start && buffer_start != MAP_FAILED) {
        if (munmap(buffer_start, buffer_length) == -1) {
            perror("munmap");
        }
    }
    if (fd >= 0) {
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
        if (close(fd) == -1) {
            perror("close");
        }
    }
    if (yuyv_data) {
        free(yuyv_data);
    }
    if (dst) {
        free(dst);
    }
    return ret;
}

