#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define PWM_FREQUENCY 50
#define NEUTRAL_ANGLE 90
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define STEP_SIZE 5
#define DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    return (int)(5000000 / 1000000 * (angle - 90) + 5000000) / 2;
}

static int set_servo_angle(int pin, int angle) {
    int pw = angle_to_pulse_width(angle);
    if (pw < 0) return -1;
    if (gpioServo(pin, PWM_FREQUENCY, pw) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, PWM_FREQUENCY, 500000);
    gpioServo(TILT_SERVO_PIN, PWM_FREQUENCY, 500000);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    printf("Servo control started. Press 'q' to quit.\n");

    while (running) {
        int c = getchar();
        if (c == 'q') break;
        if (c == EOF) {
            fprintf(stderr, "Error: stdin read failed: %s\n", strerror(errno));
            break;
        }

        switch (c) {
            case 'a':
                pan_angle -= STEP_SIZE;
                break;
            case 'd':
                pan_angle += STEP_SIZE;
                break;
            case 'w':
                tilt_angle -= STEP_SIZE;
                break;
            case 's':
                tilt_angle += STEP_SIZE;
                break;
            case 'Q':
                pan_angle -= STEP_SIZE;
                break;
            case 'S':
                pan_angle += STEP_SIZE;
                break;
            case 'W':
                tilt_angle -= STEP_SIZE;
                break;
            case 'E':
                tilt_angle += STEP_SIZE;
                break;
            case ' ':
                break;
            default:
                fprintf(stderr, "Warning: unknown key '%c'\n", c);
                continue;
        }

        if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) {
            fprintf(stderr, "Error: failed to set pan servo angle\n");
        }
        if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
            fprintf(stderr, "Error: failed to set tilt servo angle\n");
        }

        gpioDelay(DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

