#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define LCD_ENABLE 0x04
#define LCD_RS 0x01
#define LCD_I2C_NO_CS 0
#define PULSE_THRESHOLD 100.0
#define SAMPLE_INTERVAL_SEC 1
#define UPDATE_INTERVAL_SEC 10

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

static int lcd_strobe(uint8_t data) {
    uint8_t reg = data | LCD_ENABLE | LCD_I2C_NO_CS;
    if (i2cWriteByte(i2c_handle, reg) < 0) return -1;
    gpioDelay(1);
    if (i2cWriteByte(i2c_handle, data & ~LCD_ENABLE) < 0) return -1;
    gpioDelay(1);
    return 0;
}

static int lcd_byte(uint8_t bits, uint8_t mode) {
    uint8_t high = (bits & 0xF0) | LCD_BACKLIGHT | mode;
    uint8_t low = ((bits << 4) & 0xF0) | LCD_BACKLIGHT | mode;
    if (lcd_strobe(high) < 0) return -1;
    if (lcd_strobe(low) < 0) return -1;
    return 0;
}

static int lcd_init(void) {
    gpioDelay(50000);
    if (lcd_byte(0x33, LCD_CMD) < 0) return -1;
    if (lcd_byte(0x32, LCD_CMD) < 0) return -1;
    if (lcd_byte(0x28, LCD_CMD) < 0) return -1;
    if (lcd_byte(0x0C, LCD_CMD) < 0) return -1;
    if (lcd_byte(0x06, LCD_CMD) < 0) return -1;
    if (lcd_byte(0x01, LCD_CMD) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_clear(void) {
    if (lcd_byte(0x01, LCD_CMD) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_set_cursor(uint8_t col, uint8_t row) {
    uint8_t addr = (row == 0) ? (LCD_LINE_1 + col) : (LCD_LINE_2 + col);
    if (lcd_byte(addr, LCD_CMD) < 0) return -1;
    return 0;
}

static int lcd_print(const char *text) {
    while (*text) {
        if (lcd_byte((uint8_t)*text++, LCD_CHR) < 0) return -1;
    }
    return 0;
}

static void log_data(float flow_rate, float total_volume) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Flow Rate: %.2f L/min, Total Volume: %.2f L\n",
           timestamp, flow_rate, total_volume);
    fflush(stdout);
}

static void update_lcd(float flow_rate, float total_volume) {
    char line1[LCD_WIDTH + 1];
    char line2[LCD_WIDTH + 1];

    snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow_rate);
    snprintf(line2, sizeof(line2), "Vol: %.2f L", total_volume);

    if (lcd_clear() < 0) {
        fprintf(stderr, "LCD clear failed\n");
        return;
    }
    if (lcd_set_cursor(0, 0) < 0) {
        fprintf(stderr, "LCD set cursor failed\n");
        return;
    }
    if (lcd_print(line1) < 0) {
        fprintf(stderr, "LCD print line1 failed\n");
        return;
    }
    if (lcd_set_cursor(0, 1) < 0) {
        fprintf(stderr, "LCD set cursor failed\n");
        return;
    }
    if (lcd_print(line2) < 0) {
        fprintf(stderr, "LCD print line2 failed\n");
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, LCD_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init() < 0) {
        fprintf(stderr, "Failed to initialize LCD\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    float total_volume = 0.0;
    float last_flow_rate = 0.0;
    int pulse_count = 0;
    uint32_t last_tick = gpioTick();
    bool first_sample = true;

    while (running) {
        uint32_t now = gpioTick();
        uint32_t elapsed = now - last_tick;
        last_tick = now;

        int pulses = gpioRead(FLOW_SENSOR_GPIO);
        if (pulses < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", FLOW_SENSOR_GPIO);
            break;
        }

        pulse_count += pulses;

        if (first_sample) {
            last_flow_rate = 0.0;
            first_sample = false;
        }

        float flow_rate = (float)(pulse_count - last_pulse_count) / (elapsed / 1000000.0);
        last_pulse_count = pulse_count;

        if (flow_rate > PULSE_THRESHOLD) {
            total_volume += flow_rate * (elapsed / 1000000.0);
        }

        if (elapsed >= (SAMPLE_INTERVAL_SEC * 1000000)) {
            log_data(flow_rate, total_volume);
            update_lcd(flow_rate, total_volume);
            total_volume = 0.0;
            last_flow_rate = 0.0;
            pulse_count = 0;
            first_sample = true;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

