    if (lcd_send_byte(fd, 0x28, true) < 0) return -1;
    if (lcd_send_byte(fd, 0x0C, true) < 0) return -1;
    if (lcd_send_byte(fd, 0x06, true) < 0) return -1;
    if (lcd_send_byte(fd, 0x01, true) < 0) return -1;
