#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LCD_ADDR 0x27
#define GPIO_PIN 17
#define MEASUREMENT_INTERVAL_SEC 1
#define MAX_PULSES 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pulse_count = 0;
static int last_pulse_tick = 0;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void lcd_write_nibble(int fd, unsigned char nibble, int rs) {
    unsigned char data[2];
    data[0] = nibble | 0x0C;
    data[1] = nibble | (rs ? 0x08 : 0x00);
    if (write(fd, data, 2) != 2) {
        perror("I2C write failed");
    }
}

void lcd_send_byte(int fd, unsigned char val, int rs) {
    lcd_write_nibble(fd, val & 0xF0, rs);
    lcd_write_nibble(fd, (val << 4) & 0xF0, rs);
}

void lcd_command(int fd, unsigned char cmd) {
    lcd_send_byte(fd, cmd, 0);
}

void lcd_data(int fd, unsigned char data) {
    lcd_send_byte(fd, data, 1);
}

void lcd_string(int fd, const char *str) {
    while (*str) {
        lcd_data(fd, (unsigned char)*str++);
    }
}

void lcd_clear(int fd) {
    lcd_command(fd, 0x01);
    usleep(2000);
}

void lcd_init(int fd) {
    usleep(50000);
    lcd_send_byte(fd, 0x33, 0);
    lcd_send_byte(fd, 0x32, 0);
    lcd_send_byte(fd, 0x28, 0);
    lcd_send_byte(fd, 0x0C, 0);
    lcd_send_byte(fd, 0x06, 0);
    lcd_send_byte(fd, 0x01, 0);
    usleep(2000);
}

void lcd_set_cursor(int fd, int row, int col) {
    int addr = (row == 0) ? 0x80 : 0xC0;
    lcd_command(fd, addr + col);
}

void lcd_print_float(int fd, float val) {
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%.2f", val);
    lcd_set_cursor(fd, 1, 0);
    for (int i = 0; i < len; i++) {
        lcd_data(fd, (unsigned char)buf[i]);
    }
}

void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pulse_count++;
        last_pulse_tick = tick;
    }
}

float calculate_flow_rate(int pulses, int interval_sec) {
    if (interval_sec <= 0) return 0.0f;
    return ((float)pulses / (float)interval_sec) * 60.0f;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_fd = open("/dev/i2c-%d", I2C_BUS);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    lcd_init(i2c_fd);
    lcd_clear(i2c_fd);
    lcd_string(i2c_fd, "Flow Rate:");

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(GPIO_PIN, pulse_callback) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Water flow measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        int pulses = pulse_count;
        pulse_count = 0;

        if (last_pulse_tick > 0) {
            int diff = (int)(clock() - last_pulse_tick);
            if (diff < 0) diff += MAX_PULSES;
            if (diff > 1000000) {
                fprintf(stderr, "Warning: No pulses detected for extended period\n");
            }
        }

        float flow_rate = calculate_flow_rate(pulses, MEASUREMENT_INTERVAL_SEC);

        lcd_set_cursor(i2c_fd, 0, 0);
        lcd_string(i2c_fd, "Flow Rate:");
        lcd_set_cursor(i2c_fd, 1, 0);
        lcd_print_float(i2c_fd, flow_rate);

        sleep(MEASUREMENT_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    lcd_clear(i2c_fd);
    lcd_string(i2c_fd, "Shutting down...");
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

