#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define NUM_ROWS 8
#define SCAN_DELAY_US 800

static const int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[NUM_ROWS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set row pin %d as output.\n", row_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetMode(col_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set col pin %d as output.\n", col_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpioWrite(row_pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialize row pin %d LOW.\n", row_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(col_pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize col pin %d HIGH.\n", col_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(row_pins[i], 1);
        gpioWrite(col_pins[i], 0);
    }
}

static void display_row(int row_index, int state) {
    if (row_index < 0 || row_index >= NUM_ROWS) return;
    if (state) {
        gpioWrite(row_pins[row_index], 0);
        gpioWrite(col_pins[row_index], 1);
    } else {
        gpioWrite(row_pins[row_index], 1);
        gpioWrite(col_pins[row_index], 0);
    }
}

static void wave_left(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        int row_index = i;
        int col_index = (i + (NUM_ROWS / 2)) % NUM_ROWS;
        display_row(row_index, (row_index < col_index) ? 1 : 0);
    }
}

static void wave_right(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        int row_index = i;
        int col_index = (NUM_ROWS - 1 - i) % NUM_ROWS;
        display_row(row_index, (row_index > col_index) ? 1 : 0);
    }
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(row_pins[i], 0);
        gpioWrite(col_pins[i], 1);
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        clear_matrix();
        wave_left();
        usleep(SCAN_DELAY_US);
        if (!running) break;
        clear_matrix();
        wave_right();
        usleep(SCAN_DELAY_US);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

