/* Write a 16-bit register address followed by a 16-bit value (big-endian) */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value) {
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    if (write(fd, buf, 4) != 4) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address followed by a 16-bit value (big-endian) */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value) {
    uint8_t addr_buf[2];
    uint8_t data_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (write(fd, addr_buf, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data_buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)data_buf[0] << 8) | data_buf[1];
    return 0;
}

