#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75031_ADDR 0x33
#define LOG_FILE "depth_log.csv"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t reg_buf[1] = {reg};
    if (write(fd, reg_buf, 1) != 1) {
        perror("i2c_read_reg16: write reg failed");
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("i2c_read_reg16: read data failed");
        return -1;
    }
    *out = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    return 0;
}

static int init_mlx75031(int fd) {
    /*
     * Placeholder initialization sequence.
     * Replace with actual MLX75031 initialization sequence from datasheet.
     */
    if (i2c_write_reg8(fd, 0x00, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x01, 0x02) < 0) return -1;
    if (i2c_write_reg8(fd, 0x02, 0x03) < 0) return -1;
    return 0;
}

static int read_distance(int fd, uint16_t *distance) {
    return i2c_read_reg16(fd, 0x04, distance);
}

static void log_data(FILE *fp, uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance);
    fflush(fp);
}

static void cleanup(void) {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_mlx75031(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MLX75031 sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,Distance\n");
        fflush(log_fp);
    }

    printf("Logging depth data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        uint16_t distance = 0;
        if (read_distance(i2c_fd, &distance) < 0) {
            fprintf(stderr, "I2C read error. Attempting to re-initialize...\n");
            close(i2c_fd);
            i2c_fd = -1;
            usleep(100000);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("reopen I2C bus");
                break;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
                perror("reopen I2C_SLAVE");
                break;
            }
            if (init_mlx75031(i2c_fd) < 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }
            continue;
        }

        log_data(log_fp, distance);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

