#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_US 500000

/* Si1145 register addresses */
#define REG_PART_ID       0x00
#define REG_REV_ID        0x01
#define REG_SEQ_ID        0x02
#define REG_INT_CFG       0x03
#define REG_IRQ_ENABLE    0x04
#define REG_IRQ_MODE1     0x05
#define REG_IRQ_MODE2     0x06
#define REG_HW_KEY        0x07
#define REG_MEAS_RATE0    0x08
#define REG_MEAS_RATE1    0x09
#define REG_PS_LED21      0x0F
#define REG_PARAM_WR      0x17
#define REG_COMMAND       0x18
#define REG_RESPONSE      0x20
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0     0x26
#define REG_PS1_DATA1     0x27

#define CMD_RESET         0x01
#define CMD_PS_FORCE      0x05
#define CMD_ALS_FORCE     0x06
#define CMD_PSALS_FORCE   0x07
#define CMD_PARAM_QUERY   0x80
#define CMD_PARAM_SET     0xA0
#define CMD_NOP           0x00

#define HW_KEY_VAL        0x17

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int si1145_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int si1145_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int si1145_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, len=%u): %s\n",
                reg, len, pigpio_error(rc));
    }
    return rc;
}

static int si1145_init(int handle) {
    int part_id = si1145_read_reg(handle, REG_PART_ID);
    if (part_id < 0) return -1;
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    if (si1145_write_reg(handle, REG_COMMAND, CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (si1145_write_reg(handle, REG_HW_KEY, HW_KEY_VAL) < 0) return -1;

    if (si1145_write_reg(handle, REG_MEAS_RATE0, 0x08) < 0) return -1;
    if (si1145_write_reg(handle, REG_MEAS_RATE1, 0x00) < 0) return -1;

    if (si1145_write_reg(handle, REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (si1145_write_reg(handle, REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (si1145_write_reg(handle, REG_IRQ_MODE2, 0x00) < 0) return -1;

    if (si1145_write_reg(handle, REG_PS_LED21, 0x0F) < 0) return -1;

    return 0;
}

static int si1145_param_set(int handle, uint8_t param, uint8_t value) {
    if (si1145_write_reg(handle, REG_PARAM_WR, value) < 0) return -1;
    if (si1145_write_reg(handle, REG_COMMAND, CMD_PARAM_SET | (param & 0x1F)) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int si1145_param_query(int handle, uint8_t param, uint8_t *value) {
    if (si1145_write_reg(handle, REG_COMMAND, CMD_PARAM_QUERY | (param & 0x1F)) < 0) return -1;
    gpioDelay(10000);
    int rc = si1145_read_reg(handle, REG_RESPONSE);
    if (rc < 0) return -1;
    *value = (uint8_t)rc;
    return 0;
}

static int si1145_force_measurement(int handle) {
    if (si1145_write_reg(handle, REG_COMMAND, CMD_PSALS_FORCE) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient) {
    uint8_t buf[4];

    if (si1145_force_measurement(handle) < 0) return -1;

    if (si1145_read_block(handle, REG_ALS_VIS_DATA0, buf, 4) < 0) return -1;

    *ambient = (uint16_t)((buf[1] << 8) | buf[0]);
    *proximity = (uint16_t)((buf[3] << 8) | buf[2]);
    return 0;
}

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Proximity: %u, Ambient: %u\n", timestamp, proximity, ambient);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (si1145_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Si1145 logging started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t proximity = 0, ambient = 0;

        if (read_sensor_data(g_i2c_handle, &proximity, &ambient) == 0) {
            log_data(g_log_file, proximity, ambient);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");

    if (g_i2c_handle >= 0) {
        si1145_write_reg(g_i2c_handle, REG_COMMAND, CMD_RESET);
        i2cClose(g_i2c_handle);
    }

    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
    }

    gpioTerminate();
    return 0;
}

