#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "proximity.log"
#define POLL_INTERVAL_US 100000
#define LED_BLINK_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "Error converting time to UTC\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int chip = gpioGetChip();
    if (chip < 0) {
        fprintf(stderr, "Failed to get GPIO chip: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize LED state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = 1;
    int first_read = 1;

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor pin\n");
            break;
        }

        if (first_read) {
            last_state = sensor_value;
            first_read = 0;
        }

        if (sensor_value == 0 && last_state == 1) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error turning on LED\n");
                break;
            }
            gpioDelay(LED_BLINK_US);
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error turning off LED\n");
                break;
            }

            if (log_event("Object detected") != 0) {
                fprintf(stderr, "Error logging event\n");
            }
        }

        last_state = sensor_value;
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

