#define PARAM_PS_ADC_MISC252 0xFF

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_param(int handle, uint8_t param, uint8_t value) {
    if (i2cWriteByteData(handle, REG_PARAM_WR, value) < 0) return -1;
    if (i2cWriteByteData(handle, REG_COMMAND, CMD_PARAM_SET | (param & 0x1F)) < 0) return -1;
    return 0;
}

static int init_si1145(int handle) {
    int part_id;

    part_id = i2cReadByteData(handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    if (i2cWriteByteData(handle, REG_HW_KEY, 0x17) < 0) return -1;
    if (i2cWriteByteData(handle, REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, REG_IRQ_MODE2, 0x00) < 0) return -1;

    if (write_param(handle, PARAM_CHLIST, 0x03) < 0) return -1;
    if (write_param(handle, PARAM_PSLED12_SELECT, 0x03) < 0) return -1;
    if (write_param(handle, PARAM_PS_ADC_GAIN, 0x00) < 0) return -1;

    if (i2cWriteByteData(handle, REG_COMMAND, CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int read_proximity(int handle) {
    int prox;
    prox = i2cReadByteData(handle, REG_PS1_DATA0);
    if (prox < 0) {
        fprintf(stderr, "Error reading PS1_DATA0: %d\n", prox);
        return -1;
    }
    return prox;
}

static int read_ambient_light(int handle) {
    int als;
    als = i2cReadByteData(handle, REG_ALS_VIS_DATA0);
    if (als < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA0: %d\n", als);
        return -1;
    }
    return als;
}

static void log_data(FILE *fp, int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int proximity, ambient_light;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, 0x45, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting data acquisition...\n");

    while (running) {
        proximity = read_proximity(i2c_handle);
        ambient_light = read_ambient_light(i2c_handle);

        if (proximity >= 0 && ambient_light >= 0) {
            log_data(log_file, proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

