#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define WATER_THRESHOLD_CM 15.0
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_SEC 60
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define ECHO_WAIT_US 30000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN\n");
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN low\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void) {
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start;

    trigger_sensor();

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo start (sensor absent?)\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo end (object out of range?)\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    double pulse_us = (double)(end_tick - start_tick);
    double distance_cm = (pulse_us * SPEED_OF_SOUND) / 2000000.0;
    return distance_cm;
}

static void log_distance(double distance) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (distance < 0) {
        fprintf(log_file, "%s, Error: measurement failed\n", timestamp);
    } else if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(log_file, "%s, Error: distance out of range (%.2f cm)\n", timestamp, distance);
    } else {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
        if (distance < WATER_THRESHOLD_CM) {
            fprintf(log_file, "%s, Time to water the plant!\n", timestamp);
        }
    }
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();
        log_distance(distance);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

