#define I2C_BUS "/dev/i2c-1"
#define APDS9960_I2C_ADDR 0x39

#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_PDATA 0x96
#define APDS9960_PSTATUS 0x97

#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[1] << 8 | buf[0];
    return 0;
}

int apds9960_init(int fd) {
    if (i2c_write_reg8(fd, APDS9960_ENABLE, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, APDS9960_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, APDS9960_WTIME, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, APDS9960_PPULSE, 0x20) < 0) return -1;
    if (i2c_write_reg8(fd, APDS9960_CONTROL, 0x03) < 0) return -1;
    if (i2c_write_reg8(fd, APDS9960_ENABLE, 0x01) < 0) return -1;
    return 0;
}

int read_apds9960(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *prox) {
    uint8_t status;
    if (i2c_read_reg8(fd, APDS9960_PSTATUS, &status) < 0) return -1;
    if ((status & 0x03) != 0x03) return 1;
    if (i2c_read_reg16(fd, APDS9960_CDATAL, r) < 0) return -1;
    if (i2c_read_reg16(fd, APDS9960_CDATAH, g) < 0) return -1;
    if (i2c_read_reg16(fd, APDS9960_PDATA, b) < 0) return -1;
    if (i2c_read_reg16(fd, APDS9960_PDATA, prox) < 0) return -1;
    return 0;
}

void log_data(uint16_t r, uint16_t g, uint16_t b, uint16_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, r, g, b, prox);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, APDS9960_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (apds9960_init(i2c_fd) < 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        uint16_t r, g, b, prox;
        int ret = read_apds9960(i2c_fd, &r, &g, &b, &prox);
        if (ret == 0) {
            if (prox > PROXIMITY_THRESHOLD) {
                log_data(r, g, b, prox);
            }
        } else if (ret < 0) {
            fprintf(stderr, "I2C read error, re-initializing...\n");
            close(i2c_fd);
            i2c_fd = -1;
            usleep(100000);
            if (apds9960_init(i2c_fd) < 0) {
                fprintf(stderr, "Re-initialization failed\n");
                close(i2c_fd);
                return 1;
            }
        }
        usleep(100000);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

