#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L0X_ADDR 0x29
#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"

#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L0X_REG_SYSTEM_MODE_START 0x0000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0014
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096
#define VL53L0X_REG_GPIO_HV_MUX_ACTIVE_HIGH 0x0030
#define VL53L0X_REG_GPIO_TIO_HV_STATUS 0x0031
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0015

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, int len) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int vl53l0x_init(int fd) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(fd, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read model ID from sensor.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X. Expected 0xEA.\n", model_id);
        return -1;
    }
    printf("VL53L0X detected (model ID: 0x%02X).\n", model_id);
    return 0;
}

static int vl53l0x_start_measurement(int fd) {
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    return 0;
}

static int vl53l0x_wait_for_data(int fd, int timeout_ms) {
    uint8_t status = 0;
    int elapsed = 0;
    while (elapsed < timeout_ms) {
        if (i2c_read_reg16(fd, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0) return -1;
        if (status & 0x01) return 0;
