#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define TRIGGER_CMD 0x01
#define MEASURE_CMD 0x02
#define SAMPLE_INTERVAL_US 200000
#define TRIGGER_DELAY_US 50000
#define MAX_DISTANCE_MM 400
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int trigger_sensor(void) {
    int rc = i2cWriteByte(i2c_handle, TRIGGER_CMD);
    if (rc < 0) {
        fprintf(stderr, "Error writing trigger command: %d\n", rc);
        return -1;
    }
    return 0;
}

static int read_distance(int *distance) {
    int rc = i2cReadWordData(i2c_handle, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error reading distance: %d\n", rc);
        return -1;
    }
    *distance = (int)rc;
    return 0;
}

static void log_distance(int distance) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file);
    printf("%s, %d\n", timestamp, distance);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting distance measurements (Ctrl-C to stop)...\n");

    while (running) {
        if (trigger_sensor() != 0) {
            gpioDelay(TRIGGER_DELAY_US);
            continue;
        }

        gpioDelay(TRIGGER_DELAY_US);

        int distance;
        if (read_distance(&distance) == 0) {
            if (distance > MAX_DISTANCE_MM) {
                distance = -1;
            }
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance, skipping sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

