#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define LED_PIN 17
#define DISTANCE_THRESHOLD_CM 20.0
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_US 100000

/*
 * ICU-20201 I2C register map (representative; adjust per your datasheet/firmware).
 * The sensor returns a 16-bit distance value in the 'Distance' register.
 */
#define REG_DISTANCE 0x00
#define REG_CONFIG 0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_PIN);
        return -1;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing GPIO %d to LOW\n", LED_PIN);
        return -1;
    }
    return 0;
}

static int read_distance(float *distance_cm) {
    int raw = i2cReadWordData(i2c_handle, REG_DISTANCE);
    if (raw < 0) {
        fprintf(stderr, "Error reading distance register: %d\n", raw);
        return -1;
    }
    /* pigpio returns data in little-endian byte order; swap to big-endian. */
    uint16_t swapped = (uint16_t)((raw & 0xFF) << 8 | ((raw >> 8) & 0xFF));
    *distance_cm = (float)swapped / 10.0f;
    return 0;
}

static int log_distance(float distance_cm) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting current time\n");
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time to local time\n");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }
    if (fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure LED is off before terminating pigpio. */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting distance monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        float distance_cm;
        if (read_distance(&distance_cm) == 0) {
            int led_state = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
            if (gpioWrite(LED_PIN, led_state) != 0) {
                fprintf(stderr, "Error writing to GPIO %d\n", LED_PIN);
            }
            if (log_distance(distance_cm) != 0) {
                fprintf(stderr, "Warning: failed to log distance reading\n");
            }
            printf("Distance: %.2f cm, LED: %s\n",
                   distance_cm, led_state ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Error reading distance; continuing...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

