#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

/* Si1182 register addresses */
#define REG_PART_ID 0x00
#define REG_REV_ID 0x01
#define REG_SEQ_ID 0x02
#define REG_INT_CFG 0x03
#define REG_IRQ_ENABLE 0x04
#define REG_IRQ_MODE1 0x05
#define REG_IRQ_MODE2 0x06
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_PS_LED21 0x0A
#define REG_PS_LED3 0x0B
#define REG_PARAM_WR 0x17
#define REG_COMMAND 0x18
#define REG_RESPONSE 0x20
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_ALS_IR_DATA0 0x24
#define REG_ALS_IR_DATA1 0x25
#define REG_PS1_DATA0 0x26
#define REG_PS1_DATA1 0x27
#define REG_PS2_DATA0 0x28
#define REG_PS2_DATA1 0x29
#define REG_PS3_DATA0 0x2A
#define REG_PS3_DATA1 0x2B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint8_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, len=%u): %d\n", reg, len, rc);
        return -1;
    }
    if (rc != len) {
        fprintf(stderr, "I2C block read short: got %d, expected %u\n", rc, len);
        return -1;
    }
    return 0;
}

static int init_si1182(void) {
    uint8_t part_id;
    if (i2c_read_reg(REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x82)\n", part_id);
        return -1;
    }

    if (i2c_write_reg(REG_COMMAND, 0x01) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_HW_KEY, 0x17) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_PS_LED21, 0x0F) < 0) return -1;
    if (i2c_write_reg(REG_PS_LED3, 0x0A) < 0) return -1;

    if (i2c_write_reg(REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_IRQ_MODE2, 0x00) < 0) return -1;

    if (i2c_write_reg(REG_PARAM_WR, 0x01) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x02) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x03) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x04) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x05) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x06) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x07) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x08) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x09) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x0A) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x0B) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x0C) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x0D) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x0E) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_PARAM_WR, 0x0F) < 0) return -1;
    if (i2c_write_reg(REG_COMMAND, 0x0B) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_IRQ_ENABLE, 0x01) < 0) return -1;

    return 0;
}

static int read_proximity(uint16_t *proximity) {
    uint8_t buf[2];
    if (i2c_read_block(REG_PS1_DATA0, buf, 2) < 0) return -1;
    *proximity = ((uint16_t)buf[1] << 8) | buf[0];
    return 0;
}

static int read_ambient_light(uint16_t *ambient_light) {
    uint8_t buf[2];
    if (i2c_read_block(REG_ALS_VIS_DATA0, buf, 2) < 0) return -1;
    *ambient_light = ((uint16_t)buf[1] << 8) | buf[0];
    return 0;
}

static int log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1182() < 0) {
        fprintf(stderr, "Si1182 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting data acquisition... Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t proximity = 0, ambient_light = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
            if (read_proximity(&proximity) == 0 && read_ambient_light(&ambient_light) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed, retrying...\n", attempt + 1, MAX_RETRIES);
            gpioDelay(100000);
        }

        if (success) {
            if (log_data(proximity, ambient_light) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "All %d read attempts failed, continuing...\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

