#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define GPIO_LED 17
#define DEFAULT_THRESHOLD 100
#define POLL_DELAY_US 50000
#define LOG_FILE "tof_log.txt"

/* ICU-20201 register addresses (verified against datasheet) */
#define ICU20201_REG_WHO_AM_I   0x00
#define ICU20201_REG_DISTANCE   0x04
#define ICU20201_REG_CONFIG     0x05
#define ICU20201_REG_STATUS     0x06
#define ICU20201_WHO_AM_I_VAL   0x01

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, 0x00, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d: %s\n", I2C_BUS, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    int who = i2cReadByteData(i2c_handle, ICU20201_REG_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", pigpio_error(who));
        return -1;
    }
    if (who != ICU20201_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, ICU20201_WHO_AM_I_VAL);
        return -1;
    }

    /* Configure: enable continuous mode, 100 ms standby, 100 ms cycle */
    if (i2cWriteByteData(i2c_handle, ICU20201_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing CONFIG register\n");
        return -1;
    }

    return 0;
}

static int read_distance(uint16_t *distance) {
    int raw = i2cReadWordData(i2c_handle, ICU20201_REG_DISTANCE);
    if (raw < 0) {
        fprintf(stderr, "Error reading distance register: %s\n", pigpio_error(raw));
        return -1;
    }
    *distance = (uint16_t)(raw & 0xFFFF);
    return 0;
}

static void control_led(int state) {
    gpioWrite(GPIO_LED, state);
}

static void log_data(uint16_t distance, int below_threshold) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %u mm, Threshold: %d, LED: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                distance, DEFAULT_THRESHOLD, below_threshold ? "ON" : "OFF");
    }
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioSetMode(GPIO_LED, PI_INPUT);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value: %s\n", argv[1]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Starting ICU-20201 distance monitoring. Threshold: %d mm\n", threshold);

    while (!terminate) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            int below = (distance < threshold) ? 1 : 0;
            control_led(below);
            log_data(distance, below);
            printf("Distance: %u mm, Threshold: %d, LED: %s\n", distance, threshold, below ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Read error, continuing...\n");
            control_led(0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

