#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_I2C_ADDR   0x28
#define LOG_FILE       "intrusion_log.txt"
#define DIST_THRESHOLD 1000
#define NUM_SAMPLES    10
#define CYCLE_DELAY_US 100000
#define MEAS_DELAY_US  10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance_mm) {
    uint8_t cmd[4] = {0x01, 0x00, 0x00, 0x00};
    uint8_t data[15];

    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) < 0)
        return -1;

    usleep(MEAS_DELAY_US);

    if (i2c_read_data(fd, data, sizeof(data)) < 0)
        return -1;

    if (data[0] != 0x01) {
        fprintf(stderr, "Unexpected header: 0x%02X (expected 0x01)\n", data[0]);
        return -1;
    }

    *distance_mm = ((uint16_t)data[11] << 8) | data[12];
    return 0;
}

static int log_intrusion(const char *filename, uint16_t avg_distance) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Average Distance: %u mm\n", ts, avg_distance);
    } else {
        fprintf(fp, "(unknown time), Average Distance: %u mm\n", avg_distance);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

