        int error_count = 0;

        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            uint16_t dist;
            if (read_distance(g_i2c_fd, &dist) == 0) {
                distances[valid_samples++] = dist;
                sum += dist;
            } else {
                fprintf(stderr, "Sensor read error (sample %d)\n", i);
                error_count++;
            }
            if (i < NUM_SAMPLES - 1)
                usleep(CYCLE_DELAY_US);
        }

        if (valid_samples > 0) {
            uint16_t avg = (uint16_t)(sum / valid_samples);
            printf("Average Distance: %u mm (valid samples: %d, errors: %d)\n",
                   avg, valid_samples, error_count);

