#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define VL53L0X_MODEL_ID_REG 0x010F
#define VL53L0X_EXPECTED_MODEL_ID 0xEA
#define VL53L0X_SOFT_RESET_GO2_SOFT_RESET_N 0x0003
#define VL53L0X_SYSTEM_START 0x0000
#define VL53L0X_RESULT_INTERRUPT_STATUS 0x0014
#define VL53L0X_RESULT_RANGE_STATUS 0x0014
#define VL53L0X_RESULT_DISTANCE 0x0096
#define POLL_TIMEOUT_MS 100
#define POLL_INTERVAL_US 1000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device (reg 0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        fprintf(stderr, "Error writing register address 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)data, len) != (int)len) {
        fprintf(stderr, "Error reading from I2C device (reg 0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l0x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L0X_MODEL_ID_REG, &model_id, 1) != 0) {
        fprintf(stderr, "Failed to read model ID from VL53L0X\n");
        return -1;
    }
    if (model_id != VL53L0X_EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n", model_id, VL53L0X_EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L0X detected (model ID: 0x%02X)\n", model_id);

    if (i2c_write_reg16(handle, VL53L0X_SOFT_RESET_GO2_SOFT_RESET_N, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L0X_SOFT_RESET_GO2_SOFT_RESET_N, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L0X_SYSTEM_START, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L0X_SYSTEM_START, 0x40) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l0x_get_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    int timeout = 0;
    while (timeout < POLL_TIMEOUT_MS) {
        if (i2c_read_reg16(handle, VL53L0X_RESULT_INTERRUPT_STATUS, &status, 1) != 0) return -1;
        if (status & 0x01) break;
        gpioDelay(POLL_INTERVAL_US);
        timeout++;
    }
    if (timeout >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, VL53L0X_RESULT_DISTANCE, dist_buf, 2) != 0) return -1;
    *distance = (dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s ", buffer);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (vl53l0x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t distance = 0;
    while (running) {
        if (vl53l0x_get_distance(i2c_handle, &distance) == 0) {
            print_timestamp();
            printf("Distance: %u mm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to get distance\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

