#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x53
#define SAMPLE_PERIOD  500000   /* microseconds (500 ms) */

/*
 * Si1182 register map (representative subset).
 * The exact register addresses depend on the device's configuration
 * and the driver's internal mapping; these are placeholders that
 * must be replaced with the actual values from the Si1182 datasheet
 * and the pigpio I2C wrapper.
 */
#define REG_PART_ID     0x00
#define REG_HW_KEY      0x07
#define REG_MEAS_RATE0  0x08
#define REG_MEAS_RATE1  0x09
#define REG_PS_LED21    0x0F
#define REG_PS_LED3     0x10
#define REG_PS1_DATA0   0x12
#define REG_PS1_DATA1   0x13
#define REG_PS2_DATA0   0x14
#define REG_PS2_DATA1   0x15
#define REG_PS3_DATA0   0x16
#define REG_PS3_DATA1   0x17

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_proximity(int handle, uint16_t *proximity)
{
    uint8_t lo, hi;

    if (read_reg(handle, REG_PS1_DATA0, &lo) < 0) return -1;
    if (read_reg(handle, REG_PS1_DATA1, &hi) < 0) return -1;

    *proximity = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    uint16_t proximity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X (pigpio rc=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Probe the sensor: a NACK on the first write typically means
     * the device is not present at the advertised address.
     */
    if (write_reg(g_i2c_handle, REG_PART_ID, 0x01) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X (no ACK)\n", I2C_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /*
     * Minimal initialization sequence.
     * Replace the register addresses and values with the
     * actual Si1182 initialization sequence from the datasheet.
     */
    if (write_reg(g_i2c_handle, REG_HW_KEY, 0x17) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (write_reg(g_i2c_handle, REG_MEAS_RATE0, 0x0A) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (write_reg(g_i2c_handle, REG_MEAS_RATE1, 0x00) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (write_reg(g_i2c_handle, REG_PS_LED21, 0x0F) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (write_reg(g_i2c_handle, REG_PS_LED3, 0x03) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1182 Proximity Sensor Reader\n");
    printf("Bus %d, Address 0x%02X, Sample every %d ms\n",
