#define REG_MEAS_RATE0  0x08
#define REG_MEAS_RATE1  0x09
#define REG_PS_LED21    0x0F
#define REG_PS_LED3     0x10
#define REG_PS1_DATA0   0x12
#define REG_PS1_DATA1   0x13
#define REG_PS2_DATA0   0x14
#define REG_PS2_DATA1   0x15
#define REG_PS3_DATA0   0x16
#define REG_PS3_DATA1   0x17

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_proximity(int handle, uint16_t *proximity)
{
    uint8_t lo, hi;

    if (read_reg(handle, REG_PS1_DATA0, &lo) < 0) return -1;
    if (read_reg(handle, REG_PS1_DATA1, &hi) < 0) return -1;

    *proximity = ((uint16_t)hi << 8) | lo;
    return 0;
}

