#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

/* OPT3101 I2C address (7-bit) */
#define OPT3101_ADDR 0x33

/* OPT3101 register addresses */
#define OPT3101_REG_SYSTEM_CONFIG 0x00
#define OPT3101_REG_RESULT_DATA   0x04
#define OPT3101_REG_AMBIENT_DATA  0x08
#define OPT3101_REG_ERROR_STATUS  0x0A

/* Error codes */
#define OPT3101_ERROR_NONE        0x00
#define OPT3101_ERROR_I2C        0x01
#define OPT3101_ERROR_RANGE      0x02
#define OPT3101_ERROR_AMBIENT    0x03

/* Global variables for graceful shutdown */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/* Signal handler for SIGINT (Ctrl+C) */
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Function to initialize the OPT3101 sensor */
int init_opt3101(int handle) {
    /*
     * Example configuration for the OPT3101.
     * In a production environment, this would be based on the
     * specific application requirements and the sensor's datasheet.
     */
    uint8_t config_data[] = {
        0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08,
        0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F, 0x10
    };

    for (size_t i = 0; i < sizeof(config_data); i++) {
        if (i2cWriteByteData(handle, OPT3101_REG_SYSTEM_CONFIG, config_data[i]) < 0) {
            fprintf(stderr, "Error writing to system config register: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

/* Function to read data from the OPT3101 sensor */
int read_opt3101_data(int handle, uint16_t *distance, uint16_t *ambient_light, uint16_t *error_status) {
    uint8_t data[6];

    /* Read 6 bytes of data from the sensor */
    if (i2cReadI2CBlockData(handle, OPT3101_REG_RESULT_DATA, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading data from I2C: %s\n", strerror(errno));
        return -1;
    }

    /* Extract distance and ambient light values */
    *distance = (data[0] << 8) | data[1];
    *ambient_light = (data[2] << 8) | data[3];
    *error_status = (data[4] << 8) | data[5];

    return 0;
}

/* Function to log the sensor data */
void log_data(uint16_t distance, uint16_t ambient_light, uint16_t error_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Distance: %u mm, Ambient Light: %u, Error Status: %u\n",
           timestamp, distance, ambient_light, error_status);
}

int main() {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C device on bus 1 */
    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Initialize the OPT3101 sensor */
    if (init_opt3101(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing OPT3101 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    uint16_t distance, ambient_light, error_status;

    /* Main loop */
    while (running) {
        /* Read data from the sensor */
        if (read_opt3101_data(i2c_handle, &distance, &ambient_light, &error_status) == 0) {
            /* Log the data */
            log_data(distance, ambient_light, error_status);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        /* Delay for 500 milliseconds */
        gpioDelay(500000);
    }

    /* Close I2C device and terminate pigpio library */
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

