/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   - Trigger: GPIO 17 (BCM) -> 3.3 V (via 1 kΩ resistor) -> HC-SR04 TRIG
 *   - Echo:    GPIO 18 (BCM) -> 3.3 V (via 1 kΩ resistor) <- HC-SR04 ECHO
 *   - VCC:     5 V (external supply, NOT 3.3 V)
 *   - GND:     GND (common with Pi)
 *
 * NOTE: The HC-SR04 operates at 5 V.  The Raspberry Pi GPIO pins are 3.3 V
 *       tolerant, but the echo line is driven by a 5 V MCU output.  A 1 kΩ
 *       resistor must be placed between the echo pin and the Pi GPIO to
 *       protect the Pi's input.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms max echo wait           */
#define SAMPLE_PERIOD_S  1.0         /* 1 s between samples            */
#define MAX_RANGE_MM     38000       /* HC-SR04 max range ~38 m        */
#define MIN_VALID_MM     200         /* 2 cm minimum valid distance    */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
    } else {
        snprintf(buf, len, "----");
    }
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* HC-SR04 measurement via pigpio                                     */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   distance in mm on success, or -1.0 on any error.
 *
 * The HC-SR04 echo pin is 5 V tolerant; a 1 kΩ resistor must be placed
 * between the echo pin and the Pi GPIO to protect the Pi's input.
 */
static float measure_distance(void)
{
    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        log_error("gpioWrite(TRIGGER, 0) failed");
        return -1.0;
    }
    gpioDelay(5);  /* settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        log_error("gpioWrite(TRIGGER, 1) failed");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        log_error("gpioWrite(TRIGGER, 0) failed");
        return -1.0;
    }

    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t deadline;

