#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <linux/serial.h>
#include <linux/types.h>
#include <linux/ioctl.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 1.0f
#define LOG_FILE "intrusion_log.csv"
#define READ_TIMEOUT_SEC 1
#define ALERT_DURATION_SEC 2
#define FRAME_HEADER_SIZE 8
#define FRAME_DATA_SIZE 128
#define NUM_BINS 64
#define BITS_PER_BIN 16
#define BITS_PER_BYTE 8
#define BYTES_PER_BIN (BITS_PER_BIN / BITS_PER_BYTE)

static volatile sig_atomic_t program_running = 1;
static int uart_fd = -1;
static int log_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

static int log_intrusion(float distance) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm_info = localtime(&tv.tv_sec);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    char log_entry[128];
    int len = snprintf(log_entry, sizeof(log_entry), "%s.%06ld,%.2f\n", timestamp, tv.tv_usec, distance);
    if (len < 0 || len >= (int)sizeof(log_entry)) {
        fprintf(stderr, "Error formatting log entry\n");
        return -1;
    }

    if (lseek(log_fd, 0, SEEK_END) == 0) {
        if (write(log_fd, log_entry, len) != len) {
            perror("Error writing to log file");
            return -1;
        }
        fsync(log_fd);
        return 0;
    } else {
        perror("Error seeking in log file");
        return -1;
    }
}

static void activate_alert(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error activating alert LED\n");
        return;
    }
    sleep(ALERT_DURATION_SEC);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error deactivating alert LED\n");
    }
}

static int process_frame(const uint8_t *frame, int frame_len) {
    if (frame_len < FRAME_HEADER_SIZE + FRAME_DATA_SIZE) {
        fprintf(stderr, "Frame too short: %d bytes\n", frame_len);
        return -1;
    }

    uint8_t magic_word[FRAME_HEADER_SIZE] = {0};
    memcpy(magic_word, frame, FRAME_HEADER_SIZE);

    if (magic_word[0] != 0x02 || magic_word[1] != 0x01) {
        fprintf(stderr, "Invalid magic word: 0x%02X 0x%02X\n", magic_word[0], magic_word[1]);
        return -1;
    }

    uint8_t *data = frame + FRAME_HEADER_SIZE;
    uint16_t *range_profile = (uint16_t *)data;

    for (int i = 0; i < NUM_BINS; i++) {
        if (range_profile[i] > 0) {
            float distance = (float)range_profile[i] / 1000.0f;
            if (distance <= DISTANCE_THRESHOLD) {
                printf("Intrusion detected! Distance: %.2f meters\n", distance);
                if (log_intrusion(distance) != 0) {
                    fprintf(stderr, "Error logging intrusion\n");
                }
                activate_alert(GPIO_PIN);
                return 1;
            }
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        return 1;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Error opening log file");
        close(uart_fd);
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_PIN);
        close(uart_fd);
        close(log_fd);
        return 1;
    }
    gpioWrite(GPIO_PIN, 0);

    uint8_t frame_buf[FRAME_HEADER_SIZE + FRAME_DATA_SIZE];
    int frame_len = 0;
    int bytes_read;

    while (program_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        struct timeval timeout = { .tv_sec = READ_TIMEOUT_SEC, .tv_usec = 0 };

        int select_result = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result < 0) {
            if (errno == EINTR) continue;
            perror("Error in select()");
            break;
        } else if (select_result > 0) {
            bytes_read = read(uart_fd, frame_buf + frame_len, sizeof(frame_buf) - frame_len);
            if (bytes_read > 0) {
                frame_len += bytes_read;
                if (frame_len >= FRAME_HEADER_SIZE) {
                    uint8_t *header = frame_buf;
                    uint8_t *data = header + FRAME_HEADER_SIZE;
                    int header_len = FRAME_HEADER_SIZE;
                    int data_len = FRAME_DATA_SIZE;

                    if (header_len + data_len > frame_len) {
                        fprintf(stderr, "Incomplete frame received\n");
                        frame_len = 0;
                        continue;
                    }

                    memcpy(header, frame_buf, header_len);
                    memcpy(data, frame_buf + header_len, data_len);

                    if (process_frame(data, data_len) == 1) {
                        frame_len = 0;
                    }
                } else if (frame_len > 0) {
                    memmove(frame_buf, frame_buf + frame_len, sizeof(frame_buf) - frame_len);
                    frame_len = 0;
                }
            } else if (bytes_read < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) continue;
                perror("Error reading from UART");
                break;
            }
        } else {
            continue;
        }
    }

    if (uart_fd >= 0) close(uart_fd);
    if (log_fd >= 0) close(log_fd);
    gpioWrite(GPIO_PIN, 0);

    return 0;
}

