        int select_result = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result < 0) {
            if (errno == EINTR) continue;
            perror("Error in select()");
            break;
        } else if (select_result > 0) {
            bytes_read = read(uart_fd, frame_buf + frame_len, sizeof(frame_buf) - frame_len);
            if (bytes_read > 0) {
                frame_len += bytes_read;
                if (frame_len >= FRAME_HEADER_SIZE) {
                    uint8_t *header = frame_buf;
                    uint8_t *data = header + FRAME_HEADER_SIZE;
                    int header_len = FRAME_HEADER_SIZE;
                    int data_len = FRAME_DATA_SIZE;

                    if (header_len + data_len > frame_len) {
                        fprintf(stderr, "Incomplete frame received\n");
                        frame_len = 0;
                        continue;
                    }

                    memcpy(header, frame_buf, header_len);
                    memcpy(data, frame_buf + header_len, data_len);

                    if (process_frame(data, data_len) == 1) {
                        frame_len = 0;
                    }
                } else if (frame_len > 0) {
                    memmove(frame_buf, frame_buf + frame_len, sizeof(frame_buf) - frame_len);
                    frame_len = 0;
                }
            } else if (bytes_read < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) continue;
                perror("Error reading from UART");
                break;
            }
        } else {
            continue;
        }
    }

    if (uart_fd >= 0) close(uart_fd);
    if (log_fd >= 0) close(log_fd);
    gpioWrite(GPIO_PIN, 0);

    return 0;
}

