    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure buzzer pin as output and ensure it is off */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize buzzer state on GPIO %d\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = -1;  /* -1 = unknown, 0 = no obstacle, 1 = obstacle detected */

    printf("Obstacle detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor on GPIO %d\n", SENSOR_PIN);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* E18-D80NK is active-low: 0 means obstacle detected, 1 means clear */
        int obstacle_detected = (sensor_value == 0) ? 1 : 0;

        if (obstacle_detected != last_state) {
            if (gpioWrite(BUZZER_PIN, obstacle_detected) != 0) {
                fprintf(stderr, "Error writing to buzzer on GPIO %d\n", BUZZER_PIN);
            } else {
                if (obstacle_detected) {
                    printf("Obstacle detected! Buzzer ON.\n");
                    if (log_event("Obstacle detected, buzzer activated") != 0) {
                        fprintf(stderr, "Warning: failed to log obstacle detection event.\n");
                    }
                } else {
                    printf("Obstacle cleared. Buzzer OFF.\n");
                    if (log_event("Obstacle cleared, buzzer deactivated") != 0) {
                        fprintf(stderr, "Warning: failed to log obstacle clear event.\n");
                    }
                }
                last_state = obstacle_detected;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown: turn off buzzer and release resources */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

