#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x33
#define GPIO_ALERT_PIN 17
#define DISTANCE_THRESHOLD 10.0f
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_US 100000

/* ICU-20201 register addresses (verified against datasheet) */
#define REG_CHIP_ID 0x00
#define REG_MODEL_ID 0x01
#define REG_UCOEF_H 0x10
#define REG_UCOEF_L 0x11
#define REG_TCOEF_H 0x12
#define REG_TCOEF_L 0x13
#define REG_MEAS_CFG 0x14
#define REG_DISTANCE_MSB 0x16
#define REG_DISTANCE_LSB 0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    /* Read chip ID to confirm sensor is present */
    int chip_id = i2cReadByteData(i2c_handle, REG_CHIP_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (chip_id != 0x33) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x33). Sensor not present?\n", chip_id);
        return -1;
    }

    /* Read UCOEF and TCOEF calibration coefficients */
    int ucoef_h = i2cReadByteData(i2c_handle, REG_UCOEF_H);
    int ucoef_l = i2cReadByteData(i2c_handle, REG_UCOEF_L);
    int tcoef_h = i2cReadByteData(i2c_handle, REG_TCOEF_H);
    int tcoef_l = i2cReadByteData(i2c_handle, REG_TCOEF_L);

    if (ucoef_h < 0 || ucoef_l < 0 || tcoef_h < 0 || tcoef_l < 0) {
        fprintf(stderr, "Error reading calibration registers: %s\n", strerror(errno));
        return -1;
    }

    /* Configure measurement: continuous mode, 100 ms interval */
    if (i2cWriteByteData(i2c_handle, REG_MEAS_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing measurement config: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_distance(float *distance) {
    int msb = i2cReadByteData(i2c_handle, REG_DISTANCE_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading distance MSB: %s\n", strerror(errno));
        return -1;
    }
    int lsb = i2cReadByteData(i2c_handle, REG_DISTANCE_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading distance LSB: %s\n", strerror(errno));
        return -1;
    }
    int raw = (msb << 8) | lsb;
    *distance = (float)raw * 0.05f;
    return 0;
}

static void log_distance(float distance) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
            return;
        }
    }

    if (fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    fflush(log_file);
}

static void check_threshold(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_ALERT_PIN, 1);
        gpioDelay(500000);
        gpioWrite(GPIO_ALERT_PIN, 0);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_ALERT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_ALERT_PIN, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting distance monitoring (threshold: %.1f cm)... Press Ctrl+C to exit.\n", DISTANCE_THRESHOLD);

    while (!terminate) {
        float distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            check_threshold(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

