#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define LED_PIN        18
#define BLINK_PERIOD_US 100000   /* 100 ms half-cycle */
#define SAMPLE_PERIOD_US 100000 /* 100 ms between samples */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000     /* 10 ms */

/* CH201 register addresses (datasheet) */
#define REG_PROD_ID      0x00
#define REG_DISTANCE     0x04
#define REG_CONFIG       0x05

#define CH201_PROD_ID    0x29

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a register; returns 0 on success, -1 on failure. */
static int ch201_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* Read one byte from a register; returns 0 on success, -1 on failure. */
static int ch201_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Initialize the CH201 sensor: verify product ID, configure, then start ranging. */
static int ch201_init(int handle)
{
    uint8_t prod_id = 0;

    /* Read and verify product ID */
    if (ch201_read_reg(handle, REG_PROD_ID, &prod_id) != 0) {
        fprintf(stderr, "Failed to read CH201 product ID\n");
        return -1;
    }
    if (prod_id != CH201_PROD_ID) {
        fprintf(stderr, "Unexpected product ID: 0x%02X (expected 0x%02X)\n",
                prod_id, CH201_PROD_ID);
        return -1;
    }

    /* Configure: enable ranging, set range to 200 mm (0x00), etc.
       The exact config depends on the specific CH201 variant; 0x00 is a safe default. */
    if (ch201_write_reg(handle, REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to configure CH201\n");
        return -1;
    }

    /* Start ranging: write 0x01 to REG_CONFIG to begin continuous mode */
    if (ch201_write_reg(handle, REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Failed to start CH201 ranging\n");
        return -1;
    }

    return 0;
}

/* Read distance from the CH201; returns distance in mm, or -1 on error. */
static int ch201_read_distance(int handle)
{
    uint8_t dist_raw = 0;
    int retries = MAX_RETRIES;

    while (retries > 0) {
        if (ch201_read_reg(handle, REG_DISTANCE, &dist_raw) == 0) {
            return (int)dist_raw;
        }
        retries--;
        if (retries > 0) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

/* Calculate LED blink frequency (Hz) from distance (mm). */
static int calculate_frequency(int distance)
{
    if (distance <= 0) {
        return 0;
    }
    /* Inverse relationship: shorter distance -> faster blink */
    return 1000000 / distance;
}

/* Blink the LED once (one half-cycle) to keep timing smooth across samples. */
static void blink_led(int pin, int frequency_hz)
{
    if (frequency_hz <= 0) {
        gpioWrite(pin, 0);
        return;
    }

    /* Half-cycle duration in microseconds */
    uint32_t half_cycle_us = (uint32_t)(BLINK_PERIOD_US / frequency_hz);
    uint32_t elapsed = 0;

    while (elapsed < half_cycle_us && g_running) {
        gpioWrite(pin, 1);
        gpioDelay(1000); /* 1 ms polling */
        elapsed += 1000;
    }
    gpioWrite(pin, 0);
    gpioDelay(1000); /* Finish the half-cycle */
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "CH201 initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance reader started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int distance = ch201_read_distance(g_i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
            /* Keep LED off on sensor failure for safety */
            gpioWrite(LED_PIN, 0);
        } else {
            int frequency = calculate_frequency(distance);
            printf("Distance: %d mm, Frequency: %d Hz\n", distance, frequency);
            blink_led(LED_PIN, frequency);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

