        perror("Error opening log file");
        cleanup();
        return 1;
    }

    while (running) {
        uint16_t distance = 0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success && running) {
            if (read_distance(&distance) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Retrying (%d/%d)...\n", retries, MAX_RETRIES);
                    gpioDelay(100000);
                }
            }
        }

        if (success) {
            if (log_data(distance) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL_MS * 1000);
        }
    }

    cleanup();
    return 0;
}

