#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define POLL_INTERVAL_US 10000    /* 10 ms */
#define LOG_FILE_NAME "proximity_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 UTC timestamp into buf (size >= 25)              */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1)
        return -1;

    if (gmtime_r(&rawtime, &tm_info) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a log entry to the log file                                 */
/* ------------------------------------------------------------------ */
static int log_event(int sensor_id, const char *event_type)
{
    char timestamp[32];

    if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
        fprintf(stderr, "Error: failed to generate timestamp.\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Sensor %d - %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor with software debounce                               */
/* Returns: 1 = obstacle detected (HIGH), 0 = clear (LOW), -1 = error  */
/* ------------------------------------------------------------------ */
static int read_sensor_debounced(int gpio_pin)
{
    int first_read, second_read;
    int stable_value;

    first_read = gpioRead(gpio_pin);
    if (first_read < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d: %s\n",
                gpio_pin, pigpio_error(first_read));
        return -1;
    }

    gpioDelay(DEBOUNCE_DELAY_US);

    second_read = gpioRead(gpio_pin);
    if (second_read < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d: %s\n",
                gpio_pin, pigpio_error(second_read));
        return -1;
    }

    /* If the two reads differ, the line is unstable — treat as error */
    if (first_read != second_read)
        return -1;

    stable_value = first_read;

    /*
     * TCRT5000 module output is active-HIGH when an obstacle is
     * detected.  We log a transition only when HIGH -> LOW (obstacle
     * cleared) and LOW -> HIGH (obstacle detected).
     */
    if (stable_value == 1)
        return 0;                 /* clear (LOW) -> obstacle detected */
    if (stable_value == 0)
        return 1;                 /* obstacle (HIGH) -> clear */

    return -1;
}

/* ------------------------------------------------------------------ */
/* Release all GPIO resources and close the log file                 */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        if (fclose(log_file) != 0)
            fprintf(stderr, "Warning: error closing log file: %s\n",
                    strerror(errno));
        log_file = NULL;
    }

    /*
     * gpioTerminate() is the official way to release all pigpio
     * resources.  Passing NULL for the gpio parameter is acceptable
     * when no individual pins need release.
     */
    if (gpioTerminate() != 0)
        fprintf(stderr, "Warning: gpioTerminate() failed.\n");
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int last_state_1 = -1;
    int last_state_2 = -1;
    int ret;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n",
                pigpio_error(ret));
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor GPIOs as inputs ---- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /*
     * Enable internal pull-down resistors so the inputs read LOW
     * when no obstacle is present (TCRT5000 output is open-collector
     * style).
     */
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0)
        fprintf(stderr, "Warning: failed to set pull-down on GPIO %d.\n",
                SENSOR_1_GPIO);
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0)
        fprintf(stderr, "Warning: failed to set pull-down on GPIO %d.\n",
                SENSOR_2_GPIO);

    /* ---- Open log file in append mode ---- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TCRT5000 obstacle avoidance monitor started.\n");
    printf("  Sensor 1: GPIO %d\n", SENSOR_1_GPIO);
    printf("  Sensor 2: GPIO %d\n", SENSOR_2_GPIO);
    printf("  Log file: %s\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    while (program_running) {
        int sensor_1_value = read_sensor_debounced(SENSOR_1_GPIO);
        int sensor_2_value = read_sensor_debounced(SENSOR_2_GPIO);

        if (sensor_1_value < 0 || sensor_2_value < 0) {
            fprintf(stderr, "Error: sensor read failed; continuing.\n");
        } else {
            /* Sensor 1 */
            if (sensor_1_value != last_state_1) {
                const char *event = (sensor_1_value == 1) ? "DETECTED" : "CLEARED";
                if (log_event(1, event) != 0)
                    fprintf(stderr, "Warning: failed to log sensor 1 event.\n");
                last_state_1 = sensor_1_value;
            }

            /* Sensor 2 */
            if (sensor_2_value != last_state_2) {
                const char *event = (sensor_2_value == 1) ? "DETECTED" : "CLEARED";
                if (log_event(2, event) != 0)
                    fprintf(stderr, "Warning: failed to log sensor 2 event.\n");
                last_state_2 = sensor_2_value;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

