    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int ch101_start_measurement(int fd)
{
    return i2c_write_reg8(fd, MEAS_CMD, 0x01);
}

static int ch101_wait_measurement(int fd)
{
    uint8_t status;
    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        if (i2c_read_reg8(fd, MEAS_STATUS, &status) != 0)
            return -1;
        if ((status & 0x01) != 0)
            return 0;
        usleep(1000);
    }
    fprintf(stderr, "CH-101 measurement timeout\n");
    return -1;
}

static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, 0x02, &lo) != 0)
        return -1;
    if (i2c_read_reg8(fd, 0x03, &hi) != 0)
        return -1;
    *distance_mm = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int log_data(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u\n", ts, (unsigned)distance_mm) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    g_csv = fopen(CSV_FILENAME, "a");
    if (g_csv == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (fprintf(g_csv, "timestamp,distance_mm\n") < 0) {
        fprintf(stderr, "fprintf header failed: %s\n", strerror(errno));
        fclose(g_csv);
        close(g_i2c_fd);
        return 1;
    }
    fflush(g_csv);

    printf("CH-101 distance logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (ch101_start_measurement(g_i2c_fd) != 0) {
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }
        if (ch101_wait_measurement(g_i2c_fd) != 0) {
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }
        uint16_t dist;
        if (ch101_read_distance(g_i2c_fd, &dist) != 0) {
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }
        if (log_data(g_csv, dist) != 0) {
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_csv != NULL) {
        fflush(g_csv);
        fclose(g_csv);
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return 0;
}

