#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x54

#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L5CX_REG_SYSTEM_MODE_START 0x0000
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

#define NUM_ZONES 64
#define POLL_DELAY_MS 500

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *data, size_t len) {
    uint8_t addr[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l5cx_init(int fd) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(fd, VL53L5CX_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID: 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    if (i2c_write_reg16(fd, VL53L5CX_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg16(fd, VL53L5CX_REG_SYSTEM_MODE_START, 0x40) < 0) return -1;
    usleep(10000);

    return 0;
}

static int read_zone_data(int fd, uint16_t *distances) {
    uint8_t status = 0;
    if (i2c_read_reg16(fd, VL53L5CX_REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;

    if ((status & 0x01) == 0) {
        return 1;
    }

    uint8_t data[NUM_ZONES * 2];
    if (i2c_read_reg16(fd, VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, NUM_ZONES * 2) < 0) {
        return -1;
    }

    for (int i = 0; i < NUM_ZONES; i++) {
        distances[i] = (uint16_t)data[i * 2] | ((uint16_t)data[i * 2 + 1] << 8);
    }

    if (i2c_write_reg16(fd, VL53L5CX_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L5CX_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (vl53l5cx_init(fd) < 0) {
        fprintf(stderr, "VL53L5CX initialization failed.\n");
        close(fd);
        return 1;
    }

    uint16_t distances[NUM_ZONES];

    while (running) {
        int ret = read_zone_data(fd, distances);
        if (ret < 0) {
            fprintf(stderr, "Error reading zone data.\n");
        } else if (ret == 0) {
            printf("Zone 0: %5u mm, Zone 1: %5u mm, ..., Zone %d: %5u mm\n",
                   distances[0], distances[1], NUM_ZONES - 1, distances[NUM_ZONES - 1]);
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    i2c_write_reg16(fd, VL53L5CX_REG_SYSTEM_MODE_START, 0x00);
    close(fd);
    return 0;
}

