#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x33
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

/*
 * MLX75030 I2C protocol notes:
 *
 * The MLX75030 exposes a 16-bit register space via I2C.
 * A read of 2 bytes returns the distance in millimetres.
 *
 * The sensor must be configured via a preceding write of a 16-bit
 * command register (0x00) before distance reads can be issued.
 * The command register is written as a 2-byte sequence: [cmd_msb, cmd_lsb].
 *
 * The distance read command is 0x01.
 */

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Write a 16-bit command to the MLX75030 command register.
 * Returns 0 on success, -1 on failure.
 */
static int mlx75030_write_cmd(uint8_t msb, uint8_t lsb) {
    char buf[2];
    buf[0] = (char)msb;
    buf[1] = (char)lsb;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing command 0x%02X%02X: %s\n", msb, lsb, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit distance value from the MLX75030.
 * Returns 0 on success and stores the distance in *distance_mm.
 * Returns -1 on failure.
 */
static int mlx75030_read_distance(uint16_t *distance_mm) {
    char buf[2];

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    *distance_mm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Initialize the MLX75030 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int mlx75030_init(void) {
    /*
     * Issue a dummy write to the command register to select the
     * distance measurement mode.  The MLX75030 requires a command
     * before distance reads are valid.
     */
    if (mlx75030_write_cmd(0x00, 0x01) != 0) {
        fprintf(stderr, "Failed to initialize MLX75030\n");
        return -1;
    }
    return 0;
}

/*
 * Read distance with retry logic.
 * Returns 0 on success and stores the distance in *distance_mm.
 * Returns -1 on failure after all retries.
 */
static int read_distance_with_retry(uint16_t *distance_mm) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (mlx75030_read_distance(distance_mm) == 0) {
            return 0;
        }
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

/*
 * Log a distance measurement with a millisecond timestamp.
 */
static void log_distance(uint16_t distance_mm) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    printf("%s Distance: %u mm\n", timestamp, distance_mm);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mlx75030_init() != 0) {
        fprintf(stderr, "MLX75030 initialization failed. Sensor may be absent or bus error.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX75030 distance sensor running. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t distance_mm;
        if (read_distance_with_retry(&distance_mm) == 0) {
            log_distance(distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

