                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mlx75030_init() != 0) {
        fprintf(stderr, "MLX75030 initialization failed. Sensor may be absent or bus error.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX75030 distance sensor running. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t distance_mm;
        if (read_distance_with_retry(&distance_mm) == 0) {
            log_distance(distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

