/* VL53L4CX register addresses */
#define VL53L4CX_SOFT_RESET 0x0003
#define VL53L4CX_SYSTEM_MODE 0x0001
#define VL53L4CX_SYSTEM_INTERRUPT_CLEAR 0x0004
#define VL53L4CX_RESULT_INTERRUPT_STATUS 0x0010
#define VL53L4CX_RESULT_RANGE_STATUS 0x0014
#define VL53L4CX_RESULT_DISTANCE 0x0018

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device (reg 0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        fprintf(stderr, "Error writing register address 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, (char *)data, len) != len) {
        fprintf(stderr, "Error reading from I2C device (reg 0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l4cx_init(int handle) {
    /* Soft reset */
    if (i2c_write_reg16(handle, VL53L4CX_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000); /* 10 ms */
    if (i2c_write_reg16(handle, VL53L4CX_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000); /* 10 ms */

    /* Set mode to single shot */
    if (i2c_write_reg16(handle, VL53L4CX_SYSTEM_MODE, 0x00) != 0) return -1;

    return 0;
}

static int vl53l4cx_read_distance(int handle, uint16_t *distance) {
    uint8_t status;
    uint8_t data[2];

