    while (running) {
        uint16_t distance;
        int ret = vl53l4cx_read_distance(i2c_handle, &distance);

        if (ret == 0) {
            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));
            printf("Timestamp: %s, Distance: %u mm\n", timestamp, distance);
