            fprintf(stderr, "I2C communication error, continuing...\n");
        }
        /* ret == 1: no new data available */

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nExiting gracefully...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

