    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read model ID\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: Invalid model ID: 0x%02X (expected 0x%02X)\n", model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, VL53L1X_SOFT_RESET) < 0) {
        fprintf(stderr, "Error: Failed to soft reset sensor\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, VL53L1X_SYSTEM_MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging\n");
        return -1;
