        return 1;
    }

    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
        fprintf(stderr, "Error: Failed to read distance\n");
        return -1;
    }

    *distance = (dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

