#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x0010
#define VL53L1X_REG_SYSTEM_MODE_START 0x0016
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int msg_queue_id = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint16_t reg, uint8_t *data, int len) {
    uint8_t buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write address error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "I2C read error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int vl53l1x_init(int fd) {
    if (i2c_write_reg16(fd, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(fd, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    gpioDelay(10000);
    return 0;
