        fprintf(stderr, "VL53L1X initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if ((msg_queue_id = msgget(msg_queue_name, 0666)) == -1) {
        perror("msgget");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Distance monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (vl53l1x_read_distance(i2c_fd, &distance) == 0) {
            log_distance(distance);
            if (distance < DISTANCE_THRESHOLD) {
