#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MAX_DISTANCE_CM          400.0
#define MIN_DISTANCE_CM          2.0
#define BUZZER_THRESHOLD_CM      30.0
#define ECHO_TIMEOUT_US          30000   /* 30 ms */
#define SAMPLE_INTERVAL_US       100000 /* 100 ms */
#define TRIGGER_PULSE_US         10

/* Shared state between the echo interrupt and the main loop */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_ready = 0;
static volatile int      g_echo_error  = 0;

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for clean shutdown (Ctrl+C)                          */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo interrupt callback (runs in pigpio thread)                     */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_ready = 0;
        g_echo_error = 0;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_end_tick = tick;
        g_echo_ready = 1;
    }
    /* level == 2 (timeout) is handled in the main loop */
}

/* ------------------------------------------------------------------ */
/* Compute distance in cm from the elapsed tick delta                  */
/* ------------------------------------------------------------------ */
static float calculate_distance(uint32_t start_tick, uint32_t end_tick)
{
    uint32_t diff;
    float distance;

    /* Handle 32-bit tick wraparound (pigpio ticks are microseconds) */
    if (end_tick >= start_tick) {
        diff = end_tick - start_tick;
    } else {
        diff = (0xFFFFFFFFu - start_tick) + end_tick + 1u;
    }

    distance = (float)diff * SPEED_OF_SOUND_CM_PER_US / 2.0f;

