#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 20
#define LOG_FILE "gate_log.txt"
#define POLL_DELAY_US 100000

#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_MODE 0x0001
#define VL53L1X_REG_RANGE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

#define VL53L1X_SOFT_RESET_GO2_SHUD 0x00
#define VL53L1X_SOFT_RESET_GO1_SHUD 0x01
#define VL53L1X_SOFT_RESET_GO0_SHUD 0x02
#define VL53L1X_SOFT_RESET_GO1_VAL 0x01
#define VL53L1X_SOFT_RESET_GO0_VAL 0x01

#define VL53L1X_SYSTEM_MODE_SINGLE_SHOT 0x00
#define VL53L1X_SYSTEM_MODE_CONTINUOUS 0x01

#define VL53L1X_RANGE_STATUS_NEW_DATA 0x01

typedef struct {
    int i2c_fd;
    volatile sig_atomic_t running;
    volatile sig_atomic_t gate_open;
    volatile sig_atomic_t servo_angle;
} gate_t;

static gate_t gate;

static void signal_handler(int sig) {
    (void)sig;
    gate.running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t val) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, val };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, int len) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int vl53l1x_init(int fd) {
    if (i2c_write_reg16(fd, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_GO2_SHUD) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg16(fd, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_GO1_SHUD) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg16(fd, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_GO0_SHUD) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg16(fd, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_GO0_VAL) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE, VL53L1X_SYSTEM_MODE_SINGLE_SHOT) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance) {
    uint8_t status;
    int timeout = 100;
    do {
        if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
        if (--timeout == 0) return -1;
        usleep(10000);
    } while (!(status & VL53L1X_RANGE_STATUS_NEW_DATA));

    uint8_t buf[2];
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, buf, 2) < 0) return -1;
    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

static void gate_open(gate_t *g) {
    if (g->gate_open) return;
    g->gate_open = 1;
    printf("Gate OPEN\n");
    gpioServo(SERVO_PIN, 1500);
}

static void gate_close(gate_t *g) {
    if (!g->gate_open) return;
    g->gate_open = 0;
    printf("Gate CLOSE\n");
    gpioServo(SERVO_PIN, 0);
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: %s\n", ts, msg);
    fclose(fp);
}

static void rc_callback(int cmd, void *user) {
    (void)user;
    switch (cmd) {
        case 1: gate_open(&gate); break;
        case 2: gate_close(&gate); break;
        case 3: {
            uint16_t dist;
            if (vl53l1x_read_distance(gate.i2c_fd, &dist) == 0) {
                printf("Distance: %u cm\n", dist);
                if (dist < DISTANCE_THRESHOLD) gate_open(&gate);
                else gate_close(&gate);
            } else {
                log_event("I2C read error");
            }
            break;
        }
        default: break;
    }
}

static void cleanup(gate_t *g) {
    if (g->i2c_fd >= 0) {
        i2c_write_reg16(g->i2c_fd, VL53L1X_REG_SYSTEM_MODE, 0x00);
        close(g->i2c_fd);
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gate.i2c_fd = -1;
    gate.gate_open = 0;
    gate.servo_angle = 0;
    gate.running = 1;

    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO set mode failed\n");
        cleanup(&gate);
        return 1;
    }
    gpioSetPWMfrequency(SERVO_PIN, 50);
    gpioSetPWMrange(SERVO_PIN, 20000);
    gpioServo(SERVO_PIN, 0);

    char dev[32];
    snprintf(dev, sizeof(dev), "/dev/i2c-%d", I2C_BUS);
    gate.i2c_fd = open(dev, O_RDWR);
    if (gate.i2c_fd < 0) {
        fprintf(stderr, "I2C open failed\n");
        cleanup(&gate);
        return 1;
    }

    if (ioctl(gate.i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "I2C slave set failed\n");
        cleanup(&gate);
        return 1;
    }

    if (vl53l1x_init(gate.i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        cleanup(&gate);
        return 1;
    }

    printf("Gate control started. Ctrl+C to exit.\n");

    while (gate.running) {
        if (gate.gate_open) {
            if (gpioServo(SERVO_PIN, 1000) < 0) {
                log_event("Servo write error");
                break;
            }
        } else {
            if (gpioServo(SERVO_PIN, 0) < 0) {
                log_event("Servo write error");
                break;
            }
        }
        usleep(POLL_DELAY_US);
    }

    cleanup(&gate);
    return 0;
}

