        cleanup(&gate);
        return 1;
    }

    printf("Gate control started. Ctrl+C to exit.\n");

    while (gate.running) {
        if (gate.gate_open) {
            if (gpioServo(SERVO_PIN, 1000) < 0) {
                log_event("Servo write error");
                break;
            }
        } else {
            if (gpioServo(SERVO_PIN, 0) < 0) {
                log_event("Servo write error");
                break;
            }
        }
        usleep(POLL_DELAY_US);
    }

    cleanup(&gate);
    return 0;
}

