#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24

#define TRIGGER_PULSE_US  10
#define SAMPLE_PERIOD_US  200000
#define ECHO_TIMEOUT_US   30000
#define MIN_PULSE_US      100
#define MAX_PULSE_US      30000
#define ECHO_TIMEOUT_WARN 60000

static volatile uint32_t g_rising_tick = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_echo_seen = false;
static volatile bool     g_echo_active = false;

static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio tick is a 32-bit microsecond counter that wraps every ~72 min.
 * Compute the signed difference correctly across a wrap.
 */
static inline uint32_t tick_diff(uint32_t later, uint32_t earlier)
{
    return later - earlier;  /* unsigned subtraction wraps correctly */
}

/*
 * pigpio alert callback — runs in a dedicated thread.
 * rising_tick is the time the rising edge was detected.
 * falling_tick is the time the falling edge was detected.
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge — echo pulse starts */
        g_rising_tick = tick;
        g_echo_active = true;
    } else if (level == 0 && g_echo_active) {
        /* Falling edge — echo pulse ends */
        g_falling_tick = tick;
        g_echo_active = false;
        g_echo_seen = true;
    }
}

static void log_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    if (g_log_file) {
        fprintf(g_log_file, "%s,%.2f\n", timestamp, distance);
        fflush(g_log_file);
    }
}

static void log_warning(const char *msg)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s WARNING: %s\n", timestamp, msg);

    if (g_log_file) {
        fprintf(g_log_file, "%s,WARNING: %s\n", timestamp, msg);
        fflush(g_log_file);
    }
}

static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN LOW.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register alert callback for echo pin --- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIGGER: GPIO %d | ECHO: GPIO %d\n", TRIGGER_PIN, ECHO_PIN);
    printf("  Sampling every %d ms (5 Hz). Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_US / 1000);

    /* --- Main sampling loop --- */
    while (g_running) {
        /* Reset state for this cycle */
        g_echo_seen = false;
        g_echo_active = false;
        g_rising_tick = 0;
        g_falling_tick = 0;

        /* Generate 10 µs trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set TRIGGER_PIN HIGH.\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set TRIGGER_PIN LOW.\n");
            break;
        }

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        while (!g_echo_seen && g_running) {
            if (tick_diff(gpioTick(), wait_start) > ECHO_TIMEOUT_WARN) {
                log_warning("Timeout: no echo received within 60 ms");
                break;
            }
            gpioDelay(100);  /* poll every 100 µs */
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_active) {
            log_warning("No valid echo pulse detected");
            continue;
        }

        uint32_t pulse_us = tick_diff(g_falling_tick, g_rising_tick);

        if (pulse_us < MIN_PULSE_US) {
            log_warning("Pulse too short: noise (pulse < 100 µs)");
        } else if (pulse_us > MAX_PULSE_US) {
            log_warning("Pulse too long: timeout (pulse > 30000 µs)");
        } else {
            float distance = (float)pulse_us * 0.0343f / 2.0f;  /* cm */
            log_distance(distance);
        }

        /* Wait remainder of the sample period */
        uint32_t elapsed = gpioTick() - wait_start;
        if (elapsed < SAMPLE_PERIOD_US) {
            gpioDelay(SAMPLE_PERIOD_US - elapsed);
        }
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

