        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_distance(int handle, float *distance) {
    uint8_t status = 0;
    uint8_t data[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1;
    }
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) < 0) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }
    uint16_t raw = (data[0] << 8) | data[1];
    *distance = raw / 10.0f;
    return 0;
}

static void control_servo(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = 1000 + (angle * 1000 / 180);
    gpioServo(SERVO_PIN, pulse_width);
}

static void log_event(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance);
    fclose(fp);
}

static void open_gate(float distance) {
    if (distance < DISTANCE_OPEN_CM && !gate_open) {
        control_servo(90);
        gate_open = 1;
        log_event(distance);
        printf("Gate opened (Distance: %.2f cm)\n", distance);
    }
}

static void close_gate(float distance) {
    if (distance > DISTANCE_CLOSE_CM && gate_open) {
        control_servo(180);
        gate_closing = 1;
        gpioDelay(500000);
        if (!gate_closing_complete) {
            control_servo(0);
            gate_closing_complete = 1;
        }
        gate_open = 0;
        log_event(distance);
        printf("Gate closed (Distance: %.2f cm)\n", distance);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_DOWN);
    gpioServo(SERVO_PIN, 0);
    gpioWrite(SHUTDOWN_PIN, 0);
    gpioDelay(100000);
    gpioWrite(SHUTDOWN_PIN, 1);
    int i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("Smart Parking Gate System started.\n");
    while (running) {
        float distance = 0.0f;
        int ret = read_distance(i2c_handle, &distance);
        if (ret == 0) {
            open_gate(distance);
            close_gate(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }
        gpioDelay(100000);
    }
    gpioServo(SERVO_PIN, 0);
    gpioWrite(SHUTDOWN_PIN, 1);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Smart Parking Gate System stopped.\n");
    return 0;
}

