#include <unistd.h>
#include <stdbool.h>

#define I2C_BUS 1
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18
#define GPIO_TRIGGER 24

#define VL53L1X_REG_SOFT_RESET 0x000B
#define VL53L1X_REG_SYSTEM_MODE 0x0080
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_RESULT_PEAK_SIGNAL_RATE_RATIO 0x0098
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300
#define POLL_TIMEOUT_MS 100
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static bool motor_running = false;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, (char *)value, 1) < 0) return -1;
    return 0;
}

static int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    char read_buf[2];
    if (i2cReadDevice(handle, read_buf, 2) < 0) return -1;
    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write_byte(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (vl53l1x_write_byte(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    if (vl53l1x_write_byte(handle, VL53L1X_REG_SYSTEM_MODE, 0x00) < 0) return -1;
    return 0;
}

static int vl53l1x_start_measurement(int handle) {
    if (vl53l1x_write_byte(handle, VL53L1X_REG_SYSTEM_MODE, 0x40) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int vl53l1x_get_distance(int handle, uint16_t *distance) {
    uint8_t status;
    int retries = 0;
    int delay_ms = 10;

    while (retries < MAX_RETRIES) {
        if (vl53l1x_read_byte(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) {
            fprintf(stderr, "Error reading range status.\n");
            return -1;
        }
        if ((status & 0x01) == 0x01) break;
        gpioDelay(delay_ms * 1000);
        retries++;
        delay_ms *= 2;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Timeout waiting for measurement.\n");
        return -1;
    }

    if (vl53l1x_read_word(handle, VL53L1X_REG_RESULT_DISTANCE, distance) < 0) {
        fprintf(stderr, "Error reading distance.\n");
        return -1;
    }

    if (vl53l1x_write_byte(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error clearing interrupt.\n");
        return -1;
    }

    return 0;
}

static void motor_forward(void) {
    if (!motor_running) {
        gpioWrite(GPIO_MOTOR_FORWARD, 1);
        gpioWrite(GPIO_MOTOR_BACKWARD, 0);
        motor_running = true;
        printf("Motor running forward.\n");
    }
}

static void motor_backward(void) {
    if (motor_running) {
        gpioWrite(GPIO_MOTOR_FORWARD, 0);
        gpioWrite(GPIO_MOTOR_BACKWARD, 1);
        motor_running = false;
        printf("Motor running backward.\n");
    }
}

static void motor_stop(void) {
    if (motor_running) {
        gpioWrite(GPIO_MOTOR_FORWARD, 0);
        gpioWrite(GPIO_MOTOR_BACKWARD, 0);
        motor_running = false;
        printf("Motor stopped.\n");
    }
}

static void trigger_distance_reading(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio;
    (void)tick;
    (void)user;
    if (level == 1) {
        uint16_t distance;
        if (vl53l1x_get_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD_LOW) {
                motor_forward();
            } else if (distance > DISTANCE_THRESHOLD_HIGH) {
                motor_backward();
            } else {
                motor_stop();
            }
        } else {
            fprintf(stderr, "Failed to get distance.\n");
            motor_stop();
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, 0x29, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_DOWN);

    if (vl53l1x_start_measurement(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X start measurement failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, trigger_distance_reading, NULL) < 0) {
        fprintf(stderr, "Error setting ISR function.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Distance-based motor control started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    motor_stop();
    vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSTEM_MODE, 0x00);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

