#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x5C
#define MPR121_TOUCHSTATUS 0x00
#define MPR121_ECR      0x5E
#define MPR121_SOFTRESET 0x80
#define NUM_ELECTRODES  12
#define POLL_DELAY_US  50000

#define LED_PIN_0 17
#define LED_PIN_1 18
#define LED_PIN_2 27
#define LED_PIN_3 22

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, MPR121_SOFTRESET, &id) < 0) return -1;
    if (id != 0x01) {
        fprintf(stderr, "Unexpected MPR121 ID: 0x%02X (expected 0x01)\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg8(fd, MPR121_ECR, 0x0F) < 0) return -1;
    return 0;
}

static int read_touch_status(int fd, uint16_t *status) {
    uint8_t buf[2];
    if (write(fd, (uint8_t[]){MPR121_TOUCHSTATUS}, 1) != 1) {
        fprintf(stderr, "I2C write (touch status select) failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (touch status) failed: %s\n", strerror(errno));
        return -1;
    }
    *status = ((uint16_t)buf[1] << 8) | buf[0];
    return 0;
}

static void set_led_pattern(uint16_t status) {
    int p0 = (status & 1) ? 1 : 0;
    int p1 = (status & (1 << 1)) ? 1 : 0;
    int p2 = (status & (1 << 2)) ? 1 : 0;
    int p3 = (status & (1 << 3)) ? 1 : 0;
    gpioWrite(LED_PIN_0, p0);
    gpioWrite(LED_PIN_1, p1);
    gpioWrite(LED_PIN_2, p2);
    gpioWrite(LED_PIN_3, p3);
}

static void log_event(uint16_t status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - Electrodes: 0x%04X\n", ts, status);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, MPR121_ECR, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN_0, PI_OUTPUT);
    gpioSetMode(LED_PIN_1, PI_OUTPUT);
    gpioSetMode(LED_PIN_2, PI_OUTPUT);
    gpioSetMode(LED_PIN_3, PI_OUTPUT);
    gpioWrite(LED_PIN_0, 0);
    gpioWrite(LED_PIN_1, 0);
    gpioWrite(LED_PIN_2, 0);
    gpioWrite(LED_PIN_3, 0);

