#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define MIN_DISTANCE 2.0f
#define MAX_DISTANCE 400.0f
#define TIMEOUT_US   30000   /* 30 ms timeout for echo */
#define TRIGGER_PULSE_US 10   /* 10 µs trigger pulse */
#define TRIGGER_SETTLE_US 5   /* 5 µs settle before trigger */
#define LOOP_DELAY_US 1000000 /* 1 s between readings */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm.
 * Returns >= 0 on success, -1.0 on timeout, -2.0 on sensor-absent.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_SETTLE_US);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
