#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define MIN_PULSE_WIDTH_US  10
#define MAX_PULSE_WIDTH_US  25000
#define MIN_DISTANCE_M      0.001f
#define MAX_DISTANCE_M      4.0f
#define LOG_FILE_NAME       "distance_log.txt"
#define SAMPLE_PERIOD_S     1.0

/* Shared state between ISR and main thread */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_done  = false;
static volatile bool     g_valid      = false;
static volatile float    g_distance   = 0.0f;

static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* ISR callback (runs in pigpio thread)                                */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_done  = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        if (g_start_tick != 0) {
            g_end_tick = tick;
            g_echo_done = true;
        }
    }
    /* level == 2 indicates a timeout; ignored here */
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

static void log_data(float distance)
{
    char timestamp[32];
    get_timestamp(timestamp, sizeof(timestamp));

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s, %.2f\n", timestamp, distance);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Error: log file is not open.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable ISR first so no more callbacks fire during teardown */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down on ECHO_PIN so it reads LOW when idle */
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000); /* 50 ms settle */

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE_NAME);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register ISR on ECHO_PIN ---- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  Trigger: GPIO%d | Echo: GPIO%d\n", TRIGGER_PIN, ECHO_PIN);
    printf("  Logging to: %s\n", LOG_FILE_NAME);
    printf("  Sampling every %.1f s. Press Ctrl+C to exit.\n", SAMPLE_PERIOD_S);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Reset shared state for this measurement cycle */
        g_echo_done  = false;
        g_valid      = false;
        g_distance   = 0.0f;

        /* Generate 10 µs trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "Warning: failed to set TRIGGER_PIN high.\n");
        }
        gpioDelay(10); /* 10 µs */
        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "Warning: failed to set TRIGGER_PIN low.\n");
        }

        /* Wait for echo with timeout (~25 ms) */
        double wait_start = time_time();
        while (!g_echo_done && g_running) {
            if (time_time() - wait_start > 0.025) {
                break;
            }
            gpioDelay(100); /* 100 µs */
        }

        /* Compute pulse width with tick wrap-around handling */
        uint32_t pulse_width = 0;
        if (g_echo_done) {
            pulse_width = g_end_tick - g_start_tick;
        }

        /* Validate pulse width */
        if (pulse_width > 0 && pulse_width < MAX_PULSE_WIDTH_US) {
            /*
             * Speed of sound ~343 m/s =>
             *   time(s) = distance(m) / 34300
             *   distance(m) = time(s) * 34300
             */
            g_distance = (float)pulse_width * 0.0343f;

            if (g_distance >= MIN_DISTANCE_M && g_distance <= MAX_DISTANCE_M) {
                g_valid = true;
            } else {
                fprintf(stderr, "Warning: pulse width %.1f µs out of range (%.2f–%.2f µs).\n",
                        pulse_width, MIN_PULSE_WIDTH_US, MAX_PULSE_WIDTH_US);
            }
        } else {
            fprintf(stderr, "Warning: invalid pulse width %u µs (echo not received or out of range).\n",
                    pulse_width);
        }

        /* Log and print */
        if (g_valid) {
            log_data(g_distance);
            printf("Distance: %.2f m\n", g_distance);
        } else {
            printf("Distance: N/A\n");
        }

        /* Sleep for the remainder of the sample period */
        double elapsed = time_time() - wait_start;
        double remaining = SAMPLE_PERIOD_S - elapsed;
        if (remaining > 0.0) {
            gpioDelay((uint32_t)(remaining * 1e6));
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

