#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define POLL_DELAY_US 100000
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_MODE 0x0001
#define VL53L1X_REG_RANGE_START 0x0002
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0003
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, int len) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)data, len) != len) {
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset register.\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set system mode.\n");
        return -1;
    }

    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, float *distance_cm) {
    uint8_t status = 0;
    uint8_t dist_data[2];

    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0) {
        return -1;
    }

    if ((status & 0x01) == 0) {
        return 1;
    }

    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_data, 2) != 0) {
        return -1;
    }

    uint16_t raw_distance = (dist_data[0] << 8) | dist_data[1];
    *distance_cm = (float)raw_distance / 10.0f;
    return 0;
}

static void log_event(const char *message) {
    if (log_file == NULL) {
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", GATE_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GATE_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Gate control system started.");

    while (!terminate) {
        float distance_cm = 0.0f;
        int ret = vl53l1x_read_distance(i2c_handle, &distance_cm);

        if (ret == 0) {
            char log_msg[128];
            snprintf(log_msg, sizeof(log_msg), "Distance: %.2f cm", distance_cm);
            log_event(log_msg);

            if (distance_cm < DISTANCE_THRESHOLD_CM) {
                gpioWrite(GATE_GPIO, 1);
                log_event("Gate opened.");
            } else {
                gpioWrite(GATE_GPIO, 0);
                log_event("Gate closed.");
            }
        } else if (ret < 0) {
            log_event("Error: Failed to read distance from sensor.");
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Gate control system shutting down.");
    gpioWrite(GATE_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

