    if (pulse_width_us == 0) {
        return -1.0;
    }
    float distance = (float)pulse_width_us * 0.0343 / 2.0;
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0;
    }
    return distance;
}

static int update_moving_average(float new_distance) {
    if (history_filled) {
        distance_history[history_index] = distance_history[history_index - 1];
    } else {
        distance_history[0] = new_distance;
        history_filled = 1;
    }
    history_index = (history_index + 1) % MOVING_AVG_SIZE;
    float sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += distance_history[i];
    }
    return (int)(sum / MOVING_AVG_SIZE);
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Error: Servo angle %d out of range [%d, %d]\n", angle, SERVO_MIN_ANGLE, SERVO_MAX_ANGLE);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE_WIDTH_US +
        (int)((float)angle / SERVO_MAX_ANGLE * (SERVO_MAX_PULSE_WIDTH_US - SERVO_MIN_PULSE_WIDTH_US));
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse width %d\n", pulse_width);
        return -1;
    }
    return 0;
}

static int log_data(float distance, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, servo_angle) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set SERVO_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set ISR for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open distance_log.csv\n");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (deg)\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set SIGINT handler\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (new_pulse) {
            uint32_t pulse_width_us = pulse_width;
            float distance = calculate_distance(pulse_width_us);
            int servo_angle = update_moving_average(distance);

            if (distance < 0.0) {
                fprintf(stderr, "Warning: Invalid distance reading, setting servo to 90 degrees\n");
                set_servo_angle(90);
                servo_angle = 90;
            }

            if (log_data(distance, servo_angle) < 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }

            new_pulse = 0;
        }
        gpioDelay(TRIGGER_INTERVAL_MS * 1000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioDelay(SERVO_SETTLE_MS * 1000);

    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

