#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x52
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_GPIO 27
#define LOG_FILE "proximity.log"
#define I2C_BUS 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t interrupt_flag = 0;
static volatile int proximity_value = 0;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDRESS;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user_data;
    interrupt_flag = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", i2c_address, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(PROXIMITY_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", PROXIMITY_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(PROXIMITY_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d\n", PROXIMITY_GPIO);
        return -1;
    }
    if (gpioSetAlertFunc(PROXIMITY_GPIO, interrupt_handler) != 0) {
        fprintf(stderr, "Error setting alert function on GPIO %d\n", PROXIMITY_GPIO);
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    /*
     * Si1102 initialization sequence (simplified for pigpio driver):
     * 1. Write 0x00 to register 0x00 to reset the device.
     * 2. Write 0x01 to register 0x01 to set the measurement rate.
     * 3. Write 0x02 to register 0x02 to enable proximity interrupt.
     * 4. Write 0x03 to register 0x03 to set the interrupt threshold.
