     * Note: The Si1102 uses a proprietary command protocol. The
     * pigpio I2C interface does not support register-level access
     * to the Si1102. This example assumes the sensor is pre-configured
     * or that the driver layer handles the full initialization.
     */
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error writing to I2C device (reset): %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x01, 0x01) < 0) {
        fprintf(stderr, "Error writing to I2C device (config): %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) {
        fprintf(stderr, "Error writing to I2C device (enable interrupt): %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x03, 0x01) < 0) {
        fprintf(stderr, "Error writing to I2C device (threshold): %s\n", strerror(errno));
        return -1;
    }
    return 0;
