    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (interrupt_flag) {
            interrupt_flag = 0;
            if (i2cReadWordData(i2c_handle, 0x00) >= 0) {
                proximity_value = (int)i2cReadWordData(i2c_handle, 0x00);
                log_data(proximity_value);
            } else {
                fprintf(stderr, "Error reading proximity value: %s\n", strerror(errno));
            }
        }
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

