#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define MIN_FREQUENCY 200.0
#define MAX_FREQUENCY 2000.0
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  200.0
#define PWM_DUTY_CYCLE 128
#define ECHO_TIMEOUT_US 200000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    10000

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick;
    int timeout;

    trigger_sensor();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        if (timeout++ > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin did not go high (timeout).\n");
            return -1.0;
        }
        gpioDelay(1);
    }

    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (timeout++ > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin did not go low (timeout).\n");
            return -1.0;
        }
        gpioDelay(1);
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    double distance = (diff / 1000000.0) * 34300.0 / 2.0;
    return distance;
}

static double calculate_frequency(double distance) {
    if (distance < 0.0) return MIN_FREQUENCY;
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    double log_distance = log10(distance / MIN_DISTANCE + 1.0);
    double frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * log_distance;
    return frequency;
}

static void set_pwm_frequency(double frequency) {
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

    int pwm_freq = (int)frequency;
    if (gpioSetPWMfrequency(PWM_PIN, pwm_freq) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency to %d Hz.\n", pwm_freq);
        return;
    }
    gpioPWM(PWM_PIN, PWM_DUTY_CYCLE);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set echo pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set PWM pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioPWM(PWM_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double previous_frequency = MIN_FREQUENCY;
    int pwm_initialized = 0;

    while (!terminate) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: Invalid distance measurement. Using previous frequency.\n");
        } else {
            double frequency = calculate_frequency(distance);
            if (frequency != previous_frequency) {
                if (pwm_initialized) {
                    gpioPWM(PWM_PIN, 0);
                }
                set_pwm_frequency(frequency);
                previous_frequency = frequency;
                pwm_initialized = 1;
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

