            fprintf(stderr, "Error: Echo pin did not go high (timeout).\n");
            return -1.0;
        }
        gpioDelay(1);
    }

    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (timeout++ > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin did not go low (timeout).\n");
            return -1.0;
        }
        gpioDelay(1);
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    double distance = (diff / 1000000.0) * 34300.0 / 2.0;
    return distance;
}

static double calculate_frequency(double distance) {
    if (distance < 0.0) return MIN_FREQUENCY;
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    double log_distance = log10(distance / MIN_DISTANCE + 1.0);
    double frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * log_distance;
    return frequency;
}

static void set_pwm_frequency(double frequency) {
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

    int pwm_freq = (int)frequency;
    if (gpioSetPWMfrequency(PWM_PIN, pwm_freq) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency to %d Hz.\n", pwm_freq);
        return;
    }
    gpioPWM(PWM_PIN, PWM_DUTY_CYCLE);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set echo pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set PWM pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioPWM(PWM_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double previous_frequency = MIN_FREQUENCY;
    int pwm_initialized = 0;

    while (!terminate) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: Invalid distance measurement. Using previous frequency.\n");
        } else {
            double frequency = calculate_frequency(distance);
            if (frequency != previous_frequency) {
                if (pwm_initialized) {
                    gpioPWM(PWM_PIN, 0);
                }
                set_pwm_frequency(frequency);
                previous_frequency = frequency;
                pwm_initialized = 1;
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

