#define BUZZER_PIN      18
#define TRIGGER_PIN     23
#define ECHO_PIN        24

#define MIN_DISTANCE_CM  5.0f
#define MAX_DISTANCE_CM  50.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000
#define ECHO_TIMEOUT_US  100000
#define LOOP_DELAY_US    10000
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static float read_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    trigger_sensor();

    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout.\n");
            return -1.0f;
        }
    }

    uint32_t start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout.\n");
            return -1.0f;
        }
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start;
    float distance = (diff / 1000000.0f) * 34300.0f / 2.0f;

    if (distance < 0.0f || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance out of range (%.2f cm).\n", distance);
        return -1.0f;
    }

    return distance;
}

static int calculate_frequency(float distance) {
    if (distance < 0.0f) return -1;
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float freq = MIN_FREQUENCY_HZ +
        (distance - MIN_DISTANCE_CM) *
        (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
        (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;

    return (int)freq;
}

static void generate_tone(int frequency) {
    if (frequency <= 0) return;
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) != 0) {
        fprintf(stderr, "Warning: failed to set PWM frequency to %d Hz.\n", frequency);
        return;
    }
    if (gpioPWM(BUZZER_PIN, 128) != 0) {
        fprintf(stderr, "Warning: failed to start PWM on buzzer.\n");
    }
}

static void cleanup(void) {
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    float last_distance = MIN_DISTANCE_CM;
    int last_frequency = MIN_FREQUENCY_HZ;

    while (g_running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: sensor read failed, using last distance.\n");
            distance = last_distance;
        } else {
            last_distance = distance;
        }

        int frequency = calculate_frequency(distance);
        if (frequency < 0) {
            fprintf(stderr, "Error: frequency calculation failed, using last frequency.\n");
            frequency = last_frequency;
        } else {
            last_frequency = frequency;
        }

        generate_tone(frequency);
        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

