#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define CLOSE_THRESHOLD 10.0
#define TIMEOUT_US 50000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(int trigger_pin) {
    if (gpioWrite(trigger_pin, 1) < 0) return -1;
    gpioDelay(10);
    if (gpioWrite(trigger_pin, 0) < 0) return -1;
    return 0;
}

static double measure_distance(int trigger_pin, int echo_pin) {
    uint32_t start_tick, end_tick, timeout_tick;

    if (trigger_sensor(trigger_pin) < 0) return -1.0;

    start_tick = gpioTick();
    timeout_tick = start_tick + TIMEOUT_US;

    while (gpioRead(echo_pin) == 0) {
        if (gpioTick() > timeout_tick) return -1.0;
    }
    start_tick = gpioTick();

    while (gpioRead(echo_pin) == 1) {
        if (gpioTick() > timeout_tick) return -1.0;
    }
    end_tick = gpioTick();

    return (double)(end_tick - start_tick) / 2.0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance(TRIGGER_PIN, ECHO_PIN);

        if (distance < 0) {
            printf("Invalid reading (timeout)\n");
        } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading (%.2f cm)\n", distance);
