            if (distance < CLOSE_THRESHOLD) {
                printf(" Too close!");
            }
            printf("\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

