#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define GPIO_CS     8
#define LOG_FILE    "distance_log.csv"
#define READ_DELAY  100000  /* microseconds (100 ms) */

/* ICU-20201 register addresses (example values; adjust per datasheet) */
#define REG_DISTANCE_MSB 0x00
#define REG_DISTANCE_LSB 0x01
#define REG_CONFIG       0x02

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (gpioWrite(GPIO_CS, 0) < 0) {
        fprintf(stderr, "Error: failed to assert CS\n");
        return -1;
    }

    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        gpioWrite(GPIO_CS, 1);
        return -1;
    }

    if (gpioWrite(GPIO_CS, 1) < 0) {
        fprintf(stderr, "Error: failed to deassert CS\n");
        return -1;
    }

    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0, 0 };

    if (gpioWrite(GPIO_CS, 0) < 0) {
        fprintf(stderr, "Error: failed to assert CS\n");
        return -1;
    }

    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        gpioWrite(GPIO_CS, 1);
        return -1;
    }

    if (gpioWrite(GPIO_CS, 1) < 0) {
        fprintf(stderr, "Error: failed to deassert CS\n");
        return -1;
    }

    return 0;
}

static int read_distance(uint16_t *distance_mm) {
    uint8_t msb, lsb;

    if (spi_read_register(REG_DISTANCE_MSB, &msb) < 0) {
        return -1;
    }
    if (spi_read_register(REG_DISTANCE_LSB, &lsb) < 0) {
        return -1;
    }

    *distance_mm = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static void log_data(uint16_t distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%u\n", timestamp, (unsigned)distance_mm) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
    }
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", GPIO_CS);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_CS, 1) < 0) {
        fprintf(stderr, "Error: failed to initialise CS high\n");
        cleanup();
