    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", GPIO_CS);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_CS, 1) < 0) {
        fprintf(stderr, "Error: failed to initialise CS high\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Example configuration: enable continuous mode, 100 ms range interval */
    if (spi_write_register(REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to configure sensor\n");
    }

    printf("ICU-20201 distance logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t distance_mm;
        if (read_distance(&distance_mm) == 0) {
            log_data(distance_mm);
        } else {
            fprintf(stderr, "Warning: SPI read error, skipping log entry\n");
        }
