#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_I2C_ADDR 0x53
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.csv"
#define SAMPLE_INTERVAL_SEC 5

/* Si1175 register addresses (documented in datasheet) */
#define SI1175_REG_PART_ID      0x00
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23
#define SI1175_REG_COMMAND       0x30
#define SI1175_REG_RESPONSE      0x20

#define SI1175_CMD_RESET         0x01
#define SI1175_CMD_ALS_FORCE     0x06

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int si1175_reset(int fd) {
    if (i2c_write_reg8(fd, SI1175_REG_COMMAND, SI1175_CMD_RESET) < 0)
        return -1;
    usleep(10000); /* 10 ms reset settling time */
    return 0;
}

static int si1175_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1175_REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != 0x75) {
        fprintf(stderr, "Unexpected Part ID 0x%02X (expected 0x75). Sensor not present?\n", part_id);
        return -1;
    }
    if (si1175_reset(fd) < 0)
        return -1;
    /* Force an ALS measurement to verify functionality */
    if (i2c_write_reg8(fd, SI1175_REG_COMMAND, SI1175_CMD_ALS_FORCE) < 0)
        return -1;
    usleep(10000);
    return 0;
}

static int read_als_visible(int fd, uint16_t *als_vis) {
    uint8_t resp;
    if (i2c_read_reg8(fd, SI1175_REG_RESPONSE, &resp) < 0)
        return -1;
    if (resp & 0x01) {
        fprintf(stderr, "Si1175 command incomplete (response bit set).\n");
        return -1;
    }
    if (i2c_read_reg16(fd, SI1175_REG_ALS_VIS_DATA0, als_vis) < 0)
        return -1;
    return 0;
}

static int log_data(FILE *fp, uint16_t als_vis) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%u\n", timestamp, (unsigned)als_vis) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (si1175_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1175 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,als_visible\n");
        fflush(g_log_fp);
    }

    printf("Si1175 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als_vis;
        if (read_als_visible(g_i2c_fd, &als_vis) < 0) {
            fprintf(stderr, "Read error; continuing.\n");
        } else {
            if (log_data(g_log_fp, als_vis) < 0) {
                fprintf(stderr, "Logging error; continuing.\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

