#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define SPEED_OF_SOUND 34300.0
#define DISTANCE_THRESHOLD 20.0

/* Shared state between main thread and ISR */
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_state = 0;   /* 0=idle, 1=rising seen, 2=falling seen */

static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* ISR callback — runs in pigpio thread, keep it minimal               */
/* ------------------------------------------------------------------ */
static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        start_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state == 1) {
        end_tick = tick;
        echo_state = 2;
    }
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 µs pulse on the trigger pin                            */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);   /* 10 µs high */
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Compute distance (cm) from pulse width (µs)                          */
/* ------------------------------------------------------------------ */
static double calculate_distance(uint32_t pulse_us)
{
    return (double)pulse_us * SPEED_OF_SOUND / 2000000.0;
}

/* ------------------------------------------------------------------ */
/* Set buzzer on or off                                                 */
/* ------------------------------------------------------------------ */
static void set_buzzer(int on)
{
    gpioWrite(BUZZER_PIN, on ? 1 : 0);
}

/* ------------------------------------------------------------------ */
/* SIGINT handler — clean shutdown                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* --- Register ISR on rising edge --- */
    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install SIGINT handler --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler.\n");
        gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (running) {
        /* Reset shared state before triggering */
        echo_state = 0;
        start_tick = 0;
        end_tick   = 0;

        trigger_sensor();

        /* Wait for echo ISR to set the flags (max ~5 m round trip ~100 ms) */
        uint32_t wait_start = gpioTick();
        while (echo_state != 2 && running) {
            if ((gpioTick() - wait_start) > 100000) {
                fprintf(stderr, "Warning: echo timeout (no falling edge).\n");
                echo_state = 0;
                break;
            }
            gpioDelay(100);   /* 100 µs */
        }

        if (echo_state == 2) {
            uint32_t pulse_us = end_tick - start_tick;
            double distance = calculate_distance(pulse_us);

            printf("Distance: %.2f cm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                set_buzzer(1);
            } else {
                set_buzzer(0);
            }
        }

        /* Sleep 1 s between measurements */
        sleep(1);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

