#define SERVO_MAX_PULSE_US 2500

#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US   100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode.\n");
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);

    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick;

    trigger_sensor();

    /* Wait for echo rising edge (timeout) */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    end_tick = gpioTick();

    double pulse_duration_us = (double)(end_tick - start_tick);
    double distance_cm = (pulse_duration_us * SPEED_OF_SOUND_CM_PER_US) / 2.0;

    return distance_cm;
}

static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = SERVO_MIN_PULSE_US +
        (int)((long)angle * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) / 180);

    gpioServo(SERVO_PIN, pulse_width);
}

static void cleanup(void) {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Warning: sensor read timeout, retrying...\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle;
        if (distance >= MAX_DISTANCE_CM) {
            angle = 0;
        } else if (distance <= MIN_DISTANCE_CM) {
            angle = 180;
        } else {
            angle = (int)((MAX_DISTANCE_CM - distance) /
                          (MAX_DISTANCE_CM - MIN_DISTANCE_CM) * 180.0);
        }

        set_servo_angle(angle);
        printf("Distance: %.2f cm, Servo Angle: %d°\n", distance, angle);

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

