#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x44
#define CONFIG_REG 0x01
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONVERSION_DELAY_US 10000
#define READ_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SI7005_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor(float *temperature, float *humidity) {
    char config = 0x10;
    char buf[2];

    if (i2cWriteDevice(i2c_handle, &config, 1) != 0) {
        fprintf(stderr, "Error writing config register\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    if (i2cWriteDevice(i2c_handle, (char *)TEMP_REG, 1) != 0) {
        fprintf(stderr, "Error writing temperature register address\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    *temperature = -46.85 + 175.72 * ((float)raw_temp / 65536.0);

    if (i2cWriteDevice(i2c_handle, (char *)HUMID_REG, 1) != 0) {
        fprintf(stderr, "Error writing humidity register address\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }

    uint16_t raw_hum = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    *humidity = -6.0 + 125.0 * ((float)raw_hum / 65536.0);

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;
    while (running) {
        if (read_sensor(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Re-initializing I2C.\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }
        }
        gpioDelay(READ_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

