#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* Global handle for signal handler */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Initialize MPU-6050: verify device, wake up, set sample rate */
static int init_mpu6050(int handle) {
    int who_am_i = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: I2C read failed for WHO_AM_I register (pigpio error %d)\n", who_am_i);
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Sensor not present.\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilization delay */

    /* Set sample rate to 1 kHz (0x00) and default range (0x00) */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to configure PWR_MGMT_1\n");
        return -1;
    }

    return 0;
}

/* Read 14 bytes of raw sensor data and parse into int16 values */
static int read_mpu6050_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                              int16_t *gx, int16_t *gy, int16_t *gz,
                              int16_t *temp) {
    char buf[14];

    /* Read 14 bytes starting at ACCEL_XOUT_H (0x3B) */
    int bytes_read = i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buf, 14);
    if (bytes_read != 14) {
        fprintf(stderr, "Error: I2C block read failed (read %d bytes, expected 14)\n", bytes_read);
        return -1;
    }

    /* Parse big-endian int16 values */
