#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x57
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

int read_temperature(int fd, float *ambient, float *object) {
    uint8_t cmd[2] = {0x44, 0x00};
    uint8_t data[4];

    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);

    if (read(fd, data, 4) != 4) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_ambient = (data[0] << 8) | data[1];
    uint16_t raw_object = (data[2] << 8) | data[3];

    *ambient = (float)raw_ambient * 0.02 - 273.15;
    *object = (float)raw_object * 0.02 - 273.15;

    return 0;
}

int log_temperature(FILE *fp, float ambient, float object) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, ambient, object) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = init_i2c(I2C_BUS, MLX90614_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float ambient, object;
        if (read_temperature(i2c_fd, &ambient, &object) == 0) {
            if (log_temperature(log_file, ambient, object) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }
        sleep(READ_INTERVAL);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

