#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x24
#define LOG_FILE "pressure_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MEASUREMENT_DELAY_US 1000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int init_sensor(void) {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SDP810_ADDR, i2c_handle);
        return -1;
    }

    uint8_t cmd[2] = {0x36, 0x1F};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error configuring SDP810 for continuous measurement\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_sensor_data(float *pressure, float *temperature) {
    uint8_t data[9];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading sensor data: expected 9 bytes, got %d\n", bytes_read);
        return -1;
    }

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CRC error in differential pressure data\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "CRC error in scale factor data\n");
        return -1;
    }

    int16_t dp_raw = (data[0] << 8) | data[1];
    int16_t temp_raw = (data[3] << 8) | data[4];
    int16_t dp_scale = (data[6] << 8) | data[7];
    int16_t temp_scale = (data[9] << 8) | data[10];

    if (dp_scale == 0 || temp_scale == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)dp_raw / dp_scale;
    *temperature = (float)temp_raw / temp_scale;

    return 0;
}

static int log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Differential Pressure (Pa),Temperature (C)\n");
        fflush(log_file);
    }

    float pressure, temperature;
    while (running) {
        if (read_sensor_data(&pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

