    return i2cWriteDevice(handle, (char *)cmd, 2);
}

static int sdp31_read_measurement(int handle, uint8_t *buf, int len) {
    return i2cReadDevice(handle, (char *)buf, len);
}

static int sdp31_crc4(const uint8_t *data, int len, uint8_t *crc) {
    uint8_t c = 0x05;
    for (int i = 0; i < len; i++) {
        c ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (c & 0x08) c = (c << 1) ^ 0x07;
