#include <pigpio.h>

#define I2C_BUS 1
#define SI7015_ADDR 0x50
#define MEASURE_TEMP_NO_HOLD 0xE3
#define MEASURE_HUMID_NO_HOLD 0xE5
#define LOG_FILE "sensor_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define MEASURE_TIMEOUT_MS 20

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_measurement(int handle, uint8_t cmd, uint16_t *raw) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(handle, cmd);
        if (result < 0) {
            fprintf(stderr, "I2C write failed (cmd 0x%02X), retry %d/%d: %s\n",
                    cmd, retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASURE_TIMEOUT_MS * 1000);

        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }

        fprintf(stderr, "I2C read failed (cmd 0x%02X), retry %d/%d: %s\n",
                cmd, retries + 1, MAX_RETRIES, strerror(errno));
        retries++;
        gpioDelay(10000);
    }

    return -1;
}

static int read_sensor(int handle, float *temperature, float *humidity) {
    uint16_t raw_temp, raw_hum;

    if (read_measurement(handle, MEASURE_TEMP_NO_HOLD, &raw_temp) != 0) {
        fprintf(stderr, "Failed to read temperature\n");
        return -1;
    }

    if (read_measurement(handle, MEASURE_HUMID_NO_HOLD, &raw_hum) != 0) {
        fprintf(stderr, "Failed to read humidity\n");
        return -1;
    }

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_hum / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (fp == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, SI7015_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_sensor(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(log_file, temperature, humidity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            } else {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                       temperature, humidity);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

