#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x14
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_SEC 1

#define CMD_START_PERIODIC_MEASUREMENT 0x2001
#define CMD_STOP_PERIODIC_MEASUREMENT  0x2011
#define CMD_READ_MEASUREMENT            0x200F

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT       0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(int handle, uint16_t cmd) {
    uint8_t buf[2];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to write command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int start_periodic_measurement(int handle) {
    if (send_command(handle, CMD_START_PERIODIC_MEASUREMENT) != 0)
        return -1;
    return 0;
}

static int stop_periodic_measurement(int handle) {
    if (send_command(handle, CMD_STOP_PERIODIC_MEASUREMENT) != 0)
        return -1;
    return 0;
}

static int read_measurement(int handle, uint16_t *co2, float *temperature, float *humidity) {
    uint8_t buf[9];
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from sensor\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CO2 CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    *co2 = (buf[0] << 8) | buf[1];
    *temperature = (buf[3] << 8) | buf[4];
    *humidity = (buf[6] << 8) | buf[7];
    return 0;
}

static void log_data(FILE *fp, uint16_t co2, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device on bus %d at address 0x%02X (handle=%d)\n",
                I2C_BUS, SCD40_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    if (start_periodic_measurement(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Periodic measurement started. Waiting %d seconds for first data...\n", MEASUREMENT_DELAY_SEC);
    sleep(MEASUREMENT_DELAY_SEC);

    while (g_running) {
        uint16_t co2 = 0;
        float temperature = 0.0f;
        float humidity = 0.0f;

        if (read_measurement(g_i2c_handle, &co2, &temperature, &humidity) == 0) {
            log_data(g_log_file, co2, temperature, humidity);
            printf("CO2: %u ppm, Temperature: %.2f C, Humidity: %.2f %%\n", co2, temperature, humidity);
        } else {
            fprintf(stderr, "Warning: Failed to read measurement, will retry next cycle\n");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    stop_periodic_measurement(g_i2c_handle);
    i2cClose(g_i2c_handle);
    fclose(g_log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

