#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_ADDR 0x28
#define I2C_BUS 1
#define LED_PIN 17
#define CO2_THRESHOLD 1000.0
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 5000000

#define SCD40_CMD_START_CONT_MEAS 0x1000
#define SCD40_CMD_STOP_MEAS 0x0000
#define SCD40_CMD_READ_MEAS 0x0001
#define SCD40_CMD_RESET 0x8003

#define SCD40_DATA_READY_BIT 0x80
#define SCD40_CRC_POLY 0x31

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ SCD40_CRC_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int scd40_write_command(uint16_t cmd) {
    uint8_t buf[2];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd40_read_data(uint8_t *data, int len) {
    if (i2cReadDevice(i2c_handle, (char *)data, len) != len) {
        fprintf(stderr, "Error: I2C read failed (expected %d bytes)\n", len);
        return -1;
    }
    return 0;
}

static int scd40_init(void) {
    if (scd40_write_command(SCD40_CMD_RESET) != 0) {
        fprintf(stderr, "Error: SCD40 reset failed\n");
        return -1;
    }
    gpioDelay(10000);

    if (scd40_write_command(SCD40_CMD_START_CONT_MEAS) != 0) {
        fprintf(stderr, "Error: SCD40 start measurement failed\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int scd40_stop(void) {
    return scd40_write_command(SCD40_CMD_STOP_MEAS);
}

static int scd40_read_measurement(float *co2, float *temperature, float *humidity) {
    uint8_t data[9];
    if (scd40_write_command(SCD40_CMD_READ_MEAS) != 0) {
        fprintf(stderr, "Error: SCD40 read measurement command failed\n");
        return -1;
    }
    gpioDelay(10000);

    if (scd40_read_data(data, 9) != 0) {
        fprintf(stderr, "Error: SCD40 read measurement data failed\n");
        return -1;
    }

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: CO2 CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t co2_raw = (data[0] << 8) | data[1];
    uint16_t temp_raw = (data[3] << 8) | data[4];
    uint16_t hum_raw = (data[6] << 8) | data[7];

    *co2 = (float)co2_raw / 100.0f;
    *temperature = (float)temp_raw / 100.0f;
    *humidity = (float)hum_raw / 100.0f;

    return 0;
}

static void add_to_buffer(time_t timestamp, float co2, float temperature, float humidity) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].co2 = co2;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Sensor Data Buffer ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&circular_buffer[idx].timestamp);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] CO2: %.2f ppm, Temp: %.2f C, Hum: %.2f %%\n",
               time_str, circular_buffer[idx].co2, circular_buffer[idx].temperature, circular_buffer[idx].humidity);
    }
    printf("--- End of Buffer ---\n\n");
}

static void control_led(float co2) {
    if (co2 > CO2_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed on bus %d addr 0x%02X\n", I2C_BUS, SCD40_ADDR);
        gpioTerminate();
        return 1;
    }

    if (scd40_init() != 0) {
        fprintf(stderr, "Error: SCD40 initialization failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float co2, temperature, humidity;
        if (scd40_read_measurement(&co2, &temperature, &humidity) == 0) {
            time_t now = time(NULL);
            add_to_buffer(now, co2, temperature, humidity);
            printf("CO2: %.2f ppm, Temp: %.2f C, Hum: %.2f %%\n", co2, temperature, humidity);
            control_led(co2);
            print_buffer();
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    scd40_stop();
    gpioWrite(LED_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

