#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define POLL_INTERVAL_SEC 5
#define TIMEOUT_US 50000
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
    if (log_file) {
        fprintf(log_file, "%s,ERROR,%s\n", ts, msg);
        fflush(log_file);
    }
}

static void log_reading(float temp) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f\n", ts, temp);
    fflush(log_file);
}

/*
 * Wait for the specified edge with a microsecond timeout using pigpio's
 * call() API. Returns 0 on success, -1 on timeout or error.
 */
static int wait_for_edge(int pin, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (running) {
        int val = gpioRead(pin);
        if (val == level) return 0;
        if (gpioTick() - start > timeout_us) return -1;
    }
    return -1;
}

/*
 * Measure the high-pulse width in microseconds.
 * Returns 0 on success, -1 on timeout or error.
 */
static int measure_high_pulse(int pin, uint32_t *high_us) {
    uint32_t start = gpioTick();
    if (wait_for_edge(pin, 0, TIMEOUT_US) < 0) return -1;
    if (!running) return -1;
    if (wait_for_edge(pin, 1, TIMEOUT_US) < 0) return -1;
    if (!running) return -1;
    if (wait_for_edge(pin, 0, TIMEOUT_US) < 0) return -1;
    *high_us = gpioTick() - start;
    return 0;
}

/*
 * Measure the total cycle width in microseconds.
 * Returns 0 on success, -1 on timeout or error.
 */
static int measure_cycle(int pin, uint32_t *cycle_us) {
    uint32_t start = gpioTick();
    if (wait_for_edge(pin, 1, TIMEOUT_US) < 0) return -1;
    if (!running) return -1;
    if (wait_for_edge(pin, 0, TIMEOUT_US) < 0) return -1;
    *cycle_us = gpioTick() - start;
    return 0;
}

/*
 * Convert high-pulse width (us) to temperature (°C).
 * TMP05: T = 125 - (high_us / 1000)
 * Returns 0 on success, -1 on invalid input.
 */
static int convert_to_celsius(uint32_t high_us, float *temp) {
    if (high_us == 0) return -1;
    *temp = 125.0f - (high_us / 1000.0f);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int consecutive_errors = 0;

    while (running) {
        uint32_t high_us = 0, cycle_us = 0;
        float temp = 0.0f;

        if (measure_high_pulse(GPIO_PIN, &high_us) < 0) {
            log_error("Timeout waiting for PWM edge");
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_error("SENSOR MALFUNCTION");
                break;
            }
            sleep(POLL_INTERVAL_SEC);
            continue;
        }
        consecutive_errors = 0;

        if (measure_cycle(GPIO_PIN, &cycle_us) < 0) {
            log_error("Timeout waiting for PWM cycle");
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_error("SENSOR MALFUNCTION");
                break;
            }
            sleep(POLL_INTERVAL_SEC);
            continue;
        }
        consecutive_errors = 0;

        if (convert_to_celsius(high_us, &temp) < 0) {
            log_error("Invalid temperature calculation (high_us=0)");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (temp < -40.0f || temp > 150.0f) {
            log_error("Temperature out of valid range");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        log_reading(temp);
        sleep(POLL_INTERVAL_SEC);
    }

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

