#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x25
#define MEASURE_CMD 0x2C
#define MEASURE_HIGH_REP 0x10
#define MEASURE_CMD_HIGH_REP 0x2C | MEASURE_HIGH_REP
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 1
#define MEASUREMENT_DELAY_US 15000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = { (uint8_t)(MEASURE_CMD_HIGH_REP >> 8), (uint8_t)(MEASURE_CMD_HIGH_REP & 0xFF) };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed.\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed.\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    uint16_t hum_raw = (buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static void simulate_greenhouse_offset(float *temp, float *hum) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    double t_offset = 2.0 * sin(2.0 * M_PI * (double)utc->tm_hour / 24.0);
    double h_offset = 5.0 * sin(2.0 * M_PI * (double)utc->tm_hour / 24.0);

    *temp += t_offset;
    *hum += h_offset;
}

static void log_data(FILE *fp, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", utc);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temp, hum;
    while (running) {
        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_sht35(i2c_handle, &temp, &hum) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                sleep(RETRY_DELAY_SEC);
            }
        }

        if (ok) {
            simulate_greenhouse_offset(&temp, &hum);
            log_data(log_file, temp, hum);
        } else {
            fprintf(stderr, "Error: Failed to read sensor after %d attempts.\n", MAX_RETRIES);
            log_data(log_file, NAN, NAN);
        }

        for (int s = 0; s < SAMPLE_INTERVAL_SEC && running; s++) {
            sleep(1);
        }
    }

    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

