        return 1;
    }

    if (i2c_write_cmd(i2c_fd, MEASURE_CMD) < 0) {
        fprintf(stderr, "Sensor not responding at address 0x%02X\n", SDP810_ADDR);
        close(i2c_fd);
        return 1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float pressure, temperature;
        if (read_sensor_data(i2c_fd, &pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, skipping log entry\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

