        fprintf(stderr, "Error: I2C open failed on bus %d addr 0x%02X (err %d)\n",
                I2C_BUS, SHT35_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (g_running) {
        if (read_sht35(g_i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(CSV_FILENAME, temperature, humidity) != 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return 0;
}

