#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x5A
#define MEASURE_CMD    0xE3
#define RESET_CMD      0xFE
#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (int)n;
    }
    return 0;
}

static int read_sensor(int fd, float *temperature, float *humidity) {
    uint8_t buf[3];
    int16_t raw_h, raw_t;

    if (i2c_write_cmd(fd, MEASURE_CMD) < 0)
        return -1;

    /* Si7021 measurement conversion takes ~12 ms; wait a bit longer for margin */
    usleep(15000);

    if (i2c_read_bytes(fd, buf, 3) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on humidity data\n");
        return -1;
    }
    if (crc8(buf + 1, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    raw_h = (int16_t)((buf[0] << 8) | buf[1]);
    raw_t = (int16_t)((buf[1] << 8) | buf[2]);

    *humidity = (float)raw_h / 10.0f;
    *temperature = (float)raw_t / 10.0f;

    /* Sanity range checks */
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.1f%%\n", *humidity);
        return -1;
    }
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.1f°C\n", *temperature);
        return -1;
    }
    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.1f,%.1f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

static void log_error(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    }
    fclose(fp);
}

static void reset_sensor(int fd) {
    if (i2c_write_cmd(fd, RESET_CMD) < 0)
        return;
    usleep(15000);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    /* Quick presence check: try a measurement */
    uint8_t dummy;
    if (i2c_read_bytes(g_i2c_fd, &dummy, 1) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X on %s\n",
                SI7021_ADDR, I2C_BUS);
        close(g_i2c_fd);
        return 1;
    }

    printf("Si7021 greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int ok = 0;

        /* Poll until data is ready or timeout */
        for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS && g_running; elapsed += 5) {
            if (read_sensor(g_i2c_fd, &temperature, &humidity) == 0) {
                ok = 1;
                break;
            }
            reset_sensor(g_i2c_fd);
            usleep(5000);
        }

        if (ok) {
            if (log_data(temperature, humidity) < 0)
                fprintf(stderr, "Failed to log data\n");
        } else {
            log_error("Sensor read failed after timeout");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return 0;
}

