    if (i2c_read_bytes(g_i2c_fd, &dummy, 1) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X on %s\n",
                SI7021_ADDR, I2C_BUS);
        close(g_i2c_fd);
        return 1;
    }

    printf("Si7021 greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int ok = 0;

        /* Poll until data is ready or timeout */
        for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS && g_running; elapsed += 5) {
            if (read_sensor(g_i2c_fd, &temperature, &humidity) == 0) {
                ok = 1;
                break;
            }
            reset_sensor(g_i2c_fd);
            usleep(5000);
        }

        if (ok) {
            if (log_data(temperature, humidity) < 0)
                fprintf(stderr, "Failed to log data\n");
        } else {
            log_error("Sensor read failed after timeout");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return 0;
}

