    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting data acquisition on SDP810-500Pa at 0x%02X...\n", SDP810_ADDR);

    while (running) {
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
