    int duty_cycle = (int)(flow_rate / 100.0f);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float pressure, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure, flow_rate;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &pressure) == 0) {
            flow_rate = calculate_flow_rate(pressure);
            if (set_fan_speed(FAN_GPIO, flow_rate) != 0) {
                fprintf(stderr, "Error setting fan speed\n");
            }
            log_data(log_file, pressure, flow_rate);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioPWM(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

