#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LPS33HW_ADDR 0x5C
#define LOG_FILE "environmental_data.txt"

/* LPS33HW register addresses */
#define LPS33HW_REG_WHO_AM_I   0x0F
#define LPS33HW_REG_CTRL_REG1  0x10
#define LPS33HW_REG_CTRL_REG2  0x11
#define LPS33HW_REG_PRESS_OUT  0x28
#define LPS33HW_REG_TEMP_OUT   0x2B

#define LPS33HW_WHO_AM_I_VAL   0x5C

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_pressure(int handle, float *pressure)
{
    char buffer[2];
    int rc = i2cReadI2CBlockData(handle, LPS33HW_REG_PRESS_OUT, buffer, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", rc);
        return -1;
    }
    int32_t raw = ((int32_t)(uint8_t)buffer[0] << 8) | (uint8_t)buffer[1];
    *pressure = (float)raw / 100.0f;
    return 0;
}

static int read_temperature(int handle, float *temperature)
{
    char buffer[2];
    int rc = i2cReadI2CBlockData(handle, LPS33HW_REG_TEMP_OUT, buffer, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", rc);
        return -1;
    }
    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buffer[0] << 8) | (uint8_t)buffer[1]);
    *temperature = (float)raw / 100.0f;
    return 0;
}

static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure, temperature);
    fflush(fp);
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, LPS33HW_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i = 0;
    if (read_register(g_i2c_handle, LPS33HW_REG_WHO_AM_I, &who_am_i) != 0) {
        cleanup();
        return 1;
    }
    if (who_am_i != LPS33HW_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                LPS33HW_WHO_AM_I_VAL, who_am_i);
        cleanup();
        return 1;
    }

    /* CTRL_REG1: PD=1, ODR=1Hz (0x01) */
    if (write_register(g_i2c_handle, LPS33HW_REG_CTRL_REG1, 0x01) != 0) {
        cleanup();
        return 1;
    }
    /* CTRL_REG2: BDU=1, SIM=0 (0x00) */
    if (write_register(g_i2c_handle, LPS33HW_REG_CTRL_REG2, 0x00) != 0) {
        cleanup();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        int p_ok = read_pressure(g_i2c_handle, &pressure);
        int t_ok = read_temperature(g_i2c_handle, &temperature);

        if (p_ok == 0 && t_ok == 0) {
            if (log_data(g_log_file, pressure, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            if (log_data(g_log_file, 0.0f, 0.0f) != 0) {
                fprintf(stderr, "Error logging error message\n");
            }
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

