#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x44
#define LED_PIN        17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0
#define POLL_INTERVAL  1.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static int read_temperature(int handle, float *out) {
    char buf[2];
    int  rc;

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (rc=%d)\n", rc);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *out = (float)raw / 100.0f;
    return 0;
}

int main(void) {
    int handle = -1;
    CircularBuffer cb;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X (err=%d)\n",
                I2C_BUS, I2C_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    cb_init(&cb);

    while (running) {
        float temp;
        if (read_temperature(handle, &temp) == 0) {
            cb_add(&cb, temp);
            float avg = cb_average(&cb);
            printf("Temperature: %.2f C, Average: %.2f C\n", temp, avg);

            if (avg > TEMP_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Skipping iteration due to read error\n");
        }
        time_sleep(POLL_INTERVAL);
    }

    gpioWrite(LED_PIN, 0);
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

