#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x14
#define LOG_FILE "air_quality.log"
#define CO2_LOW_THRESHOLD 800
#define CO2_HIGH_THRESHOLD 1200
#define MEASUREMENT_INTERVAL 5
#define MAX_RETRIES 3

#define SCD30_CMD_START_MEASUREMENT 0x0001
#define SCD30_CMD_READ_MEASUREMENT 0x0002
#define SCD30_CMD_STOP_MEASUREMENT 0x0003
#define SCD30_CMD_SOFT_RESET 0x0004

#define SCD30_DATA_READY_BIT 0x01
#define SCD30_ERROR_BIT 0x02
#define SCD30_CRC_POLY 0x07

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", t);
    fprintf(stderr, "%s ERROR: %s (errno: %s)\n", ts, msg, strerror(errno));
    if (log_file) {
        fprintf(log_file, "%s ERROR: %s (errno: %s)\n", ts, msg, strerror(errno));
        fflush(log_file);
    }
}

static int scd30_write_cmd(int handle, uint16_t cmd) {
    char buf[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int scd30_read_data(int handle, uint8_t *data, int len) {
    if (i2cReadDevice(handle, (char *)data, len) != len) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

static int scd30_start_measurement(int handle) {
    return scd30_write_cmd(handle, SCD30_CMD_START_MEASUREMENT);
}

static int scd30_stop_measurement(int handle) {
