#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x24
#define READ_INTERVAL  1.0
#define CONV_DELAY_US  45000

/* SDP810-125Pa: differential pressure, ±125 Pa, 0.0125 Pa resolution */
#define PRESSURE_SCALE  0.0125f

/* SDP8xx: trigger continuous conversion by writing 0x00 to the command register */
#define TRIGGER_CMD     0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion sensors */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read one 9-byte measurement frame from the SDP810.
 * Layout (big-endian, as returned by the sensor):
 *   [0]  word_addr | [1]  word_MSB | [2]  word_LSB | [3]  word_CRC
 *   [4]  word_addr | [5]  word_MSB | [6]  word_LSB | [7]  word_CRC
 *   [8]  word_addr | [9]  word_MSB | [10] word_LSB | [11] word_CRC
 *
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_sensor_data(float *pressure, float *temperature)
{
    uint8_t buf[9];
    int rc;

    /* Trigger a continuous conversion by writing 0x00 to the command register */
    rc = i2cWriteByte(g_i2c_handle, TRIGGER_CMD);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByte(trigger) failed (rc=%d)\n", rc);
        return -1;
    }

    /* Wait for the conversion to complete (max ~45 ms for 0.0125 Pa mode) */
    gpioDelay(CONV_DELAY_US);

    /* Read 9 bytes: pressure(3) + temperature(3) + scale_factor(3) */
    rc = i2cReadDevice(g_i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 9)\n", rc);
        return -1;
    }

    /* Validate CRC for each 3-byte word */
    for (int i = 0; i < 9; i += 3) {
        if (crc8(&buf[i], 2) != buf[i + 2]) {
            fprintf(stderr, "Error: CRC mismatch on word %d\n", i / 3);
            return -2;
        }
    }

    /* Word 0: differential pressure */
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw_pressure * PRESSURE_SCALE;

    /* Word 3: temperature */
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    *temperature = (float)raw_temperature / 256.0f;

    return 0;
}

int main(void)
{
    float pressure, temperature;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x24 */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP810-125Pa sensor reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, I2C_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int rc = read_sensor_data(&pressure, &temperature);
        if (rc == 0) {
            printf("Pressure: %.3f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
        } else if (rc == -1) {
            fprintf(stderr, "Warning: I/O error, retrying next cycle...\n");
        } else {
            fprintf(stderr, "Warning: CRC mismatch, retrying next cycle...\n");
        }

        time_sleep(READ_INTERVAL);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

