#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC1000_ADDR   0x44
#define HDC1000_REG_TEMP 0x00
#define HDC1000_REG_HUM  0x01
#define HDC1000_REG_CONFIG 0x02
#define HDC1000_CMD_TEMP_HUM 0x10
#define HDC1000_CMD_RESET    0xFE
#define CONVERSION_DELAY_MS 20
#define LOOP_DELAY_MS       5000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg(0x%02X, 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg write(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg read(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int hdc1000_reset(int fd) {
    if (i2c_write_reg(fd, HDC1000_REG_CONFIG, HDC1000_CMD_RESET) < 0)
        return -1;
    usleep(15000);
    return 0;
}

static int hdc1000_trigger(int fd) {
    if (i2c_write_reg(fd, HDC1000_REG_CONFIG, HDC1000_CMD_TEMP_HUM) < 0)
        return -1;
    usleep(CONVERSION_DELAY_MS * 1000);
    return 0;
}

static int hdc1000_read(int fd, float *temp, float *hum) {
    uint8_t t_raw, h_raw;
    if (i2c_read_reg(fd, HDC1000_REG_TEMP, &t_raw) < 0)
        return -1;
    if (i2c_read_reg(fd, HDC1000_REG_HUM, &h_raw) < 0)
        return -1;
    *temp = (175.72f * (float)t_raw + 32768.0f) / 65536.0f;
    *hum  = (125.0f * (float)h_raw + 32768.0f) / 65536.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_reset(fd) < 0) {
        fprintf(stderr, "HDC1000 reset failed (sensor absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (hdc1000_trigger(fd) < 0) {
            fprintf(stderr, "Trigger conversion failed; retrying in %d ms\n", LOOP_DELAY_MS);
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        float temp, hum;
        if (hdc1000_read(fd, &temp, &hum) < 0) {
            fprintf(stderr, "Read failed; retrying in %d ms\n", LOOP_DELAY_MS);
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        fflush(stdout);
        usleep(LOOP_DELAY_MS * 1000);
    }

    fprintf(stderr, "\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

