#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x50
#define MEASURE_CMD 0x3600
#define MEASURE_DELAY_US 7000
#define LOOP_DELAY_US 5000000
#define ERROR_VALUE -1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_icp10101(int handle, float *temperature, float *pressure) {
    char cmd[2] = { (char)(MEASURE_CMD >> 8), (char)(MEASURE_CMD & 0xFF) };
    char buf[6];

    if (i2cWriteDevice(handle, cmd, 2) != 2) {
        fprintf(stderr, "Error: I2C write failed (sensor absent or bus error)\n");
        return ERROR_VALUE;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed (sensor absent or bus error)\n");
        return ERROR_VALUE;
    }

    uint16_t raw_pressure = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t raw_temperature = ((uint16_t)(uint8_t)buf[3] << 8) | (uint8_t)buf[4];

    *pressure = (float)raw_pressure / 100.0f;
    *temperature = (float)raw_temperature / 100.0f;

    return 0;
}

static void log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: I2C open failed on bus %d addr 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
