#define I2C_BUS "/dev/i2c-1"
#define MLX90819_ADDR 0x44
#define MLX90819_REG_PRESSURE 0x00
#define MLX90819_REG_CONFIG 0x01
#define MLX90819_REG_STATUS 0x02
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure) {
    uint8_t status = 0;
    if (i2c_read_reg8(fd, MLX90819_REG_STATUS, &status) < 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* Data not ready */
    }

    uint8_t raw_pressure = 0;
    if (i2c_read_reg8(fd, MLX90819_REG_PRESSURE, &raw_pressure) < 0) {
        return -1;
    }

    /*
     * Placeholder conversion: MLX90819 datasheet specifies a 24-bit
     * resolution. For brevity, we apply a simple linear scaling.
     * In a production environment, refer to the datasheet for the
     * exact conversion formula.
     */
    *pressure = (float)raw_pressure * 0.1f;
    return 0;
}

static void print_timestamp(void) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] ", buf);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * Example configuration: enable continuous measurement mode.
     * Refer to the MLX90819 datasheet for the correct register values.
     */
    if (i2c_write_reg8(fd, MLX90819_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure sensor.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure = 0.0f;
        int ret = read_pressure(fd, &pressure);

        if (ret == 0) {
            print_timestamp();
            printf("Pressure: %.2f Pa\n", pressure);
        } else if (ret < 0) {
            print_timestamp();
            fprintf(stderr, "Error: I2C communication failure.\n");
        } else {
            print_timestamp();
            printf("Error: Data not ready (sensor busy or not present).\n");
        }

        if (g_running) {
            sleep(SAMPLE_INTERVAL_SEC);
        }
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return EXIT_SUCCESS;
}

