#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x24
#define LOG_FILE "airflow_log.csv"
#define MEASUREMENT_DELAY_MS 8
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure) {
    uint8_t buf[3];

    if (i2c_write_cmd(fd, 0x36) < 0) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, buf, 3) < 0) {
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        return -2;
    }

    int16_t raw = (buf[0] << 8) | buf[1];
    *pressure = (float)raw / 100.0f;
    return 0;
}

static int log_data(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa)\n");
    }

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    printf("SDP800 Airflow Monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure;
        int ret = read_sdp800(fd, &pressure);

        if (ret == 0) {
            if (log_data(pressure) < 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else if (ret == -1) {
            fprintf(stderr, "Error: I2C communication failure or sensor absent.\n");
        } else {
            fprintf(stderr, "Error: CRC mismatch.\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return 0;
}

