#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0
#define SAFE_MIN_KPA   200.0
#define SAFE_MAX_KPA   250.0
#define MAX_RETRIES    2

/* MLX90821 register addresses (16-bit, big-endian on the bus) */
#define REG_PRESSURE_MSB 0x00
#define REG_PRESSURE_LSB 0x01
#define REG_CONFIG       0x02

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int sensor_init(void)
{
    /*
     * The MLX90821 is a sealed, factory-calibrated sensor.
     * A bare-minimum configuration register write is typically 0x0000.
     * A real deployment would read the part ID first, then apply
     * the manufacturer-recommended calibration sequence.
     */
    uint16_t config = 0x0000;
    char buf[2];
    buf[0] = (char)((config >> 8) & 0xFF);
    buf[1] = (char)(config & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, buf, 2) < 0) {
        fprintf(stderr, "Error: failed to write sensor configuration register: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure (kPa)                                                */
/* ------------------------------------------------------------------ */
static int read_pressure(float *pressure_kpa)
{
    char reg = (char)REG_PRESSURE_MSB;
    char data[2];

    /* Write the register pointer */
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: failed to set pressure register pointer: %s\n",
                strerror(errno));
        return -1;
    }

    /* Read two bytes (MSB first) */
    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read pressure data: %s\n",
                strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    *pressure_kpa = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log pressure to CSV                                                */
/* ------------------------------------------------------------------ */
static int log_pressure(float pressure_kpa)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kpa) < 0) {
        fprintf(stderr, "Error: fprintf() to log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen() failed (handle=%d): %s\n",
                g_i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sensor_init() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode) */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    long file_size = ftell(g_log_file);
    if (file_size == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Error: cannot write CSV header: %s\n",
                    strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("MLX90821 pressure logger started. Logging to %s every %.1f s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        float pressure_kpa = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_pressure(&pressure_kpa) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                fprintf(stderr, "Retrying I2C read (%d/%d)...\n",
                        attempt + 1, MAX_RETRIES);
                sleep(1);
            }
        }

        if (ok) {
            if (log_pressure(pressure_kpa) != 0) {
                fprintf(stderr, "Warning: failed to log pressure reading\n");
            }

            if (pressure_kpa < SAFE_MIN_KPA || pressure_kpa > SAFE_MAX_KPA) {
                fprintf(stderr,
                        "Warning: pressure %.2f kPa outside safe range "
                        "(%.0f-%.0f kPa)\n",
                        pressure_kpa, SAFE_MIN_KPA, SAFE_MAX_KPA);
            }
        } else {
            fprintf(stderr, "Error: I2C read failed after %d attempts; "
                            "reopening bus...\n", MAX_RETRIES);
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            sleep(1);
            g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Error: i2cOpen() failed after retry: %s\n",
                        strerror(errno));
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

