#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576
#define MEASUREMENT_DELAY_US 40000
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_measurement(int handle) {
    /* Send a 0-length write to trigger a measurement */
    if (i2cWriteDevice(handle, (char *)"", 0) < 0) {
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);
    return 0;
}

static int read_sensor_data(int handle, uint8_t *data) {
    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        return -1;
    }
    return 0;
}

static int parse_sensor_data(const uint8_t *data, float *temperature, float *humidity) {
    uint16_t raw_humidity = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_temperature = ((uint16_t)data[3] << 8) | data[4];

    *humidity = (float)raw_humidity / 10.0f;
    *temperature = (float)raw_temperature / 10.0f;

    /* Validate status bits (bits 7:6 of the temperature word) */
    if (data[4] & 0xC0) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", data[4] & 0xC0);
        return -1;
    }
    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    struct stat st;
    if (stat(filename, &st) != 0) {
        if (errno != ENOENT) {
            fprintf(stderr, "Error checking log file size: %s\n", strerror(errno));
            return -1;
        }
        /* File does not exist yet; create it */
        FILE *fp = fopen(filename, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error creating log file: %s\n", strerror(errno));
            return -1;
        }
        fclose(fp);
    }

    if (st.st_size >= LOG_FILE_SIZE_LIMIT) {
        /* File is too large; truncate it */
        FILE *fp = fopen(filename, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error truncating log file: %s\n", strerror(errno));
            return -1;
        }
        fclose(fp);
    }

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting environmental monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        uint8_t data[6];
        float temperature, humidity;

        if (trigger_measurement(i2c_handle) < 0) {
            fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        if (read_sensor_data(i2c_handle, data) < 0) {
