    (void)sig;
    running = 0;
}

static int read_sent_frame(int gpio, int *pressure_raw) {
    int tick_count = 0;
    int last_tick = 0;
    int last_level = 0;
    int timeout_count = 0;

    /* Wait for falling edge (start of sync pulse) */
    while (gpioRead(gpio) == last_level) {
        tick_count++;
        if (tick_count > SENT_TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for falling edge on GPIO%d\n", gpio);
            return -1;
        }
    }

    /* Measure sync pulse width */
    tick_count = 0;
    while (gpioRead(gpio) == last_level) {
        tick_count++;
        if (tick_count > SENT_TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout measuring sync pulse on GPIO%d\n", gpio);
            return -1;
        }
    }
    if (tick_count < SENT_SYNC_TICKS - 10 || tick_count > SENT_SYNC_TICKS + 10) {
        fprintf(stderr, "Error: Invalid sync pulse width on GPIO%d (ticks=%d)\n", gpio, tick_count);
        return -1;
    }

    /* Read 5 nibbles: status, D1, D2, D3, checksum */
    for (int i = 0; i < 5; i++) {
        tick_count = 0;
        while (gpioRead(gpio) == last_level) {
            tick_count++;
            if (tick_count > SENT_TIMEOUT_US) {
                fprintf(stderr, "Error: Timeout reading nibble %d on GPIO%d\n", i, gpio);
                return -1;
            }
        }
        last_level = gpioRead(gpio);

        int nibble_ticks = tick_count;
        if (nibble_ticks < SENT_MIN_NIBBLE_TICKS || nibble_ticks > SENT_MAX_NIBBLE_TICKS) {
            fprintf(stderr, "Error: Nibble %d out of range on GPIO%d (ticks=%d)\n", i, gpio, nibble_ticks);
            return -1;
        }

        /* Convert ticks to 4-bit nibble (0-15) */
        int nibble = (nibble_ticks - SENT_MIN_NIBBLE_TICKS) / (SENT_MAX_NIBBLE_TICKS - SENT_MIN_NIBBLE_TICKS + 1) * 15;
