        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP);

    printf("Monitoring SENT pressure sensor on GPIO%d. Press Ctrl+C to exit.\n", SENT_GPIO);

