            fprintf(stderr, "Warning: Failed to log pressure data\n");
        }

        printf("Pressure: %d Pa\n", pressure_raw);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

