#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define TMP117_TEMP_REG 0x00
#define TMP117_CONFIG_REG 0x01
#define TMP117_DEVICE_ID_REG 0x0F
#define TMP117_EXPECTED_DEVICE_ID 0x17
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_temperature(int fd, float *temperature) {
    uint16_t raw_temp;
    if (i2c_read_reg16(fd, TMP117_TEMP_REG, &raw_temp) < 0) {
        return -1;
    }
    *temperature = (float)raw_temp / 100.0f;
    return 0;
}

static int log_temperature(FILE *fp, float temperature) {
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    uint16_t device_id;
    if (i2c_read_reg16(i2c_fd, TMP117_DEVICE_ID_REG, &device_id) < 0) {
        fprintf(stderr, "Failed to read device ID\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (device_id != TMP117_EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n",
                device_id, TMP117_EXPECTED_DEVICE_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitoring started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        float temperature;
        if (read_temperature(i2c_fd, &temperature) == 0) {
            if (log_temperature(log_file, temperature) != 0) {
                fprintf(stderr, "Failed to write temperature to log file\n");
            } else {
                printf("Temperature: %.2f C\n", temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature from sensor\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

