#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define CONFIG_REG 0x01
#define LOG_FILE "temperature_log.dat"
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

static TemperatureReading circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, (uint8_t)(value >> 8), (uint8_t)(value & 0xFF)};
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int init_tmp117(int fd) {
    /* Configure TMP117: continuous conversion, 12-bit resolution, 1 Hz ODR */
    if (i2c_write_reg16(fd, CONFIG_REG, 0x0000) < 0) {
        return -1;
    }
    usleep(10000);
    return 0;
}

static int read_temperature(int fd, float *temperature) {
    uint16_t raw;
    if (i2c_read_reg16(fd, TEMP_REG, &raw) < 0) {
        return -1;
    }
    /* TMP117: 12-bit resolution, LSB = 1/16 °C */
    *temperature = (float)raw / 16.0f;
    return 0;
}

static void add_reading(float temperature) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static int write_buffer_to_file(const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }
    int start_index = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    int items_to_write = buffer_count;
    if (items_to_write > BUFFER_SIZE) items_to_write = BUFFER_SIZE;
    for (int i = 0; i < items_to_write; i++) {
        int idx = (start_index + i) % BUFFER_SIZE;
        if (fwrite(&circular_buffer[idx], sizeof(TemperatureReading), 1, fp) != 1) {
            perror("Error writing to file");
            fclose(fp);
            return -1;
        }
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return 1;
    }

    if (init_tmp117(fd) < 0) {
        fprintf(stderr, "Error initializing TMP117 sensor\n");
        close(fd);
        return 1;
    }

    printf("TMP117 initialized. Sampling every %d seconds. Press Ctrl+C to exit.\n", SAMPLE_INTERVAL);

    while (running) {
        float temperature;
        if (read_temperature(fd, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            add_reading(temperature);
        } else {
            fprintf(stderr, "Error reading temperature. Skipping sample.\n");
        }

        /* Sleep in 1-second increments to allow prompt signal handling */
        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    write_buffer_to_file(LOG_FILE);
    close(fd);
    printf("Data written to %s\n", LOG_FILE);
    return 0;
}

