    int16_t speed_raw = (int16_t)((speed_high << 8) | speed_low);

    *temperature = (float)temp_raw / 100.0f;

    if (speed_raw == 0) {
        *speed = 0.0f;
    } else {
        *speed = (float)speed_raw / 100.0f;
    }

    return 0;
}

