        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Speed(RPM),Temperature(C)\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    float speed, temperature;
    while (running) {
        if (read_sensor_data(i2c_handle, &speed, &temperature) == 0) {
            log_data(log_file, speed, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data. Logging NaN values.\n");
            log_data(log_file, NAN, NAN);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

