#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x30
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint8_t *data) {
    if (i2c_handle < 0) return -1;
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "I2C read error: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    return 0;
}

static int process_sensor_data(const uint8_t *data, float *airflow, float *temperature) {
    uint16_t flow_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t temp_raw = ((uint16_t)data[2] << 6) | (data[3] >> 2);
    *airflow = (float)flow_raw / 16383.0f * 25.0f;
    *temperature = (float)temp_raw / 4095.0f * 125.0f - 40.0f;
    return 0;
}

static int log_data(float airflow, float temperature) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Airflow: %.2f SLPM, Temperature: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            airflow, temperature);
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    if (initialize_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    uint8_t data[4];
    float airflow, temperature;
    int retries = 0;

    while (running) {
        if (read_sensor_data(data) == 0) {
            if (process_sensor_data(data, &airflow, &temperature) == 0) {
                if (log_data(airflow, temperature) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
                retries = 0;
            } else {
                fprintf(stderr, "Error processing sensor data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying initialization...\n");
            if (initialize_i2c() != 0) {
                retries++;
                if (retries > MAX_RETRIES) {
                    fprintf(stderr, "Max retries reached. Exiting.\n");
                    break;
                }
            } else {
                retries = 0;
