#include <pigpio.h>

#define DHT11_GPIO 4
#define READ_INTERVAL_SEC 2
#define MAX_RETRIES 3
#define TIMEOUT_US 1000

#define DHT11_START_LOW_US 18000
#define DHT11_START_HIGH_US 40
#define DHT11_BIT_LOW_US 50
#define DHT11_BIT_THRESHOLD_US 50
#define DHT11_TIMEOUT_US 1000

#define DHT11_OK 0
#define DHT11_ERROR -1
#define DHT11_CHECKSUM_ERROR -2
#define DHT11_STUCK_LOW -3
#define DHT11_STUCK_HIGH -4

typedef struct {
    float temperature;
    float humidity;
    int status;
} DHT11Data;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    FILE *fp = fopen("dht11_errors.log", "a");
    if (!fp) {
        perror("fopen dht11_errors.log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,ERROR,%s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "ERROR,%s\n", message);
    }
    fclose(fp);
}

static int read_dht11(int gpio, DHT11Data *data) {
    uint8_t raw[5] = {0};
    int i, j;
    uint32_t start_tick, end_tick, bit_start, bit_end;
    int last_state = 1;
    int bit_count = 0;

    data->status = DHT11_ERROR;
    data->temperature = -999.0f;
    data->humidity = -999.0f;

    for (i = 0; i < MAX_RETRIES; i++) {
        memset(raw, 0, sizeof(raw));
        bit_count = 0;

        if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
            log_error("gpioSetMode failed");
            goto retry;
        }
        if (gpioWrite(gpio, 0) < 0) {
            log_error("gpioWrite failed (start low)");
            goto retry;
        }
        gpioDelay(DHT11_START_LOW_US);

        if (gpioSetMode(gpio, PI_INPUT) < 0) {
            log_error("gpioSetMode failed (input)");
            goto retry;
        }

        start_tick = gpioTick();
        end_tick = start_tick;
        while (gpioRead(gpio) == 0) {
            end_tick = gpioTick();
            if ((end_tick - start_tick) > DHT11_TIMEOUT_US) {
                log_error("DHT11 start signal timeout (line stuck low)");
                goto retry;
            }
        }

        start_tick = gpioTick();
        end_tick = start_tick;
        while (gpioRead(gpio) == 1) {
            end_tick = gpioTick();
            if ((end_tick - start_tick) > DHT11_TIMEOUT_US) {
                log_error("DHT11 response timeout (line stuck high)");
                goto retry;
            }
        }

        for (j = 0; j < 40; j++) {
            start_tick = gpioTick();
            end_tick = start_tick;
            while (gpioRead(gpio) == 0) {
                end_tick = gpioTick();
                if ((end_tick - start_tick) > DHT11_TIMEOUT_US) {
                    log_error("DHT11 data bit timeout (low pulse)");
                    goto retry;
                }
            }
            start_tick = gpioTick();
            end_tick = start_tick;
            while (gpioRead(gpio) == 1) {
                end_tick = gpioTick();
                if ((end_tick - start_tick) > DHT11_TIMEOUT_US) {
                    log_error("DHT11 data bit timeout (high pulse)");
                    goto retry;
                }
            }
            uint32_t high_us = end_tick - start_tick;
            if (high_us > DHT11_BIT_THRESHOLD_US) {
                raw[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
            }
            bit_count++;
        }

        if (bit_count == 40) {
            uint8_t checksum = (uint8_t)(raw[0] + raw[1] + raw[2] + raw[3]);
            if (checksum != raw[4]) {
                log_error("DHT11 checksum error");
                goto retry;
            }
            data->humidity = (float)raw[0];
            data->temperature = (float)raw[2];
            data->status = DHT11_OK;
            return 0;
        }

    retry:
        gpioDelay(1000000);
    }

    log_error("DHT11 read failed after all retries");
    return DHT11_ERROR;
}

static void log_reading(float temperature, float humidity) {
