        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    while (running) {
        DHT11Data data;
        int result = read_dht11(DHT11_GPIO, &data);

        if (data.status == DHT11_OK) {
            log_reading(data.temperature, data.humidity);
        } else {
            char msg[128];
            switch (data.status) {
                case DHT11_CHECKSUM_ERROR:
                    snprintf(msg, sizeof(msg), "DHT11 checksum error");
                    break;
                case DHT11_STUCK_LOW:
                    snprintf(msg, sizeof(msg), "DHT11 line stuck low");
                    break;
                case DHT11_STUCK_HIGH:
                    snprintf(msg, sizeof(msg), "DHT11 line stuck high");
                    break;
                default:
                    snprintf(msg, sizeof(msg), "DHT11 read failed");
                    break;
            }
            log_error(msg);
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    gpioTerminate();
    return 0;
}

