#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT31_ADDR 0x25
#define I2C_BUS 1
#define LOG_FILE "sht31d_data.log"
#define MEASURE_CMD 0x2C
#define MEASURE_DELAY_US 20000
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht31d(int handle, float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t buf[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "I2C write failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(10000);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(10000);
            continue;
        }

        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(10000);
            continue;
        }

        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        uint16_t raw_hum  = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * raw_temp / 65535.0f);
        *humidity    = 100.0f * raw_hum / 65535.0f;

        return 0;
    }

    fprintf(stderr, "SHT31-D read failed after %d retries\n", RETRY_COUNT);
    return -1;
}

static void log_data(FILE *fp, float temp, float hum) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temp, hum;
    while (running) {
        if (read_sht31d(i2c_handle, &temp, &hum) == 0) {
            log_data(log_file, temp, hum);
        } else {
            time_t t = time(NULL);
            struct tm tm;
            localtime_r(&t, &tm);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(log_file, "%s,ERROR,ERROR\n", ts);
            fflush(log_file);
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

