#define SENSOR2_ADDR 0x11
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_SEC 1

/* ADPD105 Register Map (example values; adjust per datasheet) */
#define REG_CHIP_ID 0x00
#define REG_MODE 0x01
#define REG_DATA_OUT 0x04
#define REG_STATUS 0x05

#define CHIP_ID_EXPECTED 0x10

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select) error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t r, g, b;
    if (i2c_read_reg(handle, REG_DATA_OUT, &r) != 0) return -1;
    if (i2c_read_reg(handle, REG_DATA_OUT + 1, &g) != 0) return -1;
    if (i2c_read_reg(handle, REG_DATA_OUT + 2, &b) != 0) return -1;
    *red = (uint16_t)r;
    *green = (uint16_t)g;
    *blue = (uint16_t)b;
    return 0;
}

static float calculate_cct(uint16_t r, uint16_t g, uint16_t b) {
    /* Placeholder CCT calculation; replace with actual ADPD105 algorithm */
    float red_norm = (float)r / 65535.0f;
    float green_norm = (float)g / 65535.0f;
    float blue_norm = (float)b / 65535.0f;
    float cct = 449.0f * (green_norm - 0.3320f * red_norm - 0.1805f * blue_norm);
    return cct;
}

static int log_cct(float cct) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%.2f\n", timestamp, cct) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

