    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1 (addr 0x%02X): %s\n", SENSOR1_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2 (addr 0x%02X): %s\n", SENSOR2_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    /* Verify sensor presence via chip ID */
    uint8_t chip_id1 = 0, chip_id2 = 0;
    if (i2c_read_reg(i2c_handle1, REG_CHIP_ID, &chip_id1) != 0 || chip_id1 != CHIP_ID_EXPECTED) {
        fprintf(stderr, "Sensor 1 (addr 0x%02X) not detected or wrong chip ID: 0x%02X\n", SENSOR1_ADDR, chip_id1);
        cleanup();
        return 1;
    }
    if (i2c_read_reg(i2c_handle2, REG_CHIP_ID, &chip_id2) != 0 || chip_id2 != CHIP_ID_EXPECTED) {
        fprintf(stderr, "Sensor 2 (addr 0x%02X) not detected or wrong chip ID: 0x%02X\n", SENSOR2_ADDR, chip_id2);
        cleanup();
        return 1;
    }

    /* Open log file in append mode; write header if file is empty */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
        fflush(log_file);
    }

    printf("Starting CCT logging. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t r1, g1, b1, r2, g2, b2;
        int err = 0;

        if (read_sensor_data(i2c_handle1, &r1, &g1, &b1) != 0) {
            err = 1;
        }
        if (read_sensor_data(i2c_handle2, &r2, &g2, &b2) != 0) {
            err = 1;
        }

        if (err) {
            fprintf(stderr, "Error reading sensor data. Skipping this cycle.\n");
        } else {
            float cct1 = calculate_cct(r1, g1, b1);
            float cct2 = calculate_cct(r2, g2, b2);
            float avg_cct = (cct1 + cct2) / 2.0f;
            if (log_cct(avg_cct) != 0) {
                fprintf(stderr, "Error logging CCT.\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully.\n");
    cleanup();
    return 0;
}

