#include <pigpio.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x33
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 2

/* MLX90824 register addresses (datasheet) */
#define REG_PRESSURE_MSB 0x00
#define REG_PRESSURE_LSB 0x01
#define REG_TEMP_MSB    0x02
#define REG_TEMP_LSB    0x03
#define REG_DIAG_MSB    0x04
#define REG_DIAG_LSB    0x05

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Call sensor library cleanup if available */
    /* For pigpio, no explicit sensor-library cleanup; pigpio handles bus close */
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int read_pressure(int handle, float *pressure) {
    uint8_t msb, lsb;
    if (read_register(handle, REG_PRESSURE_MSB, &msb) < 0) {
        return -1;
    }
    if (read_register(handle, REG_PRESSURE_LSB, &lsb) < 0) {
        return -1;
    }
    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    /* Convert raw ADC value to Pa (example conversion; datasheet specifies formula) */
    *pressure = (float)raw * 0.1f;
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    uint8_t msb, lsb;
    if (read_register(handle, REG_TEMP_MSB, &msb) < 0) {
        return -1;
    }
    if (read_register(handle, REG_TEMP_LSB, &lsb) < 0) {
        return -1;
    }
    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    *temperature = (float)raw * 0.01f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(fp, "Timestamp: (error)\n");
    } else {
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "Timestamp: %s, Pressure: %.2f Pa, Temperature: %.2f C\n",
                timestamp, pressure, temperature);
    }
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(fp, "Timestamp: (error), Error: %s\n", message);
    } else {
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "Timestamp: %s, Error: %s\n", timestamp, message);
    }
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %s\n",
                I2C_BUS, MLX90824_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting MLX90824 pressure logging. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure = 0.0f;
        float temperature = 0.0f;
        int ret_p = read_pressure(g_i2c_handle, &pressure);
        int ret_t = read_temperature(g_i2c_handle, &temperature);

        if (ret_p == 0 && ret_t == 0) {
            log_data(g_log_file, pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            if (ret_p < 0) {
                log_error(g_log_file, "Failed to read pressure register");
            }
            if (ret_t < 0) {
                log_error(g_log_file, "Failed to read temperature register");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

