#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define FAN_GPIO       18
#define TEMP_THRESHOLD_ON  28.0f
#define TEMP_THRESHOLD_OFF 26.0f
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD_US 1000000  /* 1 second */

/* LM75B register addresses */
#define LM75B_TEMP_REG 0x00
#define LM75B_CONFIG_REG 0x01

/* Config: continuous conversion, 12-bit resolution, no alarm */
#define LM75B_CONFIG_VAL 0x0000

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gpio(void)
{
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n",
                FAN_GPIO, strerror(errno));
        return -1;
    }
    if (gpioWrite(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error writing GPIO %d: %s\n",
                FAN_GPIO, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lm75b(void)
{
    /* Write config: continuous conversion, 12-bit, no alarm */
    char cfg[2] = {
        (char)((LM75B_CONFIG_VAL >> 8) & 0xFF),
        (char)(LM75B_CONFIG_VAL & 0xFF)
    };
    if (i2cWriteDevice(g_i2c_handle, cfg, 2) != 0) {
        fprintf(stderr, "Error writing LM75B config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp)
{
    char reg = LM75B_TEMP_REG;
    char data[2];

    if (i2cWriteDevice(g_i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing LM75B register address: %s\n", strerror(errno));
        return -1;
    }
    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading LM75B temperature: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)(((uint8_t)data[0] << 8) | (uint8_t)data[1]);
    /* 12-bit two's complement: shift right 4 to get 12-bit value */
    raw >>= 4;
    *temp = (float)raw * 0.0625f;
    return 0;
}

static void update_buffer(CircularBuffer *cb, float temp)
{
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float calculate_average(const CircularBuffer *cb)
{
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static int control_fan(float avg_temp)
{
    static bool fan_on = false;

    if (avg_temp > TEMP_THRESHOLD_ON && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON  (avg %.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Error turning fan ON: %s\n", strerror(errno));
        }
    } else if (avg_temp < TEMP_THRESHOLD_OFF && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (avg %.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Error turning fan OFF: %s\n", strerror(errno));
        }
    }
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    CircularBuffer temp_buffer = {0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0 || init_gpio() != 0 || init_lm75b() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            update_buffer(&temp_buffer, temp);
            float avg = calculate_average(&temp_buffer);
            printf("Temperature: %.2f C, Average: %.2f C\n", temp, avg);
            control_fan(avg);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

