#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define LOG_FILE "environment.log"
#define SAMPLE_INTERVAL 60
#define MAX_RETRIES 3
#define MEASURE_CMD_RH 0xE3
#define MEASURE_CMD_TEMP 0xE5
#define READ_PREV_CMD 0xE0
#define CMD_LEN 1
#define MEASURE_DELAY_US 20000
#define CONV_DELAY_US 15000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(uint8_t cmd) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteByte(i2c_handle, cmd) == 0) return 0;
        gpioDelay(10000);
    }
    return -1;
}

static int i2c_read_bytes(uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int n = i2cReadDevice(i2c_handle, (char *)buf, len);
        if (n == len) return 0;
        gpioDelay(10000);
    }
    return -1;
}

static int read_sensor(uint8_t cmd, uint16_t *raw) {
    if (i2c_write_cmd(cmd) != 0) return -1;
    gpioDelay(MEASURE_DELAY_US);
    uint8_t buf[3];
    if (i2c_read_bytes(buf, 3) != 0) return -1;
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_sensor_prev(uint16_t *raw) {
    if (i2c_write_cmd(READ_PREV_CMD) != 0) return -1;
    gpioDelay(MEASURE_DELAY_US);
    uint8_t buf[3];
    if (i2c_read_bytes(buf, 3) != 0) return -1;
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float convert_temperature(uint16_t raw) {
    return 175.72f * (float)raw / 65536.0f - 46.85f;
}

static float convert_humidity(uint16_t raw) {
    float h = 125.0f * (float)raw / 65536.0f - 6.0f;
    if (h < 0.0f) h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    return h;
}

static void log_data(float temp, float hum) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp, hum);
    fflush(log_file);
    printf("%s,%.2f,%.2f\n", ts, temp, hum);
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,ERROR,%s\n", ts, msg);
    fflush(log_file);
    fprintf(stderr, "%s,ERROR,%s\n", ts, msg);
}

static int init_sensor(void) {
    uint8_t id[8];
    if (i2c_read_bytes(id, 8) != 0) {
        log_error("Sensor not responding (electronic ID read failed)");
        return -1;
    }
    uint16_t rev = ((uint16_t)id[7] << 8) | id[6];
    if ((rev & 0x07) != 0x07) {
        log_error("Invalid firmware revision");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting environmental monitoring (Si7021 @ 0x%02X)...\n", I2C_ADDR);

    while (running) {
        uint16_t raw_rh, raw_t;
        if (read_sensor_prev(&raw_t) == 0) {
            float temp = convert_temperature(raw_t);
            if (read_sensor(MEASURE_CMD_RH, &raw_rh) == 0) {
                float hum = convert_humidity(raw_rh);
                log_data(temp, hum);
            } else {
                log_error("Failed to read humidity");
            }
        } else {
            log_error("Failed to read previous temperature");
        }
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

