#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define SCD40_ADDR 0x12
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG "/var/log/scd40_error.log"
#define BUFFER_SIZE 100
#define READ_INTERVAL_SEC 5
#define LOG_INTERVAL_SEC 60
#define START_PERIODIC_CMD 0x2001
#define STOP_PERIODIC_CMD 0x2002
#define MEASUREMENT_DELAY_MS 100

#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_fd = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static pthread_t log_thread;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG, "a");
    if (!fp) {
        perror("fopen error log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void add_to_buffer(circular_buffer_t *cb, sensor_data_t data) {
    pthread_mutex_lock(&cb->mutex);
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

static int write_i2c_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (cmd >> 8) & 0xFF, cmd & 0xFF };
    if (write(i2c_fd, buf, 2) != 2) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int read_i2c_data(uint8_t *buf, int len) {
    if (read(i2c_fd, buf, len) != len) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_scd40_data(sensor_data_t *data) {
    if (write_i2c_cmd(START_PERIODIC_MEASUREMENT) < 0) return -1;
    usleep(MEASUREMENT_DELAY_MS * 1000);

    uint8_t buf[12];
    if (read_i2c_data(buf, 12) < 0) return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CRC check failed for CO2");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("CRC check failed for temperature");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("CRC check failed for humidity");
        return -1;
    }

    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (buf[3] << 8) | buf[4];
    data->humidity = (buf[6] << 8) | buf[7];

    time(&data->timestamp);
    return 0;
}

static void *log_data_to_file(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOG_INTERVAL_SEC);
        if (!running) break;
        pthread_mutex_lock(&buffer.mutex);
        int count = buffer.count;
        if (count > 0) {
            FILE *fp = fopen(LOG_DIR "/scd40_data.csv", "a");
            if (!fp) {
                log_error("fopen scd40_data.csv");
                pthread_mutex_unlock(&buffer.mutex);
                continue;
            }
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec);
            for (int i = 0; i < count; i++) {
                sensor_data_t d;
                int idx = (buffer.tail + i) % BUFFER_SIZE;
                pthread_mutex_lock(&buffer.mutex);
                d = buffer.data[idx];
                pthread_mutex_unlock(&buffer.mutex);
                fprintf(fp, ",%u,%.2f,%.2f,%.2f\n",
                        d.co2, d.temperature, d.humidity, d.timestamp);
            }
            fclose(fp);
            buffer.head = (buffer.head + i + 1) % BUFFER_SIZE;
            buffer.count = 0;
            pthread_mutex_unlock(&buffer.mutex);
        }
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        write_i2c_cmd(STOP_PERIODIC_MEASUREMENT);
        close(i2c_fd);
        i2c_fd = -1;
    }
    pthread_join(log_thread, NULL);
    pthread_mutex_destroy(&buffer.mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (mkdir(LOG_DIR, 0755) == -1 && errno != EEXIST) {
        perror("mkdir");
        return 1;
    }

    if (init_i2c() < 0) {
        return 1;
    }

    init_circular_buffer(&buffer);

    if (pthread_create(&log_thread, NULL, log_data_to_file, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return 1;
    }

    while (running) {
        sensor_data_t data;
        if (read_scd40_data(&data) == 0) {
            add_to_buffer(&buffer, data);
        } else {
            log_error("Failed to read sensor data");
        }
        sleep(READ_INTERVAL_SEC);
    }

    pthread_join(log_thread, NULL);
    pthread_mutex_lock(&buffer.mutex);
    int count = buffer.count;
    if (count > 0) {
        FILE *fp = fopen(LOG_DIR "/scd40_data_final.csv", "a");
        if (fp) {
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec);
            for (int i = 0; i < count; i++) {
                sensor_data_t d;
                int idx = (buffer.tail + i) % BUFFER_SIZE;
                pthread_mutex_lock(&buffer.mutex);
                d = buffer.data[idx];
                pthread_mutex_unlock(&buffer.mutex);
                fprintf(fp, ",%u,%.2f,%.2f,%.2f\n",
                        d.co2, d.temperature, d.humidity, d.timestamp);
            }
            fclose(fp);
        }
    }
    pthread_mutex_destroy(&buffer.mutex);
    cleanup();
    return 0;
}

