#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x5C
#define GPIO_LED       17
#define PRESSURE_THRESHOLD 95000.0f
#define POLL_INTERVAL_US 1000000
#define TRIGGER_DELAY_US  20000
#define BLINK_HALF_US     500000
#define WARNING_HALF_US   100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_read_sensor(int fd, uint8_t *buf) {
    ssize_t n = read(fd, buf, 6);
    if (n != 6) {
        fprintf(stderr, "I2C read failed: expected 6 bytes, got %zd (%s)\n",
                n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, uint16_t *pressure, uint16_t *temperature) {
    uint8_t buf[6];
    if (i2c_read_sensor(fd, buf) != 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    *pressure = (uint16_t)((buf[0] << 8) | buf[1]);
    *temperature = (uint16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

static void blink_led(int gpio, float pressure) {
    static int phase = 0;
    if (pressure < PRESSURE_THRESHOLD) {
        phase = (phase + 1) & 1;
        gpioWrite(gpio, phase);
        gpioDelay(WARNING_HALF_US);
    } else {
        phase = (phase + 1) & 1;
        gpioWrite(gpio, phase);
        gpioDelay(BLINK_HALF_US);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    printf("ICP-10125 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t pressure, temperature;
        if (read_sensor_data(g_i2c_fd, &pressure, &temperature) != 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            printf("Pressure: %u Pa, Temperature: %u °C\n",
                   pressure, temperature);
            blink_led(GPIO_LED, (float)pressure);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(GPIO_LED, 0);
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

