#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define HDC2010_ADDR 0x14
#define I2C_BUS 1
#define POLL_TIMEOUT_MS 500
#define MAX_RETRIES 3

/* HDC2010 register addresses */
#define REG_TEMP_LOW      0x00
#define REG_TEMP_HIGH     0x01
#define REG_HUM_LOW       0x02
#define REG_HUM_HIGH      0x03
#define REG_MEAS_CONFIG   0x0E

/*
 * Measurement_Config register (0x0E):
 *   Bit 0 = TEMP_EN (1 = trigger temperature measurement)
 *   Bit 1 = HUM_EN  (1 = trigger humidity measurement)
 *   Bit 3 = MEAS_TRIG (1 = start measurement)
 *   Writing 0x03 triggers a single temperature + humidity measurement.
 */
#define MEAS_TRIG_MASK    0x04

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a single byte to an HDC2010 register.
 * Returns 0 on success, -1 on failure.
 */
static int hdc2010_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an HDC2010 register.
 * Returns 0 on success and stores the byte in *out, -1 on failure.
 */
static int hdc2010_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/*
 * Read a 16-bit little-endian value from two consecutive registers.
 * Returns 0 on success and stores the value in *out, -1 on failure.
 */
static int hdc2010_read_reg16(int handle, uint8_t reg_low, uint16_t *out)
{
    uint8_t lo, hi;
    if (hdc2010_read_reg(handle, reg_low, &lo) < 0)
        return -1;
    if (hdc2010_read_reg(handle, reg_low + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/*
 * Trigger a measurement and wait for completion.
 * Returns 0 on success, -1 on timeout or bus error.
 */
static int hdc2010_trigger_and_wait(int handle)
{
    uint8_t cfg;
    int elapsed = 0;

    /* Clear any pending measurement by writing 0x00 to MEAS_TRIG */
    if (hdc2010_write_reg(handle, REG_MEAS_CONFIG, 0x00) < 0)
        return -1;

    /* Trigger a single temperature + humidity measurement */
    cfg = MEAS_TRIG_MASK;
    if (hdc2010_write_reg(handle, REG_MEAS_CONFIG, cfg) < 0)
        return -1;

    /* Poll MEAS_TRIG until it reads 0 (measurement complete) */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (hdc2010_read_reg(handle, REG_MEAS_CONFIG, &cfg) < 0)
            return -1;
        if (cfg & MEAS_TRIG_MASK) {
            if (++elapsed >= POLL_TIMEOUT_MS) {
                fprintf(stderr, "[ERROR] HDC2010 measurement timeout (poll took %d ms)\n",
                        elapsed);
                return -1;
            }
            gpioDelay(1000); /* 1 ms */
        } else {
            break;
        }
    }

    return 0;
}

/*
 * Read temperature and humidity.
 * Returns 0 on success, -1 on failure.
 */
static int hdc2010_read_data(int handle, float *temperature, float *humidity)
{
    uint16_t raw_t, raw_h;

    if (hdc2010_trigger_and_wait(handle) < 0)
        return -1;

    if (hdc2010_read_reg16(handle, REG_TEMP_LOW, &raw_t) < 0)
        return -1;
    if (hdc2010_read_reg16(handle, REG_HUM_LOW, &raw_h) < 0)
        return -1;

    /* HDC2010: 12-bit left-justified values */
    *temperature = ((float)raw_t & 0x0FFF) / 4.0f;
    *humidity    = ((float)raw_h & 0x0FFF) / 4.0f;

    return 0;
}

int main(void)
{
    float temperature, humidity;
    int consecutive_failures = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the HDC2010 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HDC2010 sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (hdc2010_read_data(g_i2c_handle, &temperature, &humidity) == 0) {
            consecutive_failures = 0;
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            consecutive_failures++;
            fprintf(stderr, "[WARN] Read failed (%d consecutive)\n", consecutive_failures);
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "[FATAL] Max consecutive failures reached. Aborting.\n");
                break;
            }
        }

        /* Sleep 5 seconds, but wake early if signaled */
        for (int i = 0; i < 5 && g_running; i++)
            gpioDelay(1000000); /* 1 s */
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

