#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x24
#define MEASUREMENT_DELAY_US 45000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion SDP800 */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read one sample from the SDP800.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_sdp800(int handle, uint16_t *pressure, uint16_t *temperature) {
    uint8_t cmd[2] = {0x36, 0x00}; /* continuous measurement, no averaging */
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x3600).\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    int bytes = i2cReadDevice(handle, (char *)buf, 6);
    if (bytes != 6) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 6).\n", bytes);
        return -1;
    }

    /* Validate CRC for pressure (bytes 0-1, CRC byte 2) */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(buf, 2), buf[2]);
        return -2;
    }

    /* Validate CRC for temperature (bytes 3-4, CRC byte 5) */
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(buf + 3, 2), buf[5]);
        return -2;
    }

    *pressure = (uint16_t)((buf[0] << 8) | buf[1]);
    *temperature = (uint16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

int main(void) {
    int handle = -1;
    int ret = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, SDP800_ADDR, handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP800 differential pressure reader started (bus %d, addr 0x%02X).\n",
           I2C_BUS, SDP800_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t pressure, temperature;
        int rc = read_sdp800(handle, &pressure, &temperature);

        if (rc == 0) {
            printf("Pressure: %u Pa, Temperature: %u °C\n", pressure, temperature);
        } else if (rc == -1) {
            fprintf(stderr, "Warning: I2C bus error, continuing...\n");
        } else {
            fprintf(stderr, "Warning: CRC mismatch, continuing...\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    ret = 0;
    i2cClose(handle);
    gpioTerminate();
    return ret;
}

