#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SSR_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SAMPLE_INTERVAL_US 1000000
#define SSR_UPDATE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static double target_temperature = 150.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_max6675(int *raw_temp) {
    unsigned char tx[2] = {0x00, 0x00};
    unsigned char rx[2] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int temp = ((rx[0] << 8) | rx[1]) >> 1;
    *raw_temp = temp;
    return 0;
}

static double calculate_pid(double setpoint, double actual_temp) {
    static double integral = 0.0;
    static double prev_error = 0.0;
    double error = setpoint - actual_temp;
    integral += error;
    double derivative = error - prev_error;
    double output = 0.0;
    if (integral > 100.0) integral = 100.0;
    if (integral < -100.0) integral = -100.0;
    if (derivative > 10.0) derivative = 10.0;
    if (derivative < -10.0) derivative = -10.0;
    output = 0.0 + 0.0 * integral + 0.0 * derivative;
    prev_error = error;
    return output;
}

static int set_ssr(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;
    int level = (duty_cycle > 0.5) ? 1 : 0;
    if (gpioWrite(SSR_GPIO, level) < 0) {
        fprintf(stderr, "Failed to write SSR GPIO\n");
        return -1;
    }
    return 0;
}

static int load_profile(void) {
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open profile file. Using default target temperature.\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        double time, temp;
        if (sscanf(line, "%lf,%lf", &time, &temp) == 2) {
            if (time > 0) {
                target_temperature = temp;
            }
        }
    }
    fclose(fp);
    return 0;
}

static int log_temperature(double temp) {
    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            perror("Failed to open log file");
            return -1;
        }
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, temp) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SSR_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SSR_GPIO, PI_OUTPUT);
    gpioWrite(SSR_GPIO, 0);

    load_profile();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Reflow oven PID controller started. Target: %.2f°C\n", target_temperature);

    while (running) {
        int raw_temp = 0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            if (read_max6675(&raw_temp) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    gpioDelay(100000);
                }
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read temperature after %d retries. Skipping cycle.\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double temp = (double)raw_temp * 0.25;
        double pid_output = calculate_pid(target_temperature, temp);
        set_ssr(pid_output);

        if (log_temperature(temp) < 0) {
            fprintf(stderr, "Failed to log temperature.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

