    printf("Reflow oven PID controller started. Target: %.2f°C\n", target_temperature);

    while (running) {
        int raw_temp = 0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            if (read_max6675(&raw_temp) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    gpioDelay(100000);
                }
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read temperature after %d retries. Skipping cycle.\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double temp = (double)raw_temp * 0.25;
        double pid_output = calculate_pid(target_temperature, temp);
        set_ssr(pid_output);

        if (log_temperature(temp) < 0) {
            fprintf(stderr, "Failed to log temperature.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

