#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/ioctl.h>
#include <linux/w1.h>

#define DS18B20_BUS "/sys/bus/w1/devices/"
#define DS18B20_DATA_FILE "28-0x5587002425cc/w1_slave"
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define PWM_PERIOD_NS 1000000000ULL
#define PWM_RANGE 100
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL_S 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int relay_fd = -1;
static int pwm_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ds18b20(float *temperature) {
    char path[256];
    char buf[256];
    int fd;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        snprintf(path, sizeof(path), "%s%s", DS18B20_BUS, DS18B20_DATA_FILE);
        fd = open(path, O_RDONLY);
        if (fd < 0) {
            fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
            retries++;
            sleep(1);
            continue;
        }

        ssize_t n = read(fd, buf, sizeof(buf) - 1);
        if (n <= 0) {
            fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
            close(fd);
            retries++;
            sleep(1);
            continue;
        }
        buf[n] = '\0';
        close(fd);

        if (strncmp(buf, "YES", 3) != 0) {
            fprintf(stderr, "CRC check failed for %s\n", path);
            retries++;
            sleep(1);
            continue;
        }

        char *t_str = strstr(buf, "t=");
        if (!t_str) {
            fprintf(stderr, "Temperature data not found in %s\n", path);
            retries++;
            sleep(1);
            continue;
        }

        errno = 0;
        char *endptr = NULL;
        long temp_raw = strtol(t_str + 2, &endptr, 10);
        if (errno != 0 || endptr == t_str + 2) {
            fprintf(stderr, "Invalid temperature data in %s\n", path);
            retries++;
            sleep(1);
            continue;
        }

        *temperature = (float)temp_raw / 1000.0f;
        return 0;
    }

    fprintf(stderr, "Failed to read DS18B20 after %d retries\n", MAX_RETRIES);
    return -1;
}

static float pid_compute(float setpoint, float current, float *integral, float *prev_error, float kp, float ki, float kd) {
    float error = setpoint - current;
    *integral += error;
    float derivative = error - *prev_error;
    float output = kp * error + ki * (*integral) + kd * derivative;
    *prev_error = error;
    return output;
}

static int set_pwm_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    unsigned int div = (unsigned int)(PWM_PERIOD_NS / (unsigned int)duty);
    if (ioctl(pwm_fd, PWM_IOCTL_SET_DIV, &div) < 0) {
        fprintf(stderr, "Error setting PWM duty: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int set_relay(int state) {
    if (state == 0) {
        if (write(relay_fd, "0", 1) < 0) {
            fprintf(stderr, "Error turning relay off: %s\n", strerror(errno));
            return -1;
        }
    } else {
        if (write(relay_fd, "1", 1) < 0) {
            fprintf(stderr, "Error turning relay on: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void log_data(float avg_temp, float setpoint, float pid_output, int pwm_duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, %.2f, %.2f, %.2f, %d\n", timestamp, avg_temp, setpoint, pid_output, pwm_duty);
    fflush(log_file);
}

static void cleanup(void) {
    if (relay_fd >= 0) {
        set_relay(0);
        close(relay_fd);
        relay_fd = -1;
    }
    if (pwm_fd >= 0) {
        set_pwm_duty(0);
        close(pwm_fd);
        pwm_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(int argc, char *argv[]) {
    float setpoint = 25.0f;
    float kp = 1.0f, ki = 0.1f, kd = 0.01f;
    float integral = 0.0f, prev_error = 0.0f;
    float avg_temp = 0.0f;
    int pwm_duty = 0;

    if (argc > 1) setpoint = (float)atof(argv[1]);
    if (argc > 3) kp = (float)atof(argv[2]);
    if (argc > 5) ki = (float)atof(argv[3]);
    if (argc > 7) kd = (float)atof(argv[4]);

    if (argc > 9) {
        if (strcmp(argv[5], "relay") == 0) {
            RELAY_GPIO = atoi(argv[6]);
        } else if (strcmp(argv[6], "pwm") == 0) {
            PWM_GPIO = atoi(argv[7]);
        }
    }

    if (argc > 11) {
        if (strcmp(argv[8], "log") == 0) {
            log_file = fopen(LOG_FILE, "a");
            if (!log_file) {
                fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
                return 1;
            }
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (relay_fd >= 0 || pwm_fd >= 0) {
        fprintf(stderr, "Warning: GPIO already in use, aborting.\n");
        cleanup();
        return 1;
    }

    relay_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (relay_fd < 0) {
        fprintf(stderr, "Error exporting relay GPIO: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    write(relay_fd, "17", 2);
    close(relay_fd);

    pwm_fd = open("/sys/class/pwm/pwmchip0/export", O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Error exporting PWM: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    write(pwm_fd, "0", 1);
    close(pwm_fd);

    relay_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (relay_fd < 0) {
        fprintf(stderr, "Error opening relay GPIO: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    pwm_fd = open("/sys/class/pwm/pwmchip0/pwm0/period", O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Error opening PWM period: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    write(pwm_fd, "1000000000", 10);
    close(pwm_fd);

    pwm_fd = open("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Error opening PWM duty cycle: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        float temp;
        if (read_ds18b20(&temp) == 0) {
            avg_temp = temp;
            printf("Temperature: %.2f\n", temp);
        } else {
            fprintf(stderr, "Sensor read failed, using last known value\n");
            avg_temp = 0.0f;
        }

        float pid_output = pid_compute(setpoint, avg_temp, &integral, &prev_error, kp, ki, kd);
        pwm_duty = (int)pid_output;

        if (set_pwm_duty(pwm_duty) < 0) {
            fprintf(stderr, "PWM set failed\n");
        }
        if (set_relay(pwm_duty > 0) < 0) {
            fprintf(stderr, "Relay set failed\n");
        }

        log_data(avg_temp, setpoint, pid_output, pwm_duty);
        sleep(SAMPLE_INTERVAL_S);
    }

    cleanup();
    return 0;
}

