#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define AHT20_ADDR        0x38
#define I2C_BUS           "/dev/i2c-1"
#define GPIO_DEHUMIDIFIER 17
#define HUMIDITY_HIGH     60.0f
#define HUMIDITY_LOW      55.0f
#define POLL_INTERVAL_S   5
#define MEASURE_DELAY_US  80000
#define MAX_RETRIES       3
#define RETRY_DELAY_US    10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int aht20_read_humidity(int fd, float *humidity)
{
    uint8_t cmd[2] = {0x2C, 0x06};
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(fd, cmd, 2) != 2) {
            fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_US);
            continue;
        }

        usleep(MEASURE_DELAY_US);

        ssize_t n = read(fd, buf, 6);
        if (n != 6) {
            fprintf(stderr, "I2C read failed (attempt %d/%d): got %zd bytes, %s\n",
                    retries + 1, MAX_RETRIES, n, n < 0 ? strerror(errno) : "short read");
            retries++;
            usleep(RETRY_DELAY_US);
            continue;
        }

        uint16_t status = (buf[0] << 8) | buf[1];
        if (status & 0x01) {
            fprintf(stderr, "AHT20 status: busy (0x%04X)\n", status);
            retries++;
            usleep(RETRY_DELAY_US);
            continue;
        }
        if (status & 0x02) {
            fprintf(stderr, "AHT20 status: calibration required\n");
            retries++;
            usleep(RETRY_DELAY_US);
            continue;
        }

        uint32_t raw = ((uint32_t)buf[2] << 12) |
                       ((uint32_t)buf[3] << 4)  |
                       ((uint32_t)buf[4] >> 4);
        *humidity = (float)raw / 1048576.0f;
        return 0;
    }

    fprintf(stderr, "AHT20 read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void control_dehumidifier(float humidity)
{
    if (humidity > HUMIDITY_HIGH) {
        if (gpioWrite(GPIO_DEHUMIDIFIER, 1) < 0)
            fprintf(stderr, "Failed to activate dehumidifier relay\n");
        else
            printf("Dehumidifier ON  (Humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_LOW) {
        if (gpioWrite(GPIO_DEHUMIDIFIER, 0) < 0)
            fprintf(stderr, "Failed to deactivate dehumidifier relay\n");
        else
            printf("Dehumidifier OFF (Humidity: %.2f%%)\n", humidity);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_DEHUMIDIFIER, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_DEHUMIDIFIER);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_DEHUMIDIFIER, 0);

    printf("AHT20 humidity monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float humidity;
        if (aht20_read_humidity(g_i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                     localtime(&now));
            printf("[%s] Humidity: %.2f%%\n", ts, humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Sensor read failed; dehumidifier left in current state.\n");
        }

        for (int i = 0; i < POLL_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    gpioWrite(GPIO_DEHUMIDIFIER, 0);
    close(g_i2c_fd);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

