#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x15
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60
#define MAX_RETRIES 3
#define MAX_PAYLOAD 256

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sockfd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

int read_humidity(int fd, float *humidity) {
    unsigned char cmd[2] = {0x25, 0x00};
    unsigned char buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(fd, cmd, 2) != 2) {
            syslog(LOG_ERR, "I2C write failed (attempt %d): %s", retries + 1, strerror(errno));
            retries++;
            sleep(1);
            continue;
        }
        usleep(10000);
        if (read(fd, buf, 3) != 3) {
            syslog(LOG_ERR, "I2C read failed (attempt %d): %s", retries + 1, strerror(errno));
            retries++;
            sleep(1);
            continue;
        }
        unsigned short raw = (buf[0] << 8) | buf[1];
        if (raw & 0x8000) {
            syslog(LOG_ERR, "CRC mismatch on humidity data (attempt %d)", retries + 1);
            retries++;
            sleep(1);
            continue;
        }
        *humidity = -6.0f + 125.0f * (float)raw / 65536.0f;
        return 0;
    }
    syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
    return -1;
}

int send_http_post(const char *endpoint, const char *payload) {
    struct sockaddr_in addr;
    int opt = 1;
    socklen_t addrlen = sizeof(addr);

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        syslog(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(80);
    if (inet_pton(AF_INET, endpoint, &addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", endpoint);
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    char request[MAX_PAYLOAD];
    int req_len = snprintf(request, sizeof(request), "POST /humidity HTTP/1.1\r\n"
            "Host: api.example.com\r\n"
            "Content-Type: application/json\r\n"
            "Content-Length: %zu\r\n"
            "Connection: close\r\n"
            "\r\n"
            "%s", strlen(payload), payload);

    if (req_len < 0 || (size_t)req_len >= sizeof(request)) {
        syslog(LOG_ERR, "Request buffer overflow");
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    if (send(sockfd, request, (size_t)req_len, 0) < 0) {
        syslog(LOG_ERR, "send failed: %s", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    char response[1024];
    ssize_t bytes = recv(sockfd, response, sizeof(response) - 1, 0);
    if (bytes <= 0) {
        syslog(LOG_ERR, "recv failed: %s", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }
    response[bytes] = '\0';
    syslog(LOG_INFO, "HTTP Response: %s", response);
    close(sockfd);
    sockfd = -1;
    return 0;
}

int main() {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting humidity monitor");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    i2c_fd = init_i2c(I2C_BUS, HTU21D_ADDR);
    if (i2c_fd < 0) {
        closelog();
        return 1;
    }

    while (running) {
        float humidity;
        if (read_humidity(i2c_fd, &humidity) == 0) {
            char json_payload[MAX_PAYLOAD];
            int payload_len = snprintf(json_payload, sizeof(json_payload), "{\"humidity\": %.2f}", humidity);
            if (payload_len < 0 || (size_t)payload_len >= sizeof(json_payload)) {
                syslog(LOG_ERR, "Payload formatting failed");
            } else if (send_http_post(API_ENDPOINT, json_payload) != 0) {
                syslog(LOG_ERR, "Failed to send HTTP POST");
            } else {
                syslog(LOG_INFO, "Humidity: %.2f, Sent to API", humidity);
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }
        sleep(POLL_INTERVAL);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (sockfd >= 0) close(sockfd);
    syslog(LOG_INFO, "Exiting gracefully");
    closelog();
    return 0;
}

