code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID 0x59
#define BMP280_RESET_CMD 0xB6
#define BMP280_CTRL_MEAS 0xF4
#define BMP280_CONFIG 0xF5
#define BMP280_PRESS_MSB 0xF7
#define BMP280_TEMP_MSB 0xFA
#define BMP280_CALIB_START 0x88
#define BMP280_CALIB_LEN 24
#define PRESSURE_THRESHOLD_HIGH 1020.0
#define PRESSURE_THRESHOLD_LOW 980.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_WAIT_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static uint16_t dig_T1;
static int16_t dig_T2, dig_T3;
static uint16_t dig_P1;
static int16_t dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_bytes(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int bmp280_init(int handle) {
    uint8_t chip_id;
    if (i2c_read_bytes(handle, 0xD0, &chip_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read chip ID.\n");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Incorrect chip ID: 0x%02X (expected 0x%02X).\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_MEAS register.\n");
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_CONFIG, 0xA0) != 0) {
        fprintf(stderr, "Error: Failed to write CONFIG register.\n");
        return -1;
    }
    uint8_t calib[BMP280_CALIB_LEN];
    if (i2c_read_bytes(handle, BMP280_CALIB_START, calib, BMP280_CALIB_LEN) != BMP280_CALIB_LEN) {
        fprintf(stderr, "Error: Failed to read calibration data.\n");
        return -1;
    }
    dig_T1 = (uint16_t)(calib[0] | (calib[1] << 8));
    dig_T2 = (int16_t)(calib[2] | (calib[3] << 8));
    dig_T3 = (int16_t)(calib[4] | (calib[5] << 8));
    dig_P1 = (uint16_t)(calib[6] | (calib[7] << 8));
    dig_P2 = (int16_t)(calib[8] | (calib[9] << 8));
    dig_P3 = (int16_t)(calib[10] | (calib[11] << 8));
    dig_P4 = (int16_t)(calib[12] | (calib[13] << 8));
    dig_P5 = (int16_t)(calib[14] | (calib[15] << 8));
    dig_P6 = (int16_t)(calib[16] | (calib[17] << 8));
    dig_P7 = (int16_t)(calib[18] | (calib[19] << 8));
    dig_P8 = (int16_t)(calib[20] | (calib[21] << 8));
    dig_P9 = (int16_t)(calib[22] | (calib[23] << 8));
    return 0;
}

static int bmp280_read_raw(int handle, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t data[6];
    if (i2c_read_bytes(handle, BMP280_PRESS_MSB, data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw data.\n");
        return -1;
    }
    *raw_press = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    *raw_temp = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_temp) {
    double var1 = ((double)raw_temp / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)dig_T1 / 8192.0) * ((double)raw_temp / 131072.0 - (double)dig_T1 / 8192.0) * (double)dig_T3;
    t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

static double bmp280_compensate_press(int32_t raw_press) {
    double var1 = (double)t_fine / 2.0 - 64000.0;
    double var2 = var1 * var1 * (double)dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)dig_P5 * 2.0;
    var2 = var2 / 4.0 + (double)dig_P4 * 65536.0;
    var1 = ((double)dig_P3 * var1 * var1 / 524288.0 + (double)dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)dig_P1;
    if (var1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_press;
    p = (p - var2 / 4096.0) * 6250.0 / var1;
    var1 = (double)dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)dig_P7) / 16.0;
    return p;
}

static int log_pressure(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f hPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", BMP280_I2C_ADDR);
        gpioTerminate();
        return 1;
    }
    if (bmp280_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("BMP280 monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        int32_t raw_temp, raw_press;
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && running) {
            if (bmp280_read_raw(i2c_handle, &raw_temp, &raw_press) == 0) {
                success = 1;
                break;
            }
            retries++;
            fprintf(stderr, "Read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
            gpioDelay(100000);
            if (i2cClose(i2c_handle) >= 0) i2c_handle = -1;
            i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Failed to re-open I2C bus.\n");
                continue;
            }
            if (bmp280_init(i2c_handle) != 0) {
                fprintf(stderr, "Error: BMP280 re-initialisation failed.\n");
                i2cClose(i2c_handle);
                i2c_handle = -1;
                continue;
            }
        }
        if (!success) {
            fprintf(stderr, "Error: Failed to read sensor after %d retries.\n", MAX_RETRIES);
            continue;
        }
        double temperature = bmp280_compensate_temp(raw_temp);
        double pressure = bmp280_compensate_press(raw_press);
        printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);
        if (pressure > PRESSURE_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
            if (log_pressure(pressure) != 0) {
