static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_bytes(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int bmp280_init(int handle) {
    uint8_t chip_id;
    if (i2c_read_bytes(handle, 0xD0, &chip_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read chip ID.\n");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Incorrect chip ID: 0x%02X (expected 0x%02X).\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_MEAS register.\n");
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_CONFIG, 0xA0) != 0) {
        fprintf(stderr, "Error: Failed to write CONFIG register.\n");
        return -1;
    }
    uint8_t calib[BMP280_CALIB_LEN];
    if (i2c_read_bytes(handle, BMP280_CALIB_START, calib, BMP280_CALIB_LEN) != BMP280_CALIB_LEN) {
        fprintf(stderr, "Error: Failed to read calibration data.\n");
        return -1;
    }
    dig_T1 = (uint16_t)(calib[0] | (calib[1] << 8));
    dig_T2 = (int16_t)(calib[2] | (calib[3] << 8));
    dig_T3 = (int16_t)(calib[4] | (calib[5] << 8));
    dig_P1 = (uint16_t)(calib[6] | (calib[7] << 8));
    dig_P2 = (int16_t)(calib[8] | (calib[9] << 8));
    dig_P3 = (int16_t)(calib[10] | (calib[11] << 8));
    dig_P4 = (int16_t)(calib[12] | (calib[13] << 8));
    dig_P5 = (int16_t)(calib[14] | (calib[15] << 8));
    dig_P6 = (int16_t)(calib[16] | (calib[17] << 8));
    dig_P7 = (int16_t)(calib[18] | (calib[19] << 8));
    dig_P8 = (int16_t)(calib[20] | (calib[21] << 8));
    dig_P9 = (int16_t)(calib[22] | (calib[23] << 8));
    return 0;
}

static int bmp280_read_raw(int handle, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t data[6];
    if (i2c_read_bytes(handle, BMP280_PRESS_MSB, data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw data.\n");
        return -1;
    }
    *raw_press = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    *raw_temp = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_temp) {
