/*
 * logger.c — Raspberry Pi 4B environmental logger
 *
 * TMP117 temperature + AHT20 humidity on /dev/i2c-1
 * PIR motion sensor on GPIO17 (gpiochip4 line 17)
 *
 * Build:  gcc -O2 -Wall -Wextra -o logger logger.c -lgpiod -lrt
 * Run:    ./logger
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x15
#define PIR_CHIP       "gpiochip4"
#define PIR_LINE       17

#define TMP117_REG_TEMP_LOW  0x00
#define TMP117_REG_TEMP_HIGH 0x01
#define TMP117_REG_CONFIG    0x03
#define TMP117_CONFIG_CONT_H 0x01
#define TMP117_CONFIG_CONT_L 0x02

#define AHT20_REG_MEASURE    0xE3
#define AHT20_REG_CONFIG     0xE5
#define AHT20_CONFIG_MEAS_H  0x80
#define AHT20_CONFIG_MEAS_L  0x00
#define AHT20_MEAS_DELAY_US 20000

#define LOG_FILE_PREFIX "sensor_data"
#define SAMPLE_INTERVAL_S 1
#define MAX_RETRIES       3
#define RETRY_DELAY_MS    10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t wbuf[1] = { reg };
    if (write(fd, wbuf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t rbuf[2];
    if (read(fd, rbuf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)rbuf[0] | ((uint16_t)rbuf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* TMP117 temperature                                                  */
/* ------------------------------------------------------------------ */

static int tmp117_init(int fd)
{
    if (i2c_write_reg8(fd, TMP117_REG_CONFIG, TMP117_CONFIG_CONT_H) < 0)
        return -1;
    if (i2c_write_reg8(fd, TMP117_REG_CONFIG, TMP117_CONFIG_CONT_L) < 0)
        return -1;
    return 0;
}

static int tmp117_read_temp(int fd, float *temp_c)
{
    uint16_t lo, hi;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(fd, TMP117_REG_TEMP_LOW, &lo) == 0 &&
            i2c_read_reg16(fd, TMP117_REG_TEMP_HIGH, &hi) == 0) {
            int16_t raw = (int16_t)((hi << 8) | lo);
            *temp_c = (float)raw / 16.0f;
            return 0;
        }
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* AHT20 humidity                                                     */
/* ------------------------------------------------------------------ */

static int aht20_init(int fd)
{
    if (i2c_write_reg8(fd, AHT20_REG_CONFIG, AHT20_CONFIG_MEAS_H) < 0)
        return -1;
    if (i2c_write_reg8(fd, AHT20_REG_CONFIG, AHT20_CONFIG_MEAS_L) < 0)
        return -1;
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity)
{
    uint16_t config = AHT20_CONFIG_MEAS_H | AHT20_CONFIG_MEAS_L;
    if (i2c_write_reg8(fd, AHT20_REG_CONFIG, config) < 0)
        return -1;

    usleep(AHT20_MEAS_DELAY_US);

    uint16_t raw;
    if (i2c_read_reg16(fd, AHT20_REG_MEASURE, &raw) < 0)
        return -1;

    *humidity = (float)raw / 16383.0f * 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* PIR motion sensor via libgpiod                                       */
/* ------------------------------------------------------------------ */

static int pir_init(struct gpiod_chip *chip, struct gpiod_line *line)
{
    if (gpiod_line_request_input(line, "pir-logger") < 0) {
        fprintf(stderr, "Failed to request PIR line as input: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int pir_read(struct gpiod_line *line)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Failed to read PIR value: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

/* ------------------------------------------------------------------ */
/* Daily log file creation                                              */
/* ------------------------------------------------------------------ */

static int create_log_file(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char filename[64];

    localtime_r(&now, &tm_info);
    strftime(filename, sizeof(filename), LOG_FILE_PREFIX ".%Y%m%d.csv", &tm_info);

    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Failed to create log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", TMP117_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensors */
    if (tmp117_init(i2c_fd) < 0) {
        fprintf(stderr, "TMP117 init failed — sensor absent or bus error\n");
    }
    if (aht20_init(i2c_fd) < 0) {
        fprintf(stderr, "AHT20 init failed — sensor absent or bus error\n");
    }

    /* Open GPIO chip and request PIR line */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", PIR_CHIP, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_LINE);
    if (!pir_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", PIR_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (pir_init(chip, pir_line) < 0) {
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Create log file at midnight */
    if (create_log_file() < 0) {
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Logger started. Sampling every %d s. Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_S);

    while (g_running) {
        float temp_c = 0.0f;
        float humidity = 0.0f;
        int motion = -1;
        int pir_ok = 0;

        if (tmp117_read_temp(i2c_fd, &temp_c) == 0) {
            pir_ok = 1;
        }
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            pir_ok = 1;
        }

        int pir_val = pir_read(pir_line);
        if (pir_val >= 0) {
            motion = pir_val;
            pir_ok = 1;
        }

        time_t now = time(NULL);
        struct tm tm_info;
        char timestamp[32];
        localtime_r(&now, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

        FILE *fp = fopen(LOG_FILE_PREFIX ".%Y%m%d.csv", "a");
        if (!fp) {
            fprintf(stderr, "Cannot open log file: %s\n", strerror(errno));
        } else {
            if (!pir_ok)
                fprintf(fp, "%s,.,.,.\n", timestamp);
            else
                fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temp_c, humidity, motion);
            fclose(fp);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    /* Clean shutdown */
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    printf("\nLogger stopped.\n");
    return EXIT_SUCCESS;
}

