#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_SEC     5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int motor_stop(void) {
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        log_message("Error: gpioWrite(ENA, 0) failed");
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        log_message("Error: gpioWrite(IN1, 0) failed");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        log_message("Error: gpioWrite(IN2, 0) failed");
        return -1;
    }
    log_message("Motor stopped");
    return 0;
}

static int motor_run_forward(void) {
    if (gpioWrite(MOTOR_ENA_PIN, 1) < 0) {
        log_message("Error: gpioWrite(ENA, 1) failed");
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        log_message("Error: gpioWrite(IN1, 1) failed");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        log_message("Error: gpioWrite(IN2, 0) failed");
        return -1;
    }
    log_message("Motor running forward");
    return 0;
}

static int motor_stop_and_wait(void) {
    if (motor_stop() < 0) {
        return -1;
    }
    for (int i = 0; i < MOTOR_RUN_SEC && g_running; i++) {
        sleep(1);
    }
    return 0;
}

static int read_rain_sensor(void) {
    int level = gpioRead(RAIN_SENSOR_PIN);
    if (level < 0) {
        log_message("Error: gpioRead(RAIN_SENSOR_PIN) failed");
        return -1;
    }
    return (level == 0) ? 1 : 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        log_message("Error: gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        log_message("Error: gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        log_message("Error: gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        log_message("Error: gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Program started");

    while (g_running) {
        int rain = read_rain_sensor();
        if (rain < 0) {
            sleep(POLL_INTERVAL_SEC);
            continue;
        }
        if (rain) {
            log_message("Rain detected!");
            if (motor_run_forward() < 0) {
                log_message("Error: motor_run_forward() failed");
            } else if (motor_stop_and_wait() < 0) {
                log_message("Error: motor_stop_and_wait() failed");
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }

    log_message("Shutting down");
    motor_stop();
    gpioTerminate();
    return EXIT_SUCCESS;
}

