#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_load(float *current, float *previous)
{
    FILE *fp;
    char line[256];
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice, &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 16) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        return -1;
    }

    *current = ((float)(user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice) - (float)(prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice)) / (float)(prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice);
    *previous = *current;

    return 0;
}

static void set_led_color(int red, int green, int blue)
{
    if (red < 0) red = 0;
    if (red > PWM_RANGE) red = PWM_RANGE;
    if (green < 0) green = 0;
    if (green > PWM_RANGE) green = PWM_RANGE;
    if (blue < 0) blue = 0;
    if (blue > PWM_RANGE) blue = PWM_RANGE;

    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

static void turn_off_led(void)
{
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);
}

int main(void)
{
    float current_load, previous_load;
    int red, green, blue;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        if (read_cpu_load(&current_load, &previous_load) != 0) {
            fprintf(stderr, "Error reading CPU load, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (current_load >= 0.5f) {
            red   = (int)(current_load * 255.0f);
            green = 0;
            blue  = 0;
        } else if (current_load >= 0.0f) {
            red   = 0;
            green = (int)((current_load / 0.5f) * 255.0f);
            blue  = 0;
        } else {
            red   = 0;
            green = 0;
            blue  = (int)((1.0f - current_load) * 255.0f);
        }

        set_led_color(red, green, blue);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    turn_off_led();
    gpioTerminate();
    return 0;
}

