    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
