static FanData fan_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void print_buffer(void) {
    printf("\n--- Fan Data Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        char time_str[32];
        struct tm *tm_info = localtime(&fan_buffer[i].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Temp: %.2f C, Duty: %d\n", time_str,
               fan_buffer[i].temperature, fan_buffer[i].duty_cycle);
    }
    printf("--- End of Log ---\n\n");
}

static int read_max31855(int handle, float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault bit set (0x00010000)\n");
        return -1;
