    if (temperature < TEMP_LOW) {
        return DUTY_LOW;
    } else if (temperature < TEMP_MID) {
        return DUTY_LOW + (int)((temperature - TEMP_LOW) *
                               (DUTY_HIGH - DUTY_LOW_PERCENT) /
                               (TEMP_MID - TEMP_LOW));
    } else if (temperature < TEMP_HIGH) {
        return DUTY_MID + (int)((temperature - TEMP_MID) *
                               (DUTY_HIGH_PERCENT - DUTY_MID_PERCENT) /
                               (TEMP_HIGH - TEMP_MID));
    } else {
        return DUTY_HIGH;
    }
}

static void update_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty_cycle);
    }
