        int duty_cycle = calculate_duty_cycle(temperature);
        update_fan_speed(duty_cycle);
        add_to_buffer(temperature, duty_cycle);

        printf("Temp: %.2f C, Duty: %d\n", temperature, duty_cycle);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    update_fan_speed(0);
    spiClose(spi_handle);
    gpioTerminate();
    print_buffer();
    return EXIT_SUCCESS;
}

