#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define BMP180_ADDR 0x5C
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define OSS 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t logging_enabled = 0;
static volatile sig_atomic_t running = 1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    int rc;
    rc = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)ac1, 2);
    if (rc != 2) return -1;
    rc = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC2, (char *)ac2, 2);
    if (rc != 2) return -1;
    rc = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC3, (char *)ac3, 2);
    if (rc != 2) return -1;
    rc = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC4, (char *)ac4, 2);
    if (rc != 2) return -1;
    rc = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC5, (char *)ac5, 2);
    if (rc != 2) return -1;
    rc = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC6, (char *)ac6, 2);
    if (rc != 2) return -1;
    rc = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_B1, (char *)b1, 2);
    if (rc != 2) return -1;
    rc = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_B2, (char *)b2, 2);
    if (rc != 2) return -1;
    rc = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_MB, (char *)mb, 2);
    if (rc != 2) return -1;
    rc = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_MC, (char *)mc, 2);
    if (rc != 2) return -1;
    rc = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_MD, (char *)md, 2);
    if (rc != 2) return -1;
    return 0;
}

static int read_raw_temperature(int *raw_temperature) {
    int rc;
    rc = i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E);
    if (rc != 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, NULL, 2);
    if (msb != 2) return -1;
    *raw_temperature = (msb << 8) | i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB + 1, NULL, 1);
    return 0;
}

static int read_raw_pressure(int *raw_pressure) {
    int rc;
    rc = i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6));
    if (rc != 0) return -1;
    gpioDelay(2000 + (3000 << OSS));
    int msb = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, NULL, 2);
    if (msb != 3) return -1;
    *raw_pressure = ((msb << 16) | i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB + 1, NULL, 2)) >> (8 - OSS);
    return 0;
}

static int calculate_temperature(int raw_temperature, double *temperature) {
    long x1 = ((long)raw_temperature - ac6) * ac5 >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    *temperature = ((b5 + 8) >> 4) / 10.0;
    return 0;
}

static int calculate_pressure(int raw_pressure, int raw_temperature, double *pressure) {
    long x1 = ((long)raw_temperature - ac6) * ac5 >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    long b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 >> 12)) >> 11;
    x2 = (ac2 * b6) >> 11;
    long x3 = x1 + x2;
    long b3 = (((((long)ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    unsigned long b4 = (ac4 * (unsigned long)(x3 + 32768)) >> 15;
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);
    long p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    *pressure = p + ((x1 + x2 + 3791) >> 4);
    return 0;
}

static int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure) < 0) return -1;
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(2, PI_INPUT);
    gpioSetPullUpDown(2, PI_PUD_UP);
    signal(SIGINT, signal_handler);
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) {
        if (logging_enabled) {
            int raw_temperature, raw_pressure;
            double temperature, pressure;
            if (read_raw_temperature(&raw_temperature) != 0) {
                fprintf(stderr, "Error reading raw temperature\n");
            } else if (read_raw_pressure(&raw_pressure) != 0) {
                fprintf(stderr, "Error reading raw pressure\n");
            } else {
                calculate_temperature(raw_temperature, &temperature);
                calculate_pressure(raw_pressure, raw_temperature, &pressure);
                if (log_data(temperature, pressure) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            }
        }
        gpioDelay(1000000);
    }
    if (log_file != NULL) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

