#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define BME280_CHIP_ID 0x60
#define BME280_RESET_CMD 0xB6
#define BME280_CTRL_MEAS_HOLD 0x25
#define BME280_CTRL_HUMIDITY_HOLD 0x01
#define BME280_CONFIG_T_SB 0x00
#define BME280_CONFIG_FILTER_HOLD 0x01
#define BME280_CTRL_MEAS_T_HOLD 0x25
#define BME280_DATA_T_MSB 0xFA
#define BME280_DATA_P_MSB 0xF7
#define BME280_DATA_H_MSB 0xFD
#define BME280_DATA_CTRL_MEAS_HOLD 0x24
#define BME280_DATA_CTRL_HUMIDITY_HOLD 0x26
#define BME280_DATA_CONFIG_HOLD 0x27
#define BME280_DATA_RESET_HOLD 0x2E
#define BME280_DATA_STATUS_HOLD 0x27
#define BME280_DATA_ID 0xD0
#define BME280_DATA_RESET_CMD 0x80

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bme280_init(int fd) {
    uint8_t chip_id = 0;
    if (i2c_read_bytes(fd, BME280_DATA_ID, &chip_id, 1) != 0) {
        return -1;
    }
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "BME280 chip ID mismatch: expected 0x%02X, got 0x%02X\n", BME280_CHIP_ID, chip_id);
        return -1;
    }
    if (i2c_write_byte(fd, BME280_DATA_RESET_CMD, BME280_RESET_CMD) != 0) {
        return -1;
    }
    usleep(2000);
    if (i2c_write_byte(fd, BME280_DATA_CTRL_HUMIDITY_HOLD, BME280_CTRL_HUMIDITY_HOLD) != 0) {
        return -1;
    }
    if (i2c_write_byte(fd, BME280_DATA_CONFIG_HOLD, BME280_CONFIG_T_SB | BME280_CONFIG_FILTER_HOLD) != 0) {
        return -1;
    }
    if (i2c_write_byte(fd, BME280_DATA_CTRL_MEAS_HOLD, BME280_CTRL_MEAS_HOLD) != 0) {
        return -1;
    }
    return 0;
}

static int bme280_read_data(int fd, float *temperature, float *humidity, float *pressure) {
    uint8_t data[12];
    if (i2c_read_bytes(fd, BME280_DATA_CTRL_MEAS_HOLD, data, 12) != 0) {
        return -1;
    }
    int32_t raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_humidity = (data[6] << 8) | data[7];
    int32_t t_fine = (raw_temperature + 8192) >> 15;
    *pressure = (float)raw_pressure / 100.0f;
    *temperature = (float)(t_fine * 175.0f / 65536.0f) - 46.85f;
    *humidity = (float)(raw_humidity / 1024.0f) * 100.0f;
    return 0;
}

static int log_data(FILE *fp, float temperature, float humidity, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
