#define BME280_DATA_T_MSB 0xFA
#define BME280_DATA_P_MSB 0xF7
#define BME280_DATA_H_MSB 0xFD
#define BME280_DATA_CTRL_MEAS_HOLD 0x24
#define BME280_DATA_CTRL_HUMIDITY_HOLD 0x26
#define BME280_DATA_CONFIG_HOLD 0x27
#define BME280_DATA_RESET_HOLD 0x2E
#define BME280_DATA_STATUS_HOLD 0x27
#define BME280_DATA_ID 0xD0
#define BME280_DATA_RESET_CMD 0x80

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
