#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x5C
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define DEVIATION_THRESHOLD 5.0
#define SAMPLE_INTERVAL_US 50000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static int32_t t_fine;

typedef struct {
    time_t timestamp;
    double pressure;
} PressureReading;

static PressureReading pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1 = (int16_t)((buf[12] << 8) | buf[13]);
    b2 = (int16_t)((buf[14] << 8) | buf[15]);
    mb = (int16_t)((buf[16] << 8) | buf[17]);
    mc = (int16_t)((buf[18] << 8) | buf[19]);
    md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int32_t *raw_temp) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x2E};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) return -1;
    gpioDelay(5000);
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) return -1;
    *raw_temp = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static int read_raw_pressure(int32_t *raw_pressure) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) return -1;
    gpioDelay(26000);
    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) return -1;
    *raw_pressure = ((int32_t)(data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

static double calculate_pressure(int32_t ut, int32_t up) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    t_fine = x1 + x2;
    int32_t at = t_fine - 32768;
    x1 = ((int32_t)b2 * (at * at >> 12)) >> 11;
    x2 = ((int32_t)ac2 * at) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b5 = ((int32_t)b1 * (at * at >> 12)) >> 16;
    int32_t b6 = ((int32_t)ac3 * at) >> 15;
    x1 = (b5 + b6) >> 10;
    x2 = ((int32_t)ac4 * (at * at >> 12)) >> 13;
    x3 = ((x1 + x2) + 32768) >> 15;
    b3 = (((int32_t)ac1 * 4 + x3) << BMP180_OSS) >> 2;
    x1 = ((int32_t)ac3 * (at * at >> 12)) >> 13;
    x2 = ((int32_t)b1 * (at * at >> 12)) >> 16;
    x3 = ((x1 + x2) + 32768) >> 15;
    b4 = ((int32_t)ac4 * (x3 + 32768)) >> 15;
    b5 = ((int32_t)b1 * (at * at >> 12)) >> 16;
    b6 = ((int32_t)ac3 * (at * at >> 12)) >> 13;
    x1 = (b5 + b6) >> 10;
    x2 = ((int32_t)ac2 * (at * at >> 12)) >> 13;
    x3 = ((x1 + x2) + 32768) >> 15;
    b3 = (((int32_t)ac1 * 4 + x3) << BMP180_OSS) >> 2;
    x1 = ((int32_t)ac3 * (at * at >> 12)) >> 13;
    x2 = ((int32_t)b1 * (at * at >> 12)) >> 16;
    x3 = ((x1 + x2) + 32768) >> 15;
    b4 = ((int32_t)ac4 * (x3 + 32768)) >> 15;
    b5 = ((int32_t)b1 * (at * at >> 12)) >> 16;
    b6 = ((int32_t)ac3 * (at * at >> 12)) >> 13;
    x1 = (b5 + b6) >> 10;
    x2 = ((int32_t)ac2 * (at * at >> 12)) >> 13;
    x3 = ((x1 + x2) + 32768) >> 15;
    b3 = (((int32_t)ac1 * 4 + x3) << BMP180_OSS) >> 2;
    x1 = ((int32_t)ac3 * (at * at >> 12)) >> 13;
    x2 = ((int32_t)b1 * (at * at >> 12)) >> 16;
    x3 = ((x1 + x2) + 32768) >> 15;
    b4 = ((int32_t)ac4 * (x3 + 32768)) >> 15;
    b5 = ((int32_t)b1 * (at * at >> 12)) >> 16;
    b6 = ((int32_t)ac3 * (at * at >> 12)) >> 13;
    x1 = (b5 + b6) >> 10;
    x2 = ((int32_t)ac2 * (at * at >> 12)) >> 13;
    x3 = ((x1 + x2) + 32768) >> 15;
    b3 = (((int32_t)ac1 * 4 + x3) << BMP180_OSS) >> 2;
    int32_t b6_tr = b6 - 32768;
    int32_t x1_t = (b2 * (b6_tr * b6_tr >> 12)) >> 11;
    int32_t x2_t = (ac2 * b6_tr) >> 11;
    int32_t x3_t = x1_t + x2_t;
    int32_t b3_t = (((ac1 * 4 + x3_t) << BMP180_OSS) + 2) >> 2;
    int32_t x1_p = (ac3 * b6_tr) >> 13;
    int32_t x2_p = (b1 * (b6_tr * b6_tr >> 12)) >> 16;
    int32_t x3_p = (x1_p + x2_p) + 32768;
    b4 = (ac4 * x3_p) >> 15;
    b5 = (ac5 * b6_tr) >> 16;
    b6 = (b3_t + b5) >> 10;
    x1 = (b4 + b6) >> 10;
    x2 = (ac2 * b6_tr) >> 13;
    x3 = (x1 + x2) + 32768;
    return (double)b6_tr + ((x3 + 32768) >> 15) * 2.0;
}

static void add_reading(PressureReading reading) {
    pressure_buffer[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static double calculate_average_pressure(void) {
    if (buffer_count == 0) return 0.0;
    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) sum += pressure_buffer[i].pressure;
    return sum / buffer_count;
}

static void check_deviation(double current_pressure, double average_pressure) {
    if (buffer_count >= 2) {
        double deviation = current_pressure - average_pressure;
        if (deviation > DEVIATION_THRESHOLD) {
            gpioWrite(ALERT_GPIO, 1);
            fprintf(stderr, "Alert: Pressure deviation %.2f hPa exceeds threshold %.1f hPa\n", deviation, DEVIATION_THRESHOLD);
        } else {
            gpioWrite(ALERT_GPIO, 0);
        }
    }
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t raw_temp, raw_pressure;
    if (read_raw_temperature(&raw_temp) != 0) {
        fprintf(stderr, "Error: Failed to read raw temperature\n");
        return;
    }
    if (read_raw_pressure(&raw_pressure) != 0) {
        fprintf(stderr, "Error: Failed to read raw pressure\n");
        return;
    }
    double pressure = calculate_pressure(raw_temp, raw_pressure);
    time_t now = time(NULL);
    PressureReading reading = {now, pressure};
    add_reading(reading);
    double avg = calculate_average_pressure();
    check_deviation(pressure, avg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) {
        gpioDelay(1000000);
    }
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, NULL, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

