static void log_data(float temp, float press) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }
    fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    int addr = BMP280_I2C_ADDR_DEFAULT;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return 1;
    }

    bmp280_calib_t cal;
    if (bmp280_init(fd, &cal) < 0) {
        fprintf(stderr, "BMP280 init failed\n");
        close(fd);
        return 1;
    }

    printf("BMP280 initialized at 0x%02X. Logging every %d s to %s\n", addr, LOG_INTERVAL_SEC, LOG_FILE);

    while (g_running) {
        float temp, press;
        if (bmp280_read(fd, &cal, &temp, &press) < 0) {
            fprintf(stderr, "BMP280 read error: %s\n", strerror(errno));
        } else {
            log_data(temp, press);
            printf("Logged: %.2f °C, %.2f hPa\n", temp, press);
        }
        for (int i = 0; i < LOG_INTERVAL_SEC && g_running; i++) sleep(1);
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return 0;
}

