#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS          1
#define LM75_ADDR        0x48
#define GPIO_LED         18
#define BUFFER_SIZE      60
#define TEMP_THRESHOLD   28.0f
#define SAMPLE_PERIOD_S  1
#define I2C_RETRIES      3
#define I2C_RETRY_DELAY  100000  /* microseconds */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static pthread_mutex_t g_buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float    g_buffer[BUFFER_SIZE];
static int      g_buf_count = 0;
static int      g_buf_index = 0;
static float    g_running_avg = 0.0f;
static bool     g_gpio_initialized = false;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_init(void)
{
    char filename[32];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);

    g_i2c_fd = open(filename, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                LM75_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int i2c_read_temp(float *temp)
{
    uint8_t cmd = 0x00;
    uint8_t buf[2];
    int retries = I2C_RETRIES;

    while (retries > 0) {
        if (write(g_i2c_fd, &cmd, 1) != 1) {
            fprintf(stderr, "I2C write error: %s\n", strerror(errno));
            retries--;
            if (retries > 0) usleep(I2C_RETRY_DELAY);
            continue;
        }

        usleep(10000);  /* 10 ms conversion wait */

        if (read(g_i2c_fd, buf, 2) != 2) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            retries--;
            if (retries > 0) usleep(I2C_RETRY_DELAY);
            continue;
        }

        int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
        *temp = (float)raw / 16.0f;
        return 0;
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", I2C_RETRIES);
    return -1;
}

static void buffer_add(float temp)
{
    pthread_mutex_lock(&g_buffer_mutex);
    g_buffer[g_buf_index] = temp;
    g_buf_index = (g_buf_index + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE) g_buf_count++;
    pthread_mutex_unlock(&g_buffer_mutex);
}

static float buffer_avg(void)
{
    pthread_mutex_lock(&g_buffer_mutex);
    float sum = 0.0f;
    int count = (g_buf_count < BUFFER_SIZE) ? g_buf_count : BUFFER_SIZE;
    if (count > 0) {
        for (int i = 0; i < count; i++)
            sum += g_buffer[i];
    }
    pthread_mutex_unlock(&g_buffer_mutex);
    return (count > 0) ? (sum / count) : 0.0f;
}

static void led_set(bool on)
{
    if (g_gpio_initialized)
        gpioWrite(GPIO_LED, on ? 1 : 0);
}

static void *led_thread(void *arg)
{
    (void)arg;
    while (g_running) {
        float avg = buffer_avg();
        bool above = (avg > TEMP_THRESHOLD);
        led_set(above);
        sleep(1);
    }
    led_set(false);
    return NULL;
}

static void cleanup(void)
{
    if (g_gpio_initialized) {
        gpioWrite(GPIO_LED, 0);
        gpioTerminate();
        g_gpio_initialized = false;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    pthread_mutex_destroy(&g_buffer_mutex);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (i2c_init() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }
    g_gpio_initialized = true;

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", GPIO_LED);
        cleanup();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    pthread_t led_tid;
    if (pthread_create(&led_tid, NULL, led_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create LED thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (g_running) {
        float temp;
        if (i2c_read_temp(&temp) == 0) {
            buffer_add(temp);
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Sensor read failed. Re-initializing I2C.\n");
            if (g_i2c_fd >= 0) {
                close(g_i2c_fd);
                g_i2c_fd = -1;
            }
            if (i2c_init() != 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                g_running = 0;
            }
        }
        sleep(SAMPLE_PERIOD_S);
    }

    pthread_join(led_tid, NULL);
    cleanup();
    return 0;
}

