static volatile sig_atomic_t running = 1;
static double target_temp = DEFAULT_TARGET_TEMP;
static double kp = DEFAULT_KP;
static double ki = DEFAULT_KI;
static double kd = DEFAULT_KD;
static int spi_handle = -1;
static int pigpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double read_rtd(void) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};
    int ret;

    ret = spiXfer(spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return ERROR_SPI;
    }

    int32_t raw = ((int32_t)(uint8_t)rx[0] << 24) |
                  ((int32_t)(uint8_t)rx[1] << 16) |
                  ((int32_t)(uint8_t)rx[2] << 8)  |
                  ((int32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31865 fault bit set: 0x%08X\n", raw);
        return ERROR_RTD;
    }

    if (raw & 0x00000003) {
        fprintf(stderr, "MAX31865 open-circuit or short-circuit\n");
        return ERROR_RTD;
    }

    int32_t rtd_raw = raw >> 18;
    if (rtd_raw & 0x00000001) {
        rtd_raw |= 0xE0000000;
    }

    double rtd_resistance = (rtd_raw * 430.0) / 32768.0;
    return rtd_resistance;
}

static double calculate_temperature(double rtd_resistance) {
    return (rtd_resistance - 100.0) / 0.43;
}

static double pid_control(double current_temp) {
    double error = target_temp - current_temp;
    double integral = 0.0;
    double prev_error = 0.0;

    if (fabs(error) < 0.001) {
        error = 0.0;
    }

    integral += error;
    double derivative = error - prev_error;
    double output = kp * error + ki * integral + kd * derivative;

    prev_error = error;
    return output;
}

static void set_heater_pwm(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    if (gpioPWM(HEATER_GPIO, (int)duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (pigpio_initialized) {
        gpioPWM(HEATER_GPIO, 0);
        gpioTerminate();
        pigpio_initialized = 0;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
}

static int load_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: could not open config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char *target = getenv("TARGET_TEMP");
    char *kp_str = getenv("KP");
    char *ki_str = getenv("KI");
    char *kd_str = getenv("KD");

    if (target) {
        target_temp = atof(target);
    } else {
        target_temp = DEFAULT_TARGET_TEMP;
    }

    if (kp_str) {
        kp = atof(kp_str);
    } else {
        kp = DEFAULT_KP;
    }

    if (ki_str) {
        ki = atof(ki_str);
    } else {
        ki = DEFAULT_KI;
    }

    if (kd_str) {
        kd = atof(kd_str);
    } else {
        kd = DEFAULT_KD;
    }

    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return 1;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return 1;
    }
    if (gpioPWM(HEATER_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialise PWM to 0\n");
        cleanup();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (load_config(CONFIG_FILE) != 0) {
        fprintf(stderr, "Using default configuration values.\n");
    }

    printf("PID Heater Control Started\n");
    printf("Target Temperature: %.2f C\n", target_temp);
    printf("Kp: %.2f, Ki: %.2f, Kd: %.2f\n", kp, ki, kd);

    while (running) {
        double rtd_resistance = read_rtd();
        if (rtd_resistance < ERROR_TEMP) {
            fprintf(stderr, "Error reading RTD, setting heater to 0\n");
            set_heater_pwm(0.0);
            break;
        }

        double temperature = calculate_temperature(rtd_resistance);
        if (temperature > MAX_TEMP) {
            fprintf(stderr, "Temperature exceeds max limit (%.2f > %.2f), shutting down\n",
                    temperature, MAX_TEMP);
            set_heater_pwm(0.0);
            break;
        }

        double duty_cycle = pid_control(temperature);
        set_heater_pwm(duty_cycle);

        printf("Temperature: %.2f C, Duty Cycle: %.2f %%\n", temperature, duty_cycle);
        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

