#include <string.h>

#define BMP180_ADDR 0x5C
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 30.0
#define TIMER_MS 500

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA

#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t timer_fired = 0;
static int i2c_handle = -1;
static bmp180_cal_t cal;
static circular_buffer_t buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void timer_callback(void *user) {
    (void)user;
    timer_fired = 1;
}

static int read_calibration(int handle, bmp180_cal_t *c) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: failed to read 22-byte calibration block\n");
        return -1;
    }
    c->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    c->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    c->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    c->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    c->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    c->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    c->b1 = (int16_t)((buf[12] << 8) | buf[13]);
    c->b2 = (int16_t)((buf[14] << 8) | buf[15]);
    c->mb = (int16_t)((buf[16] << 8) | buf[17]);
    c->mc = (int16_t)((buf[18] << 8) | buf[19]);
    c->md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE0) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[3];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 3) != 3) return -1;
    *up = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - 0);
    return 0;
}

static float calculate_temperature(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    int32_t b5 = x1 + x2;
    return (float)((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << 0) + 2) >> 2);
    uint32_t x1_u = ((uint32_t)c->ac3 * b6) >> 13;
    uint32_t x2_u = ((uint32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x3_u = (x1_u + x2_u + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (x3_u + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return (float)(p + ((x1 + x2 + 3791) >> 4));
}

static void add_to_buffer(circular_buffer_t *buf, time_t ts, float temp, float pres) {
    buf->data[buf->head].timestamp = ts;
    buf->data[buf->head].temperature = temp;
    buf->data[buf->head].pressure = pres;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void control_fan(float temp) {
    gpioWrite(FAN_GPIO, temp > TEMP_THRESHOLD ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration(i2c_handle, &cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);
    buffer.head = 0;
    buffer.count = 0;
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, TIMER_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        if (timer_fired) {
            timer_fired = 0;
            int32_t ut, up;
            if (read_raw_temperature(i2c_handle, &ut) == 0 && read_raw_pressure(i2c_handle, &up) == 0) {
                float temp = calculate_temperature(ut, &cal);
                float pres = calculate_pressure(up, ut, &cal);
                add_to_buffer(&buffer, time(NULL), temp, pres);
                control_fan(temp);
                printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n",
                       (long)time(NULL), temp, pres);
            } else {
                fprintf(stderr, "Error: sensor read failed, skipping sample\n");
            }
        }
        gpioDelay(10000);
    }
    gpioSetTimerFuncEx(0, TIMER_MS, NULL, NULL);
    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

