#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BMP180_ADDR 0x5C
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS 0x34
#define GPIO_INTERRUPT 27
#define DEBOUNCE_US 200000
#define LOG_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_interrupt_tick = 0;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg16u(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration_data(void) {
    if (i2c_read_reg16(i2c_fd, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (i2c_read_reg16u(i2c_fd, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (i2c_read_reg16u(i2c_fd, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (i2c_read_reg16u(i2c_fd, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, BMP180_REG_CAL_MD, &md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int32_t *raw_temp) {
    if (i2c_write_reg8(i2c_fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    uint8_t msb, lsb;
    if (i2c_read_reg8(i2c_fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(i2c_fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    *raw_temp = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int32_t *raw_pressure) {
    if (i2c_write_reg8(i2c_fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS + 0x80) < 0) return -1;
    gpioDelay(26000);
    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg8(i2c_fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(i2c_fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg8(i2c_fd, BMP180_REG_XLSB, &xlsb) < 0) return -1;
    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - 0);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    return x1 + x2;
}

static int32_t calculate_pressure(int32_t up, int32_t ut) {
    int32_t b5 = compute_b5(ut);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) / 4;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_pressure(int32_t pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, Pressure: %d Pa\n", timestamp, pressure);
    fflush(log_file);
}

static void interrupt_handler(int gpio, int level, uint32_t tick) {
