#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define HEATER_GPIO 17
#define MAX_DUTY_CYCLE 80
#define DEFAULT_TARGET_TEMPERATURE 25.0
#define LOG_FILE "heater_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d,%s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

static int read_max31855(int handle, float *temp) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(handle, tx, rx, 4) != 4) {
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000004) {
            log_message("MAX31855 Fault: Open Circuit");
        } else if (raw & 0x00000002) {
            log_message("MAX31855 Fault: Short to GND");
        } else {
            log_message("MAX31855 Fault: Short to VCC");
        }
        return -1;
    }

    int16_t temp_raw = (int16_t)(raw >> 18);
    *temp = (float)temp_raw * 0.25;
    return 0;
}

static int set_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    int pwm_range = 100;
    int pwm_value = (duty_cycle * pwm_range) / 100;
    if (gpioPWM(gpio, pwm_value) != 0) {
        return -1;
    }
    return 0;
}

static int pi_controller(float target_temp, float current_temp, float *integral, float *prev_error) {
    float error = target_temp - current_temp;
    float kp = 1.0;
    float ki = 0.1;
    *integral += error;
    if (*integral > 100.0) *integral = 100.0;
    if (*integral < 0.0) *integral = 0.0;
    float derivative = error - *prev_error;
    float output = kp * error + ki * (*integral);
    *prev_error = error;
    if (output < 0) output = 0;
    if (output > 100) output = 100;
    return (int)output;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, 100) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", HEATER_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float target_temp = DEFAULT_TARGET_TEMPERATURE;
    float integral = 0.0;
    float prev_error = 0.0;

    while (running) {
        float temp = 0.0;
        if (read_max31855(spi_handle, &temp) != 0) {
            log_message("SPI read error or MAX31855 fault");
            set_duty_cycle(HEATER_GPIO, 0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int duty_cycle = pi_controller(target_temp, temp, &integral, &prev_error);
        set_duty_cycle(HEATER_GPIO, duty_cycle);

        time_t t = time(NULL);
        struct tm tm;
        localtime_r(&t, &tm);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(log_file, "%s,%.2f,%d\n", ts, temp, duty_cycle);
        fflush(log_file);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_duty_cycle(HEATER_GPIO, 0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

