#define BLUE_PIN  27

#define PWM_RANGE 255

#define TEMP_FILE "temperature.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN,   red) != 0) return -1;
    if (gpioPWM(GREEN_PIN, green) != 0) return -1;
    if (gpioPWM(BLUE_PIN,  blue) != 0) return -1;
    return 0;
}

static int read_temperature(const char *filename, int *temperature_milli_c) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }

    if (fgets(temperature_milli_c, sizeof(temperature_milli_c), fp) == NULL) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static void map_temperature_to_color(int temperature_milli_c, int *red, int *green, int *blue) {
    if (temperature_milli_c < 40000) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temperature_milli_c < 60000) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int temperature_milli_c;
        if (read_temperature(TEMP_FILE, &temperature_milli_c) != 0) {
            fprintf(stderr, "Failed to read temperature, skipping cycle\n");
            sleep(0.5);
            continue;
        }

        int red, green, blue;
        map_temperature_to_color(temperature_milli_c, &red, &green, &blue);

        if (set_led_color(red, green, blue) != 0) {
            fprintf(stderr, "Failed to set LED color\n");
            break;
        }

        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n",
               temperature_milli_c, red, green, blue);
        fflush(stdout);

        sleep(0.5);
    }

    /* Turn off LED and release pigpio resources */
    set_led_color(0, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

