#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/select.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DHT22_GPIO 4
#define SERVER_IP "yourserver.com"
#define SERVER_PORT 80
#define MAX_RETRIES 3
#define DHT22_TIMEOUT_US 100000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_dht22(float *humidity, float *temperature) {
    int fd = open("/sys/class/gpio/gpio4/value", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO value file: %s\n", strerror(errno));
        return -1;
    }

    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int last_val = 1;
    int timeout = 0;

    while (bit_idx < 40) {
        int val = open("/sys/class/gpio/gpio4/value", O_RDONLY);
        if (val < 0) {
            fprintf(stderr, "Error opening GPIO value file: %s\n", strerror(errno));
            close(fd);
            return -1;
        }

        int current_val = open("/sys/class/gpio/gpio4/value", O_RDONLY);
        if (current_val < 0) {
            fprintf(stderr, "Error opening GPIO value file: %s\n", strerror(errno));
            close(fd);
            return -1;
        }

        if (current_val != last_val) {
            data[bit_idx / 8] <<= 1;
            if (current_val == 0) {
                data[bit_idx / 8] |= 1;
            }
            last_val = current_val;
            bit_idx++;
            timeout = 0;
        } else {
            timeout++;
            if (timeout > DHT22_TIMEOUT_US) {
                fprintf(stderr, "DHT22 timeout at bit %d\n", bit_idx);
                close(fd);
                return -1;
            }
        }
    }

    close(fd);

    if (bit_idx != 40) {
        fprintf(stderr, "DHT22 incomplete read: %d bits\n", bit_idx);
        return -1;
    }

    unsigned char checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        fprintf(stderr, "DHT22 checksum error: computed 0x%02X, received 0x%02X\n", checksum, data[4]);
        return -1;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int send_http_request(float humidity, float temperature) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);

    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address: %s\n", SERVER_IP);
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Connection failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }

    char json_payload[256];
    snprintf(json_payload, sizeof(json_payload),
             "{\"humidity\": %.1f, \"temperature\": %.1f}", humidity, temperature);

    if (send(sock, json_payload, strlen(json_payload), 0) < 0) {
        fprintf(stderr, "Send failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }

    close(sock);
    return 0;
}

int main() {
    float humidity, temperature;
    int retries;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("DHT22 sensor reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        retries = 0;
        while (retries < MAX_RETRIES && program_running) {
            if (read_dht22(&humidity, &temperature) == 0) {
                printf("Humidity: %.1f%%, Temperature: %.1f°C\n", humidity, temperature);
                if (send_http_request(humidity, temperature) != 0) {
                    fprintf(stderr, "Failed to send HTTP request.\n");
                }
                break;
            } else {
                fprintf(stderr, "DHT22 read failed. Retrying...\n");
                retries++;
                if (retries < MAX_RETRIES) {
                    sleep(2);
                }
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached. Exiting.\n");
            break;
        }

        sleep(5);
    }

    printf("Exiting.\n");
    return 0;
}

