#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x5C
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS3 0x34
#define OSS 3
#define LOG_FILE "pressure_log.txt"
#define BUTTON_GPIO 4
#define DEBOUNCE_US 200000
#define CONVERSION_DELAY_US 26000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_interrupt_tick = 0;
static int i2c_handle = -1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_interrupt_handler(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)level;
    if (tick - last_interrupt_tick > DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        fflush(stdout);
        last_interrupt_tick = tick;
    }
}

static int read_calibration_data(void) {
    int v;
    v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1);
    if (v < 0) return -1; ac1 = (int16_t)v;
    v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC2);
    if (v < 0) return -1; ac2 = (int16_t)v;
    v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC3);
    if (v < 0) return -1; ac3 = (int16_t)v;
    v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC4);
    if (v < 0) return -1; ac4 = (uint16_t)v;
    v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC5);
    if (v < 0) return -1; ac5 = (uint16_t)((v << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC6));
    v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_B1);
    if (v < 0) return -1; b1 = (int16_t)v;
    v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_B2);
    if (v < 0) return -1; b2 = (int16_t)v;
    v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_MB);
    if (v < 0) return -1; mb = (int16_t)v;
    v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_MC);
    if (v < 0) return -1; mc = (int16_t)v;
    v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_MD);
    if (v < 0) return -1; md = (int16_t)v;
    return 0;
}

static int read_raw_temperature(int32_t *raw_temp) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    *raw_temp = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *raw_pressure) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS3) < 0) return -1;
    gpioDelay(CONVERSION_DELAY_US);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (xlsb < 0) return -1;
    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    return x1 + x2;
}

static float calculate_pressure(int32_t up, int32_t ut) {
    int32_t b5 = compute_b5(ut);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)ac1 * 4 + x3) << OSS) + 2;
    b3 /= 4;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p / 100.0f;
}

static void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
