    if (read_calibration_data() < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    printf("BMP180 pressure logger started. Press button on GPIO4 to toggle logging.\n");
    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) < 0 || read_raw_pressure(&up) < 0) {
                fprintf(stderr, "I2C read error\n");
            } else {
                float p = calculate_pressure(up, ut);
                log_pressure(p);
            }
        }
        gpioDelay(100000);
    }
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
