#include <getopt.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 2
#define READ_INTERVAL_SEC 10
#define POST_INTERVAL_SEC 10
#define POST_MAX_RETRIES 3
#define POST_RETRY_DELAY_SEC 2
#define DHT22_TIMEOUT_US 1000000
#define DHT22_MAX_EDGES 85

static volatile sig_atomic_t g_terminate = 0;
static char *g_api_url = "http://your-the-librarys-api-call.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    g_terminate = 1;
}

static void log_message(int priority, const char *msg) {
    syslog(priority, "%s", msg);
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000,
        .tv_nsec = (long)(us % 1000000) * 1000
    };
    nanosleep(&ts, NULL);
}

static int dht22_read(int gpio, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int counter = 0;
    int j = 0;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, PI_LOW);
    sleep_us(2000);
    gpioWrite(gpio, PI_HIGH);
    sleep_us(30);
    gpioSetMode(gpio, PI_INPUT);

    int timeout = 0;
    while (gpioRead(gpio) == PI_HIGH) {
        if (++timeout > DHT22_TIMEOUT_US) return -1;
        sleep_us(1);
    }
    timeout = 0;
    while (gpioRead(gpio) == PI_LOW) {
        if (++timeout > DHT22_TIMEOUT_US) return -1;
        sleep_us(1);
    }
    timeout = 0;
    while (gpioRead(gpio) == PI_HIGH) {
        if (++timeout > DHT22_TIMEOUT_US) return -1;
        sleep_us(1);
    }

    for (int i = 0; i < DHT22_MAX_EDGES; i++) {
        timeout = 0;
        while (gpioRead(gpio) == PI_LOW) {
            if (++timeout > DHT22_TIMEOUT_US) return -1;
            sleep_us(1);
        }
        if (timeout > 50) break;
        timeout = 0;
        while (gpioRead(gpio) == PI_HIGH) {
            if (++timeout > DHT22_TIMEOUT_US) return -1;
            sleep_us(1);
        }
        if (timeout > 50) break;

        int duration = 0;
        while (gpioRead(gpio) == PI_HIGH) {
            if (++duration > DHT22_TIMEOUT_US) return -1;
            sleep_us(1);
        }
        data[j / 8] <<= 1;
        if (duration > 50) data[j / 8] |= 1;
        j++;
    }

    if (j < 40) return -1;

    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) return -2;

    *humidity = (float)(((data[0] << 8) + data[1]) / 10.0);
    return 0;
}

static int post_humidity(const char *url, float humidity) {
    char json[128];
    snprintf(json, sizeof(json), "{\"humidity\":%.2f}", humidity);

    char cmd[512];
    snprintf(cmd, sizeof(cmd), "curl -s -o /dev/null -w '%%{http_code}' -X POST -H 'Content-Type: application/json' -d '%s' %s", json, url);

    for (int i = 0; i < POST_MAX_RETRIES; i++) {
        int rc = system(cmd);
        if (rc == 0 && (WEXITSTATUS(g_child_status) == 0 || WEXITSTATUS(g_child_status) == 1)) {
            return 0;
        }
        if (rc == 0 && WEXITSTATUS(g_child_status) == 2) {
            log_message(LOG_WARNING, "HTTP 400 received, retrying...");
            sleep_us(POST_RETRY_DELAY_SEC * 1000000);
            continue;
        }
        log_message(LOG_WARNING, "POST failed, retrying...");
        sleep_us(POST_RETRY_DELAY_SEC * 1000000);
    }
    return -1;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                g_api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s api_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_uploader", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message(LOG_INFO, "Starting DHT22 humidity uploader");

    while (!g_terminate) {
        float humidity = 0.0f;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && !g_terminate) {
            int rc = dht22_read(DHT22_GPIO, &humidity);
            if (rc == 0) {
                read_ok = 1;
                break;
            }
            log_message(LOG_WARNING, "DHT22 read failed (rc=%d), retrying...", rc);
            retries++;
            sleep_us(RETRY_DELAY_SEC * 1000000);
        }

        if (read_ok) {
            log_message(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (post_humidity(g_api_url, humidity) != 0) {
                log_message(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            log_message(LOG_ERR, "DHT22 read failed after %d retries", MAX_RETRIES);
        }

        for (int i = 0; i < READ_INTERVAL_SEC && !g_terminate; i++) {
            sleep_us(1000000);
        }
    }

    log_message(LOG_INFO, "Shutting down");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

