#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 50.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define LOG_FILE "heater_log.txt"

#define KP 1.0
#define KI 0.1
#define KD 0.01

#define PWM_RANGE_INT (PWM_RANGE + 1)

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static double integral = 0.0;
static double previous_error = 0.0;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void log_message(const char *message) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file);
    }
}

static void log_data(double temperature, int pwm_duty_cycle, double pid_output) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f C, PWM: %d, PID: %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                temperature, pwm_duty_cycle, pid_output);
        fflush(log_file);
    }
}

static int read_max31855(double *temperature) {
    char tx_buf[4] = {0, 0, 0, 0};
    char rx_buf[4] = {0, 0, 0, 0};

    if (spi_handle < 0) {
        log_message("Error: SPI handle is invalid.");
        return -1;
    }

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        log_message("Error: SPI transfer failed.");
        return -1;
    }

    uint32_t raw_data = ((uint32_t)(uint8_t)rx_buf[0] << 24) |
                        ((uint32_t)(uint8_t)rx_buf[1] << 16) |
                        ((uint32_t)(uint8_t)rx_buf[2] << 8)  |
                        ((uint32_t)(uint8_t)rx_buf[3]);

    if (raw_data & 0x00010000) {
        uint8_t fault_bits = (uint8_t)(raw_data & 0x07);
        if (fault_bits & 0x01) {
            log_message("Error: MAX31855 fault - Open circuit detected.");
        } else if (fault_bits & 0x02) {
            log_message("Error: MAX31855 fault - Short to GND detected.");
        } else if (fault_bits & 0x04) {
            log_message("Error: MAX31855 fault - Short to VCC detected.");
        } else {
            log_message("Error: MAX31855 fault - Unknown fault detected.");
        }
        return -1;
    }

    int16_t thermocouple_data = (int16_t)(raw_data >> 18);
    *temperature = thermocouple_data * 0.25;
    return 0;
}

static double calculate_pid(double setpoint, double actual_value) {
    double error = setpoint - actual_value;
    double derivative = error - previous_error;
    integral += error;
    double output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    return output;
}

static int set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(HEATER_GPIO, duty_cycle) != 0) {
        log_message("Error: Failed to set PWM duty cycle.");
        return -1;
    }
    return 0;
}

static void cleanup() {
    set_pwm_duty_cycle(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        log_message("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started.");

    while (running) {
        double temperature = 0.0;
        int result = read_max31855(&temperature);

        if (result == 0) {
            if (temperature > MAX_TEMPERATURE || temperature < MIN_TEMPERATURE) {
                log_message("Error: Temperature out of range. Heater disabled.");
                set_pwm_duty_cycle(0);
                integral = 0.0;
                previous_error = 0.0;
            } else {
                double pid_output = calculate_pid(TARGET_TEMPERATURE, temperature);
                int pwm_duty_cycle = (int)pid_output;

                if (pwm_duty_cycle < 0) pwm_duty_cycle = 0;
                if (pwm_duty_cycle > PWM_RANGE) pwm_duty_cycle = PWM_RANGE;

                set_pwm_duty_cycle(pwm_duty_cycle);
                log_data(temperature, pwm_duty_cycle, pid_output);
            }
        } else {
            set_pwm_duty_cycle(0);
            integral = 0.0;
            previous_error = 0.0;
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

