#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL_SEC 5
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define MIN_DUTY 0
#define MAX_DUTY 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        perror("fopen thermal_zone0");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "fscanf thermal_zone0 failed\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return (int)(temp_milli / 1000);
}

static int calculate_duty_cycle(float temp) {
    if (temp <= MIN_TEMP) return MIN_DUTY;
    if (temp >= MAX_TEMP) return MAX_DUTY;
    float frac = (temp - MIN_TEMP) / (MAX_TEMP - MIN_TEMP);
    return (int)(frac * (MAX_DUTY - MIN_DUTY) + 0.5f);
}

static int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    int pwm_range = 1000000;
    int pwm_value = (duty_cycle * pwm_range) / 100;
    if (gpioPWM(FAN_GPIO, pwm_value) < 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static int log_data(float temp, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
