#define I2C_BUS 1
#define SENSOR1_ADDR 0x24
#define SENSOR2_ADDR 0x25
#define LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sensor(int handle, float *flow_rate) {
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(handle, (char *)buf, 3);
        if (bytes_read == 3) {
            if (crc8(buf, 2) == buf[2]) {
                uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
                *flow_rate = (float)raw / 100.0f;
                return 0;
            }
        }
        retries++;
        if (retries < MAX_RETRIES) {
            time_sleep(0.01);
        }
    }
    return -1;
}

static int log_flow_data(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1 (addr 0x%02X): %d\n", SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2 (addr 0x%02X): %d\n", SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting flow monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ret1 = read_sensor(i2c_handle1, &flow1);
        int ret2 = read_sensor(i2c_handle2, &flow2);

        if (ret1 == 0 && ret2 == 0) {
            if (log_flow_data(flow1, flow2) == 0) {
                printf("Flow1: %.2f, Flow2: %.2f\n", flow1, flow2);
            } else {
                fprintf(stderr, "Failed to log flow data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        }

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

