#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define CHANNEL_A 17
#define CHANNEL_B 18
#define PULSES_PER_REV 360
#define LOG_FILE "encoder_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_channel(int gpio) {
    return gpioRead(gpio) == 0;
}

static void log_position(double position) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, position);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(CHANNEL_A, PI_OUTPUT);
    gpioSetMode(CHANNEL_B, PI_OUTPUT);
    gpioSetPullUpDown(CHANNEL_A, PI_PUD_UP);
    gpioSetPullUpDown(CHANNEL_B, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int prev_a = read_channel(CHANNEL_A);
    int prev_b = read_channel(CHANNEL_B);
    double position = 0.0;

    while (running) {
        int cur_a = read_channel(CHANNEL_A);
        int cur_b = read_channel(CHANNEL_B);

        if (cur_a != prev_a) {
            if (cur_b == prev_b) {
                position += 1.0;
            } else {
                position -= 1.0;
            }
        }

        if (cur_b != prev_b) {
            if (cur_a == prev_a) {
                position += 2.0;
            } else {
                position -= 2.0;
            }
        }

        if (position >= 360.0) position -= 360.0;
        if (position < 0.0) position += 360.0;

        log_position(position);
        prev_a = cur_a;
        prev_b = cur_b;
        gpioDelay(10000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

