#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD144RI_ADDR 0x48
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) error: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_adpd144ri(int fd) {
    if (i2c_write_reg8(fd, 0x00, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x01, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x02, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x03, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x04, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x05, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x06, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x07, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x08, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x09, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x0A, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x0B, 0x01) < 0) return -1;
