#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define PULSES_PER_REVOLUTION 1

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, rpm);
        fflush(log_file);
    }
}

static void pulse_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user;

    pthread_mutex_lock(&pulse_mutex);
    static int pulse_count = 0;
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

int main(void) {
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error setting up signal handler");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", GPIO_PIN);
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_isr, NULL);
    if (ret != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO %d\n", GPIO_PIN);
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        pthread_mutex_lock(&pulse_mutex);
        int pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = 0.0;
        if (pulse_count > 0) {
            rpm = (double)pulse_count / PULSES_PER_REVOLUTION * 60.0;
        }

        log_rpm(rpm);
        printf("RPM: %.2f\n", rpm);
    }

    printf("\nShutting down...\n");

    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    pthread_mutex_destroy(&pulse_mutex);

    return EXIT_SUCCESS;
}

