#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x48
#define LED_GPIO 17
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define SAMPLE_INTERVAL_MS 100

#define REG_RED_DATA 0x00
#define REG_IR_DATA 0x04
#define REG_DEVICE_ID 0x0A
#define REG_CONTROL 0x0B

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_adpd144ri(int fd) {
    uint8_t device_id;
    if (i2c_read_reg8(fd, REG_DEVICE_ID, &device_id) < 0) {
        return -1;
    }
    if (device_id != 0x48) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x48)\n", device_id);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_CONTROL, 0x01) < 0) {
        return -1;
    }
    return 0;
}

static int read_adpd144ri(int fd, uint16_t *red, uint16_t *ir) {
    uint8_t red_low, red_high, ir_low, ir_high;
    if (i2c_read_reg8(fd, REG_RED_DATA, &red_low) < 0) return -1;
    if (i2c_read_reg8(fd, REG_RED_DATA + 1, &red_high) < 0) return -1;
    if (i2c_read_reg8(fd, REG_IR_DATA, &ir_low) < 0) return -1;
    if (i2c_read_reg8(fd, REG_IR_DATA + 1, &ir_high) < 0) return -1;
    *red = ((uint16_t)red_high << 8) | red_low;
    *ir = ((uint16_t)ir_high << 8) | ir_low;
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADPD144RI_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_adpd144ri(i2c_fd) < 0) {
        fprintf(stderr, "ADPD144RI initialization failed (sensor may be absent or bus error).\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    printf("ADPD144RI logging started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t red, ir;
        if (read_adpd144ri(i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }
        log_data(log_file, red, ir);
        if (ir > THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    cleanup();
    return 0;
}

