#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", AUDIO_INPUT_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(GAIN_SELECT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GAIN_SELECT_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(GAIN_SELECT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", GAIN_SELECT_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int detect_rising_edge(int *prev_state) {
    int current_state = gpioRead(AUDIO_INPUT_PIN);
    if (current_state < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", AUDIO_INPUT_PIN);
        return -1;
    }

    if (current_state == 1 && *prev_state == 0) {
        *prev_state = 1;
        return 1;
    }

    *prev_state = current_state;
    return 0;
}

static int log_event(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s LEVEL\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (setup_gpio() != 0) {
        return 1;
    }

    printf("Audio event detector started. Press Ctrl+C to exit.\n");

    int prev_state = 0;
    int first_run = 1;

    while (running) {
        int rising_edge = detect_rising_edge(&prev_state);
        if (rising_edge < 0) {
            break;
        }

        if (rising_edge) {
            if (log_event(LOG_FILE) != 0) {
                fprintf(stderr, "Failed to log event\n");
            } else {
                printf("Event logged\n");
            }
            first_run = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("Audio event detector stopped.\n");
    return 0;
}

