#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x20
#define LOG_FILE "flow_log.csv"
#define READ_INTERVAL_US 1000000
#define MEASUREMENT_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buf[3];
    int result;

    result = i2cWriteByte(i2c_handle, 0x36);
    if (result < 0) {
        fprintf(stderr, "Error: i2cWriteByte failed (0x36): %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: i2cReadDevice failed: expected 3 bytes, got %d\n", result);
        return -1;
