#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x33
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_SEC 5

/* MICS-VZ-89TE register addresses (16-bit, big-endian on the bus) */
#define REG_SENSOR_STATUS 0x00
#define REG_TVOC_PPB 0x02
#define REG_ECO2_PPM 0x04
#define REG_RESET 0x06

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *value)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0)
        return -1;

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;

    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int read_sensor_data(int handle, uint16_t *tvoc_ppb, uint16_t *eco2_ppm)
{
    if (i2c_read_reg16(handle, REG_TVOC_PPB, tvoc_ppb) != 0) {
        fprintf(stderr, "Error: failed to read TVOC register\n");
        return -1;
    }
    if (i2c_read_reg16(handle, REG_ECO2_PPM, eco2_ppm) != 0) {
        fprintf(stderr, "Error: failed to read eCO2 register\n");
        return -1;
    }
    return 0;
}

static float calculate_iaq(uint16_t tvoc_ppb, uint16_t eco2_ppm)
{
    return (float)tvoc_ppb + (float)eco2_ppm * 0.01f;
}

static int log_data(FILE *fp, float iaq, uint16_t tvoc_ppb, uint16_t eco2_ppm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%u,%u\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                iaq, tvoc_ppb, eco2_ppm) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Sensor may be absent or bus unavailable.\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,iaq,tvoc_ppb,eco2_ppm\n");
        fflush(g_log_file);
    }

    /* Reset sensor to known state */
    if (i2c_write_reg16(g_i2c_handle, REG_RESET, 0x0001) != 0) {
        fprintf(stderr, "Warning: sensor reset write failed; continuing anyway\n");
    }
    gpioDelay(10000); /* 10 ms settle */

    printf("Air quality monitoring started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t tvoc_ppb = 0, eco2_ppm = 0;

        if (read_sensor_data(g_i2c_handle, &tvoc_ppb, &eco2_ppm) == 0) {
            float iaq = calculate_iaq(tvoc_ppb, eco2_ppm);
            if (log_data(g_log_file, iaq, tvoc_ppb, eco2_ppm) != 0) {
                fprintf(stderr, "Error: failed to log data\n");
            } else {
                printf("TVOC: %u ppb, eCO2: %u ppm, IAQ: %.2f\n",
                       tvoc_ppb, eco2_ppm, iaq);
            }
        } else {
            fprintf(stderr, "Error: sensor read failed; skipping this sample\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

