#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 17
#define POLL_INTERVAL_US 100000   /* 100 ms */
#define INTRUSION_THRESHOLD_S 5
#define CONSUMER_NAME "ttp223_tamper"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Release the line so it can be used by other programs */
    gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_OFF);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n",
                TOUCH_SENSOR_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_OFF) != 0) {
        fprintf(stderr, "Failed to set pull-up/down on GPIO %d: %s\n",
                TOUCH_SENSOR_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (BCM)...\n",
           TOUCH_SENSOR_GPIO);
    printf("Alert after continuous HIGH for %d seconds.\n",
           INTRUSION_THRESHOLD_S);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    struct timespec last_alert_time = {0, 0};
    int alert_active = 0;

    while (g_running) {
        int level = gpioRead(TOUCH_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d: %s\n",
                    TOUCH_SENSOR_GPIO, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (level == 1) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
                perror("clock_gettime");
                cleanup();
                return EXIT_FAILURE;
            }

            if (!alert_active) {
                double elapsed = (now.tv_sec - last_alert_time.tv_sec)
                               + (now.tv_nsec - last_alert_time.tv_nsec) / 1e9;

                if (elapsed >= INTRUSION_THRESHOLD_S) {
                    printf("INTRUSION DETECTED!\n");
                    fflush(stdout);
                    last_alert_time = now;
                    alert_active = 1;
                }
            }
        } else {
            alert_active = 0;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

