#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define CHANNEL_SELECT_GPIO 17
#define SAMPLE_RATE 48000
#define NUM_CHANNELS 1
#define BUFFER_SIZE 4096
#define OUTPUT_FILE "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2s(void) {
    int fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2S device %s: %s\n", I2S_DEVICE, strerror(errno));
        return -1;
    }

    struct snd_pcm_hw_params params;
    memset(&params, 0, sizeof(params));
    params.interface = SNDRV_PCM_INTERFACE_NONE;
    params.format = AFMT_S16_LE;
    params.channels = NUM_CHANNELS;
    params.rate = SAMPLE_RATE;
    params.period_size = BUFFER_SIZE;

    if (snd_pcm_hw_params_alloca(&params) < 0) {
        fprintf(stderr, "Error allocating hw_params\n");
        close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_any(fd, &params) < 0) {
        fprintf(stderr, "Error initializing hw_params: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_set_access(fd, &params, SNDRV_PCM_ACCESS_RW_SEQUENTIAL) < 0) {
        fprintf(stderr, "Error setting access: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_set_format(fd, &params, AFMT_S16_LE) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_set_channels(fd, &params, NUM_CHANNELS) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_set_rate_near(fd, &params, &SAMPLE_RATE, 0) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (snd_pcm_hw_params(fd, &params) < 0) {
        fprintf(stderr, "Error applying hw_params: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return 0;
}

static int write_pcm_file(const char *filename, const int16_t *data, int num_samples) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t written = fwrite(data, sizeof(int16_t), num_samples, fp);
    if (written != (size_t)num_samples) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2s() < 0) {
        return 1;
    }

    int fd = open("/sys/class/gpio/gpio17", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO 17: %s\n", strerror(errno));
        snd_pcm_close(fd);
        return 1;
    }

    if (ioctl(fd, GPIO_EXPORT, 17) < 0) {
        fprintf(stderr, "Error exporting GPIO 17: %s\n", strerror(errno));
        close(fd);
        snd_pcm_close(fd);
        return 1;
    }

    if (ioctl(fd, GPIO_DIRECTION_OUTPUT, 0) < 0) {
        fprintf(stderr, "Error setting GPIO 17 direction: %s\n", strerror(errno));
        close(fd);
        snd_pcm_close(fd);
        return 1;
    }

    if (ioctl(fd, GPIO_DIRECTION_OUTPUT, 1) < 0) {
        fprintf(stderr, "Error setting GPIO 17 direction: %s\n", strerror(errno));
        close(fd);
        snd_pcm_close(fd);
        return 1;
    }

    int16_t *buffer = malloc(BUFFER_SIZE * sizeof(int16_t));
    if (!buffer) {
        fprintf(stderr, "Error allocating buffer\n");
        close(fd);
        snd_pcm_close(fd);
        return 1;
    }

    printf("Starting audio capture on %s...\n", I2S_DEVICE);

    while (running) {
        int read_result = snd_pcm_readi(fd, buffer, BUFFER_SIZE);
        if (read_result < 0) {
            fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
            break;
        }

        if (write_pcm_file(OUTPUT_FILE, buffer, read_result) < 0) {
            fprintf(stderr, "Error writing PCM file\n");
            break;
        }

        usleep(10000);
    }

    free(buffer);
    close(fd);
    snd_pcm_close(fd);

    printf("Audio capture stopped.\n");
    return 0;
}

