#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define DEBOUNCE_DELAY_US 50000
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_US 100000
#define SENSOR_TIMEOUT_US 5000000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(FAN_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void control_fan(int state) {
    if (gpioPWM(FAN_PIN, state ? PWM_RANGE : 0) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
    }
}

static void cleanup(void) {
    control_fan(0);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioTerminate();
    if (log_file) {
        log_event("Program shutdown");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }
    log_event("Program start");

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed");
        fclose(log_file);
        return 1;
    }

    int last_state = 1;
    uint32_t last_change_tick = 0;
    int no_data_count = 0;

    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read flame sensor\n");
            log_event("Error reading flame sensor");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint32_t current_tick = gpioTick();
        if (sensor_value != last_state) {
            last_state = sensor_value;
            last_change_tick = current_tick;
            no_data_count = 0;
        } else if (current_tick - last_change_tick > SENSOR_TIMEOUT_US) {
            fprintf(stderr, "Sensor absent: no valid reading for 5 seconds\n");
            log_event("Sensor absent: no valid reading for 5 seconds");
            last_state = 1;
            last_change_tick = current_tick;
            no_data_count = 0;
        } else {
            no_data_count++;
        }

        if (sensor_value == 0) {
            log_event("Flame detected");
            control_fan(1);
            while (program_running && no_data_count < 10) {
                sensor_value = gpioRead(FLAME_SENSOR_PIN);
                if (sensor_value < 0) {
                    fprintf(stderr, "Failed to read flame sensor during flame event\n");
                    log_event("Error reading flame sensor during flame event");
                    break;
                }
                if (sensor_value == 1) {
                    break;
                }
                gpioDelay(DEBOUNCE_DELAY_US);
            }
            if (no_data_count >= 10) {
                log_event("Flame ended");
                control_fan(0);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

