static pthread_cond_t data_ready_cond = PTHREAD_COND_INITIALIZER;
static volatile uint32_t frame_number = 0;
static volatile uint32_t last_frame_time_ms = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    if (log_file) {
        pthread_mutex_lock(&log_mutex);
        fflush(log_file);
        pthread_mutex_unlock(&log_mutex);
    }
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1; return -1;
    }

    return 0;
}

static int gpio_init(void) {
    if (gpio_set_mode(GPIO_TRIGGER_PIN, PI_INPUT) < 0) {
        perror("gpio_set_mode trigger");
        return -1;
    }
    if (gpio_set_mode(GPIO_DATA_READY_PIN, PI_INPUT) < 0) {
        perror("gpio_set_mode data_ready");
        return -1;
    }
    return 0;
}

static void gpio_trigger_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)level; (void)tick;
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        fwrite(&frame_number, sizeof(frame_number), 1, log_file);
        fwrite(&last_frame_time_ms, sizeof(last_frame_time_ms), 1, log_file);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void *data_ready_thread(void *arg) {
    (void)arg;
    struct timespec ts_start, ts_end;
    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    while (running) {
        int val = gpio_get_value(GPIO_DATA_READY_PIN);
        if (val < 0) {
            perror("gpio_get_value data_ready");
            break;
        }
        if (val == 1) {
            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            uint32_t elapsed_ms = (ts_end.tv_sec - ts_start.tv_sec) * 1000 + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000000;
            if (elapsed_ms >= FRAME_PERIOD_MS) {
                pthread_mutex_lock(&log_mutex);
                if (log_file) {
                    struct config_t cfg;
                    memcpy(&cfg, &frame_number, sizeof(frame_number));
                    memcpy(&cfg.num_chirps, &frame_number + 4, sizeof(uint32_t));
                    memcpy(&cfg.num_samples, &frame_number + 8, sizeof(uint32_t));
                    memcpy(&cfg.start_freq, &frame_number + 12, sizeof(uint32_t));
                    memcpy(&cfg.end_freq, &frame_number + 16, sizeof(uint32_t));
                    fwrite(&cfg, sizeof(config_t), 1, log_file);
                    fflush(log_file);
                }
                pthread_mutex_unlock(&log_mutex);
                frame_number++;
                last_frame_time_ms = elapsed_ms;
            }
        }
        usleep(1000);
    }
    return NULL;
}

static int log_frame_data(uint8_t *data, size_t data_len) {
    pthread_mutex_lock(&log_mutex);
    if (!log_file) {
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }
    size_t written = fwrite(data, 1, data_len, log_file);
    if (written != data_len) {
        fprintf(stderr, "Error writing frame data to log file\n");
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }
    fflush(log_file);
    pthread_mutex_unlock(&log_mutex);
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        pthread_mutex_lock(&log_mutex);
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
        pthread_mutex_unlock(&log_mutex);
    }
    pthread_cond_destroy(&data_ready_cond);
    pthread_mutex_destroy(&log_mutex);
}

