    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main polling loop --- */
    int prev_state = -1;  /* Force initial log */

    while (g_running) {
        int level = gpioRead(FLAME_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", FLAME_SENSOR_GPIO);
            break;
        }

        if (level != prev_state) {
            if (log_flame_event(level) != 0) {
                fprintf(stderr, "Failed to log flame event\n");
                break;
            }
            prev_state = level;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    gpioTerminate();
    return EXIT_SUCCESS;
}

