#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x44
#define LOG_FILE       "light_data.txt"
#define CONV_TIME_MS   100
#define POLL_DELAY_MS  10

/* OPT3001 register addresses */
#define REG_RESULT     0x00
#define REG_CONFIG     0x01
#define REG_MANUF_ID   0x7E
#define REG_DEVICE_ID  0x7F

#define OPT3001_MANUF_ID 0x5449
#define OPT3001_DEVICE_ID 0x3001

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int opt3001_init(int fd)
{
    uint16_t manuf_id = 0, device_id = 0;

    if (i2c_read_reg16(fd, REG_MANUF_ID, &manuf_id) < 0)
        return -1;
    if (manuf_id != OPT3001_MANUF_ID) {
        fprintf(stderr, "Manufacturer ID mismatch: 0x%04X (expected 0x%04X)\n",
                manuf_id, OPT3001_MANUF_ID);
        return -1;
    }

    if (i2c_read_reg16(fd, REG_DEVICE_ID, &device_id) < 0)
        return -1;
    if (device_id != OPT3001_DEVICE_ID) {
        fprintf(stderr, "Device ID mismatch: 0x%04X (expected 0x%04X)\n",
                device_id, OPT3001_DEVICE_ID);
        return -1;
    }

    /*
     * Config register (0x01):
     *   Bit 15   RN[1:0] = 00 -> 1x range
     *   Bit 14   M[1:0]  = 00 -> 100 ms conversion time
     *   Bit 13   CT[1:0] = 00 -> 100 ms conversion time (matches above)
     *   Bit 12   FC[1:0] = 00 -> 1x full-scale
     *   Bit 11   POL[1:0] = 00 -> 100 ms conversion time
     *   Bit 10   ME[1:0] = 00 -> 100 ms conversion time
     *   Bit 9    OVF[1:0] = 00 -> no overflow
     *   Bit 8    MODE[1:0] = 10 -> continuous conversion
     *   Bit 7    FL[1:0]  = 00 -> 1x full-scale
     *   Bit 6    FLD[1:0] = 00 -> 1x full-scale
     *   Bit 5    FLO[1:0] = 00 -> 1x full-scale
     *   Bit 4    FHI[1:0] = 00 -> 1x full-scale
     *   Bit 3    FLN[1:0] = 00 -> 1x full-scale
     *   Bit 2    FLF[1:0] = 00 -> 1x full-scale
     *   Bit 1    FLN_EN = 0
     *   Bit 0    FLF_EN = 0
     * => 0x0000
     */
    if (i2c_write_reg16(fd, REG_CONFIG, 0x0000) < 0)
        return -1;

    return 0;
}

static int opt3001_read_lux(int fd, float *lux_out)
{
    uint16_t raw = 0;
    if (i2c_read_reg16(fd, REG_RESULT, &raw) < 0)
        return -1;

    /*
     * Result register (0x00):
     *   Bits 15:12   RN[1:0] = 00 -> 1x range
     *   Bits 11:4   Result value
     *   Bits 3:0    MSB status
     * => raw value is the 12-bit result in the lower 12 bits
     */
    uint16_t result = raw & 0x0FFF;

    /*
     * Conversion time is 100 ms (bits 15:14 = 00).
     * Lux = raw * 0.01 (1 lux per count in 1x range).
     */
    *lux_out = (float)result * 0.01f;
    return 0;
}

static int log_data(const char *filename, float lux)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                OPT3001_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (opt3001_init(g_i2c_fd) < 0) {
        fprintf(stderr, "OPT3001 initialization failed (sensor may be absent or bus error).\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("OPT3001 initialized. Logging to %s every %d ms.\n", LOG_FILE, CONV_TIME_MS);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float lux = 0.0f;
        if (opt3001_read_lux(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Error reading lux value. Retrying in %d ms.\n", POLL_DELAY_MS);
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        if (log_data(LOG_FILE, lux) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("Lux: %.2f\n", lux);
        usleep(CONV_TIME_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

