#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] ", buffer);
    }
}

int main(void) {
    int ret;
    int i;
    int last_error = 0;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler.\n");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    for (i = 0; i < NUM_CHANNELS; i++) {
        ret = gpioSetMode(sensor_pins[i], PI_INPUT);
        if (ret != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input (code %d).\n",
                    sensor_pins[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 touch sensor monitor started. Press Ctrl+C to exit.\n");
    printf("  OUT1->BCM2, OUT2->BCM3, OUT3->BCM4, OUT4->BCM5, OUT5->BCM6, OUT6->BCM7, OUT7->BCM8, OUT8->BCM9\n");
    printf("  Polling every %d ms. Press Ctrl+C to exit.\n\n", POLL_DELAY_US / 1000);

    /* Main polling loop */
    while (program_running) {
        int values[NUM_CHANNELS];
        int error = 0;

        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpioRead(sensor_pins[i]);
            if (val < 0) {
                fprintf(stderr, "Error: failed to read GPIO %d (code %d).\n",
                        sensor_pins[i], val);
                error = 1;
                break;
            }
            values[i] = val;
        }

        if (error) {
            last_error = 1;
        } else {
            print_timestamp();
            for (i = 0; i < NUM_CHANNELS; i++) {
                printf("%d", values[i]);
            }
            printf("\n");
            fflush(stdout);
        }

        /* Sleep 100 ms, but wake early if signal received */
        for (int elapsed = 0; elapsed < POLL_DELAY_US && program_running; elapsed += 10000) {
            usleep(10000);
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioTerminate();

    if (last_error) {
        fprintf(stderr, "Warning: sensor read errors occurred during shutdown.\n");
    }

    return EXIT_SUCCESS;
}

