    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs with pull-down resistors */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: failed to set pull-down on GPIO %d\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int values[NUM_CHANNELS];
        int result = gpioRead(sensor_pins);
        if (result != 0) {
            fprintf(stderr, "Error: gpioRead failed with code %d\n", result);
            break;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpioRead(sensor_pins[i]);
        }

        printf("[%ld] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               (long)gpioTick(),
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

