/*
 * TMAG5110 Hall-Effect Latch Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Sensor 1 OUT -> BCM GPIO4
 *   Sensor 2 OUT -> BCM GPIO5
 *   Both VCC -> 3.3 V, GND -> GND
 *
 * The TMAG5110 output is open-drain with an internal pull-up;
 * therefore an unasserted output reads HIGH and a magnet-detected
 * assertion reads LOW.
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lthe_driver_library -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <the_driver_library.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 5
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    int rc;
    int sensor1_state, sensor2_state;
    struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000L};

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize the TMAG5110 driver library */
    rc = the_driver_library_init();
    if (rc != 0) {
        fprintf(stderr, "Error: TMAG5110 driver initialization failed (rc=%d).\n", rc);
        fprintf(stderr, "Ensure the library is built and linked correctly.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs */
    rc = the_driver_library_gpio_set_mode(SENSOR_1_PIN, THE_DRIVER_LIBRARY_GPIO_MODE_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", SENSOR_1_PIN);
        the_driver_library_terminate();
        return EXIT_FAILURE;
    }

    rc = the_driver_library_gpio_set_mode(SENSOR_2_PIN, THE_DRIVER_LIBRARY_GPIO_MODE_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", SENSOR_2_PIN);
        the_driver_library_terminate();
        return EXIT_FAILURE;
    }

    printf("TMAG5110 Hall-Effect Sensor Reader\n");
    printf("Sensor 1: BCM GPIO%d | Sensor 2: BCM GPIO%d\n", SENSOR_1_PIN, SENSOR_2_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main polling loop */
    while (running) {
        sensor1_state = the_driver_library_gpio_read(SENSOR_1_PIN);
        if (sensor1_state < 0) {
            fprintf(stderr, "Error: Failed to read GPIO %d.\n", SENSOR_1_PIN);
            break;
        }

        sensor2_state = the_driver_library_gpio_read(SENSOR_2_PIN);
        if (sensor2_state < 0) {
            fprintf(stderr, "Error: Failed to read GPIO %d.\n", SENSOR_2_PIN);
            break;
        }

        /* Open-drain: HIGH = no magnet, LOW = magnet detected */
        printf("Sensor 1: %s | Sensor 2: %s\n",
               sensor1_state == 0 ? "LOW" : "HIGH",
               sensor2_state == 0 ? "LOW" : "HIGH");

        fflush(stdout);

        nanosleep(&sleep_time, NULL);
    }

    /* Clean resource release */
    the_driver_library_terminate();
    printf("\nExiting cleanly.\n");

    return EXIT_SUCCESS;
}

