#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000  /* 50 ms */

static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set BCM pin %d as input\n", sensor_pins[i]);
            gpioTerminate();
            return -1;
        }
        /* TTP226 has an internal pull-up; disabling bias on the Pi side avoids contention */
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr, "Error: failed to set pull-up/down on BCM pin %d\n", sensor_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_OFF);
        gpioSetMode(sensor_pins[i], PI_INPUT);
    }
    gpioTerminate();
}

static int read_sensor_data(int *states)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int val = gpioRead(sensor_pins[i]);
        if (val < 0) {
            fprintf(stderr, "Error: failed to read BCM pin %d\n", sensor_pins[i]);
            return -1;
        }
        states[i] = val;
    }
    return 0;
}

static void log_data(const int *states)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s", timestamp);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf(",");
        printf("%d", states[i]);
    }
    printf("\n");
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int states[NUM_CHANNELS];

    while (g_running) {
        if (read_sensor_data(states) == 0) {
            log_data(states);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

