#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_SENSOR_PIN 4
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int last_state = -1;  /* force initial print */

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO4 as input with internal pull-up --- */
    if (gpioSetMode(TILT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TILT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", TILT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Print startup banner --- */
    printf("Tilt sensor monitoring started on GPIO%d.\n", TILT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int value = gpioRead(TILT_SENSOR_PIN);
        if (value < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", TILT_SENSOR_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (value != last_state) {
            if (value == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
            last_state = value;
        }

        usleep(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

