#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x20
#define SENSOR2_ADDR   0x21
#define ALARM_GPIO     17
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define START_CMD      0x3608
#define MEAS_CMD       0x3687
#define MEAS_DELAY_US  100000
#define LOOP_DELAY_US  1000000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, float *flow_rate) {
    if (i2c_write_cmd(fd, MEAS_CMD) < 0)
        return -1;

    gpioDelay(MEAS_DELAY_US);

    uint8_t data[9];
    if (i2c_read_data(fd, data, sizeof(data)) < 0)
        return -1;

    if (sensirion_crc8(data, 8) != data[8]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)data[0] << 24) |
                   ((uint32_t)data[1] << 16) |
                   ((uint32_t)data[2] << 8)  |
                   ((uint32_t)data[3]);
    *flow_rate = (float)raw / 1000.0f;
    return 0;
}

static void log_flow_rate(FILE *fp, float flow1, float flow2, float avg) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Avg: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow1, flow2, avg);
    fflush(fp);
}

static void check_alarm(float avg) {
    if (avg < FLOW_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1);
    } else {
        gpioWrite(ALARM_GPIO, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (i2c_write_cmd(i2c_fd, START_CMD) < 0) {
        fprintf(stderr, "Failed to start sensor 1\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (i2c_write_cmd(i2c_fd, START_CMD) < 0) {
        fprintf(stderr, "Failed to start sensor 2\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int valid1 = (read_flow_rate(i2c_fd, &flow1) == 0);
        int valid2 = (read_flow_rate(i2c_fd, &flow2) == 0);

        if (valid1 && valid2) {
            float avg = (flow1 + flow2) / 2.0f;
            log_flow_rate(log_fp, flow1, flow2, avg);
            check_alarm(avg);
        } else {
            fprintf(stderr, "Sensor read error (s1=%s, s2=%s)\n",
                    valid1 ? "ok" : "fail", valid2 ? "ok" : "fail");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(ALARM_GPIO, 0);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

