#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x0D
#define D7S_MODE_REG   0x00
#define D7S_X_LSB_REG  0x02
#define D7S_X_MSB_REG  0x03
#define D7S_Y_LSB_REG  0x04
#define D7S_Y_MSB_REG  0x05
#define D7S_Z_LSB_REG  0x06
#define D7S_Z_MSB_REG  0x07
#define MODE_ACTIVE    0x01
#define ACTIVE_TIMEOUT_MS 1000
#define POLL_INTERVAL_MS   500
#define CSV_FILENAME "fan_health.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int d7s_init(int fd) {
    if (i2c_write_reg8(fd, D7S_MODE_REG, MODE_ACTIVE) < 0)
        return -1;
    usleep(10000);
    uint8_t mode = 0;
    if (i2c_read_reg8(fd, D7S_MODE_REG, &mode) < 0)
        return -1;
    if ((mode & MODE_ACTIVE) == 0) {
        fprintf(stderr, "D7S not active after mode set\n");
        return -1;
    }
    return 0;
}

static int d7s_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg8(fd, D7S_X_LSB_REG, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_X_MSB_REG, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_Y_LSB_REG, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_Y_MSB_REG, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_Z_LSB_REG, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_Z_MSB_REG, &zh) < 0) return -1;
    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

static int write_csv(FILE *fp, const char *ts, int16_t x, int16_t y, int16_t z) {
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "CSV write failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (d7s_init(g_i2c_fd) < 0) {
        fprintf(stderr, "D7S initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,x,y,z\n");
        fflush(g_csv);
    }

    printf("Monitoring vibration (Ctrl+C to stop)...\n");

    while (g_running) {
        struct timespec ts_start, ts_now;
        clock_gettime(CLOCK_MONOTONIC, &ts_start);

        int active = 0;
        for (int i = 0; i < ACTIVE_TIMEOUT_MS && g_running; i += 10) {
            usleep(10000);
            uint8_t mode = 0;
            if (i2c_read_reg8(g_i2c_fd, D7S_MODE_REG, &mode) == 0) {
                if (mode & MODE_ACTIVE) {
                    active = 1;
                    break;
                }
            }
        }

        if (!active) {
            fprintf(stderr, "D7S not active within %d ms\n", ACTIVE_TIMEOUT_MS);
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        long elapsed_ms = (ts_now.tv_sec - ts_start.tv_sec) * 1000L +
                          (ts_now.tv_nsec - ts_start.tv_nsec) / 1000000L;
        if (elapsed_ms > ACTIVE_TIMEOUT_MS) {
            fprintf(stderr, "Timeout during active window (%ld ms)\n", elapsed_ms);
            continue;
        }

        int16_t x, y, z;
        if (d7s_read_xyz(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, retrying...\n");
            continue;
        }

        char ts[32];
        get_timestamp(ts, sizeof(ts));
        if (write_csv(g_csv, ts, x, y, z) < 0) {
            fprintf(stderr, "CSV write error, continuing...\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_csv) fclose(g_csv);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

