#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170‑Q1 I2C address (ADDR pin tied to GND) */
#define TMAG5170_ADDR 0x00

/* TMAG5170‑Q1 register addresses */
#define TMAG5170_REG_DEVICE_CONFIG 0x00
#define TMAG5170_REG_X_AXIS_LSB 0x01
#define TMAG5170_REG_X_AXIS_MSB 0x02
#define TMAG5170_REG_Y_AXIS_LSB 0x03
#define TMAG5170_REG_Y_AXIS_MSB 0x04
#define TMAG5170_REG_Z_AXIS_LSB 0x05
#define TMAG5170_REG_Z_AXIS_MSB 0x06
#define TMAG5170_REG_DIAG_RESULT 0x07

/*
 * Device configuration register (0x00) bit layout (16-bit, big-endian on wire):
 *   [15:14]  Mode (0x0 = continuous conversion)
 *   [13:12]  Range (0x0 = +/-50 mT)
 *   [11:10]  X axis enable (0x1 = enabled)
 *   [9:8]    Y axis enable (0x1 = enabled)
 *   [7:6]    Z axis enable (0x1 = enabled)
 *   [5:4]    X/Y/Z axis selection (0x0 = all axes)
 *   [3:2]    Output data rate (0x0 = 100 Hz)
 *   [1:0]    Operational status (0x0 = normal)
 *
 * Value = 0x0001 (mode=0, range=0, X=1, Y=1, Z=1, ODR=0, status=0)
 */
#define TMAG5170_CONFIG_VALUE 0x0001

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit TMAG5170 register                  */
/* ------------------------------------------------------------------ */
static int write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: I2C write to register 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit TMAG5170 register                 */
/* ------------------------------------------------------------------ */
static int read_reg16(int handle, uint8_t reg, uint16_t *value)
{
    char reg_buf[1] = { (char)reg };
    char data_buf[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C write (select reg 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error: I2C read from register 0x%02X failed\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the TMAG5170 sensor                                    */
/* ------------------------------------------------------------------ */
static int init_sensor(int handle)
{
    if (write_reg16(handle, TMAG5170_REG_DEVICE_CONFIG, TMAG5170_CONFIG_VALUE) != 0) {
        fprintf(stderr, "Error: Failed to configure TMAG5170\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read magnetic field data from the TMAG5170                        */
/* ------------------------------------------------------------------ */
static int read_magnetic_data(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t raw_x, raw_y, raw_z;

    if (read_reg16(handle, TMAG5170_REG_X_AXIS_LSB, &raw_x) != 0)
        return -1;
    if (read_reg16(handle, TMAG5170_REG_Y_AXIS_LSB, &raw_y) != 0)
        return -1;
    if (read_reg16(handle, TMAG5170_REG_Z_AXIS_LSB, &raw_z) != 0)
        return -1;

    *x = (int16_t)raw_x;
    *y = (int16_t)raw_y;
    *z = (int16_t)raw_z;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log magnetic field data to a CSV file                              */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /*
     * The TMAG5170 library may require a cleanup call to release
     * internal resources.  Call the library-provided cleanup function
     * if it is available.
     */
    /*
     * Example (placeholder):
     *   tm5170_cleanup();
     */
    (void)tm5170_cleanup();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t x, y, z;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the TMAG5170 address */
    g_i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("magnetic_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error: fopen(magnetic_log.csv)");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,X,Y,Z\n");
        fflush(g_log_file);
    }

    /* Initialise the sensor */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: Sensor initialisation failed — check wiring and I2C address.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TMAG5170 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        if (read_magnetic_data(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "Warning: I2C read error — continuing.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

