#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s %s\n", timestamp, message);
    fclose(fp);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);

        if (sensor_value < 0) {
            log_event("ERROR: Failed to read sensor value");
            fprintf(stderr, "GPIO read error on pin %d\n", SENSOR_PIN);

            time_t reinit_time = time(NULL) + REINIT_DELAY_SEC;
            while (running && (time(NULL) < reinit_time)) {
                sleep(1);
            }

            if (running) {
                if (initialize_gpio() != 0) {
                    log_event("ERROR: GPIO re-initialization failed");
                    fprintf(stderr, "Re-initialization failed\n");
                }
            }
        } else if (sensor_value == 1) {
            printf("ALERT: Water detected!\n");
            log_event("ALERT: Water detected");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

