#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define PULSE_WINDOW_US 1000000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        pulse_count++;
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (gpioSetAlertFunc(GPIO_PIN, pulse_callback) != 0) {
        fprintf(stderr, "Error: failed to set alert function on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioSetAlertFunc(GPIO_PIN, NULL);
    gpioTerminate();
}

static int log_rpm(FILE *fp, float rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s %.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: failed to flush log file\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        pulse_count = 0;
        uint32_t start_tick = gpioTick();
        uint32_t elapsed = 0;

        while (running && elapsed < PULSE_WINDOW_US) {
            gpioDelay(10000);
            elapsed = gpioTick() - start_tick;
        }

        int pulses = pulse_count;
        float rpm = 0.0f;

        if (pulses > 0) {
            rpm = (float)pulses * 60.0f / (float)(PULSE_WINDOW_US / 1000000.0f);
        }

        if (log_rpm(log_file, rpm) != 0) {
            fprintf(stderr, "Error: failed to log RPM\n");
        }

        printf("%s %.2f\n", "RPM", rpm);
        fflush(stdout);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    return EXIT_SUCCESS;
}

