#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE_NAME "rotation_log.txt"
#define DEBOUNCE_US 100000  /* 100 ms debounce */

/* Quadrature state machine */
typedef enum {
    STATE_IDLE = 0,
    STATE_A_RISING,
    STATE_A_FALLING,
    STATE_B_RISING,
    STATE_B_FALLING
} quadrature_state_t;

static quadrature_state_t current_state = STATE_IDLE;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* ISR: called by pigpio on edge transition of either sensor pin      */
/* ------------------------------------------------------------------ */
static void sensor_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)userdata;

    if (gpio != SENSOR_A_PIN && gpio != SENSOR_B_PIN)
        return;

    if (level == PI_TIMEOUT)
        return;  /* ignore timeout events */

    pthread_mutex_lock(&state_mutex);

    switch (current_state) {
    case STATE_IDLE:
        if (gpio == SENSOR_A_PIN) {
            current_state = STATE_A_RISING;
            pthread_mutex_unlock(&state_mutex);
            return;
        }
        break;

    case STATE_A_RISING:
        if (gpio == SENSOR_B_PIN) {
            current_state = STATE_B_RISING;
            pthread_mutex_unlock(&state_mutex);
            return;
        }
        current_state = STATE_IDLE;
        pthread_mutex_unlock(&state_mutex);
        break;

    case STATE_A_FALLING:
        if (gpio == SENSOR_B_PIN) {
            current_state = STATE_B_FALLING;
            pthread_mutex_unlock(&state_mutex);
            return;
        }
        current_state = STATE_IDLE;
        pthread_mutex_unlock(&state_mutex);
        break;

    case STATE_B_RISING:
        if (gpio == SENSOR_A_PIN) {
            current_state = STATE_A_RISING;
            pthread_mutex_unlock(&state_mutex);
            return;
        }
        current_state = STATE_IDLE;
        pthread_mutex_unlock(&state_mutex);
        break;

    case STATE_B_FALLING:
        if (gpio == SENSOR_A_PIN) {
            current_state = STATE_A_FALLING;
            pthread_mutex_unlock(&state_mutex);
            return;
        }
        current_state = STATE_IDLE;
        pthread_mutex_unlock(&state_mutex);
        break;
    }

    pthread_mutex_unlock(&state_mutex);
}

/* ------------------------------------------------------------------ */
/* Helper: generate millisecond-precision timestamp                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(buf + strlen(buf), len - strlen(buf), ".%03ld", ts.tv_nsec / 1000000);
}

/* ------------------------------------------------------------------ */
/* Helper: log one rotation event with millisecond timestamp           */
/* ------------------------------------------------------------------ */
static void log_rotation(const char *direction)
{
    char timestamp[40];

    get_timestamp(timestamp, sizeof(timestamp));

    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, direction);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: log file is not open.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Signal handler: graceful shutdown                                   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
