#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN          18
#define POLL_DELAY_US    50000   /* 50 ms */
#define CHIP_NAME        "gpiochip0"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(int priority, const char *message)
{
    openlog("touch_led_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set touch sensor pin %d as input", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set LED pin %d as output", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise LED pin %d to LOW", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort: turn LED off and release pigpio resources */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Touch LED monitor started. Touch sensor on GPIO23, LED on GPIO18.");

    while (g_running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);

        if (touch_state < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor pin %d: %s",
                   TOUCH_SENSOR_PIN, strerror(errno));
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (touch_state == 1) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                syslog(LOG_ERR, "Failed to turn LED on: %s", strerror(errno));
            } else {
                log_message(LOG_INFO, "Touch detected, LED turned ON.");
            }
        } else {
            if (gpioWrite(LED_PIN, 0) != 0) {
                syslog(LOG_ERR, "Failed to turn LED off: %s", strerror(errno));
            } else {
                log_message(LOG_INFO, "Touch released, LED turned OFF.");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_message(LOG_INFO, "Touch LED monitor shutting down.");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

