#define TOUCH_SENSOR_PIN 17
#define LED_PIN          18
#define DEBOUNCE_US      50000   /* 50 ms debounce */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    int ret;

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio library --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure touch sensor pin as input with pull-down --- */
    ret = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %s\n",
                TOUCH_SENSOR_PIN, pigpio_error(ret));
        goto cleanup_fail;
    }
    ret = gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d: %s\n",
                TOUCH_SENSOR_PIN, pigpio_error(ret));
        goto cleanup_fail;
    }

    /* --- Configure LED pin as output and ensure it starts OFF --- */
    ret = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %s\n",
                LED_PIN, pigpio_error(ret));
        goto cleanup_fail;
    }
    ret = gpioWrite(LED_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d LOW: %s\n",
                LED_PIN, pigpio_error(ret));
        goto cleanup_fail;
    }

    printf("Touch sensor monitoring started.\n");
    printf("  Touch sensor: GPIO%d (rising-edge event)\n", TOUCH_SENSOR_PIN);
    printf("  LED indicator: GPIO%d\n", LED_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main event loop: wait for rising edges with 50 ms debounce --- */
    while (running) {
        /*
         * gpioTime(0, PI_TIME_RELATIVE) returns the current monotonic
         * time in microseconds.  We use a 50 ms timeout so that if no
         * event occurs within that window, we can check `running` and
         * exit cleanly.
         */
        int wait_ret = gpioTime(0, DEBOUNCE_US);
        if (wait_ret < 0) {
            fprintf(stderr, "gpioTime failed: %s\n", pigpio_error(wait_ret));
            break;
        }
        if (wait_ret == 0) {
            /* Timeout — loop back and check running flag */
            continue;
        }

        /*
         * gpioSetAlertFuncEx registers a callback that fires on the
         * specified edge of the specified line.  We request a rising
         * edge event here.
         */
        ret = gpioSetAlertFuncEx(TOUCH_SENSOR_PIN,
                                  (gpioAlertFuncEx_t)touch_callback,
                                  NULL);
        if (ret != 0) {
            fprintf(stderr, "gpioSetAlertFuncEx failed: %s\n",
                    pigpio_error(ret));
            break;
        }

        /*
         * Wait for the rising-edge event with a 50 ms timeout.
         * gpioSetAlertFuncEx returns the number of events that fired
         * during the wait; 0 means no event occurred within the window.
         */
        int events = gpioSetAlertFuncEx(TOUCH_SENSOR_PIN,
                                        (gpioAlertFuncEx_t)touch_callback,
                                        NULL);
        if (events < 0) {
            fprintf(stderr, "gpioSetAlertFuncEx returned error: %s\n",
                    pigpio_error(events));
            break;
        }
        if (events == 0) {
            continue;
        }

        /* --- Rising-edge event detected --- */
        ret = gpioWrite(LED_PIN, !gpioRead(LED_PIN));
        if (ret != 0) {
            fprintf(stderr, "gpioWrite(LED) failed: %s\n",
                    pigpio_error(ret));
            break;
        }

        /* Debounce: ignore further events for 50 ms */
        gpioDelay(DEBOUNCE_US);
    }

    /* --- Graceful shutdown --- */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;

cleanup_fail:
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_FAILURE;
}

