#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE_PATH "/var/log/rain_events.log"
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int last_state = -1;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %d\n", RAIN_SENSOR_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d: %d\n", RAIN_SENSOR_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE_PATH, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", RAIN_SENSOR_GPIO);

    while (running) {
        int sensor_value = gpioRead(RAIN_SENSOR_GPIO);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %d\n", RAIN_SENSOR_GPIO, sensor_value);
            break;
        }

        if (sensor_value != last_state) {
            if (sensor_value == 0) {
                if (log_event("Rain Detected") != 0) {
                    break;
                }
                printf("Rain detected!\n");
            } else {
                if (log_event("No Rain") != 0) {
                    break;
                }
                printf("No rain.\n");
            }
            last_state = sensor_value;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

