#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_DELAY_US 5000
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

int calculate_rpm(int sensor1_state, int sensor2_state, double elapsed_time) {
    if (elapsed_time <= 0.0) {
        return 0.0;
    }
    int transitions = 0;
    if (sensor1_state != previous_sensor1_state) {
        transitions++;
    }
    if (sensor2_state != previous_sensor2_state) {
        transitions++;
    }
    return (double)transitions / elapsed_time * 60.0;
}

int log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    signal(SIGINT, signal_handler);

    int previous_sensor1_state = -1;
    int previous_sensor2_state = -1;

    while (running) {
        int sensor1_state = read_sensor(SENSOR_1_GPIO);
        int sensor2_state = read_sensor(SENSOR_2_GPIO);

        if (sensor1_state < 0 || sensor2_state < 0) {
            gpioDelay(100000);
            continue;
        }

        if (sensor1_state != previous_sensor1_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int sensor1_state_debounced = read_sensor(SENSOR_1_GPIO);
            if (sensor1_state_debounced < 0) {
                continue;
            }
            if (sensor1_state_debounced == sensor1_state) {
                previous_sensor1_state = sensor1_state;
            }
        }

        if (sensor2_state != previous_sensor2_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int sensor2_state_debounced = read_sensor(SENSOR_2_GPIO);
            if (sensor2_state_debounced < 0) {
                continue;
            }
            if (sensor2_state_debounced == sensor2_state) {
                previous_sensor2_state = sensor2_state;
            }
        }

        if (previous_sensor1_state != -1 && previous_sensor2_state != -1) {
            double elapsed_time = (double)(clock() - start_time) / CLOCKS_PER_SEC;
            double rpm = calculate_rpm(sensor1_state, sensor2_state, elapsed_time);
            printf("RPM: %.2f\n", rpm);

            if (log_data(sensor1_state, sensor2_state) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        gpioDelay(10000);
    }

    gpioTerminate();
    return 0;
}

