#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "biometric_log.txt"
#define READ_INTERVAL_SEC 1

/* Si1182 register addresses (example values; adjust per datasheet) */
#define REG_PART_ID 0x00
#define REG_HW_KEY  0x07
#define REG_MEAS_RATE 0x08
#define REG_DATA_OUT 0x10

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_si1182(void) {
    /* Write HW_KEY to enable the device */
    if (i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY\n");
        return -1;
    }
    /* Set measurement rate to 1 Hz */
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set measurement rate\n");
        return -1;
    }
    return 0;
}

static int read_si1182_data(int *heart_rate, int *spo2) {
    char data[4];
    int result = i2cReadI2CBlockData(i2c_handle, REG_DATA_OUT, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error: Failed to read data block (got %d bytes)\n", result);
        return -1;
    }
    /* Example parsing: data[0] = heart rate, data[1] = SpO2 */
    *heart_rate = (data[0] << 8) | data[1];
    *spo2 = (data[2] << 8) | data[3];
    return 0;
}

static void log_data(int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1182() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    int heart_rate, spo2;
    while (!terminate) {
        if (read_si1182_data(&heart_rate, &spo2) == 0) {
            log_data(heart_rate, spo2);
        }
        sleep(READ_INTERVAL_SEC);
    }

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

