#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27
#define TILT_THRESHOLD_SEC 2
#define POLL_INTERVAL_US 100000
#define LOG_FILE_NAME "bridge_integrity.log"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR_2_PIN);
        return -1;
    }

    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize alarm state on GPIO%d\n", ALARM_PIN);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(ALARM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup_gpio();
        return 1;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");
    log_event("Bridge integrity monitoring started");

    int alarm_active = 0;
    time_t alarm_start_time = 0;
    int sensor1_state = 0;
    int sensor2_state = 0;

    while (program_running) {
        sensor1_state = gpioRead(SENSOR_1_PIN);
        sensor2_state = gpioRead(SENSOR_2_PIN);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor GPIOs\n");
            log_event("Error reading sensor GPIOs");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (sensor1_state == 1 && !alarm_active) {
            if (log_event("Tilt detected on sensor 1") != 0) {
                fprintf(stderr, "Failed to log tilt event for sensor 1\n");
            }
            alarm_active = 1;
            alarm_start_time = time(NULL);
            if (gpioWrite(ALARM_PIN, 1) != 0) {
                fprintf(stderr, "Failed to activate alarm\n");
            }
        } else if (sensor1_state == 0 && alarm_active) {
            if (log_event("Tilt ended on sensor 1") != 0) {
                fprintf(stderr, "Failed to log tilt end event for sensor 1\n");
            }
            alarm_active = 0;
            if (gpioWrite(ALARM_PIN, 0) != 0) {
                fprintf(stderr, "Failed to deactivate alarm\n");
            }
        }

        if (sensor2_state == 1 && !alarm_active) {
            if (log_event("Tilt detected on sensor 2") != 0) {
                fprintf(stderr, "Failed to log tilt event for sensor 2\n");
            }
            alarm_active = 1;
            alarm_start_time = time(NULL);
            if (gpioWrite(ALARM_PIN, 1) != 0) {
                fprintf(stderr, "Failed to activate alarm\n");
            }
        } else if (sensor2_state == 0 && alarm_active) {
            if (log_event("Tilt ended on sensor 2") != 0) {
                fprintf(stderr, "Failed to log tilt end event for sensor 2\n");
            }
            alarm_active = 0;
            if (gpioWrite(ALARM_PIN, 0) != 0) {
                fprintf(stderr, "Failed to deactivate alarm\n");
            }
        }

        if (alarm_active) {
            time_t current_time = time(NULL);
            if (current_time - alarm_start_time >= TILT_THRESHOLD_SEC) {
                if (log_event("Alarm triggered: Tilt exceeded threshold") != 0) {
                    fprintf(stderr, "Failed to log alarm trigger event\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    log_event("Bridge integrity monitoring stopped");
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

