/*
 * seismic.c — Raspberry Pi 3 Model B+ seismic monitor
 *
 * Sensor : Omron D7S-A0011 (I2C 0x33, 0x34)
 * Bus    : /dev/i2c-1  (SDA = GPIO2, SCL = GPIO3)
 * LED    : GPIO17 (BCM)
 *
 * Build  : gcc -O2 -Wall -o seismic seismic.c -lthe-driver-lib -lm -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x33
#define LED_PIN        17
#define VIB_THRESHOLD  500.0f
#define POLL_MS        100
#define ALERT_MS       1000
#define MAX_RETRIES    3
#define LOG_FILE       "seismic_events.log"

/* D7S-A0011 register map */
#define REG_X_LSB      0x00
#define REG_X_MSB      0x01
#define REG_Y_LSB      0x02
#define REG_Y_MSB      0x03
#define REG_Z_LSB      0x04
#define REG_Z_MSB      0x05
#define REG_STATUS     0x06
#define REG_CTRL1      0x07
#define REG_CTRL2      0x08
#define REG_CTRL3      0x09
#define REG_CTRL4      0x0A
#define REG_TEMP_LSB   0x0B
#define REG_TEMP_MSB   0x0C
#define REG_DIAG_LSB   0x0D
#define REG_DIAG_MSB   0x0E

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void msleep(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
