#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define LOG_FILE "/var/log/flame_events.log"
#define POLL_INTERVAL_SEC 1
#define DEBOUNCE_DELAY_MS 50
#define DEBOUNCE_READ_COUNT 1

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char *sensor_names[NUM_SENSORS] = {"Sensor1", "Sensor2", "Sensor3", "Sensor4", "Sensor5"};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static void log_event(int sensor_id, unsigned int gpio_pin) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];
    char log_message[256];

    time(&rawtime);
    gmtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    snprintf(log_message, sizeof(log_message),
             "%s - Sensor ID: %d (GPIO %u) - Flame Detected",
             timestamp, sensor_id, gpio_pin);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file %s: %s", LOG_FILE, strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to lock log file: %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s\n", log_message) < 0) {
        syslog(LOG_ERR, "Failed to write to log file: %s", strerror(errno));
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "Failed to flush log file: %s", strerror(errno));
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to unlock log file: %s", strerror(errno));
    }

    fclose(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_values[NUM_SENSORS];
    int ret;
    int i;

    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
        prev_values[i] = 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "Failed to get GPIO line %u: %s", sensor_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_input(lines[i], "flame_monitor");
