#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 8
#define POLL_INTERVAL_MS 50

/* BCM GPIO pin numbers for the TTP226 OUT0-OUT7 */
static const unsigned int sensor_pins[NUM_SENSORS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        if (strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &timeinfo) > 0) {
            printf("[%s] ", buffer);
        }
    } else {
        printf("[unknown-time] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk bulk;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int ret;
    int i;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: cannot open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Resolve each BCM pin into a gpiod_line pointer */
    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: cannot get GPIO line %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request all eight lines as inputs in a bulk request */
    ret = gpiod_line_request_bulk_input(&bulk, lines);
    if (ret < 0) {
        fprintf(stderr, "Error: cannot request bulk input lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Initialize previous states to -1 so that the first reading always logs */
    for (i = 0; i < NUM_SENSORS; i++) {
        prev_state[i] = -1;
    }

    printf("TTP226 8-channel touch sensor monitoring started.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        ret = gpiod_line_get_value_bulk(&bulk, NULL);
        if (ret < 0) {
            fprintf(stderr, "Error: failed to read touch sensor values: %s\n", strerror(errno));
            goto cleanup;
        }

        for (i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error: failed to read GPIO %u: %s\n",
                        sensor_pins[i], strerror(errno));
                goto cleanup;
            }

            if (val != prev_state[i]) {
                print_timestamp();
                printf("Sensor %d (BCM %u): %s\n",
                       i, sensor_pins[i], val ? "TOUCHED" : "released");
                fflush(stdout);
                prev_state[i] = val;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    /* Release the bulk request; individual lines are released automatically */
    if (ret < 0) {
        fprintf(stderr, "Warning: gpiod_line_get_value_bulk failed, releasing lines...\n");
    }
    gpiod_line_release_bulk(&bulk);

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting gracefully.\n");
    return (ret < 0) ? EXIT_FAILURE : EXIT_SUCCESS;
}

