#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define LED_PIN 17
#define POLL_DELAY_US 50000
#define DEBOUNCE_US 100000

static const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as input\n", touch_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Error: failed to set pull-down on GPIO%d\n", touch_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
