#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x44
#define LOG_FILE       "light_data.txt"
#define SAMPLE_PERIOD  1
#define OPT3001_PWR_MGT 0x00
#define OPT3001_INT_CFG 0x01
#define OPT3001_REG_DATA 0x02
#define OPT3001_REG_CONFIG 0x03
#define OPT3001_REG_MANUF 0x7E
#define OPT3001_REG_DEV_ID 0x7F
#define OPT3001_MANUF_ID   0x5449
#define OPT3001_DEV_ID     0x3001
#define OPT3001_CONFIG_DEFAULT 0x0000
#define OPT3001_DATA_SCALE  0.0000004096f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int opt3001_init(int fd) {
    uint16_t dev_id = 0;
    if (i2c_read_reg16(fd, OPT3001_REG_DEV_ID, &dev_id) != 0) {
        return -1;
    }
    if (dev_id != OPT3001_DEV_ID) {
        fprintf(stderr, "OPT3001 not detected (dev_id=0x%04X, expected 0x%04X)\n", dev_id, OPT3001_DEV_ID);
        return -1;
    }
    if (i2c_write_reg16(fd, OPT3001_PWR_MGT, 0x00) != 0) return -1;
    usleep(10000);
    if (i2c_write_reg16(fd, OPT3001_INT_CFG, 0x00) != 0) return -1;
    if (i2c_write_reg16(fd, OPT3001_REG_CONFIG, OPT3001_CONFIG_DEFAULT) != 0) return -1;
    if (i2c_write_reg16(fd, OPT3001_PWR_MGT, 0x01) != 0) return -1;
    usleep(100000);
    return 0;
}

static int read_lux(int fd, float *lux_out) {
    uint16_t raw = 0;
    if (i2c_read_reg16(fd, OPT3001_REG_DATA, &raw) != 0) {
        return -1;
    }
    uint16_t swapped = ((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF);
    *lux_out = (float)swapped * OPT3001_DATA_SCALE;
    return 0;
}

static int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", timestamp, lux);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus '%s': %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", OPT3001_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (opt3001_init(g_i2c_fd) != 0) {
        fprintf(stderr, "OPT3001 initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    printf("OPT3001 initialized. Logging to %s every %d second(s).\n", LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        if (read_lux(g_i2c_fd, &lux) != 0) {
            fprintf(stderr, "Failed to read lux value.\n");
        } else {
            if (log_data(LOG_FILE, lux) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
            printf("%s, %.2f lux\n", LOG_FILE, lux);
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return 0;
}

