    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALERT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d to LOW\n", ALERT_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup_gpio();
        return 1;
    }

    printf("Monitoring flame sensor on GPIO%d. Alert on GPIO%d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_PIN, ALERT_PIN);

    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO%d: %s\n", FLAME_SENSOR_PIN, strerror(errno));
            log_event("Error: Failed to read flame sensor");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (sensor_value == 0) {
            printf("Flame detected!\n");
            log_event("Flame detected");
            if (gpioWrite(ALERT_PIN, 1) != 0) {
                fprintf(stderr, "Failed to set GPIO%d HIGH\n", ALERT_PIN);
                log_event("Error: Failed to activate alert");
            }
            gpioDelay(ALERT_DURATION_US);
            if (gpioWrite(ALERT_PIN, 0) != 0) {
                fprintf(stderr, "Failed to set GPIO%d LOW\n", ALERT_PIN);
                log_event("Error: Failed to deactivate alert");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully.\n");
    cleanup_gpio();
    return 0;
}

