        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor logging started on GPIO %d. Press Ctrl+C to exit.\n", TOUCH_PIN);

    while (running) {
        current_state = gpioRead(TOUCH_PIN);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", TOUCH_PIN);
            break;
        }

        if (current_state != last_state) {
            if (current_state == 1) {
                if (log_event("Touch Detected") != 0) {
                    break;
                }
                printf("Touch Detected\n");
            } else {
                if (log_event("Touch Released") != 0) {
                    break;
                }
                printf("Touch Released\n");
            }
            last_state = current_state;
        }

        gpioDelay(DEBOUNCE_US);
    }

    printf("\nCleaning up...\n");
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

