#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define TOUCH_PIN 23
#define LED_PIN   24
#define LOG_FILE  "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;
static int log_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int led_state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];
    char line[128];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    int len = snprintf(line, sizeof(line), "%s LED=%d\n", timestamp, led_state);
    if (len < 0 || (size_t)len >= sizeof(line)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }

    if (write(log_fd, line, (size_t)len) != len) {
        fprintf(stderr, "write to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fsync(log_fd) != 0) {
        fprintf(stderr, "fsync failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    int chip_path[] = { "/dev/gpiochip4" };
    for (size_t i = 0; i < sizeof(chip_path) / sizeof(chip_path[0]); i++) {
        int fd = open(chip_path[i], O_RDWR);
        if (fd < 0) {
            fprintf(stderr, "open(%s) failed: %s\n", chip_path[i], strerror(errno));
            close(log_fd);
            log_fd = -1;
            return EXIT_FAILURE;
        }

        if (ioctl(fd, GPIO_SET_DIRECTION, TOUCH_PIN) < 0) {
            fprintf(stderr, "GPIO_SET_DIRECTION(TOUCH_PIN) failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (ioctl(fd, GPIO_SET_DIRECTION, LED_PIN) < 0) {
            fprintf(stderr, "GPIO_SET_DIRECTION(LED_PIN) failed: %s\n", strerror(errno));
            goto cleanup;
        }

        if (ioctl(fd, GPIO_SET_VALUE, TOUCH_PIN, 0) < 0) {
            fprintf(stderr, "GPIO_SET_VALUE(TOUCH_PIN, 0) failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (ioctl(fd, GPIO_SET_VALUE, LED_PIN, 0) < 0) {
            fprintf(stderr, "GPIO_SET_VALUE(LED_PIN, 0) failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("Touch-activated lamp running. Touch GPIO%d to toggle GPIO%d.\n", TOUCH_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    int led_state = 0;
    int ret = EXIT_SUCCESS;

    while (running) {
        struct timespec ts = { 0, POLL_TIMEOUT_MS * 1000000L };
        int ev = ioctl(fd, GPIO_EVENT_READ, &ts);
        if (ev < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "GPIO_EVENT_READ failed: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
            break;
        }

        if (ev == 0) {
            continue;
        }

        if (ev & GPIO_EVENT_RISING_EDGE) {
            led_state = !led_state;
            if (ioctl(fd, GPIO_SET_VALUE, LED_PIN, led_state) < 0) {
                fprintf(stderr, "GPIO_SET_VALUE(LED_PIN, %d) failed: %s\n", led_state, strerror(errno));
                ret = EXIT_FAILURE;
                break;
            }

            if (log_event(led_state) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }

            printf("Touch detected! LED is now %s\n", led_state ? "ON" : "OFF");
        }
    }

cleanup:
    if (fd >= 0) {
        if (ioctl(fd, GPIO_SET_VALUE, LED_PIN, 0) < 0) {
            fprintf(stderr, "GPIO_SET_VALUE(LED_PIN, 0) cleanup failed: %s\n", strerror(errno));
        }
        close(fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return ret;
}

