/*
 * Flame detection safety system — Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 flame sensor (digital output, active-low)
 * Buzzer : Active buzzer on GPIO18 (BCM)
 *
 * Wiring
 *   KY-026 DO  -> GPIO17 (BCM, physical pin 11)
 *   Buzzer +   -> GPIO18 (BCM, physical pin 12)
 *   Buzzer -   -> GND
 *   KY-026 VCC -> 3.3 V
 *   KY-026 GND -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN  17   /* BCM 17 — KY-026 DO  */
#define BUZZER_PIN        18   /* BCM 18 — buzzer control */
#define LOG_FILE          "alert_log.txt"
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_MS 2000
#define SLICE_MS          100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a timestamped entry to the alert log. */
static int log_alert(FILE *log_file)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s: FLAME DETECTED\n", timestamp) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Activate the buzzer for BUZZER_DURATION_MS in SLICE_MS slices. */
static int activate_buzzer(struct gpiod_line *buzzer_line, int duration_ms)
{
    int slices = (duration_ms + SLICE_MS - 1) / SLICE_MS;
    for (int i = 0; i < slices && g_running; i++) {
