/* TMAG5110A1 open-drain output:
 *   OUT is LOW  when a south pole is present (magnet detected).
 *   OUT is HIGH when no magnet is present (magnet removed).
 * pigpio's gpioRead returns 0 or 1; we treat 0 as "magnet present".
 */
#define MAGNET_PRESENT 0
#define MAGNET_REMOVED 1

static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int gpios[] = {SENSOR_1_GPIO, SENSOR_2_GPIO, SENSOR_3_GPIO};
    for (size_t i = 0; i < sizeof(gpios) / sizeof(gpios[0]); ++i) {
        if (gpioSetMode(gpios[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", gpios[i]);
            return -1;
        }
        if (gpioSetPullUpDown(gpios[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Failed to set pull-up on GPIO %d\n", gpios[i]);
            return -1;
        }
    }
    return 0;
}

static int read_sensor(int gpio)
{
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, pigpio_error(value));
        return -1;
    }
    return value;
}

static const char *interpret_state(int state)
{
    return (state == MAGNET_PRESENT) ? "magnet_present" : "magnet_removed";
}

static void log_event(int sensor_id, const char *state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_id, state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    int prev_state[3] = {MAGNET_REMOVED, MAGNET_REMOVED, MAGNET_REMOVED};
    int gpios[] = {SENSOR_1_GPIO, SENSOR_2_GPIO, SENSOR_3_GPIO};

    for (size_t i = 0; i < sizeof(gpios) / sizeof(gpios[0]); ++i) {
        int v = read_sensor(gpios[i]);
        if (v == -1) {
            continue;
        }
        prev_state[i] = v;
    }

    while (!terminate) {
        for (size_t i = 0; i < sizeof(gpios) / sizeof(gpios[0]); ++i) {
            int v = read_sensor(gpios[i]);
            if (v == -1) {
                continue;
            }
            if (v != prev_state[i]) {
                const char *state = interpret_state(v);
                log_event(i + 1, state);
                prev_state[i] = v;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

