#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_HR_DATA 0x24
#define REG_CONFIG 0x01

#define EXPECTED_PART_ID 0x82
#define EXPECTED_HW_REV 0x01

#define MOVING_AVG_SIZE 5
#define SAMPLE_DELAY_US 100000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int init_sensor(int handle) {
    uint8_t part_id = 0, hw_rev = 0;
    if (i2c_read_reg(handle, REG_PART_ID, &part_id) < 0) return -1;
    if (i2c_read_reg(handle, REG_HW_REV, &hw_rev) < 0) return -1;
    if (part_id != EXPECTED_PART_ID || hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Sensor not detected: PART_ID=0x%02X HW_REV=0x%02X (expected 0x%02X 0x%02X)\n",
                part_id, hw_rev, EXPECTED_PART_ID, EXPECTED_HW_REV);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X, HW_REV=0x%02X)\n", part_id, hw_rev);

    if (i2c_write_reg(handle, REG_CONFIG, 0x01) < 0) return -1;
    return 0;
}

static int read_heart_rate(int handle, int *raw_hr) {
    uint8_t hr_data = 0;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg(handle, REG_HR_DATA, &hr_data) == 0) {
            *raw_hr = (int)hr_data;
            return 0;
        }
        usleep(10000);
    }
    return -1;
}

static int moving_average(int new_value, int *history, int history_size, int *index) {
    history[*index] = new_value;
    *index = (*index + 1) % history_size;
    int sum = 0;
    for (int i = 0; i < history_size; i++) sum += history[i];
    return sum / history_size;
}

static int validate_heart_rate(int bpm) {
    return (bpm >= 30 && bpm <= 220);
}

static void log_heart_rate(FILE *fp, int bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, bpm);
    fflush(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        cleanup();
        return 1;
    }

    int history[MOVING_AVG_SIZE] = {0};
    int history_index = 0;
    int consecutive_errors = 0;

    while (!terminate) {
        int raw_hr = 0;
        if (read_heart_rate(i2c_handle, &raw_hr) == 0) {
            consecutive_errors = 0;
            int filtered_hr = moving_average(raw_hr, history, MOVING_AVG_SIZE, &history_index);
            if (validate_heart_rate(filtered_hr)) {
                log_heart_rate(log_file, filtered_hr);
            } else {
                fprintf(stderr, "Invalid heart rate: %d BPM\n", filtered_hr);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Failed to read heart rate (attempt %d/%d)\n",
                    consecutive_errors, MAX_RETRIES);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive I2C errors, aborting\n");
                break;
            }
        }
        usleep(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

