#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped flame-detection record to the log file.       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_flame_event(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s: FLAME DETECTED\n", timestamp) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_SUCCESS;
    int last_state = 1;   /* assume no flame at startup (HIGH)          */
    int first_read = 1;

    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file in append mode ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as input with internal pull-up ---- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n",
                FLAME_SENSOR_GPIO);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n",
                FLAME_SENSOR_GPIO);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    /* ---- Main polling loop ---- */
    while (g_running) {
        int current_state = gpioRead(FLAME_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "gpioRead(%d) failed: %s\n",
                    FLAME_SENSOR_GPIO, strerror(errno));
            ret = EXIT_FAILURE;
            break;
        }

        /* Detect falling edge: HIGH -> LOW (active-low sensor) */
        if (first_read || current_state == 0) {
            if (current_state == 0 && last_state == 1) {
                printf("FLAME DETECTED\n");
                fflush(stdout);

                if (log_flame_event() != 0) {
                    fprintf(stderr, "Failed to log flame event\n");
                }
            }
            last_state = current_state;
            first_read = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    /* ---- Release GPIO resources ---- */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();

    return ret;
}

