        if (current_state < 0) {
            fprintf(stderr, "gpioRead(%d) failed: %s\n",
                    FLAME_SENSOR_GPIO, strerror(errno));
            ret = EXIT_FAILURE;
            break;
        }

        /* Detect falling edge: HIGH -> LOW (active-low sensor) */
        if (first_read || current_state == 0) {
            if (current_state == 0 && last_state == 1) {
