            last_state = current_state;
            first_read = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    /* ---- Release GPIO resources ---- */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();

    return ret;
}

