/*
 * touch_counter.c — 8-channel TTP226 capacitive touch sensor → 8-bit binary counter
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    ./touch_counter
 *
 * Hardware (Raspberry Pi Zero W, gpiochip4):
 *   TTP226 OUT1..OUT8  →  BCM 5..12 (input)
 *   Counter bits:       BCM 17..24 (output)
 *
 * Each rising edge (idle 0 V → touched 3.3 V) increments the counter
 * and updates the eight output pins via libgpiod bulk/config calls.
 * Events are logged to touch_log.txt with an ISO-8601 UTC timestamp.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 10
#define STABILIZE_MS 200
#define LOG_FILE "touch_log.txt"

/* TTP226 OUT1..OUT8 on BCM 5..12 (inputs) */
static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
/* Counter bits: BCM 17..24 (outputs) */
static const unsigned int counter_bit_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Write the 8-bit counter value to the output pins.
 * Returns 0 on success, -1 on error.
 */
static int write_counter(struct gpiod_line_bulk *bulk, int value)
{
    int ret;

    ret = gpiod_line_set_value_bulk(bulk, value);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_set_value_bulk failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Log a touch event to LOG_FILE.
 * Returns 0 on success, -1 on error.
 */
static int log_touch_event(int channel, int counter_value)
{
    FILE *fp;
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time(&rawtime);
    gmtime_r(&rawtime, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk bulk;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request *req = NULL;
    int ret;
    int counter = 0;
    int prev_counter = 0;
    int exit_code = 0;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    /* --- Open gpiochip4 (BCM GPIO on Pi Zero W) --- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return 1;
    }

    /* --- Configure input lines (sensor) --- */
    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "gpiod_line_config_new (inputs) failed\n");
        goto cleanup;
    }

    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "gpiod_line_settings_new (inputs) failed\n");
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    ret = gpiod_line_config_add_line_settings(line_cfg, sensor_pins, NUM_CHANNELS, settings);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings (inputs) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "gpiod_request_config_new failed\n");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-touch");

    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!req) {
        fprintf(stderr, "gpiod_chip_request_lines (inputs) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Configure output lines (counter) --- */
    gpiod_line_config_reset(line_cfg);
    gpiod_line_settings_reset(settings);

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(settings, GPIOD_LINE_VALUE_INACTIVE);

    ret = gpiod_line_config_add_line_settings(line_cfg, counter_bit_pins, NUM_CHANNELS, settings);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings (outputs) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "gpiod_request_config_new (outputs) failed\n");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-counter");

    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!req) {
        fprintf(stderr, "gpiod_chip_request_lines (outputs) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Bulk line object for combined input/output operations --- */
    gpiod_line_bulk_init(&bulk);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_bulk_add(&bulk, gpiod_line_request_get_line(req, i));
    }

    /* --- Stabilization delay --- */
    printf("Waiting %d ms for TTP226 stabilization...\n", STABILIZE_MS);
    usleep(STABILIZE_MS * 1000);

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (program_running) {
        int current_value = 0;
        int read_error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(req, i);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value failed on channel %d: %s\n",
                        i, strerror(errno));
                read_error = 1;
                continue;
            }
            current_value |= (val << i);
        }

        if (read_error) {
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (current_value != prev_counter) {
            counter = (counter + 1) & 0xFF;
            if (write_counter(&bulk, counter) < 0) {
                exit_code = 1;
                goto cleanup;
            }
            for (int i = 0; i < NUM_CHANNELS; i++) {
                int val = gpiod_line_get_value(req, i);
                if (val < 0) {
                    fprintf(stderr, "gpiod_line_get_value failed on channel %d: %s\n",
                            i, strerror(errno));
                    continue;
                }
                ret = gpiod_line_set_value(req, i, val);
                if (ret < 0) {
                    fprintf(stderr, "gpiod_line_set_value failed on channel %d: %s\n",
                            i, strerror(errno));
                }
            }
            if (log_touch_event(i + 1, counter) < 0) {
                exit_code = 1;
                goto cleanup;
            }
            printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            prev_counter = counter;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    printf("\nShutting down...\n");
    if (req) {
        /* Reset all output bits to 0 */
        gpiod_line_set_value_bulk(&bulk, 0);
        gpiod_line_release_bulk(&bulk);
        gpiod_line_request_release(req);
    }
    if (req_cfg)
        gpiod_request_config_free(req_cfg);
    if (line_cfg)
        gpiod_line_config_free(line_cfg);
    if (settings)
        gpiod_line_settings_free(settings);
    if (chip)
        gpiod_chip_close(chip);

    return exit_code;
}

