        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SENSOR2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing LED state\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
