        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing CSV header: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int led_state = (s1 == 0 && s2 == 0) ? 1 : 0;

        if (control_led(led_state) < 0) {
            fprintf(stderr, "LED control error, skipping cycle\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (log_data(log_file, s1, s2, led_state) < 0) {
            fprintf(stderr, "Logging error, skipping cycle\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Obstacle avoidance system stopped.\n");
    return 0;
}

