#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdbool.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    unsigned pins[] = {LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%u as input.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Error: failed to set pull-up on GPIO%u.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("SunFounder 3-Way Tracing Sensor Reader\n");
    printf("Left: GPIO%u | Center: GPIO%u | Right: GPIO%u\n",
           LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int left_val = gpioRead(LEFT_SENSOR_PIN);
        int center_val = gpioRead(CENTER_SENSOR_PIN);
        int right_val = gpioRead(RIGHT_SENSOR_PIN);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error: GPIO read failure (L=%d, C=%d, R=%d).\n",
                    left_val, center_val, right_val);
            break;
        }

        printf("Left: %s | Center: %s | Right: %s\n",
               left_val == 0 ? "HIGH (reflected)" : "LOW (no reflection)",
               center_val == 0 ? "HIGH (reflected)" : "LOW (no reflection)",
               right_val == 0 ? "HIGH (reflected)" : "LOW (no reflection)");

        fflush(stdout);
        gpioDelay(POLL_DELAY_US);
    }

    cleanup_gpio();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

