#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Si1175 ALS (Ambient Light Sensor) reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si1175 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   Si1175 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   Si1175 VDD -> 3.3 V
 *   Si1175 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1175_als si1175_als.c -lpigpio -lrt
 *   (Run as root or with appropriate pigpio permissions.)
 */

#define I2C_BUS        1
#define I2C_ADDR       0x48          /* Si1175 default 7-bit I2C address */
#define SAMPLE_PERIOD_US 100000      /* 100 ms in microseconds */

/* Si1175 register addresses (command bit + 8-bit register) */
#define REG_COMMAND    0x18
#define REG_ALS_LSB    0x22
#define REG_ALS_MSB    0x23

/* Command-bit values */
#define CMD_RESET      0x01
#define CMD_ALS_FORCE  0x06

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */

/*
 * Write a single command byte to the Si1175 command register.
 * Returns 0 on success, -1 on failure.
 */
static int si1175_write_command(uint8_t cmd)
{
    if (i2cWriteByteData(g_i2c_handle, REG_COMMAND, cmd) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(command=0x%02X) failed\n", cmd);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit little-endian value from two consecutive registers.
 * Returns 0 on success, -1 on failure.
 */
static int si1175_read_16bit(uint8_t reg_lsb, uint16_t *out)
{
    int lsb = i2cReadByteData(g_i2c_handle, reg_lsb);
    if (lsb < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed (err=%d)\n",
                reg_lsb, lsb);
        return -1;
    }

    int msb = i2cReadByteData(g_i2c_handle, reg_lsb + 1);
    if (msb < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed (err=%d)\n",
                reg_lsb + 1, msb);
        return -1;
    }

    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                    */
/* ------------------------------------------------------------------ */

/*
 * Reset the Si1175 and wait for the device to acknowledge the reset.
 * Returns 0 on success, -1 on failure.
 */
static int si1175_reset(void)
{
    if (si1175_write_command(CMD_RESET) < 0)
        return -1;

    /* Allow the reset to complete (command bit echo back) */
    gpioDelay(10000); /* 10 ms */

    /* Verify the device is still responding by reading the command register */
    int cmd = i2cReadByteData(g_i2c_handle, REG_COMMAND);
    if (cmd < 0) {
        fprintf(stderr, "[ERROR] Si1175 not responding after reset (err=%d)\n", cmd);
        return -1;
    }

    return 0;
}

/*
 * Trigger an ALS measurement and read the 16-bit raw result.
 * Returns 0 on success, -1 on failure.
 */
static int si1175_read_als(uint16_t *raw_out)
{
    if (si1175_write_command(CMD_ALS_FORCE) < 0)
        return -1;

    gpioDelay(10000); /* 10 ms conversion time */

    return si1175_read_16bit(REG_ALS_LSB, raw_out);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed (err=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Reset the sensor and verify it is present */
    if (si1175_reset() < 0) {
        fprintf(stderr, "[FATAL] Si1175 reset failed — sensor may be absent or unresponsive\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1175 ALS reader started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t raw = 0;

        if (si1175_read_als(&raw) == 0) {
            printf("ALS Raw: %u\n", raw);
        } else {
            fprintf(stderr, "[WARN] Failed to read ALS data\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

