#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/gpio.h>
#include <sys/ioctl.h>

#define LEFT_PIN 2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

static int gpio_export(int pin) {
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (len < 0 || len >= (int)sizeof(buf)) return -1;
    if (ioctl(G_DEV_GPIO_LINE, GPIO_EXPORT, buf) < 0) {
        fprintf(stderr, "gpio_export failed for pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_get_line(int fd, int pin) {
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (len < 0 || len >= (int)sizeof(buf)) return -1;
    if (ioctl(fd, GPIO_GET_LINE, buf) < 0) {
        fprintf(stderr, "gpio_get_line failed for pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_request_line(int fd, int pin, int direction, int value) {
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (len < 0 || len >= (int)sizeof(buf)) return -1;
    if (ioctl(fd, GPIO_REQUEST_LINE, buf) < 0) {
        fprintf(stderr, "gpio_request_line failed for pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    if (direction != 0 && direction != 1) {
        fprintf(stderr, "Invalid direction %d for pin %d\n", direction, pin);
        return -1;
    }
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid value %d for pin %d\n", value, pin);
        return -1;
    }
    return 0;
}

static int gpio_read_line(int fd, int pin) {
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (len < 0 || len >= (int)sizeof(buf)) return -1;
    if (ioctl(fd, GPIO_READ_LINE, buf) < 0) {
        fprintf(stderr, "gpio_read_line failed for pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(int fd) {
    if (fd >= 0) {
