#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 200000

static const int touch_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_touch_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

static void print_timestamp(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        fprintf(stderr, "Error getting monotonic time: %s\n", strerror(errno));
        return;
    }
    double seconds = ts.tv_sec + ts.tv_nsec / 1e9;
    printf("[%.6f] ", seconds);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = touch_pins[i];
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input: %s\n", pin, strerror(errno));
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d: %s\n", pin, strerror(errno));
            gpioTerminate();
            return 1;
        }
    }

    printf("TTP226 Touch Sensor Polling (Ctrl+C to exit)\n");

    while (running) {
        print_timestamp();
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = read_touch_sensor(touch_pins[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading channel %d\n", i + 1);
                continue;
            }
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");
        fflush(stdout);
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    return 0;
}

