#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQ  1000
#define PWM_RANGE 255

#define STEP_COUNT 50
#define STEP_DELAY_US 100000  /* 100 ms per step */
#define FADE_DURATION_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int clamp_u8(int v, uint8_t max)
{
    if (v < 0) return 0;
    if (v > max) return max;
    return (int)v;
}

static void set_led_color(uint8_t r, uint8_t g, uint8_t b)
{
    gpioPWM(RED_PIN,   clamp_u8(r, PWM_RANGE));
    gpioPWM(GREEN_PIN, clamp_u8(g, PWM_RANGE));
    gpioPWM(BLUE_PIN,  clamp_u8(b, PWM_RANGE));
}

static void fade_to_color(uint8_t r, uint8_t g, uint8_t b)
{
    float dr = (float)(r - (uint8_t)RED_PIN) / (float)PWM_RANGE;
    float dg = (float)(g - (uint8_t)GREEN_PIN) / (float)PWM_RANGE;
    float db = (float)(b - (uint8_t)BLUE_PIN) / (float)PWM_RANGE;

    for (int i = 0; i < STEP_COUNT && g_running; i++) {
        float t = (float)i / (float)(STEP_COUNT - 1);
        float r_val = (uint8_t)RED_PIN + t * PWM_RANGE * dr;
        float g_val = (uint8_t)GREEN_PIN + t * PWM_RANGE * dg;
        float b_val = (uint8_t)BLUE_PIN + t * PWM_RANGE * db;
        set_led_color(clamp_u8((int)r_val, PWM_RANGE),
                       clamp_u8((int)g_val, PWM_RANGE),
                       clamp_u8((int)b_val, PWM_RANGE));
        usleep(STEP_DELAY_US);
    }
}

static void generate_random_color(uint8_t *r, uint8_t *g, uint8_t *b)
{
    *r = (uint8_t)(rand() % 256);
    *g = (uint8_t)(rand() % 256);
    *b = (uint8_t)(rand() % 256);
}

int main(void)
{
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) != PWM_FREQ) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != PWM_RANGE) {
        syslog(LOG_ERR, "Failed to set PWM range");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        uint8_t r, g, b;
        generate_random_color(&r, &g, &b);
        syslog(LOG_INFO, "Fading to R=%u G=%u B=%u", r, g, b);
        fade_to_color(r, g, b);
    }

    syslog(LOG_INFO, "Shutting down: turning off LED");
    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

