#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_CMD   0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME  0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA  0x14
#define TCS34725_RDATA  0x12
#define TCS34725_GDATA  0x13
#define TCS34725_BDATA  0x14

#define TCS34725_PON   0x01
#define TCS34725_AEN   0x02

#define RED_THRESHOLD  200
#define LED_GPIO       17
#define POLL_DELAY_US  200000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(TCS34725_CMD | reg), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    uint8_t cmd = (uint8_t)(TCS34725_CMD | reg);
