#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x5C
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define NUM_LEDS 10
#define LED_GPIO 18
#define PWM_FREQ 800000
#define PWM_RANGE 255
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 100
#define BH1750_MEASUREMENT_DELAY_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pigpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *value) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_bh1750(int fd, uint16_t *lux_raw) {
    if (i2c_write_byte(fd, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
        return -1;
    }
    usleep(BH1750_MEASUREMENT_DELAY_MS * 1000);
    uint16_t raw;
    if (i2c_read_word(fd, &raw) < 0) {
        return -1;
    }
    *lux_raw = raw;
    return 0;
}

static int map_lux_to_brightness(uint16_t lux) {
    if (lux > 0) {
        float log_lux = log10f((float)lux);
        float brightness = (float)log_lux / log10f(100.0f);
        if (brightness < 0.0f) brightness = 0.0f;
        if (brightness > 1.0f) brightness = 1.0f;
        return (int)(brightness * 255.0f);
    }
    return 0;
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    uint32_t pulse_width = 1000000 / PWM_FREQ;
    uint32_t high_time = (pulse_width * brightness) / 255;
    uint32_t low_time = pulse_width - high_time;

    gpioWrite(LED_GPIO, 1);
    gpioDelay(high_time);
    gpioWrite(LED_GPIO, 0);
    gpioDelay(low_time);
}

static void cleanup() {
    if (pigpio_initialized) {
        gpioPWM(LED_GPIO, 0);
        gpioSetMode(LED_GPIO, PI_INPUT);
        gpioTerminate();
        pigpio_initialized = 0;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        cleanup();
        return 1;
    }

    int retries = I2C_RETRY_COUNT;
    while (retries > 0 && running) {
        if (read_bh1750(i2c_fd, NULL) == 0) {
            break;
        }
        fprintf(stderr, "BH1750 read failed, retrying (%d left)\n", retries - 1);
        retries--;
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read BH1750 after retries. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("BH1750 initialized. Reading lux values...\n");

    while (running) {
        uint16_t lux_raw;
        if (read_bh1750(i2c_fd, &lux_raw) < 0) {
            fprintf(stderr, "BH1750 read failed. Retrying...\n");
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }

        int brightness = map_lux_to_brightness(lux_raw);
        set_led_brightness(brightness);
        printf("Lux: %u, Brightness: %d\n", lux_raw, brightness);

        usleep(50000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

