#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define NUM_LEDS 10
#define CONVERSION_TIME_MS 120
#define SPI_SPEED_HZ 1000000
#define SPI_BITS 8
#define SPI_MODE 0

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int bh1750_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        return -1;
    }
    uint16_t id = 0;
    if (i2c_read_reg16(fd, 0x00, &id) < 0) {
        return -1;
    }
    if (id != 0x03) {
        fprintf(stderr, "BH1750 not detected (ID: 0x%04X)\n", id);
        return -1;
    }
    return 0;
}

static int bh1750_read(int fd, uint16_t *light_level) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        return -1;
    }
    if (i2c_read_reg16(fd, 0x00, light_level) < 0) {
        return -1;
    }
    usleep(CONVERSION_TIME_MS * 1000);
    return 0;
}

static int apa102_write_frame(int fd, uint8_t brightness) {
    uint8_t frame[4];
    frame[0] = 0x00;
    frame[1] = 0x00;
    frame[2] = 0x00;
    frame[3] = brightness;
    if (write(fd, frame, 4) != 4) {
        return -1;
    }
    return 0;
}

static int apa102_set_brightness(int fd, uint8_t brightness) {
    for (int i = 0; i < NUM_LEDS; i++) {
        if (apa102_write_frame(fd, brightness) < 0) {
            return -1;
        }
    }
    return 0;
}

