#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_SENSORS 3
#define I2C_BUS 1
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define APA102_COUNT 10
#define FADE_STEPS 50
#define FADE_DELAY_US 50000
#define LOOP_DELAY_US 100000
#define BH1750_CONV_DELAY_US 180000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(int handle, int address) {
    if (i2cWriteByte(handle, 0x10) < 0) {
        fprintf(stderr, "BH1750 init failed (addr 0x%02X): %s\n", address, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read(int handle, int address, uint16_t *lux) {
    if (i2cWriteByte(handle, 0x22) < 0) {
        fprintf(stderr, "BH1750 write trigger (0x%02X) failed: %s\n", address, strerror(errno));
        return -1;
    }
    gpioDelay(BH1750_CONV_DELAY_US);

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "BH1750 read (0x%02X) failed: %s\n", address, strerror(errno));
        return -1;
    }
    *lux = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int apa102_init(int spi_handle) {
    gpioSetMode(10, PI_ALT0);
    gpioSetMode(11, PI_ALT0);
    return 0;
}

static int apa102_write_frame(int spi_handle, uint8_t *data, int count) {
    return spiWrite(spi_handle, (char *)data, count);
}

static void apa102_set_brightness(int spi_handle, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    uint8_t frame[4 + APA102_COUNT * 4];
    frame[0] = 0xE0;
    frame[1] = 0xF0;
    frame[2] = 0x03;
    frame[3] = 0x03;

    for (int i = 0; i < APA102_COUNT; i++) {
        int idx = 4 + i * 4;
        frame[idx + 0] = 0xE0;
        frame[idx + 1] = 0xF0;
        frame[idx + 2] = 0x00;
        frame[idx + 3] = 0x00;
    }

    for (int i = 0; i < 256; i++) {
        if (i <= brightness) {
            frame[4 + (i / 8) * 4 + 2] = 0xFF;
        } else {
            frame[4 + (i / 8) * 4 + 2] = 0x00;
        }
    }

    if (apa102_write_frame(spi_handle, frame, 4 + APA102_COUNT * 4) < 0) {
        fprintf(stderr, "SPI write failed: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int i2c_handles[NUM_SENSORS];
    int bh1750_addresses[NUM_SENSORS] = {0x01, 0x02, 0x03};
    int bh1750_handles[NUM_SENSORS];
    int bh1750_opened = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, bh1750_addresses[i], 0);
        if (i2c_handles[i] >= 0) {
            bh1750_handles[i] = i2c_handles[i];
            bh1750_opened++;
            if (bh1750_init(bh1750_handles[i], bh1750_addresses[i]) != 0) {
                i2cClose(i2c_handles[i]);
                i2c_handles[i] = -1;
            }
        } else {
            fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", bh1750_addresses[i], strerror(errno));
            i2c_handles[i] = -1;
        }
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(spi_handle));
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) i2cClose(i2c_handles[i]);
        }
        gpioTerminate();
        return 1;
    }

    if (apa102_init(spi_handle) != 0) {
        fprintf(stderr, "APA102 init failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) i2cClose(i2c_handles[i]);
        }
        return 1;
    }

    uint16_t lux_values[NUM_SENSORS];
    int valid_count = 0;

    while (running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] < 0) continue;
            uint16_t lux;
            if (bh1750_read(i2c_handles[i], bh1750_addresses[i], &lux) == 0) {
                lux_values[valid_count++] = lux;
            } else {
                fprintf(stderr, "Sensor %d read failed, skipping\n", i);
            }
        }

        if (valid_count > 0) {
            uint16_t sum = 0;
            for (int i = 0; i < valid_count; i++) {
                sum += lux_values[i];
            }
            uint16_t avg = sum / valid_count;
            apa102_set_brightness(spi_handle, (int)avg);
        } else {
            fprintf(stderr, "No valid sensor readings, setting strip to off\n");
            apa102_set_brightness(spi_handle, 0);
        }

        for (int i = 0; i < FADE_STEPS && running; i++) {
            int target = (i + 1) * 255 / FADE_STEPS;
            apa102_set_brightness(spi_handle, target);
            gpioDelay(FADE_DELAY_US);
        }

        for (int i = 0; i < LOOP_DELAY_US / 1000 && running; i++) {
            gpioDelay(1000);
        }
    }

    apa102_set_brightness(spi_handle, 0);
    spiClose(spi_handle);
    apa102_init(spi_handle);
    gpioDelay(100000);
    spiClose(spi_handle);
    gpioTerminate();

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) i2cClose(i2c_handles[i]);
    }

    return 0;
}

