    uint8_t data[NUM_LEDS * 4];
    for (int i = 0; i < NUM_LEDS; i++) {
        data[i * 4 + 0] = 0x00;
        data[i * 4 + 1] = 0xE0 | (r >> 3);
        data[i * 4 + 2] = 0xE0 | (g >> 3);
        data[i * 4 + 3] = 0xE0 | (b >> 3);
    }
    for (int i = 0; i < NUM_LEDS * 4; i++) {
        int bit = (data[i] >> 7) & 1;
        if (gpioWrite(gpio, bit) < 0) return -1;
        usleep(1);
    }
    return 0;
}

static int ws2812b_init(int gpio) {
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(gpio, 0) < 0) return -1;
    return 0;
}

static void ws2812b_cleanup(int gpio) {
    ws2812b_set_leds(gpio, 0, 0, 0);
    gpioWrite(gpio, 0);
