#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define BUZZER_PATTERN_DURATION_MS 200
#define BUZZER_SHORT_DURATION_MS 200
#define BUZZER_LONG_DURATION_MS 600
#define BUZZER_SHORT_SHORT_DURATION_MS 200

#define LED_BLINK_DURATION_MS 500
#define LED_BLINK_INTERVAL_MS 500
#define LED_BLINK_COUNT 2

#define SELF_TEST_SAMPLES 5
#define SELF_TEST_INTERVAL_MS 100

#define POLL_INTERVAL_MS 50

#define ERROR_LED_BLINK_DURATION_MS 100
#define ERROR_LED_BLINK_COUNT 5

#define ERROR_BUZZER_PATTERN_DURATION_MS 100
#define ERROR_BUZZER_PATTERN_REPEATS 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, event);
    fflush(stdout);
}

static void error_led_blink(void) {
    for (int i = 0; i < ERROR_LED_BLINK_COUNT; i++) {
        if (gpioWrite(LED_PIN, 1) < 0) {
            log_event("ERROR: Failed to write LED_PIN high");
            return;
        }
        gpioDelay(ERROR_LED_BLINK_DURATION_MS * 1000);
        if (gpioWrite(LED_PIN, 0) < 0) {
            log_event("ERROR: Failed to write LED_PIN low");
            return;
        }
        gpioDelay(ERROR_LED_BLINK_DURATION_MS * 1000);
    }
}

static void error_buzzer_pattern(void) {
    for (int i = 0; i < ERROR_BUZZER_PATTERN_REPEATS; i++) {
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            log_event("ERROR: Failed to write BUZZER_PIN high");
            return;
        }
        gpioDelay(BUZZER_SHORT_SHORT_DURATION_MS * 1000);
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            log_event("ERROR: Failed to write BUZZER_PIN low");
            return;
        }
        gpioDelay(BUZZER_SHORT_SHORT_DURATION_MS * 1000);
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            log_event("ERROR: Failed to write BUZZER_PIN high");
            return;
        }
        gpioDelay(BUZZER_LONG_DURATION_MS * 1000);
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            log_event("ERROR: Failed to write BUZZER_PIN low");
            return;
        }
        gpioDelay(BUZZER_SHORT_SHORT_DURATION_MS * 1000);
    }
}

static void self_test(void) {
    log_event("Starting self-test...");
    for (int i = 0; i < SELF_TEST_SAMPLES; i++) {
        int val = gpioRead(FLAME_SENSOR_PIN);
        if (val < 0) {
            log_event("ERROR: Failed to read flame sensor during self-test");
            return;
        }
        if (val == 0) {
            log_event("ERROR: Flame detected during self-test (sensor stuck low)");
            error_led_blink();
            error_buzzer_pattern();
            return;
        }
        gpioDelay(SELF_TEST_INTERVAL_MS * 1000);
    }
    log_event("Self-test complete. No errors detected.");
}

static void cleanup(void) {
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return 1;
    }

    self_test();

    log_event("Entering main loop.");

    while (running) {
        int val = gpioRead(FLAME_SENSOR_PIN);
        if (val < 0) {
            log_event("ERROR: Failed to read flame sensor");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (val == 0) {
            log_event("Flame detected!");
            if (gpioWrite(BUZZER_PIN, 1) < 0) {
                log_event("ERROR: Failed to activate buzzer");
            }
            if (gpioWrite(LED_PIN, 1) < 0) {
                log_event("ERROR: Failed to activate LED");
            }
            gpioDelay(POLL_INTERVAL_MS * 1000);

            int new_val = gpioRead(FLAME_SENSOR_PIN);
            if (new_val < 0) {
                log_event("ERROR: Failed to read flame sensor after detection");
            } else if (new_val == 1) {
                if (gpioWrite(BUZZER_PIN, 0) < 0) {
                    log_event("ERROR: Failed to deactivate buzzer");
                }
                if (gpioWrite(LED_PIN, 0) < 0) {
                    log_event("ERROR: Failed to deactivate LED");
                }
            }
        } else {
            gpioDelay(POLL_INTERVAL_MS * 1000);
        }
    }

    log_event("Shutting down gracefully.");
    cleanup();
    return 0;
}

