#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x5C
#define GPIO_PIN        17
#define BUFFER_SIZE     60
#define SAMPLE_PERIOD_S 1
#define MAX_LUX         1000
#define BH1750_PWR_ON   0x01
#define BH1750_RESET    0x07
#define BH1750_CONT_HRES 0x10
#define BH1750_CONV_MS  180

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

typedef struct {
    int i2c_fd;
    int gpio_pin;
    int buffer[BUFFER_SIZE];
    int buffer_index;
    int buffer_count;
    int lux_read_error;
} AppState;

static AppState g_app_state = {
    .i2c_fd = -1,
    .gpio_pin = GPIO_PIN,
    .buffer_index = 0,
    .buffer_count = 0,
    .lux_read_error = 0,
};

static void app_state_init(AppState *s) {
    memset(s, 0, sizeof(*s));
}

static void app_state_cleanup(AppState *s) {
    if (s->i2c_fd >= 0) {
        close(s->i2c_fd);
        s->i2c_fd = -1;
    }
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
