#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define ON_TIME_MS 500
#define OFF_TIME_MS 500

static volatile sig_atomic_t running = 1;

static void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set DATA_PIN %d as output\n", DATA_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set CLOCK_PIN %d as output\n", CLOCK_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LATCH_PIN %d as output\n", LATCH_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        int bit = (data >> i) & 1;
        if (gpioWrite(DATA_PIN, bit) != 0) {
            fprintf(stderr, "Failed to write DATA_PIN\n");
            return;
        }
        if (gpioWrite(CLOCK_PIN, 1) != 0) {
            fprintf(stderr, "Failed to write CLOCK_PIN\n");
            return;
        }
        gpioDelay(1);
        if (gpioWrite(CLOCK_PIN, 0) != 0) {
            fprintf(stderr, "Failed to write CLOCK_PIN\n");
            return;
        }
        gpioDelay(1);
    }
}

static void display_digit(unsigned char digit) {
    unsigned char pattern[] = {
        0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07
    };
    shift_out(pattern[digit]);
    if (gpioWrite(LATCH_PIN, 1) != 0) {
        fprintf(stderr, "Failed to write LATCH_PIN\n");
    }
    gpioDelay(1);
    if (gpioWrite(LATCH_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write LATCH_PIN\n");
    }
    gpioDelay(1);
}

static void blink_digit(unsigned char digit) {
    display_digit(digit);
    gpioDelay(ON_TIME_MS * 1000);
    if (!running) return;
    display_digit(0x00);
    gpioDelay(OFF_TIME_MS * 1000);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (setup_gpio() != 0) {
        return 1;
    }

    while (running) {
        blink_digit(5);
    }

    gpioWrite(LATCH_PIN, 0);
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioTerminate();
    return 0;
}

