/*
 * blink_button.c — Blink an LED on GPIO17 with a 2-second period.
 * Detect a falling edge on GPIO18 (button press) and exit cleanly.
 *
 * Build:  gcc -O2 -Wall -Wextra -o blink_button blink_button.c -lgpiod
 * Run:    sudo ./blink_button   (or ensure user is in the 'gpio' group)
 */
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN      17
#define BUTTON_PIN   18
#define CHIP_NAME    "gpiochip0"
#define PERIOD_SEC   2
#define POLL_TIMEOUT_SEC 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip --- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* --- Get the LED line (GPIO17) --- */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        perror("gpiod_chip_get_line(LED)");
        goto cleanup;
    }

    /* --- Request LED as output, initially low --- */
    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        perror("gpiod_line_request_output(LED)");
        goto cleanup;
    }

    /* --- Get the button line (GPIO18) --- */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (button_line == NULL) {
        perror("gpiod_chip_get_line(BUTTON)");
        goto cleanup;
    }

    /* --- Request button as input with pull-up and falling-edge events --- */
    if (gpiod_line_request_input_flags(button_line, "blink_button",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP |
                                       GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE) < 0) {
        perror("gpiod_line_request_input_flags(BUTTON)");
        goto cleanup;
    }

    /* --- Main blink loop --- */
    while (g_running) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("gpiod_line_set_value(on)");
            goto cleanup;
        }

        /* Sleep 1 second, but wake early if a signal arrives */
        for (int i = 0; i < PERIOD_SEC && g_running; i++) {
            sleep(1);
        }
        if (!g_running) {
            break;
        }

        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("gpiod_line_set_value(off)");
            goto cleanup;
        }

        /* Sleep 1 second, waking early on signal */
        for (int i = 0; i < PERIOD_SEC && g_running; i++) {
            sleep(1);
        }
        if (!g_running) {
            break;
        }
    }

    /* --- Graceful exit: turn LED off, release lines, close chip --- */
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("gpiod_line_set_value(off) on exit");
    }
    ret = EXIT_SUCCESS;

cleanup:
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

