    /* --- Request button as input with pull-up and falling-edge events --- */
    if (gpiod_line_request_input_flags(button_line, "blink_button",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP |
                                       GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE) < 0) {
        perror("gpiod_line_request_input_flags(BUTTON)");
        goto cleanup;
    }

    /* --- Main blink loop --- */
    while (g_running) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("gpiod_line_set_value(on)");
            goto cleanup;
        }

        /* Sleep 1 second, but wake early if a signal arrives */
        for (int i = 0; i < PERIOD_SEC && g_running; i++) {
            sleep(1);
        }
        if (!g_running) {
            break;
        }

        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("gpiod_line_set_value(off)");
            goto cleanup;
        }

        /* Sleep 1 second, waking early on signal */
        for (int i = 0; i < PERIOD_SEC && g_running; i++) {
            sleep(1);
        }
        if (!g_running) {
            break;
        }
    }

    /* --- Graceful exit: turn LED off, release lines, close chip --- */
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("gpiod_line_set_value(off) on exit");
    }
    ret = EXIT_SUCCESS;

cleanup:
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

