#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define BLINK_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output, initially off */
    ret = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output (code %d).\n", LED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioWrite(LED_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d low (code %d).\n", LED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pin as input with internal pull-down */
    ret = gpioSetMode(BUTTON_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d).\n", BUTTON_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d (code %d).\n", BUTTON_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LED blinking on GPIO%d, button on GPIO%d. Press Ctrl+C to exit.\n",
           LED_PIN, BUTTON_PIN);

    while (running) {
        int button_state = gpioRead(BUTTON_PIN);
        if (button_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d (code %d).\n",
                    BUTTON_PIN, button_state);
            break;
        }

        if (button_state == 1) {
            /* Button pressed: blink LED */
            ret = gpioWrite(LED_PIN, 1);
            if (ret != 0) {
                fprintf(stderr, "Error: failed to turn LED on (code %d).\n", ret);
                break;
            }
            gpioDelay(BLINK_DELAY_US);
            if (!running) break;

            ret = gpioWrite(LED_PIN, 0);
            if (ret != 0) {
                fprintf(stderr, "Error: failed to turn LED off (code %d).\n", ret);
                break;
            }
            gpioDelay(BLINK_DELAY_US);
        } else {
            /* Button released: ensure LED is off */
            ret = gpioWrite(LED_PIN, 0);
            if (ret != 0) {
                fprintf(stderr, "Error: failed to turn LED off on release (code %d).\n", ret);
                break;
            }
            gpioDelay(10000);  /* 10 ms poll interval to reduce CPU usage */
        }
    }

    /* Clean shutdown: turn LED off and release resources */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

