#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_FREQ  100
#define PWM_RANGE 100
#define PWM_DUTY  100

#define CHANGE_INTERVAL_MS 100
#define LOOP_DELAY_MS      1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN,   red) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on RED_PIN %d\n", RED_PIN);
        return -1;
    }
    if (gpioPWM(GREEN_PIN, green) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on GREEN_PIN %d\n", GREEN_PIN);
        return -1;
    }
    if (gpioPWM(BLUE_PIN,  blue) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on BLUE_PIN %d\n", BLUE_PIN);
        return -1;
    }
    return 0;
}

static int generate_random_color(int *red, int *green, int *blue) {
    *red = rand() % (PWM_RANGE + 1);
    *green = rand() % (PWM_RANGE + 1);
    *blue = rand() % (PWM_RANGE + 1);
    return 0;
}

int main(void) {
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(RED_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode failed on RED_PIN %d (ret=%d)\n", RED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetMode(GREEN_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode failed on GREEN_PIN %d (ret=%d)\n", GREEN_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetMode(BLUE_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode failed on BLUE_PIN %d (ret=%d)\n", BLUE_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPWMfrequency(RED_PIN, PWM_FREQ);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed on RED_PIN %d (ret=%d)\n", RED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed on GREEN_PIN %d (ret=%d)\n", GREEN_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed on BLUE_PIN %d (ret=%d)\n", BLUE_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPWMrange(RED_PIN, PWM_RANGE);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed on RED_PIN %d (ret=%d)\n", RED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed on GREEN_PIN %d (ret=%d)\n", GREEN_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMrange(BLUE_PIN, PWM_RANGE);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed on BLUE_PIN %d (ret=%d)\n", BLUE_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPWMdutycycle(RED_PIN, PWM_DUTY);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMdutycycle failed on RED_PIN %d (ret=%d)\n", RED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMdutycycle(GREEN_PIN, PWM_DUTY);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMdutycycle failed on GREEN_PIN %d (ret=%d)\n", GREEN_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMdutycycle(BLUE_PIN, PWM_DUTY);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMdutycycle failed on BLUE_PIN %d (ret=%d)\n", BLUE_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }

    srand((unsigned int)time(NULL));

    while (running) {
        int red, green, blue;
        if (generate_random_color(&red, &green, &blue) != 0) {
            fprintf(stderr, "Error: failed to generate random color\n");
            break;
        }

        if (set_led_color(red, green, blue) != 0) {
            fprintf(stderr, "Error: failed to set LED color\n");
            break;
        }

        struct timespec ts;
        ts.tv_sec = CHANGE_INTERVAL_MS / 1000;
        ts.tv_nsec = (CHANGE_INTERVAL_MS % 1000) * 1000000L;
        nanosleep(&ts, NULL);
    }

    /* Turn off LED and release GPIO lines */
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    gpioTerminate();
    return EXIT_SUCCESS;
}

