#define LSM303_OUT_X_L_A 0x28
#define LSM303_OUT_X_H_A 0x29
#define LSM303_OUT_Y_L_A 0x2A
#define LSM303_OUT_Y_H_A 0x2B
#define LSM303_OUT_Z_L_A 0x2C
#define LSM303_OUT_Z_H_A 0x2D
#define IMPACT_GPIO 17
#define DEFAULT_THRESHOLD 2.0
#define POLL_DELAY_US 100000
#define IMPACT_PULSE_US 50000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, LSM303_OUT_X_L_A, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        return -1;
    }
    int16_t x_raw = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y_raw = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z_raw = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)x_raw / 16384.0f;
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;
    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void log_data(float x, float y, float z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, X: %.3f, Y: %.3f, Z: %.3f\n", ts, x, y, z);
    fclose(fp);
}

static void trigger_impact(int gpio) {
    gpioWrite(gpio, 1);
    gpioDelay(IMPACT_PULSE_US);
    gpioWrite(gpio, 0);
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0.0f) {
            fprintf(stderr, "Error: Threshold must be greater than 0\n");
            return 1;
        }
    }
    printf("Threshold: %.2f G\n", threshold);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X\n", LSM303_ADDR);
        gpioTerminate();
        return 1;
    }

