        fprintf(stderr, "Error: Could not set GPIO%d as output\n", IMPACT_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(IMPACT_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring accelerometer... (Ctrl+C to exit)\n");

    while (!terminate) {
        float x, y, z;
        if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
            float mag = calculate_magnitude(x, y, z);
            if (mag > threshold) {
                printf("Impact detected! Magnitude: %.2f G\n", mag);
                log_data(x, y, z);
                trigger_impact(IMPACT_GPIO);
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nCleaning up...\n");
    gpioWrite(IMPACT_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

