#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LED_GPIO 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 500000
#define ERROR_RETRY_DELAY_US 100000

#define REG_ALS_LSB 0x00
#define REG_ALS_MSB 0x01
#define REG_RED_LSB 0x02
#define REG_RED_MSB 0x03
#define REG_GREEN_LSB 0x04
#define REG_GREEN_MSB 0x05
#define REG_BLUE_LSB 0x06
#define REG_BLUE_MSB 0x07

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int read_sensor_data(int handle, uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t als_lsb, als_msb, red_lsb, red_msb, green_lsb, green_msb, blue_lsb, blue_msb;

    if (read_register(handle, REG_ALS_LSB, &als_lsb) < 0) return -1;
    if (read_register(handle, REG_ALS_MSB, &als_msb) < 0) return -1;
    if (read_register(handle, REG_RED_LSB, &red_lsb) < 0) return -1;
    if (read_register(handle, REG_RED_MSB, &red_msb) < 0) return -1;
    if (read_register(handle, REG_GREEN_LSB, &green_lsb) < 0) return -1;
    if (read_register(handle, REG_GREEN_MSB, &green_msb) < 0) return -1;
    if (read_register(handle, REG_BLUE_LSB, &blue_lsb) < 0) return -1;
    if (read_register(handle, REG_BLUE_MSB, &blue_msb) < 0) return -1;

    *als = ((uint16_t)als_msb << 8) | als_lsb;
    *red = ((uint16_t)red_msb << 8) | red_lsb;
    *green = ((uint16_t)green_msb << 8) | green_lsb;
    *blue = ((uint16_t)blue_msb << 8) | blue_lsb;

    return 0;
}

static int control_led(int gpio, uint16_t als) {
    int duty_cycle = (als * PWM_RANGE) / 65535;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (duty_cycle < 0) duty_cycle = 0;

    if (gpioPWM(gpio, duty_cycle) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Ambient Light,Red,Green,Blue\n");
        fflush(log_file);
    }

    printf("Starting data acquisition. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t als, red, green, blue;

        if (read_sensor_data(i2c_handle, &als, &red, &green, &blue) == 0) {
            control_led(LED_GPIO, als);
            log_data(log_file, als, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();

    return 0;
}

