#define FXOS8700_REG_M_CTRL_REG151 0xF1
#define FXOS8700_REG_M_CTRL_REG152 0xF2
#define FXOS8700_REG_M_CTRL_REG153 0xF3
#define FXOS8700_REG_M_CTRL_REG154 0xF4
#define FXOS8700_REG_M_CTRL_REG155 0xF5
#define FXOS8700_REG_M_CTRL_REG156 0xF6
#define FXOS8700_REG_M_CTRL_REG157 0xF7
#define FXOS8700_REG_M_CTRL_REG158 0xF8
#define FXOS8700_REG_M_CTRL_REG159 0xF9
#define FXOS8700_REG_M_CTRL_REG160 0xFA
#define FXOS8700_REG_M_CTRL_REG161 0xFB
#define FXOS8700_REG_M_CTRL_REG162 0xFC
#define FXOS8700_REG_M_CTRL_REG163 0xFD
#define FXOS8700_REG_M_CTRL_REG164 0xFE
#define FXOS8700_REG_M_CTRL_REG165 0xFF

/* FXOS8700CQ WHO_AM_I value */
#define FXOS8700_WHO_AM_I_VALUE 0xD3

/* Impact threshold (acceleration magnitude in g) */
#define IMPACT_THRESHOLD 0.5

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int initialize_i2c(void);
static int configure_fxos8700(void);
static int read_accelerometer_data(float *x, float *y, float *z);
static float calculate_magnitude(float x, float y, float z);
static int log_impact(float x, float y, float z, float magnitude);
static void signal_handler(int signal);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Initializes the I2C interface using pigpio */
static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Configures the FXOS8700CQ sensor */
static int configure_fxos8700(void) {
    /* Verify WHO_AM_I register */
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700_REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                FXOS8700_WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    /* Put device in standby mode */
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1 (standby)\n");
        return -1;
    }

    /* Configure accelerometer range to +/- 2g (0x00) */
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1 (range)\n");
        return -1;
    }

    /* Configure magnetometer: 80 Hz ODR, +/- 4 gauss, high performance */
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_M_CTRL_REG1, 0x1F) < 0) {
        fprintf(stderr, "Failed to write M_CTRL_REG1\n");
        return -1;
    }

    /* Configure magnetometer: 80 Hz ODR, +/- 4 gauss, high performance */
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_M_CTRL_REG2, 0x20) < 0) {
        fprintf(stderr, "Failed to write M_CTRL_REG2\n");
        return -1;
    }

    /* Configure magnetometer: 80 Hz ODR, +/- 4 gauss, high performance */
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_M_CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Failed to write M_CTRL_REG3\n");
        return -1;
    }

    /* Activate the sensor */
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x08) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1 (activate)\n");
        return -1;
    }

    return 0;
}

/* Reads accelerometer data from the FXOS8700CQ */
static int read_accelerometer_data(float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, FXOS8700_REG_OUT_X_MSB, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read accelerometer data: %d\n", result);
        return -1;
    }

    int16_t x_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t y_raw = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t z_raw = (int16_t)((buffer[4] << 8) | buffer[5]);

    /* Convert to g-force units (sensitivity: 16384 LSB/g for +/- 2g range) */
    *x = (float)x_raw / 16384.0f;
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;

    return 0;
}

/* Calculates the magnitude of the acceleration vector */
static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

/* Logs the impact event to a file */
static int log_impact(float x, float y, float z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open impact_log.txt\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
    return 0;
}

int main(void) {
    /* Set up signal handling for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        return 1;
    }

    /* Configure FXOS8700CQ */
    if (configure_fxos8700() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float x, y, z, magnitude;

    /* Main loop */
    while (program_running) {
        if (read_accelerometer_data(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                if (log_impact(x, y, z, magnitude) != 0) {
                    fprintf(stderr, "Failed to log impact\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        gpioDelay(50000); /* 50 ms delay (microseconds) */
    }

    /* Clean up */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

