#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x18
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0x33
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D
#define TEMP_OUT_L     0x2E
#define TEMP_OUT_H     0x2F
#define TEMP_H_BIT     0x80
#define TEMP_L_MASK    0x80
#define TEMP_OUT       0x30
#define TEMP_OUT_L     0x30
#define TEMP_OUT_H     0x31
#define SAMPLE_RATE    50
#define CALIB_SAMPLES  100
#define ALERT_THRESHOLD 50.0f
#define LOG_FILE       "gyro_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int gyro_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Sensor not present?\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, CTRL_REG4, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, CTRL_REG1, 0x0F) < 0) return -1;
    return 0;
}

static int gyro_read_raw(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static int gyro_read_temp(int fd, float *temp) {
    uint8_t buf[2];
    if (i2c_read_burst(fd, TEMP_OUT_L, buf, 2) < 0) return -1;
    int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
    *temp = (float)raw / 256.0f;
    return 0;
}

static int gyro_calibrate(int fd, float *x_off, float *y_off, float *z_off) {
    int16_t x, y, z;
    float x_sum = 0.0f, y_sum = 0.0f, z_sum = 0.0f;
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        if (gyro_read_raw(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error: failed to read raw data during calibration: %s\n", strerror(errno));
            return -1;
        }
        x_sum += (float)x;
        y_sum += (float)y;
        z_sum += (float)z;
        usleep(10000);
    }
    *x_off = x_sum / CALIB_SAMPLES;
    *y_off = y_sum / CALIB_SAMPLES;
    *z_off = z_sum / CALIB_SAMPLES;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(fp);
}

static void check_alert(float x, float y, float z) {
    if (fabsf(x) > ALERT_THRESHOLD || fabsf(y) > ALERT_THRESHOLD || fabsf(z) > ALERT_THRESHOLD) {
        time_t t = time(NULL);
        struct tm tm;
        localtime_r(&t, &tm);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(stderr, "ALERT: %s - Axis(s) exceeded %.1f dps: X=%.2f Y=%.2f Z=%.2f\n",
                ts, ALERT_THRESHOLD, x, y, z);
        fprintf(log_fp, "ALERT: %s - Axis(s) exceeded %.1f dps: X=%.2f Y=%.2f Z=%.2f\n",
                ts, ALERT_THRESHOLD, x, y, z);
        fflush(log_fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave address 0x%02X: %s\n", GYRO_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (gyro_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: gyroscope initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;
    if (gyro_calibrate(i2c_fd, &x_off, &y_off, &z_off) < 0) {
        fprintf(stderr, "Error: gyroscope calibration failed.\n");
        fclose(log_fp);
        close(i2c_fd);
        return 1;
    }
    printf("Calibration complete. Offsets: X=%.2f Y=%.2f Z=%.2f\n", x_off, y_off, z_off);

    while (running) {
        int16_t raw_x, raw_y, raw_z;
        float temp;
        if (gyro_read_raw(i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Error: failed to read gyro data: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }
        if (gyro_read_temp(i2c_fd, &temp) < 0) {
            fprintf(stderr, "Error: failed to read temperature: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }
        float x = (float)raw_x - x_off;
        float y = (float)raw_y - y_off;
        float z = (float)raw_z - z_off;
        log_data(log_fp, x, y, z);
        check_alert(x, y, z);
        usleep(50000);
    }

    printf("\nShutting down cleanly...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

