#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (ADDR pin tied to GND) */
#define ADXL345_ADDRESS 0x32

/* ADXL345 register addresses */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID_VAL   0xE5

/* GPIO pin for the LED (BCM numbering) */
#define LED_PIN 17

/* Sampling interval in microseconds (100 ms = 10 Hz) */
#define SAMPLE_INTERVAL_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an ADXL345 register                        */
/* Returns 0 on success (stores value in *out), -1 on error           */
/* ------------------------------------------------------------------ */
static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error on reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an ADXL345 register                         */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int adxl345_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error on reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345: verify device ID, configure full-res mode   */
/* with ±2 g range, then start measurement                           */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Read and verify device ID */
    if (adxl345_read_reg(handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Failed to read DEVID register\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X)\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }

    /* Standby mode first so configuration changes take effect */
    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Full-resolution mode (0x08) | ±2 g range (0x08) -> 0x10 */
    if (adxl345_write_reg(handle, ADXL345_DATA_FORMAT, 0x10) != 0)
        return -1;

    /* Start measurement: 0x08 | 0x02 = 0x0A */
    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, 0x0A) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (g-units) from the ADXL345                      */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int adxl345_read_acceleration(int handle, float *x, float *y, float *z)
{
    char raw[6];
    int16_t x_raw, y_raw, z_raw;

    /* Burst-read 6 bytes starting at DATAX0 (0x32) */
    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, raw, 6) != 6) {
        fprintf(stderr, "I2C block read error\n");
        return -1;
    }

    x_raw = (int16_t)(((uint8_t)raw[1] << 8) | (uint8_t)raw[0]);
    y_raw = (int16_t)(((uint8_t)raw[3] << 8) | (uint8_t)raw[2]);
    z_raw = (int16_t)(((uint8_t)raw[5] << 8) | (uint8_t)raw[4]);

    /* Full-resolution mode: 4 mg/LSB → 0.004 g/LSB */
    *x = (float)x_raw * 0.004f;
    *y = (float)y_raw * 0.004f;
    *z = (float)z_raw * 0.004f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV line to the log file                                */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure LED is off */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    float x, y, z;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- ADXL345 init --- */
    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* --- Log file --- */
    g_log_file = fopen("accel_log.txt", "a");
    if (g_log_file == NULL) {
        perror("fopen(accel_log.txt)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 logging started (10 Hz). Press Ctrl+C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        if (adxl345_read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);

            /* LED on when any axis exceeds 2.0 g */
            int led_on = (fabsf(x) > 2.0f ||
                          fabsf(y) > 2.0f ||
                          fabsf(z) > 2.0f);
            gpioWrite(LED_PIN, led_on ? 1 : 0);
        } else {
            /* On read failure, turn LED off for safety */
            gpioWrite(LED_PIN, 0);
        }

        /* Sleep 100 ms (pigpio delay is microseconds) */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

