#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* LSM303DLHC register addresses */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03

/* Sensitivity scales */
#define ACCEL_SCALE 0.000061f  /* 0.061 mg/LSB -> 0.000061 g/LSB */
#define MAG_SCALE   0.00014f   /* 0.14 mGauss/LSB -> 0.00014 G */

/* Tilt compensation */
#define ACCEL_SENSITIVITY (1.0f / ACCEL_SCALE)
#define MAG_SENSITIVITY  (1.0f / MAG_SCALE)

static volatile sig_atomic_t running = 1;
static int accel_handle = -1;
static int mag_handle   = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read error: reg=0x%02X, expected=%u, got=%d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, val=0x%02X, rc=%d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

static int init_lsm303(void) {
    accel_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Failed to open accelerometer (0x%02X): %d\n",
                LSM303_ACCEL_ADDR, accel_handle);
        return -1;
    }

    mag_handle = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Failed to open magnetometer (0x%02X): %d\n",
                LSM303_MAG_ADDR, mag_handle);
        i2cClose(accel_handle);
        accel_handle = -1;
        return -1;
    }

    /* Accelerometer: enable XYZ axes, 119 Hz ODR, normal mode */
    if (i2c_write_reg(accel_handle, LSM303_ACCEL_CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Failed to configure accelerometer\n");
        return -1;
    }

    /* Magnetometer: continuous-conversion mode */
    if (i2c_write_reg(mag_handle, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to configure magnetometer\n");
        return -1;
    }

    return 0;
}

static int read_accel(float *ax, float *ay, float *az) {
    uint8_t buf[6];
    if (i2c_read_reg(accel_handle, LSM303_ACCEL_OUT_X_L_A, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *ax = (float)raw_x * ACCEL_SENSITIVITY;
    *ay = (float)raw_y * ACCEL_SENSITIVITY;
    *az = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

static int read_mag(float *mx, float *my, float *mz) {
    uint8_t buf[6];
    if (i2c_read_reg(mag_handle, LSM303_MAG_OUT_X_H_M, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_z = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_y = (int16_t)((buf[4] << 8) | buf[5]);

    *mx = (float)raw_x * MAG_SENSITIVITY;
    *mz = (float)raw_z * MAG_SENSITIVITY;
    *my = (float)raw_y * MAG_SENSITIVITY;
    return 0;
}

static float calc_heading(float ax, float ay, float az,
                          float mx, float my, float mz) {
    float roll = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));

    float mx_c = mx * cosf(pitch) + mz * sinf(pitch);
    float my_c = mx * sinf(roll) * sinf(pitch) +
                 my * cosf(roll) -
                 mz * sinf(roll) * cosf(pitch);

    float heading = atan2f(my_c, mx_c) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

static int log_data(float heading, float ax, float ay, float az,
                    float mx, float my, float mz) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0)
        fprintf(fp, "timestamp,heading_deg,ax_g,ay_g,az_g,mx_G,my_G,mz_G\n");

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            ts, heading, ax, ay, az, mx, my, mz);

    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_lsm303() < 0) {
        fprintf(stderr, "LSM303 initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LSM303 compass running. Press Ctrl+C to stop.\n");

    while (running) {
        float ax, ay, az, mx, my, mz;

        if (read_accel(&ax, &ay, &az) < 0) {
            fprintf(stderr, "Accelerometer read failed; continuing\n");
            gpioDelay(100000);
            continue;
        }
        if (read_mag(&mx, &my, &mz) < 0) {
            fprintf(stderr, "Magnetometer read failed; continuing\n");
            gpioDelay(100000);
            continue;
        }

        float heading = calc_heading(ax, ay, az, mx, my, mz);

        if (log_data(heading, ax, ay, az, mx, my, mz) < 0)
            fprintf(stderr, "Logging failed\n");

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    if (accel_handle >= 0) i2cClose(accel_handle);
    if (mag_handle >= 0)   i2cClose(mag_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

