#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR_1 0x33
#define I2C_ADDR_2 0x34
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_audio_sample(int handle, int16_t *sample) {
    char buffer[2];
    int bytes_read = i2cReadDevice(handle, buffer, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading audio sample from handle %d: %s\n", handle, strerror(errno));
        return -1;
    }
    *sample = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

static double calculate_tdoa(int16_t sample1, int16_t sample2) {
    int16_t diff = (int16_t)(sample2 - sample1);
    return (double)diff / 32768.0;
}

static int log_data(double timestamp, int16_t sample1, int16_t sample2, double tdoa) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(log_file, "%ld.%09ld,%d,%d,%.6f\n",
                (long)ts.tv_sec, ts.tv_nsec, sample1, sample2, tdoa) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle_1 >= 0) {
        i2cClose(i2c_handle_1);
        i2c_handle_1 = -1;
    }
    if (i2c_handle_2 >= 0) {
        i2cClose(i2c_handle_2);
        i2c_handle_2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle_1 = i2cOpen(I2C_BUS, I2C_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error opening I2C device 1 (addr 0x%02X): %s\n", I2C_ADDR_1, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, I2C_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error opening I2C device 2 (addr 0x%02X): %s\n", I2C_ADDR_2, strerror(errno));
        i2cClose(i2c_handle_1);
        i2c_handle_1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle_1);
        i2c_handle_1 = -1;
        i2cClose(i2c_handle_2);
        i2c_handle_2 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting audio TDOA measurement. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t sample1 = 0, sample2 = 0;
        int ret1 = read_audio_sample(i2c_handle_1, &sample1);
        int ret2 = read_audio_sample(i2c_handle_2, &sample2);

        if (ret1 != 0 || ret2 != 0) {
            fprintf(stderr, "Error reading audio samples, skipping sample.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        struct timespec timestamp;
        if (clock_gettime(CLOCK_REALTIME, &timestamp) != 0) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double tdoa = calculate_tdoa(sample1, sample2);

        if (log_data(timestamp, sample1, sample2, tdoa) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCaught signal, cleaning up...\n");
    cleanup();
    return EXIT_SUCCESS;
}

