        fp = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_read_register(uint8_t reg, int16_t *value) {
    char tx[2], rx[2];
    tx[0] = (char)(reg & 0x7F);
    tx[1] = 0x00;
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = (int16_t)(((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[0]);
    return 0;
}

static int spi_write_register(uint8_t reg, uint16_t value) {
    char tx[2], rx[2];
    tx[0] = (char)(reg | 0x80);
    tx[1] = (char)(value & 0xFF);
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gx, raw_gy, raw_gz, raw_ax, raw_ay, raw_az;

    if (spi_read_register(0x04, &raw_gx) != 0) return -1;
    if (spi_read_register(0x06, &raw_gy) != 0) return -1;
    if (spi_read_register(0x08, &raw_gz) != 0) return -1;
    if (spi_read_register(0x0A, &raw_ax) != 0) return -1;
    if (spi_read_register(0x0C, &raw_ay) != 0) return -1;
    if (spi_read_register(0x0E, &raw_az) != 0) return -1;

    *gyro_x = (float)raw_gx * GYRO_SENS;
    *gyro_y = (float)raw_gy * GYRO_SENS;
    *gyro_z = (float)raw_gz * GYRO_SENS;
    *accel_x = (float)raw_ax * ACCEL_SENS;
    *accel_y = (float)raw_ay * ACCEL_SENS;
    *accel_z = (float)raw_az * ACCEL_SENS;

    return 0;
}

static void log_data(float gx, float gy, float gz,
                     float ax, float ay, float az) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tm_buf[32];
    strftime(tm_buf, sizeof(tm_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            tm_buf, ts.tv_nsec / 1000000, gx, gy, gz, ax, ay, az);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz, mode %d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    atexit(cleanup);

    printf("Starting ADIS16488A IMU data logging. Press Ctrl+C to stop.\n");

    while (running) {
        float gx, gy, gz, ax, ay, az;
        if (read_imu_data(&gx, &gy, &gz, &ax, &ay, &az) == 0) {
            log_data(gx, gy, gz, ax, ay, az);
        } else {
            fprintf(stderr, "Error reading IMU data, skipping sample.\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

