#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

/* ADIS16448 SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0
#define SPI_CE0    8        /* BCM GPIO8 */

/* ADIS16448 Register Addresses (16-bit, bit15=1 for read) */
#define ADIS16448_REG_GYRO_XOUT  0x04
#define ADIS16448_REG_GYRO_YOUT  0x06
#define ADIS16448_REG_GYRO_ZOUT  0x08
#define ADIS16448_REG_ACCEL_XOUT 0x0A
#define ADIS16448_REG_ACCEL_YOUT 0x0C
#define ADIS16448_REG_ACCEL_ZOUT 0x0E

/* Scaling factors from ADIS16448 datasheet */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCEL_SCALE 0.00025f /* g per LSB */

/* Stall time between the two SPI cycles (at least 40 µs) */
#define STALL_US  40

/* Read interval in microseconds */
#define READ_INTERVAL_US 100000

/* Global SPI handle for signal handler */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit register from the ADIS16448.
 * The first 16-bit transfer sends the register address with bit15 set.
 * After a stall, the second 16-bit transfer sends a dummy value to clock
 * out the data.  The data is returned in the second transfer's rx_buf[1].
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int read_register16(uint8_t reg, int16_t *value) {
    char tx_cmd[2] = { (char)(reg | 0x80), 0x00 };
    char rx_cmd[2] = { 0 };
    char tx_dummy[2] = { 0x00, 0x00 };
    char rx_data[2] = { 0 };

    /* First transfer: send read command */
    if (spiXfer(spi_handle, tx_cmd, rx_cmd, 2) != 2) {
        fprintf(stderr, "SPI read command transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    /* Stall between transfers (datasheet: >= 40 µs) */
    gpioDelay(STALL_US);

    /* Second transfer: dummy to clock out data */
    if (spiXfer(spi_handle, tx_dummy, rx_data, 2) != 2) {
        fprintf(stderr, "SPI data read transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    /* Data is in rx_data[1] (low byte) and rx_data[0] (high byte) */
    *value = (int16_t)(((uint16_t)(uint8_t)rx_data[0] << 8) | (uint8_t)rx_data[1]);
    return 0;
}

/*
 * Read all six sensor axes.
 * Returns 0 on success, -1 on any SPI transfer failure.
 */
static int read_all_axes(float *gx, float *gy, float *gz,
                         float *ax, float *ay, float *az) {
    int16_t raw_gx, raw_gy, raw_gz, raw_ax, raw_ay, raw_az;

    if (read_register16(ADIS16448_REG_GYRO_XOUT, &raw_gx) != 0) return -1;
    if (read_register16(ADIS16448_REG_GYRO_YOUT, &raw_gy) != 0) return -1;
    if (read_register16(ADIS16448_REG_GYRO_ZOUT, &raw_gz) != 0) return -1;
    if (read_register16(ADIS16448_REG_ACCEL_XOUT, &raw_ax) != 0) return -1;
    if (read_register16(ADIS16448_REG_ACCEL_YOUT, &raw_ay) != 0) return -1;
    if (read_register16(ADIS16448_REG_ACCEL_ZOUT, &raw_az) != 0) return -1;

    *gx = (float)raw_gx * GYRO_SCALE;
    *gy = (float)raw_gy * GYRO_SCALE;
    *gz = (float)raw_gz * GYRO_SCALE;
    *ax = (float)raw_ax * ACCEL_SCALE;
    *ay = (float)raw_ay * ACCEL_SCALE;
    *az = (float)raw_az * ACCEL_SCALE;

    return 0;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel: CE0, 1 MHz, Mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADIS16448 IMU Reader (SPI0, CE0, 1 MHz, Mode 0)\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        float gx, gy, gz, ax, ay, az;

        if (read_all_axes(&gx, &gy, &gz, &ax, &ay, &az) == 0) {
            printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f deg/s | "
                   "Accel: X=%.4f, Y=%.4f, Z=%.4f g\n",
                   gx, gy, gz, ax, ay, az);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(READ_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

