#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MPU-6886 I2C address (AD0 tied to GND) */
#define MPU6886_ADDR 0x68

/* MPU-6886 register addresses */
#define MPU6886_REG_SMPLRT_DIV   0x19
#define MPU6886_REG_PWR_MGMT_1   0x6B
#define MPU6886_REG_GYRO_CONFIG  0x1B
#define MPU6886_REG_ACCEL_CONFIG 0x1C
#define MPU6886_REG_ACCEL_XOUT_H 0x2D
#define MPU6886_REG_GYRO_XOUT_H  0x33

/* Scaling factors for default ±250 dps / ±2 g range */
#define ACCEL_SCALE 16384.0f
#define GYRO_SCALE  131.0f

#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_PERIOD_MS 50
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd bytes, expected %zu: %s\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6886(int fd) {
    /* Wake up: clear SLEEP bit, use internal 8 MHz oscillator */
    if (i2c_write_reg(fd, MPU6886_REG_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);

    /* Gyro: ±250 dps, 1 kHz ODR (0x00) */
    if (i2c_write_reg(fd, MPU6886_REG_GYRO_CONFIG, 0x00) < 0) return -1;

    /* Accel: ±2 g, 1 kHz ODR (0x00) */
    if (i2c_write_reg(fd, MPU6886_REG_ACCEL_CONFIG, 0x00) < 0) return -1;

    /* Sample rate divider: 1 kHz / (1 + 7) = 125 Hz → 0x07 */
    if (i2c_write_reg(fd, MPU6886_REG_SMPLRT_DIV, 0x07) < 0) return -1;

    return 0;
}

static int read_accel(int fd, float *ax, float *ay, float *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6886_REG_ACCEL_XOUT_H, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *ax = (float)raw_x / ACCEL_SCALE;
    *ay = (float)raw_y / ACCEL_SCALE;
    *az = (float)raw_z / ACCEL_SCALE;
    return 0;
}

static int read_gyro(int fd, float *gx, float *gy, float *gz) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6886_REG_GYRO_XOUT_H, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (float)raw_x / GYRO_SCALE;
    *gy = (float)raw_y / GYRO_SCALE;
    *gz = (float)raw_z / GYRO_SCALE;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPU6886_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (init_mpu6886(fd) < 0) {
        fprintf(stderr, "MPU-6886 initialization failed (sensor absent or bus error).\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6886 initialized. Reading every %d ms. Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_MS);

    while (g_running) {
        float ax, ay, az, gx, gy, gz;
        bool ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_accel(fd, &ax, &ay, &az) == 0 &&
                read_gyro(fd, &gx, &gy, &gz) == 0) {
                ok = true;
                break;
            }
            usleep(10000);
        }

        if (ok) {
            printf("Accel: X=%+7.2f  Y=%+7.2f  Z=%+7.2f  g  Gyro: X=%+7.2f  Y=%+7.2f  Z=%+7.2f  dps\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d attempts.\n", MAX_RETRIES);
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return EXIT_SUCCESS;
}

