#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (SA0 tied to GND) */
#define ADXL345_ADDRESS 0x32

/* ADXL345 register addresses */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID_VAL   0x33

/* Full resolution, +/- 2g range */
#define ADXL345_RANGE_2G    0x00

/* GPIO pin for the LED (BCM numbering) */
#define LED_PIN 17

/* Impact threshold in g */
#define IMPACT_THRESHOLD 2.5f

/* Polling interval in microseconds */
#define POLL_INTERVAL_US 10000

/* LED on-time in microseconds */
#define LED_ON_TIME_US 500000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — just set the flag; cleanup happens in main()      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register; returns 0 on success, -1 on  */
/* failure.                                                          */
/* ------------------------------------------------------------------ */
static int adxl_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): rc=%d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register; returns 0 on success, -1 on */
/* failure.                                                          */
/* ------------------------------------------------------------------ */
static int adxl_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345: verify device ID, configure full-res +/-2g,  */
/* and enable measurement mode.                                       */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Read the device ID register */
    if (adxl_read_reg(handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read DEVID — sensor absent or bus error.\n");
        return -1;
    }

    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X).\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }

    /* Set full resolution, +/- 2g range */
    if (adxl_write_reg(handle, ADXL345_DATA_FORMAT, ADXL345_RANGE_2G) != 0)
        return -1;

    /* Standby -> measurement mode */
    if (adxl_write_reg(handle, ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data and convert to g.                */
/* ------------------------------------------------------------------ */
static int adxl345_read_acceleration(int handle, float *x, float *y, float *z)
{
    char raw[6];
    int16_t x_raw, y_raw, z_raw;

    /* Read 6 bytes starting at DATAX0 (0x32) */
    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, raw, 6) != 6) {
        fprintf(stderr, "I2C block read failed.\n");
        return -1;
    }

    x_raw = (int16_t)(((uint8_t)raw[1] << 8) | (uint8_t)raw[0]);
    y_raw = (int16_t)(((uint8_t)raw[3] << 8) | (uint8_t)raw[2]);
    z_raw = (int16_t)(((uint8_t)raw[5] << 8) | (uint8_t)raw[4]);

    /* Full resolution, +/- 2g range -> 256 LSB per g */
    *x = (float)x_raw / 256.0f;
    *y = (float)y_raw / 256.0f;
    *z = (float)z_raw / 256.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute the magnitude of the acceleration vector.                  */
/* ------------------------------------------------------------------ */
static float adxl345_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped impact record to the log file.                */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float magnitude)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed.\n");
        return;
    }

    if (fprintf(g_log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g, Magnitude: %.3f g\n",
                timestamp, x, y, z, magnitude) < 0) {
        fprintf(stderr, "fprintf to log failed.\n");
        return;
    }

