#include <pigpio.h>

/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x53

/* ICM-20602 register addresses */
#define REG_BANK_SEL   0x7F
#define REG_PWR_MGMT_1 0x06
#define REG_USER_CTRL  0x03
#define REG_LP_CONFIG  0x05
#define REG_INT_PIN_CFG 0x0F
#define REG_ACCEL_XOUT_H 0x2D
#define REG_GYRO_XOUT_H  0x33

/* User control register bits */
#define USER_CTRL_GYRO_EN 0x01
#define USER_CTRL_ACCEL_EN 0x02

/* Bank selection register bits */
#define BANK_SEL_ACCEL  0x00
#define BANK_SEL_GYRO   0x01
#define BANK_SEL_TEMP   0x02
#define BANK_SEL_EXT_SENS 0x03

/* Global variables */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int init_icm20602(void);
static int read_imu_data(int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz);
static void log_data(int16_t ax, int16_t ay, int16_t az,
                     int16_t gx, int16_t gy, int16_t gz);
static void signal_handler(int signal);
static void cleanup(void);

int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x53 */
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ICM-20602 */
    if (init_icm20602() != 0) {
        fprintf(stderr, "Error: ICM-20602 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open imu_log.csv\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop: read and log data at 10 Hz */
    while (!terminate) {
        if (read_imu_data(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: I2C read failed, skipping sample\n");
        }
        gpioDelay(100000); /* 100 ms delay (microseconds) */
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* Initialize ICM-20602: enable accelerometer and gyroscope */
static int init_icm20602(void)
{
    /* Set bank to accelerometer (default bank) */
    if (i2cWriteByteData(i2c_handle, REG_BANK_SEL, BANK_SEL_ACCEL) < 0) {
        fprintf(stderr, "Error: Failed to set bank to accelerometer\n");
        return -1;
    }

    /* Wake up device: clear sleep bit in PWR_MGMT_1 */
    if (i2cWriteByteData(i2c_handle, REG_PWR_MGMT_1, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to wake up ICM-20602\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay after wake-up */

    /* Enable accelerometer and gyroscope in USER_CTRL */
    if (i2cWriteByteData(i2c_handle, REG_USER_CTRL, USER_CTRL_ACCEL_EN | USER_CTRL_GYRO_EN) < 0) {
        fprintf(stderr, "Error: Failed to enable accelerometer/gyroscope\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer and gyroscope data (burst read) */
static int read_imu_data(int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buf[12];
    int result;

    /* Read 12 bytes starting from ACCEL_XOUT_H (0x2D) */
    result = i2cReadI2CBlockData(i2c_handle, REG_ACCEL_XOUT_H, buf, 12);
    if (result != 12) {
        fprintf(stderr, "Error: I2C block read failed (returned %d)\n", result);
        return -1;
    }

    /* Accelerometer data: high and low bytes */
    *ax = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    /* Gyroscope data: high and low bytes */
    *gx = (int16_t)((buf[6] << 8) | (uint8_t)buf[7]);
    *gy = (int16_t)((buf[8] << 8) | (uint8_t)buf[9]);
    *gz = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);

    return 0;
}

/* Log data to CSV file with timestamp */
static void log_data(int16_t ax, int16_t ay, int16_t az,
                     int16_t gx, int16_t gy, int16_t gz)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d\n",
            timestamp, ax, ay, az, gx, gy, gz);
    fflush(log_file); /* Ensure data is written to disk immediately */
}

/* Signal handler for Ctrl+C */
static void signal_handler(int signal)
{
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

