    *ay = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    /* Gyroscope data: high and low bytes */
    *gx = (int16_t)((buf[6] << 8) | (uint8_t)buf[7]);
    *gy = (int16_t)((buf[8] << 8) | (uint8_t)buf[9]);
    *gz = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);

    return 0;
}

/* Log data to CSV file with timestamp */
static void log_data(int16_t ax, int16_t ay, int16_t az,
                     int16_t gx, int16_t gy, int16_t gz)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d\n",
            timestamp, ax, ay, az, gx, gy, gz);
    fflush(log_file); /* Ensure data is written to disk immediately */
}

/* Signal handler for Ctrl+C */
static void signal_handler(int signal)
{
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

