    int who_am_i = i2cReadByteData(i2c_handle, MMA8451Q_REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register (I2C error %d)\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x5A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X (expected 0x5A)\n", who_am_i);
        return -1;
    }

    /* Reset the device */
    if (i2cWriteByteData(i2c_handle, MMA8451Q_REG_CTRL_REG5, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to reset MMA8451Q\n");
        return -1;
    }
    gpioDelay(10000); /* 10ms delay for reset to complete */

    /* Set range to +/- 2g (0x00) */
    if (i2cWriteByteData(i2c_handle, MMA8451Q_REG_CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set range\n");
        return -1;
    }

    /* Set full scale to +/- 2g (0x00) */
    if (i2cWriteByteData(i2c_handle, MMA8451Q_REG_CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set full scale\n");
        return -1;
    }

    /* Set accelerometer mode to 100Hz (0x00) */
    if (i2cWriteByteData(i2c_handle, MMA8451Q_REG_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set accelerometer mode\n");
        return -1;
    }

    /* Enable accelerometer (0x01) */
    if (i2cWriteByteData(i2c_handle, MMA8451Q_REG_CTRL_REG2, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to enable accelerometer\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer data from the MMA8451Q */
static int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    /* Read 6 bytes starting from OUT_X_MSB (0x01) */
    if (i2cReadI2CBlockData(i2c_handle, MMA8451Q_REG_OUT_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        return -1;
    }

    /* Combine MSB and LSB for each axis */
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

/* Calculate the magnitude of the acceleration vector */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / SENSITIVITY;
    float y_g = (float)y / SENSITIVITY;
    float z_g = (float)z / SENSITIVITY;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

