#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SDO tied to GND) */
#define LSM6DSR_ADDR 0x19

/* LSM6DSR register addresses */
#define WHO_AM_I       0x0F
#define CTRL1_XL       0x10
#define CTRL2_G        0x11
#define OUTX_L_G       0x22
#define OUTX_L_XL      0x28

/* Expected device ID */
#define LSM6DSR_WHO_AM_I 0x33

/* Sensitivity values for ±2g and ±250dps */
#define ACCEL_SENSITIVITY 0.061f   /* mg/LSB at ±2g */
#define GYRO_SENSITIVITY  8.75f    /* mdps/LSB at ±250dps */

/* Fall detection thresholds */
#define FALL_ACCEL_THRESHOLD 0.2f   /* g */
#define IMPACT_ACCEL_THRESHOLD 2.5f  /* g */
#define FALL_TIME_WINDOW 1.0f      /* seconds */

/* Sampling interval */
#define SAMPLE_INTERVAL_US 10000   /* 100 Hz */

/* Global state for signal handler */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a single byte to an I2C register */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    return i2cWriteDevice(handle, buf, 2);
}

/* Read N bytes from an I2C register */
static int i2c_read_regs(int handle, uint8_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        return -1;
    }
    return i2cReadDevice(handle, (char *)buf, len);
}

/* Initialize the LSM6DSR sensor */
static int init_lsm6dsr(int handle) {
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (i2c_read_regs(handle, WHO_AM_I, &who_am_i, 1) != 1) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who_am_i, LSM6DSR_WHO_AM_I);
        return -1;
    }

    /* Configure accelerometer: 104 Hz ODR, ±2g full-scale */
    if (i2c_write_reg(handle, CTRL1_XL, 0x60) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL1_XL.\n");
        return -1;
    }

    /* Configure gyroscope: 104 Hz ODR, ±250dps full-scale */
    if (i2c_write_reg(handle, CTRL2_G, 0x60) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL2_G.\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer and gyroscope data */
static int read_sensor_data(int handle, float *ax, float *ay, float *az,
                            float *gx, float *gy, float *gz) {
    uint8_t buf[12];
    int16_t raw_ax, raw_ay, raw_az, raw_gx, raw_gy, raw_gz;

    /* Read 6 bytes of accelerometer data starting at OUTX_L_XL (auto-increment) */
    if (i2c_read_regs(handle, OUTX_L_XL, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data.\n");
        return -1;
    }

    /* Read 6 bytes of gyroscope data starting at OUTX_L_G (auto-increment) */
    if (i2c_read_regs(handle, OUTX_L_G, buf + 6, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data.\n");
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    raw_ax = (int16_t)((buf[1] << 8) | buf[0]);
    raw_ay = (int16_t)((buf[3] << 8) | buf[2]);
    raw_az = (int16_t)((buf[5] << 8) | buf[4]);
    raw_gx = (int16_t)((buf[7] << 8) | buf[6]);
    raw_gy = (int16_t)((buf[9] << 8) | buf[8]);
    raw_gz = (int16_t)((buf[11] << 8) | buf[10]);

    /* Convert to g and dps */
    *ax = (float)raw_ax * ACCEL_SENSITIVITY / 1000.0f;
    *ay = (float)raw_ay * ACCEL_SENSITIVITY / 1000.0f;
    *az = (float)raw_az * ACCEL_SENSITIVITY / 1000.0f;
    *gx = (float)raw_gx * GYRO_SENSITIVITY / 1000.0f;
    *gy = (float)raw_gy * GYRO_SENSITIVITY / 1000.0f;
    *gz = (float)raw_gz * GYRO_SENSITIVITY / 1000.0f;

    return 0;
}

/* Log data to CSV file */
static int log_data(FILE *fp, float ax, float ay, float az,
                    float gx, float gy, float gz) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    if (fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                (long)ts.tv_sec, ts.tv_nsec,
                ax, ay, az, gx, gy, gz) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* Fall detection state machine */
static void fall_detection(float ax, float ay, float az) {
    static struct timespec fall_start_time = {0, 0};
    static int in_freefall = 0;
    static int impact_detected = 0;

    float accel_magnitude = sqrtf(ax * ax + ay * ay + az * az);

    if (accel_magnitude < FALL_ACCEL_THRESHOLD) {
        if (!in_freefall) {
            in_freefall = 1;
            impact_detected = 0;
            fall_start_time = (struct timespec){0, 0};
        }
    } else {
        if (in_freefall) {
            in_freefall = 0;
            if (accel_magnitude > IMPACT_ACCEL_THRESHOLD && !impact_detected) {
                impact_detected = 1;
                printf("Impact detected!\n");
            }
        }
    }

    if (impact_detected) {
        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);
        double elapsed = (current_time.tv_sec - fall_start_time.tv_sec)
                       + (current_time.tv_nsec - fall_start_time.tv_nsec) / 1e9;

        if (elapsed > FALL_TIME_WINDOW) {
            printf("Fall detected!\n");
            impact_detected = 0;
        }
    }
}

int main(void) {
    /* Initialize pigpio */
