    if (init_lsm6dsr(i2c_handle) != 0) {
        fprintf(stderr, "Error: LSM6DSR initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("motion_log.txt", "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    if (fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n") < 0) {
        perror("Error writing CSV header");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
    }

    printf("LSM6DSR logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (running) {
        float ax, ay, az, gx, gy, gz;

        if (read_sensor_data(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            if (log_data(log_file, ax, ay, az, gx, gy, gz) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
            fall_detection(ax, ay, az);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

