#include <pigpio.h>

/* L3G4200D I2C address (SA0 tied to GND) */
#define GYRO_ADDR 0x18

/* L3G4200D register addresses */
#define WHO_AM_I   0x0F
#define CTRL_REG1  0x20
#define CTRL_REG4  0x23
#define OUT_X_L    0x28
#define OUT_X_H    0x29
#define OUT_Y_L    0x2A
#define OUT_Y_H    0x2B
#define OUT_Z_L    0x2C
#define OUT_Z_H    0x2D

/* Expected WHO_AM_I value for L3G4200D */
#define GYRO_WHO_AM_I_VAL 0x03

/* CTRL_REG1: ODR=100Hz (0x57) | temp off | all axes enabled */
#define CTRL_REG1_VAL 0x57
/* CTRL_REG4: FS=00 (±250 mdps) | no high-pass filter */
#define CTRL_REG4_VAL 0x00

/* Sensitivity: 8.75 mdps/LSB for ±250 mdps range */
#define SENSITIVITY 8.75f

#define I2C_BUS 1
#define LOG_FILE "gyro_log.csv"
#define SAMPLE_INTERVAL_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(1000);
    }
    return -1;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *value = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(1000);
    }
    return -1;
}

static int gyro_init(int handle) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg(handle, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != GYRO_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, GYRO_WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(handle, CTRL_REG1, CTRL_REG1_VAL) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        return -1;
    }
    if (i2c_write_reg(handle, CTRL_REG4, CTRL_REG4_VAL) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int gyro_read(int handle, float *x, float *y, float *z) {
    uint8_t xl, xh, yl, yh, zl, zh;
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg(handle, OUT_X_L, &xl) != 0) return -1;
    if (i2c_read_reg(handle, OUT_X_H, &xh) != 0) return -1;
    if (i2c_read_reg(handle, OUT_Y_L, &yl) != 0) return -1;
    if (i2c_read_reg(handle, OUT_Y_H, &yh) != 0) return -1;
    if (i2c_read_reg(handle, OUT_Z_L, &zl) != 0) return -1;
    if (i2c_read_reg(handle, OUT_Z_H, &zh) != 0) return -1;

    raw_x = (int16_t)((xh << 8) | xl);
    raw_y = (int16_t)((yh << 8) | yl);
    raw_z = (int16_t)((zh << 8) | zl);

    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%09ld,%.3f,%.3f,%.3f\n",
            (long)ts.tv_sec, ts.tv_nsec, x, y, z);
    fflush(fp);
}

int main(void) {
    float x, y, z;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, GYRO_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gyro_init(i2c_handle) != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
    }

    printf("Logging gyroscope data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        if (gyro_read(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

