    int ret = EXIT_FAILURE;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLAME_SENSOR_GPIO);
        goto cleanup_gpio;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", FLAME_SENSOR_GPIO);
        goto cleanup_gpio;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        goto cleanup_gpio;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", FLAME_SENSOR_GPIO);

    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading GPIO%d: %s\n", FLAME_SENSOR_GPIO, pigpio_error(sensor_value));
            if (log_event(log_file, "ERROR: Sensor read failure") != 0) {
                fprintf(stderr, "Failed to log sensor read error\n");
