            if (log_event(log_file, "Flame detected: NO") != 0) {
                fprintf(stderr, "Failed to log flame non-detection event\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

