#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x14
#define LOG_FILE       "vibration_log.csv"
#define SAMPLE_DELAY_US 100000  /* 100 ms */

/* Omron D7S-0001: 16-bit registers, little-endian on the bus */
#define REG_X_LSB       0x02
#define REG_X_MSB       0x03
#define REG_Y_LSB       0x04
#define REG_Y_MSB       0x05
#define REG_Z_LSB       0x06
#define REG_Z_MSB       0x07

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit little-endian register pair.
 * Returns 0 on success, -1 on error.
 */
static int read_axis(int fd, uint8_t reg_lsb, uint8_t reg_msb, int16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg_lsb, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg_lsb, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg_lsb, strerror(errno));
        return -1;
    }
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

static int read_sensor(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (read_axis(fd, REG_X_LSB, REG_X_MSB, x) != 0)
        return -1;
    if (read_axis(fd, REG_Y_LSB, REG_Y_MSB, y) != 0)
        return -1;
    if (read_axis(fd, REG_Z_LSB, REG_Z_MSB, z) != 0)
        return -1;
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SENSOR_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "Timestamp,X,Y,Z\n") < 0 || fflush(g_log_fp) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    int16_t x, y, z;
    while (g_running) {
        if (read_sensor(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_data(g_log_fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        }
        usleep(SAMPLE_DELAY_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

