#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I 0x00
#define WHO_AM_I_VAL 0x33
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define TILT_THRESHOLD 45.0
#define LOG_FILE "fall_log.txt"
#define POLL_INTERVAL_US 10000

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MMA8452Q_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int verify_sensor(void) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(i2c_fd, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Sensor identity mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VAL, who_am_i);
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    uint8_t ctrl1 = 0;
    if (i2c_read_reg8(i2c_fd, CTRL_REG1, &ctrl1) < 0) {
        fprintf(stderr, "Error reading CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }
    if (ctrl1 & 0x01) {
        if (i2c_write_reg8(i2c_fd, CTRL_REG1, ctrl1 & ~0x01) < 0) {
            fprintf(stderr, "Error writing CTRL_REG1 (standby): %s\n", strerror(errno));
            return -1;
        }
    }
    if (i2c_write_reg8(i2c_fd, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing CTRL_REG2 (DR=100Hz): %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(i2c_fd, CTRL_REG1, ctrl1 | 0x01) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 (active): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_accel(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(i2c_fd, OUT_X_MSB, buf, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

static double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double x_d = (double)x;
    double y_d = (double)y;
    double z_d = (double)z;
    return atan2(y_d, sqrt(x_d * x_d + z_d * z_d)) * 180.0 / M_PI;
}

static int log_fall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s - Fall detected! X=%d, Y=%d, Z=%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }
    if (init_i2c() < 0) return 1;
    if (verify_sensor() < 0) {
        close(i2c_fd);
        return 1;
    }
    if (init_sensor() < 0) {
        close(i2c_fd);
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    printf("Monitoring tilt... Press Ctrl+C to exit.\n");
    while (!terminate) {
        int16_t x, y, z;
        if (read_accel(&x, &y, &z) < 0) {
            usleep(POLL_INTERVAL_US);
            continue;
        }
        double tilt = calculate_tilt(x, y, z);
        if (tilt > TILT_THRESHOLD) {
            if (log_fall(x, y, z) < 0) break;
        }
        usleep(POLL_INTERVAL_US);
    }
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    printf("Exiting.\n");
    return 0;
}

