#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x0C
#define LOG_FILE       "magnetic_log.txt"
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define METAL_THRESHOLD 800.0f
#define MAX_RETRIES     3

/* LIS3MDL register addresses */
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG2 0x21
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_CTRL_REG4 0x23
#define LIS3MDL_OUT_X_L   0x28
#define LIS3MDL_OUT_X_H   0x29
#define LIS3MDL_OUT_Y_L   0x2A
#define LIS3MDL_OUT_Y_H   0x2B
#define LIS3MDL_OUT_Z_L   0x2C
#define LIS3MDL_OUT_Z_H   0x2D

/* CTRL_REG1: 0x70 = 111 0000  -> 1000 Hz ODR, all axes enabled, normal mode */
#define CTRL_REG1_VAL 0x70
/* CTRL_REG2: 0x00 = 0000 0000  -> ±4 gauss FS, continuous conversion */
#define CTRL_REG2_VAL 0x00
/* CTRL_REG3: 0x00 = 0000 0000  -> no self-test, no high-resolution */
#define CTRL_REG3_VAL 0x00
/* CTRL_REG4: 0x00 = 0000 0000  -> no temperature sensor */
#define CTRL_REG4_VAL 0x00

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg: write reg failed");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg: read failed");
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_burst: write reg failed");
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        perror("i2c_read_burst: read failed");
        return -1;
    }
    return 0;
}

static int init_lis3mdl(int fd)
{
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG1, CTRL_REG1_VAL) < 0)
        return -1;
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG2, CTRL_REG2_VAL) < 0)
        return -1;
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG3, CTRL_REG3_VAL) < 0)
        return -1;
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG4, CTRL_REG4_VAL) < 0)
        return -1;
    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
