#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL354B Register Addresses */
#define ADXL354_REG_DEVID_AD   0x00
#define ADXL354_REG_PARTID     0x02
#define ADXL354_REG_XDATA_L    0x08
#define ADXL354_REG_XDATA_H    0x09
#define ADXL354_REG_YDATA_L    0x0A
#define ADXL354_REG_YDATA_H    0x0B
#define ADXL354_REG_ZDATA_L    0x0C
#define ADXL354_REG_ZDATA_H    0x0D
#define ADXL354_REG_STATUS     0x0E
#define ADXL354_REG_POWER_CTL  0x2D
#define ADXL354_REG_RESET      0x2E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0

/* Global variables for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to an ADXL354B register via SPI */
static int adxl354_write_reg(uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (char)(reg & 0x3F);  /* MSB = 0 for write */
    tx_buf[1] = (char)value;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* Read a single byte from an ADXL354B register via SPI */
static int adxl354_read_reg(uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (char)(reg | 0x80);  /* MSB = 1 for read */
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)rx_buf[1];
    return 0;
}

/* Read 20-bit signed acceleration data from X axis (3 bytes) */
static int adxl354_read_axis(uint8_t reg_l, uint8_t reg_h, int32_t *out) {
    char tx_buf[6];
    char rx_buf[6];
    uint8_t l_val, h_val;
    int32_t raw;

    tx_buf[0] = (char)(reg_l & 0x3F);
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    tx_buf[3] = (char)(reg_h & 0x3F);
    tx_buf[4] = 0x00;
    tx_buf[5] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 6) != 6) {
        fprintf(stderr, "SPI read axis failed for register 0x%02X\n", reg_l);
        return -1;
    }

    l_val = (uint8_t)rx_buf[2];
    h_val = (uint8_t)rx_buf[4];

    raw = ((int32_t)h_val << 12) | ((int32_t)l_val << 4) | ((int32_t)rx_buf[3] >> 4);
    if (raw & 0x80000) {
        raw |= 0xFFF00000;
    }
    *out = raw;
    return 0;
}

/* Read all 6 axes */
static int adxl354_read_all_axes(int32_t *x, int32_t *y, int32_t *z) {
    if (adxl354_read_axis(ADXL354_REG_XDATA_L, ADXL354_REG_XDATA_H, x) != 0) return -1;
    if (adxl354_read_axis(ADXL354_REG_YDATA_L, ADXL354_REG_YDATA_H, y) != 0) return -1;
    if (adxl354_read_axis(ADXL354_REG_ZDATA_L, ADXL354_REG_ZDATA_H, z) != 0) return -1;
    return 0;
}

/* Initialize the ADXL354B accelerometer */
static int adxl354_init(void) {
    uint8_t partid;

    /* Reset the device */
    if (adxl354_write_reg(ADXL354_REG_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);  /* 1 ms */

    /* Verify PARTID */
    if (adxl354_read_reg(ADXL354_REG_PARTID, &partid) != 0) return -1;
    if (partid != 0x33) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x33)\n", partid);
        return -1;
    }

    /* Clear RUN bit to enter standby mode */
    if (adxl354_write_reg(ADXL354_REG_POWER_CTL, 0x00) != 0) return -1;
    gpioDelay(1000);  /* 1 ms */

    /* Wait for STABLE bit to set (data is valid) */
    uint8_t status;
    int retries = 100;
    do {
        if (adxl354_read_reg(ADXL354_REG_STATUS, &status) != 0) return -1;
        if (status & 0x04) break;
        gpioDelay(1000);
    } while (--retries > 0);
    if (retries == 0) {
        fprintf(stderr, "Timeout waiting for STABLE bit\n");
        return -1;
    }

    /* Set RUN bit to enter measurement mode */
    if (adxl354_write_reg(ADXL354_REG_POWER_CTL, 0x01) != 0) return -1;
    gpioDelay(1000);  /* 1 ms */

    return 0;
}

/* Log data to file with timestamp */
static void log_data(int32_t x, int32_t y, int32_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %ld, Y: %ld, Z: %ld\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    int32_t x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL354B */
    if (adxl354_init() != 0) {
        fprintf(stderr, "ADXL354B initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        if (adxl354_read_all_axes(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }
        gpioDelay(100000);  /* 100 ms */
    }

    /* Cleanup */
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();

    printf("Vibration monitoring stopped.\n");
    return EXIT_SUCCESS;
}

