        fprintf(stderr, "Timeout waiting for STABLE bit\n");
        return -1;
    }

    /* Set RUN bit to enter measurement mode */
    if (adxl354_write_reg(ADXL354_REG_POWER_CTL, 0x01) != 0) return -1;
    gpioDelay(1000);  /* 1 ms */

    return 0;
}

/* Log data to file with timestamp */
static void log_data(int32_t x, int32_t y, int32_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %ld, Y: %ld, Z: %ld\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    int32_t x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL354B */
    if (adxl354_init() != 0) {
        fprintf(stderr, "ADXL354B initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        if (adxl354_read_all_axes(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }
        gpioDelay(100000);  /* 100 ms */
    }

    /* Cleanup */
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();

    printf("Vibration monitoring stopped.\n");
    return EXIT_SUCCESS;
}

