#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

/* ADIS16362 SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000  /* 1 MHz */
#define SPI_FLAGS   0x0000   /* Mode 0, active-high CS, 8-bit words */

/* ADIS16362 Register Addresses */
#define ADIS16362_REG_XGYRO_OUT  0x04
#define ADIS16362_REG_YGYRO_OUT  0x06
#define ADIS16362_REG_ZGYRO_OUT  0x08
#define ADIS16362_REG_XACCEL_OUT 0x0A
#define ADIS16362_REG_YACCEL_OUT 0x0C
#define ADIS16362_REG_ZACCEL_OUT 0x0E
#define ADIS16362_REG_STATUS     0x10

/* Scaling factors (from ADIS16362 datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCEL_SCALE 0.0025f /* g per LSB */

/* Sampling interval in microseconds (100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16362 via SPI.                 */
/* Returns 0 on success and stores the value in *out; -1 on error.    */
/* ------------------------------------------------------------------ */
static int adis_read_reg16(int handle, uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];

    /*
     * ADIS16362 SPI read protocol:
     *   TX byte 0: 0x80 | (reg >> 1)  — address with MSB set
     *   TX byte 1: 0x00  — dummy byte
     *   RX byte 0:  data MSB
     *   RX byte 1:  data LSB
     */
    tx[0] = (char)(0x80 | (reg >> 1));
    tx[1] = 0x00;

    int ret = spiXfer(handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spiXfer failed for reg 0x%02X (ret=%d): %s\n",
                reg, ret, strerror(errno));
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register and apply scaling.                          */
/* ------------------------------------------------------------------ */
static void adis_read_and_scale(int handle, uint8_t reg,
                                float scale, float *out)
{
    int16_t raw;
    if (adis_read_reg16(handle, reg, &raw) != 0)
        return;
    *out = (float)raw * scale;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the CSV file.                                     */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, float gx, float gy, float gz,
                       float ax, float ay, float az)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (long)ts.tv_sec, ts.tv_nsec,
            gx, gy, gz, ax, ay, az);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call multiple times                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* gpioTerminate is safe to call even if gpioInitialise never ran */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d baud): %s\n",
                SPI_CHANNEL, SPI_BAUD, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen("imu_log.csv", "w");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening imu_log.csv: %s\n", strerror(errno));
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    if (fprintf(g_log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n") < 0) {
        fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(g_log_file);

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl-C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        adis_read_and_scale(g_spi_handle, ADIS16362_REG_XGYRO_OUT, GYRO_SCALE, &gx);
        adis_read_and_scale(g_spi_handle, ADIS16362_REG_YGYRO_OUT, GYRO_SCALE, &gy);
        adis_read_and_scale(g_spi_handle, ADIS16362_REG_ZGYRO_OUT, GYRO_SCALE, &gz);
        adis_read_and_scale(g_spi_handle, ADIS16362_REG_XACCEL_OUT, ACCEL_SCALE, &ax);
        adis_read_and_scale(g_spi_handle, ADIS16362_REG_YACCEL_OUT, ACCEL_SCALE, &ay);
        adis_read_and_scale(g_spi_handle, ADIS16362_REG_ZACCEL_OUT, ACCEL_SCALE, &az);

        log_sample(g_log_file, gx, gy, gz, ax, ay, az);

        gpioDelay(SAMPLE_INTERVAL_US); /* 10 ms — ~100 Hz */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

