#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define CHIP_NAME "gpiochip4"
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

static void log_message(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        printf("[%s] %s\n", ts, msg);
    } else {
        printf("[unknown] %s\n", msg);
    }
    fflush(stdout);
}

int main(void) {
    if (install_signal_handler() != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int chip = gpioGetChip(CHIP_NAME);
    if (chip < 0) {
        fprintf(stderr, "Failed to get GPIO chip %s\n", CHIP_NAME);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int line = gpioGetLine(chip, SENSOR_PIN);
    if (line < 0) {
        fprintf(stderr, "Failed to get GPIO line %d on chip %s\n", SENSOR_PIN, CHIP_NAME);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(line, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO line %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Self-parking sequence started");

    while (g_running) {
        int val = gpioRead(line);
        if (val < 0) {
            fprintf(stderr, "Failed to read GPIO line %d\n", SENSOR_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (val == 0) {
            log_message("Obstacle detected within 30cm range");
            sleep(POLL_INTERVAL_SEC);
            if (!g_running) break;
            log_message("Self-parking sequence completed");
        } else {
            sleep(POLL_INTERVAL_SEC);
        }
    }

    gpioSetMode(line, PI_INPUT);
    gpioTerminate();
    log_message("Program terminated");
    return EXIT_SUCCESS;
}

