    uint16_t raw_y = ((uint16_t)rx[3] << 8) | rx[4];
    uint16_t raw_z = ((uint16_t)rx[5] << 8) | rx[6];

    *x = (float)raw_x * GYRO_SCALE;
    *y = (float)raw_y * GYRO_SCALE;
    *z = (float)raw_z * GYRO_SCALE;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    float x, y, z;
    while (g_running) {
        if (read_adis16266_gyro(g_spi_fd, &x, &y, &z) == 0) {
