        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }
        usleep(READ_INTERVAL_US);
    }

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

