#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x19

/* LSM6DSR register addresses */
#define WHO_AM_I      0x0F
#define CTRL1_XL      0x10
#define CTRL2_G       0x11
#define OUTX_L_G      0x22
#define OUTX_L_XL     0x28

/* Expected WHO_AM_I value for LSM6DSR */
#define LSM6DSR_WHO_AM_I 0x33

/* Global handle for signal handler */
static int i2c_handle = -1;

/* Signal handler for Ctrl+C */
void signal_handler(int signal)
{
    (void)signal;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Function to initialize the LSM6DSR */
int init_lsm6dsr(int handle)
{
    /* Read WHO_AM_I register to verify device identity */
    int who_am_i = i2cReadByteData(handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                LSM6DSR_WHO_AM_I, who_am_i);
        return -1;
    }

    /* Set accelerometer to +/- 2g, 119 Hz ODR (CTRL1_XL: 0x80 | 0x00 = 0x80) */
    if (i2cWriteByteData(handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    /* Set gyroscope to 245 Hz ODR (CTRL2_G: 0x00) */
    if (i2cWriteByteData(handle, CTRL2_G, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

/* Function to read accelerometer and gyroscope data */
int read_lsm6dsr(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                 int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buffer[12];

    /* Read 12 bytes starting from OUTX_L_G (0x22) */
    if (i2cReadI2CBlockData(handle, OUTX_L_G, buffer, 12) != 12) {
        fprintf(stderr, "Error reading accelerometer and gyroscope data\n");
        return -1;
    }

    /* Combine high and low bytes for each axis */
    *ax = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    *ay = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    *az = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);
    /* Skip temperature bytes (buffer[6], buffer[7]) */
    *gx = (int16_t)((buffer[8] << 8) | (uint8_t)buffer[9]);
    *gy = (int16_t)((buffer[10] << 8) | (uint8_t)buffer[11]);
    *gz = 0; /* Gyroscope Z axis is not available on LSM6DSR */

    return 0;
}

int main()
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 */
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize LSM6DSR */
    if (init_lsm6dsr(i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    int16_t ax, ay, az, gx, gy, gz;

    /* Main loop */
    while (1) {
        if (read_lsm6dsr(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d | Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(100000); /* 100 ms delay (microseconds) */
    }

    /* Cleanup (unreachable in normal operation) */
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

