#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADXL345_ADDRESS 0x32
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_RANGE 0x2E
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

static int configure_adxl345(void) {
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2cWriteByteData(i2c_handle, ADXL345_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error writing to BW_RATE register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_RANGE, 0x00) < 0) {
        fprintf(stderr, "Error writing to RANGE register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register (measure mode)\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_accelerometer_data(accelerometer_data_t *data) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);
    return 0;
}

static double calculate_tilt_angle(accelerometer_data_t data) {
    double x = (double)data.x;
    double y = (double)data.y;
    double z = (double)data.z;
    return atan2(y, sqrt(x * x + z * z)) * 180.0 / M_PI;
}

static int log_tilt_event(double tilt_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
    }

    fprintf(log_file, "%s - Tilt angle: %.2f degrees\n", timestamp, tilt_angle);
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (configure_adxl345() != 0) {
        cleanup();
        return 1;
    }

    printf("Tilt detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        accelerometer_data_t data;
        if (read_accelerometer_data(&data) == 0) {
            double tilt_angle = calculate_tilt_angle(data);
            if (tilt_angle > TILT_THRESHOLD) {
                log_tilt_event(tilt_angle);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Tilt detection stopped.\n");
    return 0;
}

