#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define WINDOW_SECONDS 5
#define SAMPLE_INTERVAL_US 1000
#define STATUS_INTERVAL_US 1000000
#define MAX_THRESHOLD 1000

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    return 0;
}

static void cleanup_gpio(void) {
    gpioTerminate();
}

static int read_sensor(void) {
    return gpioRead(SENSOR_PIN);
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] ", buffer);
}

static void check_threshold(int threshold, int high_count) {
    if (high_count > threshold) {
        printf("ALERT: %d high readings in %d seconds\n", high_count, WINDOW_SECONDS);
    } else {
        printf("Status: %d high readings in %d seconds\n", high_count, WINDOW_SECONDS);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold: minimum high readings per %d-second window (1-1000)\n", WINDOW_SECONDS);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long threshold = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || threshold <= 0 || threshold > MAX_THRESHOLD) {
        fprintf(stderr, "Error: invalid threshold '%s'. Must be 1-1000.\n", argv[1]);
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int high_count = 0;
    uint32_t start_tick = gpioTick();

    while (!terminate) {
        int reading = read_sensor();
        if (reading < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d\n", SENSOR_PIN);
            break;
        }

        if (reading == 1) {
            high_count++;
        }

        uint32_t current_tick = gpioTick();
        if ((current_tick - start_tick) >= (uint32_t)(WINDOW_SECONDS * 1000000)) {
            print_timestamp();
            check_threshold(threshold, high_count);
            high_count = 0;
            start_tick = current_tick;
            usleep(STATUS_INTERVAL_US);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

