/*
 * Door access control for Raspberry Pi 4 Model B.
 *
 * Two 12 V electromagnetic door locks are driven via TIP120-driven
 * 5 V active-HIGH relay modules on the GPIO bus.
 *   GPIO17 (BCM)  -> Door A relay (lock energized = closed)
 *   GPIO27 (BCM)  -> Door B relay (lock energized = closed)
 *
 * A HIGH level on the GPIO line de-energizes the relay, unlocking the
 * door for 5 s.  A LOW level keeps the lock energized (closed).
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN 17
#define DOOR_B_PIN 27
#define UNLOCK_DURATION_SEC 5
#define LOG_FILE "access_log.txt"
#define CODE_MIN 100000
#define CODE_MAX 999999
#define CODE_LEN 6
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int generate_code(char *buf, size_t len)
{
    return snprintf(buf, len, "%06d", (rand() % (CODE_MAX - CODE_MIN + 1)) + CODE_MIN);
}

static int log_access(const char *code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%s\n", ts, code) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- Request both lines as outputs, initial value LOW (lock energized) --- */
    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Door access control system started.\n");
    printf("Enter the 6-digit code to unlock the doors for %d seconds.\n", UNLOCK_DURATION_SEC);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        char code_str[CODE_LEN + 1];
        char input[CODE_LEN + 1];

        if (generate_code(code_str, sizeof(code_str)) < 0) {
            fprintf(stderr, "Error generating code.\n");
            break;
        }

        printf("Generated code: %s\n", code_str);
        fflush(stdout);

        if (scanf("%6s", input) != 1) {
            fprintf(stderr, "Invalid input. Please enter a 6-digit code.\n");
            while (getchar() != '\n') {
                /* discard remaining input */
            }
            continue;
        }

        if (strcmp(input, code_str) == 0) {
            printf("Access granted.\n");
            fflush(stdout);

            if (gpiod_line_set_value(line_a, 1) < 0) {
                fprintf(stderr, "Failed to de-energize Door A relay: %s\n", strerror(errno));
                break;
            }
            if (gpiod_line_set_value(line_b, 1) < 0) {
                fprintf(stderr, "Failed to de-energize Door B relay: %s\n", strerror(errno));
                break;
            }

            /* Unlock for UNLOCK_DURATION_SEC, checking g_running every 100 ms */
            for (int i = 0; i < UNLOCK_DURATION_SEC * 10 && g_running; i++) {
                usleep(100000);
            }

            if (gpiod_line_set_value(line_a, 0) < 0) {
                fprintf(stderr, "Failed to re-energize Door A relay: %s\n", strerror(errno));
                break;
            }
            if (gpiod_line_set_value(line_b, 0) < 0) {
                fprintf(stderr, "Failed to re-energize Door B relay: %s\n", strerror(errno));
                break;
            }

            if (log_access(code_str) != 0) {
                fprintf(stderr, "Failed to log access.\n");
            } else {
                printf("Access logged.\n");
            }

            printf("Doors locked. Enter the next code.\n");
            fflush(stdout);
        } else {
            printf("Access denied.\n");
            fflush(stdout);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure doors are locked on exit */
    if (line_a) {
        gpiod_line_set_value(line_a, 0);
        gpiod_line_release(line_a);
    }
    if (line_b) {
        gpiod_line_set_value(line_b, 0);
        gpiod_line_release(line_b);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

