#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x5C
#define LOG_FILE "light_log.txt"
#define CONVERSION_TIME_MS 180
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char buf[2];
    int rc;

    /*
     * BH1750 continuous-high-resolution mode command:
     *   Write 0x10 (single-time high-res mode) to the device.
     *   The sensor then performs a conversion and the result is
     *   returned in two bytes (MSB first).
     */
    rc = i2cWriteByte(handle, 0x10);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByte failed (rc=%d)\n", rc);
        return -1;
    }

    /* Wait for conversion to complete (max 180 ms) */
    gpioDelay(CONVERSION_TIME_MS * 1000);

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2)\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Sensor may be absent or bus unavailable.\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BH1750 light sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;

        if (read_bh1750(i2c_handle, &lux) == 0) {
            if (log_data(LOG_FILE, lux) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            } else {
                printf("Logged: %.2f lux\n", lux);
            }
        } else {
            fprintf(stderr, "Warning: failed to read lux value\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

