static int pwm_init(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
        return -1;
    }
    if (gpioSetPWMfrequency(pin, 440) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pin);
        return -1;
    }
    if (gpioSetPWMrange(pin, 1000000) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pin);
        return -1;
    }
    if (gpioPWM(pin, 0) < 0) {
        fprintf(stderr, "Failed to initialize PWM on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static void pwm_set_duty(int pin, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int duty_ns = (PWM_PERIOD_NS * duty_percent) / 100;
    gpioPWM(pin, duty_ns);
}

static void pwm_stop(int pin) {
    gpioPWM(pin, 0);
}

static int read_touch_data(int fd, uint16_t *touch_data) {
    uint8_t buf[24];
    if (write(fd, (uint8_t[]){0x00}, 1) != 1) {
        fprintf(stderr, "Failed to select register 0x00: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 24) != 24) {
        fprintf(stderr, "Failed to read touch data: %s\n", strerror(errno));
        return -1;
    }
    for (int i = 0; i < 12; i++) {
        touch_data[i] = (buf[i * 2] << 8) | buf[i * 2 + 1];
    }
    return 0;
}

static int authenticate_message(const char *message, const char *secret) {
    if (strncmp(message, "MOTION_DETECTED:", 16) != 0) return 0;
    const char *token = message + 16;
    int len = strlen(token);
    if (len < strlen(secret)) return 0;
    return strcmp(token, secret) == 0;
}

static void log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Frequency: %d Hz\n", s, frequency);
    fclose(fp);
}

static void play_tone(int frequency, int duration_sec) {
    int period_ns = PWM_PERIOD_NS / frequency;
    int duty_ns = period_ns / 2;
    int steps = (duration_sec * 1000000000L / period_ns) + 1;
    for (int i = 0; i < steps && running; i++) {
        pwm_set_duty(PWM_PIN, i * 100);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }
    pwm_stop(PWM_PIN);
}

