#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x19
#define LED_PIN        17
#define PWM_RANGE      100
#define PWM_FREQ       1000
#define SAMPLE_US      100000
#define LOG_FILE       "mag_log.txt"

/* LSM303DLHC magnetometer register addresses */
#define LSM303_MAG_X_MSB 0x00
#define LSM303_MAG_X_LSB 0x01
#define LSM303_MAG_Z_MSB 0x02
#define LSM303_MAG_Z_LSB 0x03

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s (errno: %s)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg, strerror(errno));
    fflush(log_fp);
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_magnetometer(int fd, float *mag_z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, LSM303_MAG_X_MSB, buf, 6) < 0) {
        log_error("I2C block read failed");
        return -1;
    }
    int16_t raw_z = (int16_t)((buf[2] << 8) | buf[3]);
    *mag_z = (float)raw_z / 1000.0f;
    return 0;
}

static void set_led_brightness(float mag_z) {
    int brightness = (int)(mag_z * 10.0f);
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    if (gpioPWM(LED_PIN, brightness) < 0) {
        log_error("gpioPWM failed");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open /dev/i2c-1");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set LED pin mode");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LED_PIN, PWM_RANGE) < 0) {
        log_error("Failed to set PWM range");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LED_PIN, PWM_FREQ) < 0) {
        log_error("Failed to set PWM frequency");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(LED_PIN, 0) < 0) {
        log_error("Failed to initialise LED PWM");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LSM303DLHC magnetometer reader started. Press Ctrl+C to exit.\n");

    while (running) {
        float mag_z;
        if (read_magnetometer(i2c_fd, &mag_z) == 0) {
            set_led_brightness(mag_z);
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(LED_PIN, 0);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fp) fclose(log_fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

