#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07
#define NUM_SAMPLES 100
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hmc5883l_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int hmc5883l_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error setting register pointer to 0x%02X\n", reg);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int hmc5883l_init(void) {
    if (hmc5883l_write_reg(HMC5883L_CONFIG_A, 0x70) != 0) return -1;
    if (hmc5883l_write_reg(HMC5883L_CONFIG_B, 0x20) != 0) return -1;
    if (hmc5883l_write_reg(HMC5883L_MODE, 0x00) != 0) return -1;
    return 0;
}

static int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    if (hmc5883l_read_reg(HMC5883L_DATA_X_MSB, x_msb) != 0) return -1;
    if (hmc5883l_read_reg(HMC5883L_DATA_X_LSB, x_lsb) != 0) return -1;
    if (hmc5883l_read_reg(HMC5883L_DATA_Y_MSB, y_msb) != 0) return -1;
    if (hmc5883l_read_reg(HMC5883L_DATA_Y_LSB, y_lsb) != 0) return -1;
    if (hmc5883l_read_reg(HMC5883L_DATA_Z_MSB, z_msb) != 0) return -1;
    if (hmc5883l_read_reg(HMC5883L_DATA_Z_LSB, z_lsb) != 0) return -1;

