    static int16_t x_sum = 0, y_sum = 0, z_sum = 0;
    x_sum -= data[0];
    y_sum -= data[1];
    z_sum -= data[2];
    offsets[0] = x_sum / NUM_SAMPLES;
    offsets[1] = y_sum / NUM_SAMPLES;
    offsets[2] = z_sum / NUM_SAMPLES;
}

