        if (read_magnetometer_data(raw_data, raw_data + 1, raw_data + 2) == 0) {
            calculate_offsets(offsets, raw_data);
            printf("X: %6d, Y: %6d, Z: %6d\n", raw_data[0] - offsets[0], raw_data[1] - offsets[1], raw_data[2] - offsets[2]);
        } else {
            fprintf(stderr, "Error reading magnetometer data\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

