/*
 * LSM303D tri-axial accelerometer reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   LSM303D SDA  -> Pi GPIO2  (physical pin 3, I2C bus 1)
 *   LSM303D SCL  -> Pi GPIO3  (physical pin 5, I2C bus 1)
 *   LSM303D INT1 -> Pi GPIO23 (physical pin 16)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 *
 * The LSM303D accelerometer sensitivity is 0.061 mg/LSB in 12-bit mode.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D register definitions (from datasheet) ---- */
#define LSM303D_I2C_ADDR        0x3C
#define LSM303D_WHO_AM_I        0x0F
#define LSM303D_WHO_AM_I_VAL    0x33
#define LSM303D_CTRL_REG1_A     0x20
#define LSM303D_CTRL_REG4_A     0x23
#define LSM303D_OUT_X_L_A       0x28
#define LSM303D_INT1_CFG_A      0x25
#define LSM303D_INT1_SRC_A      0x26

/* ---- Configuration ---- */
#define I2C_BUS                "/dev/i2c-1"
#define INT1_GPIO_LINE          23          /* BCM 23, physical pin 16 */
#define BUFFER_SIZE            64
#define SAMPLE_INTERVAL_US     10000       /* 10 ms */
#define ACCEL_SENSITIVITY_MG_LSB 0.061f
#define ACCEL_THRESHOLD_MG     2000.0f
#define ACCEL_DURATION_MS      0
#define INT1_RISING_EDGE_MASK  1

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1_line = NULL;

/* ---- Circular buffer ---- */
typedef struct {
    int16_t x, y, z;
} AccelData;

static AccelData g_buffer[BUFFER_SIZE];
static int g_head = 0;
static int g_count = 0;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM303D helpers ---- */
static int lsm303d_init(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, LSM303D_WHO_AM_I, &who_am_i) < 0)
        return -1;
    if (who_am_i != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1_A: accel X/Y/Z enabled, 119 Hz ODR, normal mode */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1_A, 0x77) < 0)
        return -1;

    /* CTRL_REG4_A: INT1 enabled, active low, 2000 mg threshold,
     * 1-sample duration, immediate mode */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG4_A, 0x84) < 0)
        return -1;

    return 0;
}

static int lsm303d_disable(int fd)
{
    /* CTRL_REG1_A: accel disabled, no ODR, power-down */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1_A, 0x00) < 0)
        return -1;
    return 0;
}

static int lsm303d_read_accel(int fd, AccelData *out)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, LSM303D_OUT_X_L_A, raw, 6) < 0)
        return -1;

    out->x = (int16_t)((raw[1] << 8) | raw[0]);
    out->y = (int16_t)((raw[3] << 8) | raw[2]);
    out->z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

static void buffer_add(AccelData d)
{
    g_buffer[g_head] = d;
    g_head = (g_head + 1) % BUFFER_SIZE;
    if (g_count < BUFFER_SIZE)
        g_count++;
}

static void buffer_dump(int n)
{
    if (n > BUFFER_SIZE)
        n = BUFFER_SIZE;
    int start = (g_head - n + BUFFER_SIZE) % BUFFER_SIZE;
    printf("--- Last %d samples ---\n", n);
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        time_t t = time(NULL);
        struct tm tmv;
        if (localtime_r(&t, &tmv)) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
        } else {
            snprintf(ts, sizeof(ts), "----");
        }
        printf("%s  X: %6d  Y: %6d  Z: %6d\n", ts,
               g_buffer[idx].x, g_buffer[idx].y, g_buffer[idx].z);
    }
    fflush(stdout);
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303D_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize LSM303D */
    if (lsm303d_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        lsm303d_disable(g_i2c_fd);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    g_int1_line = gpiod_chip_get_line(g_chip, INT1_GPIO_LINE);
    if (!g_int1_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                INT1_GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        lsm303d_disable(g_i2c_fd);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(g_int1_line, "lsm303d_int1") < 0) {
        fprintf(stderr, "gpiod_line_request_input failed: %s\n",
                strerror(errno));
        gpiod_chip_close(g_chip);
        lsm303d_disable(g_i2c_fd);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("LSM303D monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        AccelData sample;
        if (lsm303d_read_accel(g_i2c_fd, &sample) < 0) {
            fprintf(stderr, "Warning: accelerometer read failed, skipping sample.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        buffer_add(sample);

        /* Check INT1 for rising edge (INT1 active low) */
        int val = gpiod_line_get_value(g_int1_line);
        if (val < 0) {
            fprintf(stderr, "Warning: gpiod_line_get_value failed: %s\n",
                    strerror(errno));
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        if (val == 1) {
            buffer_dump(10);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_int1_line)
        gpiod_line_release(g_int1_line);
    if (g_chip)
        gpiod_chip_close(g_chip);
    if (g_i2c_fd >= 0) {
        lsm303d_disable(g_i2c_fd);
        close(g_i2c_fd);
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

