#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS      500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_line(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int deenergize_all(void)
{
    if (set_line(SOLENOID_1_PIN, 0) != 0) return -1;
    if (set_line(SOLENOID_2_PIN, 0) != 0) return -1;
    return 0;
}

static int switch_solenoids(void)
{
    if (set_line(SOLENOID_1_PIN, 1) != 0) return -1;
    if (set_line(SOLENOID_2_PIN, 0) != 0) return -1;
    return 0;
}

static int sleep_ms(unsigned ms)
{
    struct timespec req = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    struct timespec rem;

    while (nanosleep(&req, &rem) != 0) {
        if (errno != EINTR) {
            fprintf(stderr, "nanosleep: %s\n", strerror(errno));
            return -1;
        }
        req = rem;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_line(SOLENOID_1_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_line(SOLENOID_2_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (switch_solenoids() != 0) break;
        if (sleep_ms(DELAY_MS) != 0) break;

        if (!g_running) break;
        if (switch_solenoids() != 0) break;
