    gpioSetMode(RELAY_PIN_2, PI_OUTPUT);
    gpioWrite(RELAY_PIN_1, 0);
    gpioWrite(RELAY_PIN_2, 0);
    return 0;
}

static int initialize_uart(int *fd) {
    *fd = serOpen("/dev/serial0", UART_BAUD, 0);
    if (*fd < 0) {
        fprintf(stderr, "Failed to open /dev/serial0: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

