    if (*fd < 0) {
        fprintf(stderr, "Failed to open /dev/serial1: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_code(int fd, char *buffer, int buffer_size) {
    int bytes_read = serRead(fd, buffer, buffer_size - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "UART read error on fd %d: %s\n", fd, strerror(errno));
        return -1;
    }
    if (bytes_read == 0) {
        return 0;
    }
    buffer[bytes_read] = '\0';
    return bytes_read;
}

static int compare_codes(const char *code1, const char *code2) {
    if (strlen(code1) != CODE_LENGTH || strlen(code2) != CODE_LENGTH) {
        return 0;
    }
    for (int i = 0; i < CODE_LENGTH; i++) {
        if (code1[i] != code2[i]) {
            return 0;
        }
    }
    return 1;
}

