    if (gpioWrite(RELAY_PIN_1, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO%d HIGH\n", RELAY_PIN_1);
        return -1;
    }
    if (gpioWrite(RELAY_PIN_2, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO%d HIGH\n", RELAY_PIN_2);
        gpioWrite(RELAY_PIN_1, 0);
        return -1;
    }
    return 0;
}

