    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    if (initialize_uart(&g_uart_fd_primary) < 0) {
        gpioTerminate();
        return 1;
    }

    if (initialize_uart_secondary(&g_uart_fd_secondary) < 0) {
        serClose(g_uart_fd_primary);
        g_uart_fd_primary = -1;
        gpioTerminate();
        return 1;
    }

    printf("Door lock authentication system started. Press Ctrl+C to exit.\n");

