        int bytes_read1 = read_code(g_uart_fd_primary, code1, CODE_LENGTH + 1);
        if (bytes_read1 < 0) {
            ret = 1;
            break;
        }
        if (bytes_read1 == 0) {
            continue;
        }
        code1[bytes_read1] = '\0';

        int bytes_read2 = read_code(g_uart_fd_secondary, code2, CODE_LENGTH + 1);
        if (bytes_read2 < 0) {
            ret = 1;
            break;
        }
        if (bytes_read2 == 0) {
            continue;
        }
        code2[bytes_read2] = '\0';

        if (code1[0] == '\0' || code2[0] == '\0') {
            continue;
        }

        if (code1[0] != '\0' && strcmp(code1, EXPECTED_CODE) == 0) {
            if (code2[0] != '\0' && strcmp(code2, EXPECTED_CODE) == 0) {
                printf("Codes match. Unlocking door...\n");
                if (unlock_door() < 0) {
