            }
        } else {
            fprintf(stderr, "Codes do not match. Code1: %s, Code2: %s\n", code1, code2);
        }

        memset(code1, 0, CODE_LENGTH + 1);
        memset(code2, 0, CODE_LENGTH + 1);
    }

    cleanup();
    return ret;
}

