#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpiochip.h>

#define PIR_PIN      4
#define RELAY_PIN    17
#define POLL_MS      50
#define RELAY_HOLD_S 1
#define MOTION_TIMEOUT_S 10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_ts(const char *level, const char *msg)
{
    time_t now = time(NULL);
    struct tm tm;
    char buf[32];
    localtime_r(&now, &tm);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm);
    syslog(level, "%s %s", buf, msg);
}

static int set_relay(int fd, int pin, int val)
{
    int ret = ioctl(fd, GPIO_SET_VALUE, pin | (val << 16));
    if (ret < 0)
        syslog(LOG_ERR, "ioctl(GPIO_SET_VALUE, pin=%d, val=%d) failed: %s",
               pin, val, strerror(errno));
    return ret;
}

static void cleanup(int pir_fd, int relay_fd)
{
    if (relay_fd >= 0) {
        (void)set_relay(relay_fd, RELAY_PIN, 0);
        close(relay_fd);
    }
    if (pir_fd >= 0)
        close(pir_fd);
    closelog();
}

int main(void)
{
    openlog("pir_door_strike", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    int pir_fd = open("/dev/gpiochip0", O_RDWR);
    if (pir_fd < 0) {
        syslog(LOG_ERR, "open(/dev/gpiochip0) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    int relay_fd = open("/dev/gpiochip0", O_RDWR);
    if (relay_fd < 0) {
        syslog(LOG_ERR, "open(/dev/gpiochip0) failed for relay: %s", strerror(errno));
        close(pir_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(pir_fd, GPIO_SET_DIRECTION, PIR_PIN) < 0) {
        syslog(LOG_ERR, "GPIO_SET_DIRECTION(PIR=%d) failed: %s", PIR_PIN, strerror(errno));
        cleanup(pir_fd, relay_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(relay_fd, GPIO_SET_DIRECTION, RELAY_PIN) < 0) {
        syslog(LOG_ERR, "GPIO_SET_DIRECTION(RELAY=%d) failed: %s", RELAY_PIN, strerror(errno));
        cleanup(pir_fd, relay_fd);
        return EXIT_FAILURE;
    }

    if (set_relay(relay_fd, RELAY_PIN, 0) < 0) {
        syslog(LOG_ERR, "initial relay reset failed");
        cleanup(pir_fd, relay_fd);
        return EXIT_FAILURE;
    }

    log_ts(LOG_INFO, "Door strike controller started");

    int pir_val = 0;
    time_t motion_start = 0;
    int relay_armed = 1;

    while (g_running) {
        pir_val = ioctl(pir_fd, GPIO_GET_VALUE, PIR_PIN);
        if (pir_val < 0) {
            syslog(LOG_ERR, "GPIO_GET_VALUE(PIR=%d) failed: %s", PIR_PIN, strerror(errno));
            break;
        }

        if (pir_val == 1) {
            if (motion_start == 0) {
                motion_start = time(NULL);
                log_ts(LOG_INFO, "Motion detected");
            } else if (difftime(time(NULL), motion_start) > MOTION_TIMEOUT_S) {
                log_ts(LOG_WARNING, "Motion timeout - potential malfunction");
                log_ts(LOG_INFO, "Failsafe: de-energizing relay");
                set_relay(relay_fd, RELAY_PIN, 0);
                log_ts(LOG_INFO, "Shutdown event triggered");
                break;
            }
        } else {
            motion_start = 0;
        }

        usleep(POLL_MS * 1000);
    }

    log_ts(LOG_INFO, "Door strike controller stopped");
    cleanup(pir_fd, relay_fd);
    return EXIT_SUCCESS;
}

