#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define TIMER_INTERVAL 60
#define RELAY_ON_TIME 300
#define RELAY_OFF_TIME 60

static volatile sig_atomic_t running = 1;

static const int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < 4; i++) {
        gpioWrite(relay_pins[i], 1);
    }
}

static void log_message(int priority, const char *message) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

static void activate_relay(int relay_index, int duration) {
    if (gpioWrite(relay_pins[relay_index], 0) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Error: Failed to activate relay %d (GPIO %d)", relay_index + 1, relay_pins[relay_index]);
        log_message(LOG_ERR, msg);
        return;
    }
    log_message(LOG_INFO, "Relay activated");
    gpioDelay(duration * 1000000);
    if (gpioWrite(relay_pins[relay_index], 1) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Error: Failed to deactivate relay %d (GPIO %d)", relay_index + 1, relay_pins[relay_index]);
        log_message(LOG_ERR, msg);
        return;
    }
    log_message(LOG_INFO, "Relay deactivated");
}

static void timer_callback(void *user_data) {
    (void)user_data;
    for (int i = 0; i < 4 && running; i++) {
        activate_relay(i, RELAY_ON_TIME);
        if (!running) break;
        if (i < 3) {
            gpioDelay(RELAY_OFF_TIME * 1000000);
            if (!running) break;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            fprintf(stderr, "Failed to set GPIO %d HIGH\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set timer");
        deactivate_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        gpioDelay(1000000);
    }

    deactivate_all_relays();
    gpioTerminate();
    return EXIT_SUCCESS;
}

