#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)

typedef struct {
    int16_t x, y, z;
} accel_data_t;

typedef struct {
    accel_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static circular_buffer_t buffer;
static FILE *driver_file = NULL;
static struct timer_t timer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, 0x6B) < 0) return -1;
    usleep(100000);
    if (i2c_write_byte(fd, 0x2D) < 0) return -1;
    usleep(100000);
    if (i2c_write_byte(fd, 0x00) < 0) return -1;
    usleep(100000);
    return 0;
}

static int read_accel_data(int fd, accel_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, buf, 6) < 0) return -1;
    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, accel_data_t data) {
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static int write_to_driver(const accel_data_t *data) {
    char buf[64];
    int len = snprintf(buf, sizeof(buf), "%d,%d,%d", data->x, data->y, data->z);
    if (len < 0 || len >= (int)sizeof(buf)) return -1;
    if (fputs(buf, driver_file) == EOF) return -1;
    fflush(driver_file);
    return 0;
}

static void timer_handler(int sig, siginfo_t *si, void *uc) {
    (void)sig; (void)si; (void)uc;
    accel_data_t data;
    if (read_accel_data(i2c_fd, &data) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return;
    }
    buffer_add(&buffer, data);
    write_to_driver(&data);
}

static void cleanup(void) {
    if (driver_file) {
        fclose(driver_file);
        driver_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    timer_delete(timer);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    buffer_init(&buffer);
    driver_file = fopen("/sys/kernel/mpu6050_accel/latest", "w");
    if (!driver_file) {
        fprintf(stderr, "Failed to open driver file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (timer_create(CLOCK_MONOTONIC, timer_handler, NULL, &timer) < 0) {
        perror("timer_create");
        cleanup();
        return 1;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = SAMPLE_PERIOD_NS;
    if (timer_settime(timer, 0, &its, NULL) < 0) {
        perror("timer_settime");
        cleanup();
        return 1;
    }

    printf("Sampling MPU6050 at %d Hz. Press Ctrl+C to stop.\n", SAMPLE_RATE_HZ);

    while (running) {
        pause();
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

