    }
    return 0;
}

static int safe_gpio_set_timer(unsigned pin, unsigned interval_ms) {
    if (gpioSetTimerFuncEx(pin, interval_ms, NULL, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed on pin %u: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int pin = *(int *)user_data;
    safe_gpio_write(pin, 1);
    printf("Relay on GPIO %d turned ON\n", pin);
    fflush(stdout);
}

static void cleanup(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioWrite(pins[i], 0);
        gpioSetTimerFuncEx(pins[i], 0, NULL, NULL);
        gpioSetMode(pins[i], PI_INPUT);
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (safe_gpio_set_mode(pins[i], PI_OUTPUT) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        if (safe_gpio_write(pins[i], 0) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    int timers[4];
    for (int i = 0; i < 4; i++) {
        timers[i] = pins[i];
        if (safe_gpio_set_timer(pins[i], RELAY_INTERVAL_SEC * 1000) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Starting relay toggling. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        for (int i = 0; i < 4; i++) {
            if (gpioGetTimerFuncEx(timers[i], NULL) == 0) {
                int *user_data = malloc(sizeof(int));
                if (user_data == NULL) {
                    fprintf(stderr, "Error: malloc failed: %s\n", strerror(errno));
                    continue;
                }
                *user_data = timers[i];
                if (gpioSetTimerFuncEx(timers[i], RELAY_INTERVAL_SEC * 1000, timer_callback, user_data) < 0) {
                    fprintf(stderr, "Error: gpioSetTimerFuncEx failed on pin %d: %s\n", timers[i], strerror(errno));
                    free(user_data);
                    continue;
                }
                free(user_data);
            }
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

