#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define RELAY_ACTIVATION_DURATION_SEC 3
#define POLL_INTERVAL_US 100000
#define LOG_FILE "alarm_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_timestamp(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_relay(int relay_pin, int duration_sec) {
    if (gpioWrite(relay_pin, 1) != 0) {
        fprintf(stderr, "Error activating relay on GPIO%d\n", relay_pin);
        return -1;
    }

    for (int i = 0; i < duration_sec * 10 && program_running; i++) {
        gpioDelay(100000);
    }

    if (gpioWrite(relay_pin, 0) != 0) {
        fprintf(stderr, "Error deactivating relay on GPIO%d\n", relay_pin);
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing relay to OFF state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started on GPIO%d. Relay on GPIO%d. Press Ctrl+C to exit.\n",
           SOUND_SENSOR_PIN, RELAY_PIN);

    while (program_running) {
        int sound_detected = gpioRead(SOUND_SENSOR_PIN);

        if (sound_detected < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", SOUND_SENSOR_PIN);
            break;
        }

        if (sound_detected == 1) {
            printf("Sound detected! Activating relay for %d seconds.\n",
                   RELAY_ACTIVATION_DURATION_SEC);

            if (activate_relay(RELAY_PIN, RELAY_ACTIVATION_DURATION_SEC) != 0) {
                fprintf(stderr, "Error activating relay.\n");
            } else {
                if (log_timestamp(LOG_FILE) != 0) {
                    fprintf(stderr, "Error logging timestamp.\n");
                }
            }

            gpioDelay(500000);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

