#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define SAMPLE_RATE_HZ 100
#define BUFFER_SIZE 100
#define THRESHOLD 50.0
#define GYRO_SCALE 131.0

#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

static volatile sig_atomic_t running = 1;

typedef struct {
    float x, y, z;
} gyro_data_t;

static gyro_data_t buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "I2C read burst error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_burst(fd, WHO_AM_I, &who_am_i, 1) < 0) return -1;
    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x68)\n", who_am_i);
        return -1;
    }
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t raw[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, raw, 6) < 0) return -1;
    int16_t x = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t y = (int16_t)((raw[2] << 8) | raw[3]);
    int16_t z = (int16_t)((raw[4] << 8) | raw[5]);
    data->x = (float)x / GYRO_SCALE;
    data->y = (float)y / GYRO_SCALE;
    data->z = (float)z / GYRO_SCALE;
    return 0;
}

static void process_data(gyro_data_t data) {
    float magnitude = sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > THRESHOLD) {
        printf("Threshold exceeded! |v| = %.2f deg/s\n", magnitude);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(fd);
        return 1;
    }

    printf("MPU6050 initialized. Reading at %d Hz...\n", SAMPLE_RATE_HZ);

    while (running) {
        gyro_data_t data;
        if (read_gyro_data(fd, &data) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(10000);
            continue;
        }
        buffer[buffer_index] = data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        process_data(data);
        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    printf("\nShutting down...\n");
    close(fd);
    return 0;
}

