#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22

#define STEPS_PER_REVOLUTION 512
#define STEP_DELAY_US 2000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned gpio, unsigned pull) {
    if (gpioSetPullUpDown(gpio, pull) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", gpio, pull);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int motor_step(int phase1, int phase2, int phase3, int phase4) {
    if (safe_write(IN1, phase1) < 0) return -1;
    if (safe_write(IN2, phase2) < 0) return -1;
    if (safe_write(IN3, phase3) < 0) return -1;
    if (safe_write(IN4, phase4) < 0) return -1;
    return 0;
}

static int rotate_steps(int steps, int direction) {
    int phase1, phase2, phase3, phase4;
    int step_delay = STEP_DELAY_US;

    if (direction > 0) {
        phase1 = 1; phase2 = 0; phase3 = 0; phase4 = 0;
    } else {
        phase1 = 0; phase2 = 0; phase3 = 1; phase4 = 1;
    }

    for (int i = 0; i < steps; i++) {
        if (!running) return 0;

        if (motor_step(phase1, phase2, phase3, phase4) < 0) {
            fprintf(stderr, "Error: motor_step failed at step %d\n", i);
            return -1;
        }
        gpioDelay(step_delay);
    }
    return 0;
}

static int lock_door(void) {
    printf("Locking door...\n");
    fflush(stdout);
    if (rotate_steps(STEPS_PER_REVOLUTION, 1) < 0) {
        fprintf(stderr, "Error: failed to rotate motor for lock\n");
        return -1;
    }
    printf("Door locked.\n");
    fflush(stdout);
    return 0;
}

static int unlock_door(void) {
    printf("Unlocking door...\n");
    fflush(stdout);
    if (rotate_steps(STEPS_PER_REVOLUTION, -1) < 0) {
        fprintf(stderr, "Error: failed to rotate motor for unlock\n");
        return -1;
    }
    printf("Door unlocked.\n");
    fflush(stdout);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(LOCK_BUTTON, PI_INPUT) < 0 ||
        safe_set_mode(UNLOCK_BUTTON, PI_INPUT) < 0 ||
        safe_set_mode(IN1, PI_OUTPUT) < 0 ||
        safe_set_mode(IN2, PI_OUTPUT) < 0 ||
        safe_set_mode(IN3, PI_OUTPUT) < 0 ||
        safe_set_mode(IN4, PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_pull(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        safe_set_pull(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Stepper motor control program started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_lock_state = 0;
    int last_unlock_state = 0;

    while (running) {
        int lock_val = gpioRead(LOCK_BUTTON);
        int unlock_val = gpioRead(UNLOCK_BUTTON);

        if (lock_val == 0 && last_lock_state == 0) {
            if (lock_door() == 0) last_lock_state = 1;
        }
        if (unlock_val == 0 && last_unlock_state == 0) {
            if (unlock_door() == 0) last_unlock_state = 1;
        }

        last_lock_state = lock_val;
        last_unlock_state = unlock_val;

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    /* De-energize motor coils */
    safe_write(IN1, 0);
    safe_write(IN2, 0);
    safe_write(IN3, 0);
    safe_write(IN4, 0);

    gpioTerminate();
    printf("Program terminated.\n");
    fflush(stdout);
    return EXIT_SUCCESS;
}

