#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

#define SERVO_GPIO 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0

#define LOG_FILE "solar_tracker.log"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

int init_mpu6050(int fd) {
    uint8_t whoami;
    if (i2c_read_reg8(fd, 0x75, &whoami) < 0) return -1;
    if (whoami != 0x68) {
        fprintf(stderr, "MPU6050 not found (WHO_AM_I=0x%02X)\n", whoami);
        return -1;
    }
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    return 0;
}

int read_accel_data(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int read_gyro_data(int fd, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) return -1;
    *gx = (int16_t)((buf[0] << 8) | buf[1]);
    *gy = (int16_t)((buf[2] << 8) | buf[3]);
    *gz = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

void calculate_pitch_roll(int16_t ax, int16_t ay, int16_t az, float *pitch, float *roll) {
    *pitch = atan2((float)ax, sqrt((float)ay * ay + (float)az * az)) * 180.0 / M_PI;
    *roll = atan2((float)ay, sqrt((float)ax * ax + (float)az * az)) * 180.0 / M_PI;
}

int set_servo_angle(int fd, int angle) {
    if (angle < 0 || angle > 180) return -1;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    int period = 1000000;
    int duty = (period * angle) / 180;
    fprintf(fp, "%d", duty);
    fclose(fp);
    return 0;
}

int log_data(float pitch, float roll, int angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, pitch, roll, angle);
    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    pwm_fd = open("/sys/class/pwm/pwmchip2/export", O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to export PWM: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    write(pwm_fd, "0", 1);
    close(pwm_fd);
    usleep(100000);
    pwm_fd = open("/sys/class/pwm/pwmchip2/pwm0/period", O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    write(pwm_fd, "1000000", 8);
    close(pwm_fd);
    pwm_fd = open("/sys/class/pwm/pwmchip2/pwm0/duty_cycle", O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (running) {
        int16_t ax, ay, az, gx, gy, gz;
        int retries = 0;
        int delay = 10000;
        int success = 0;
        while (retries < 5 && running) {
            if (read_accel_data(i2c_fd, &ax, &ay, &az) == 0 && read_gyro_data(i2c_fd, &gx, &gy, &gz) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            close(i2c_fd);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Failed to reopen I2C: %s\n", strerror(errno));
                retries++;
                usleep(delay * retries);
                delay *= 2;
                continue;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
                fprintf(stderr, "Failed to set I2C slave: %s\n", strerror(errno));
                close(i2c_fd);
                i2c_fd = open(I2C_BUS, O_RDWR);
                if (i2c_fd < 0) {
                    fprintf(stderr, "Failed to reopen I2C: %s\n", strerror(errno));
                    retries++;
                    usleep(delay * retries);
                    delay *= 2;
                    continue;
                }
            }
            retries++;
            usleep(delay);
        }
        if (!success) {
            fprintf(stderr, "Failed to read sensor after retries\n");
            continue;
        }
        float pitch, roll;
        calculate_pitch_roll(ax, ay, az, &pitch, &roll);
        int angle = (int)(pitch + roll) / 2;
        if (angle < 0) angle = 0;
        if (angle > 180) angle = 180;
        if (set_servo_angle(pwm_fd, angle) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
        }
        if (log_data(pitch, roll, angle) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }
        usleep(100000);
    }

    set_servo_angle(pwm_fd, 0);
    close(i2c_fd);
    close(pwm_fd);
    return 0;
}

