#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION 1800
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define SCHEDULE_FILE "lighting_schedule.txt"
#define MAX_SCHEDULE_ENTRIES 100

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};

typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state;
} ScheduleEntry;

static volatile sig_atomic_t program_running = 1;
static int schedule_entries[MAX_SCHEDULE_ENTRIES][3];
static int schedule_entry_count = 0;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_schedule_file(void) {
    FILE *fp = fopen(SCHEDULE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening schedule file '%s': %s\n", SCHEDULE_FILE, strerror(errno));
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL && schedule_entry_count < MAX_SCHEDULE_ENTRIES) {
        int hour, minute, second;
        if (sscanf(line, "%d:%d:%d,%d,%d", &hour, &minute, &second, &schedule_entries[schedule_entry_count][0], &schedule_entries[schedule_entry_count][1]) == 5) {
            schedule_entries[schedule_entry_count][2] = 0;
            schedule_entry_count++;
        } else {
            fprintf(stderr, "Invalid schedule entry format: %s", line);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

static int is_time_to_activate(int current_hour, int current_minute, int current_second) {
    for (int i = 0; i < schedule_entry_count; i++) {
        if (schedule_entries[i][0] == current_hour &&
            schedule_entries[i][1] == current_minute &&
            schedule_entries[i][2] == current_second) {
            return schedule_entries[i][3];
        }
    }
    return 0;
}

static void set_relay_state(int relay_number, int state) {
    if (relay_number < 0 || relay_number >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_number);
        return;
    }
    gpioWrite(relay_pins[relay_number], state);
}

static void fade_lamp(int relay_number, int target_state) {
    if (relay_number < 0 || relay_number >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_number);
        return;
    }

    if (target_state == 1) {
        for (int i = 0; i < PWM_RANGE && program_running; i++) {
            gpioPWM(relay_pins[relay_number], i);
            time_sleep(0.01);
        }
    } else {
        for (int i = PWM_RANGE - 1; i >= 0 && program_running; i--) {
            gpioPWM(relay_pins[relay_number], i);
            time_sleep(0.01);
        }
    }
    set_relay_state(relay_number, target_state);
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(relay_pins[i], PI_OUTPUT);
        gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY);
        gpioSetPWMrange(relay_pins[i], PWM_RANGE);
        set_relay_state(i, 0);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

