/*
 * Rudimentary Theremin for Raspberry Pi Zero W
 *
 * Hardware:
 *   - HC-SR04 Ultrasonic Distance Sensor
 *     VCC -> 5V, GND -> GND, TRIG -> GPIO23 (BCM), ECHO -> GPIO24 (BCM)
 *   - PWM Buzzer
 *     + -> GPIO18 (BCM), - -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 * Run:
 *   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define SPEED_OF_SOUND   34300.0   /* cm/s at 20 °C */
#define MIN_FREQUENCY    200.0     /* Hz */
#define MAX_FREQUENCY    2000.0    /* Hz */
#define MIN_DISTANCE     2.0       /* cm */
#define MAX_DISTANCE     400.0     /* cm */
#define ECHO_TIMEOUT_US  30000     /* 30 ms timeout for echo */
#define LOOP_DELAY_US    20000     /* 20 ms between measurements */
#define TRIGGER_PULSE_US 10        /* 10 µs trigger pulse */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance using the pigpio HC-SR04 API.
 * Returns distance in cm on success, or -1.0 on timeout/error.
 */
static double measure_distance(void)
{
    /* Issue a 10 µs trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) != 0) {
        fprintf(stderr, "Error: gpioTrigger failed on pin %d\n", TRIGGER_PIN);
        return -1.0;
    }

    /* Wait for echo rising edge (timeout if sensor absent or out of range) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo rising edge timeout (sensor absent or out of range)\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo falling edge timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    double pulse_us = (double)(echo_end - echo_start);
    double distance = (pulse_us * SPEED_OF_SOUND) / 2000000.0;

    /* Sanity-check against HC-SR04 operating range */
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: Distance %.2f cm out of valid range [%.0f-%.0f]\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return -1.0;
    }

    return distance;
}

/*
 * Map distance to a frequency between MIN_FREQUENCY and MAX_FREQUENCY.
 * Returns the clamped frequency.
 */
static double distance_to_frequency(double distance)
{
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    double freq = MIN_FREQUENCY +
                  (distance / MAX_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY);

    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;

    return freq;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set BUZZER_PIN %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);  /* 50 µs settle */

    /* Main loop */
    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            /* Sensor error or timeout — silence buzzer for safety */
            gpioPWM(BUZZER_PIN, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double frequency = distance_to_frequency(distance);
        int pwm_value = (int)(frequency / 50.0);  /* 50 Hz PWM resolution */

        if (gpioPWM(BUZZER_PIN, pwm_value) != 0) {
            fprintf(stderr, "Error: gpioPWM failed on pin %d\n", BUZZER_PIN);
        }

        printf("Distance: %.2f cm, Frequency: %.0f Hz\n", distance, frequency);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful cleanup */
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

