static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[14];
    if (i2c_read_regs(fd, 0x40, buf, 14) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        return 1;
    }
    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "MPU6050 not detected or initialization failed.\n");
        close(fd);
        return 1;
    }
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }
    while (running) {
        float x, y, z;
        if (read_gyro_data(fd, &x, &y, &z) == 0) {
            log_data(fp, x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data.\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return 0;
}

