#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000
#define MELODY_LEN 10

/* Melody: frequency (Hz) and duration (ms) */
static const int melody[MELODY_LEN][2] = {
    {262, 500}, {294, 500}, {330, 500}, {349, 500},
    {392, 500}, {440, 500}, {494, 500}, {523, 500},
    {587, 500}, {659, 500}
};

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    button_pressed = 1;
}

static int play_melody(void) {
    for (int i = 0; i < MELODY_LEN; i++) {
        if (!running) break;

        int freq = melody[i][0];
        int duration_ms = melody[i][1];

        if (gpioSetPWMfrequency(BUZZER_PIN, freq) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", freq);
            return -1;
        }

        if (gpioPWM(BUZZER_PIN, 128) < 0) {
            fprintf(stderr, "Error: gpioPWM(128) failed\n");
            return -1;
        }

        gpioDelay(duration_ms * 1000);

        if (gpioPWM(BUZZER_PIN, 0) < 0) {
            fprintf(stderr, "Error: gpioPWM(0) failed\n");
            return -1;
        }

        gpioDelay(50 * 1000);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(BUZZER_PIN, 1000) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM(0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, EITHER_EDGE, DEBOUNCE_US, button_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed\n");
        gpioPWM(BUZZER_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Doorbell ready. Press the button (GPIO17) to play the melody.\n");

    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            printf("Button pressed! Playing melody...\n");
            if (play_melody() < 0) {
                fprintf(stderr, "Error: melody playback failed\n");
            }
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioPWM(BUZZER_PIN, 0);
    gpioSetISRFuncEx(BUTTON_PIN, EITHER_EDGE, DEBOUNCE_US, NULL, NULL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

