#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define VIBRATION_GPIO 17
#define EVENT_WINDOW_SIZE 5
#define POLL_TIMEOUT_DEFAULT 1000
#define LOG_FILE "vibration_events.log"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo);
}

static void log_event(int value) {
    char timestamp[32];
    get_iso8601_timestamp(timestamp, sizeof(timestamp));
    if (log_file) {
        if (fprintf(log_file, "%s, %d\n", timestamp, value) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        }
        if (fsync(fileno(log_file)) != 0) {
            fprintf(stderr, "Warning: fsync failed: %s\n", strerror(errno));
        }
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void print_earthquake_alert(void) {
    char timestamp[32];
    get_iso8601_timestamp(timestamp, sizeof(timestamp));
    printf("%s - EARTHQUAKE ALERT!\n", timestamp);
    fflush(stdout);
    if (log_file) {
        fprintf(log_file, "%s - EARTHQUAKE ALERT!\n", timestamp);
        fflush(log_file);
    }
}

int main(int argc, char *argv[]) {
    int poll_timeout = POLL_TIMEOUT_DEFAULT;
    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
        if (poll_timeout <= 0) {
            fprintf(stderr, "Invalid poll timeout. Using default: %d ms\n", POLL_TIMEOUT_DEFAULT);
            poll_timeout = POLL_TIMEOUT_DEFAULT;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(VIBRATION_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", VIBRATION_GPIO);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    int event_window[EVENT_WINDOW_SIZE] = {0};
    int window_index = 0;
    int high_count = 0;

    printf("Vibration monitoring started on GPIO %d. Press Ctrl+C to exit.\n", VIBRATION_GPIO);

    while (program_running) {
        int ret = gpioRead(VIBRATION_GPIO);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", VIBRATION_GPIO, strerror(errno));
            break;
        }

        int value = ret;
        log_event(value);

        event_window[window_index] = value;
        window_index = (window_index + 1) % EVENT_WINDOW_SIZE;
        if (value == 1) {
            high_count++;
        }

        if (high_count >= 3) {
            print_earthquake_alert();
        }

        gpioDelay(poll_timeout * 1000);
    }

    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return 0;
}

