#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LSM303_ADDR    0x0C
#define LSM303_CTRL_REG1 0x20
#define LSM303_CTRL_REG2 0x21
#define LSM303_CTRL_REG3 0x22
#define LSM303_CTRL_REG4 0x23
#define LSM303_OUT_X_L   0x28
#define LSM303_OUT_X_H   0x29
#define LSM303_OUT_Y_L   0x2A
#define LSM303_OUT_Y_H   0x2B
#define LSM303_OUT_Z_L   0x2C
#define LSM303_OUT_Z_H   0x2D

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lsm303(int fd) {
    if (i2c_write_reg(fd, LSM303_CTRL_REG1, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, LSM303_CTRL_REG2, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, LSM303_CTRL_REG3, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, LSM303_CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_regs(fd, LSM303_OUT_X_L, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void calibrate_data(int16_t x, int16_t y, int16_t z, int16_t *cx, int16_t *cy, int16_t *cz) {
    *cx = x - X_OFFSET;
    *cy = y - Y_OFFSET;
    *cz = z - Z_OFFSET;
}

static double calculate_heading(int16_t cx, int16_t cy) {
    double heading = atan2((double)cx, (double)cy) * 180.0 / M_PI;
    if (heading < 0) heading += 360.0;
    return heading;
}

static const char *determine_direction(double heading) {
    if (heading >= 337.5 || heading < 22.5) return "N";
    if (heading < 67.5) return "NE";
    if (heading < 112.5) return "E";
    if (heading < 157.5) return "SE";
    if (heading < 202.5) return "S";
    if (heading < 247.5) return "SW";
    if (heading < 292.5) return "W";
    return "NW";
}

static void log_data(FILE *fp, int16_t cx, int16_t cy, int16_t cz, double heading) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d, %d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, cx, cy, cz, heading);
    fflush(fp);
}

static void print_heading(double heading) {
    const char *dir = determine_direction(heading);
    printf("Heading: %.2f degrees -> %s\n", heading, dir);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LSM303_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_lsm303(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize LSM303DLHC\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_file = fopen("mag_log.csv", "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open mag_log.csv: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
        fflush(g_log_file);
    }

    int16_t raw_x, raw_y, raw_z;
    int16_t cx, cy, cz;
    double heading;

    while (g_running) {
        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
        } else {
            calibrate_data(raw_x, raw_y, raw_z, &cx, &cy, &cz);
            heading = calculate_heading(cx, cy);
            log_data(g_log_file, cx, cy, cz, heading);
            print_heading(heading);
        }
        sleep(1);
    }

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

