#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define GAP_DURATION 1
#define POLL_INTERVAL 10

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO%d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Failed to write GPIO%d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void deactivate_relays(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioWrite(pins[i], 1);
    }
}

static void irrigate(int relay_pin, int moisture_level) {
    if (gpioWrite(relay_pin, 0) != 0) {
        fprintf(stderr, "Failed to activate relay on GPIO%d\n", relay_pin);
        return;
    }
    sleep(IRRIGATION_DURATION);
    if (gpioWrite(relay_pin, 1) != 0) {
        fprintf(stderr, "Failed to deactivate relay on GPIO%d\n", relay_pin);
        return;
    }
    if (sleep(GAP_DURATION) == -1) {
        perror("sleep");
    }
}

static int log_irrigation(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Relay %d - Moisture Level: %d\n", timestamp, relay_number, moisture_level) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static int simulate_moisture_level(void) {
    return rand() % 101;
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open irrigation_log.txt");
        deactivate_relays();
        gpioTerminate();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = simulate_moisture_level();
        printf("Simulated Moisture Level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating relays.\n");
            int relay_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
            for (size_t i = 0; i < sizeof(relay_pins) / sizeof(relay_pins[0]); ++i) {
                if (log_irrigation(i + 1, moisture_level) != 0) {
                    fprintf(stderr, "Error logging irrigation for relay %d\n", i + 1);
                }
                irrigate(relay_pins[i], moisture_level);
            }
        }

        for (int i = 0; i < POLL_INTERVAL && running; ++i) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    deactivate_relays();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Smart Irrigation System stopped.\n");
    return 0;
}

