/*
 * Plant Watering System for Raspberry Pi Zero W
 * Two SG90 servos: valve on GPIO17, nozzle on GPIO18
 * Reads a simulated soil moisture value every 1 s.
 * When moisture < 50, opens valve (90 deg) then sweeps nozzle
 * 0, 45, 90, 135, 180 deg for 2 s each, sprays 5 s, closes valve,
 * waits 5 s, repeats.
 *
 * Build: gcc -Wall -Wextra -O2 -o watering watering.c -lthe_driver_lib -lrt
 */
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define VALVE_PIN      17
#define NOZZLE_PIN     18

#define SERVO_OPEN_PW  1500   /* ~90 deg  */
#define SERVO_CLOSE_PW 500    /* ~0 deg   */

#define MOISTURE_THRESHOLD 50

#define NUM_NOZZLE_ANGLES  5
static const int nozzle_angles[NUM_NOZZLE_ANGLES] = {0, 45, 90, 135, 180};
static const int nozzle_pw[NUM_NOZZLE_ANGLES]     = {500, 1000, 1500, 2000, 2500};

#define CYCLE_DELAY_US  5000000  /* 5 s between cycles */
#define SPRAY_DURATION_US 5000000 /* 5 s spray */
#define STEP_DELAY_US    2000000  /* 2 s per nozzle step */
#define RETRY_DELAY_US   100000   /* 100 ms backoff */
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only sets flag                 */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Open a servo to the given pulse width (microseconds).               */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int servo_open(int pin, int pw)
{
    if (gpioServo(pin, pw) < 0) {
        fprintf(stderr, "gpioServo(pin=%d, pw=%d) failed: %s\n",
                pin, pw, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Close a servo (0 degrees).                                         */
/* ------------------------------------------------------------------ */
static void servo_close(int pin)
{
    gpioServo(pin, SERVO_CLOSE_PW);
}

/* ------------------------------------------------------------------ */
/* Set a servo to a given pulse width.                                 */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int servo_set(int pin, int pw)
{
    if (servo_open(pin, pw) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Safely stop both servos: call gpioServo(pin, 0) then cleanup.       */
/* ------------------------------------------------------------------ */
static void stop_servos(void)
{
    gpioServo(VALVE_PIN, 0);
    gpioServo(NOZZLE_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Attempt a servo move with retries.                                 */
/* ------------------------------------------------------------------ */
static int servo_move(int pin, int pw, int angle)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (servo_set(pin, pw) == 0)
            return 0;
        fprintf(stderr, "servo_move(pin=%d, pw=%d, angle=%d) attempt %d/%d failed: %s\n",
                pin, pw, angle, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Simulated soil moisture: cycles 20, 40, 60, 80, 100 every 1 s.       */
/* ------------------------------------------------------------------ */
static int get_soil_moisture(void)
{
    static int moisture = 20;
    moisture = (moisture + 20) % 100;
    return moisture;
}

/* ------------------------------------------------------------------ */
/* Watering cycle                                                     */
/* ------------------------------------------------------------------ */
static void water_plant(void)
{
    printf("Watering plant...\n");

    /* Open valve */
    if (servo_move(VALVE_PIN, SERVO_OPEN_PW, 90) != 0) {
        fprintf(stderr, "Failed to open valve servo after %d retries.\n", MAX_RETRIES);
        stop_servos();
        return;
    }

    /* Nozzle sweep */
    for (int i = 0; i < NUM_NOZZLE_ANGLES; i++) {
        if (!g_running)
            break;

        if (servo_move(NOZZLE_PIN, nozzle_pw[i], nozzle_angles[i]) != 0) {
            fprintf(stderr, "Failed to set nozzle servo to angle %d after %d retries.\n",
                    nozzle_angles[i], MAX_RETRIES);
            stop_servos();
            return;
        }

        gpioDelay(STEP_DELAY_US);
    }

    /* Spray */
    gpioDelay(SPRAY_DURATION_US);

    /* Close valve */
    if (servo_move(VALVE_PIN, SERVO_CLOSE_PW, 0) != 0) {
        fprintf(stderr, "Failed to close valve servo after %d retries.\n", MAX_RETRIES);
        stop_servos();
        return;
    }

    printf("Watering cycle complete.\n");
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure pins */
    gpioSetMode(VALVE_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_PIN, PI_OUTPUT);

    /* Ensure servos start in a safe (closed) position */
    servo_close(VALVE_PIN);
    servo_close(NOZZLE_PIN);

    printf("Plant Watering System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture = get_soil_moisture();
        printf("Soil moisture: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            water_plant();
        }

        /* Wait 5 s between cycles (interruptible by signals) */
        for (int i = 0; i < 5 && g_running; i++)
            gpioDelay(CYCLE_DELAY_US / 5);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    stop_servos();
    gpioTerminate();
    return EXIT_SUCCESS;
}

