#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK_PIN 24
#define UNLOCK_PIN 23
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

#define STEPS_PER_REVOLUTION 512
#define STEP_DELAY_US 3000
#define DEBOUNCE_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_gpio_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int rotate_stepper(int direction) {
    int i;
    if (direction > 0) {
        for (i = 0; i < STEPS_PER_REVOLUTION; i++) {
            if (safe_gpio_write(IN1, 1) < 0) return -1;
            if (safe_gpio_write(IN2, 0) < 0) return -1;
            if (safe_gpio_write(IN3, 0) < 0) return -1;
            if (safe_gpio_write(IN4, 0) < 0) return -1;
            gpioDelay(STEP_DELAY_US);
            if (!running) return -1;
            if (safe_gpio_write(IN1, 0) < 0) return -1;
        }
    } else {
        for (i = 0; i < STEPS_PER_REVOLUTION; i++) {
            if (safe_gpio_write(IN1, 0) < 0) return -1;
            if (safe_gpio_write(IN2, 1) < 0) return -1;
            if (safe_gpio_write(IN3, 0) < 0) return -1;
            if (safe_gpio_write(IN4, 0) < 0) return -1;
            gpioDelay(STEP_DELAY_US);
            if (!running) return -1;
            if (safe_gpio_write(IN1, 0) < 0) return -1;
        }
    }
    return 0;
}

static int deenergize_coils(void) {
    int rc = 0;
    rc |= safe_gpio_write(IN1, 0);
    rc |= safe_gpio_write(IN2, 0);
    rc |= safe_gpio_write(IN3, 0);
    rc |= safe_gpio_write(IN4, 0);
    return rc;
}

static int read_button(int pin) {
    int v1 = gpioRead(pin);
    if (v1 < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", pin);
        return -1;
    }
    gpioDelay(DEBOUNCE_US);
    int v2 = gpioRead(pin);
    if (v2 < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return (v1 == 0 && v2 == 0) ? 1 : 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_gpio_set_mode(LOCK_PIN, PI_INPUT) < 0 ||
        safe_gpio_set_mode(UNLOCK_PIN, PI_INPUT) < 0 ||
        safe_gpio_set_mode(IN1, PI_OUTPUT) < 0 ||
        safe_gpio_set_mode(IN2, PI_OUTPUT) < 0 ||
        safe_gpio_set_mode(IN3, PI_OUTPUT) < 0 ||
        safe_gpio_set_mode(IN4, PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(LOCK_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_PIN, PI_PUD_UP);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
