static int safe_gpio_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int rotate_stepper(int direction) {
    int i;
