        for (i = 0; i < STEPS_PER_REVOLUTION; i++) {
            if (safe_gpio_write(IN1, 1) < 0) return -1;
            if (safe_gpio_write(IN2, 0) < 0) return -1;
            if (safe_gpio_write(IN3, 0) < 0) return -1;
            if (safe_gpio_write(IN4, 0) < 0) return -1;
