#include <unistd.h>
#include <errno.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  50000   /* 50 ms */
#define SAMPLE_US   1000000 /* 1 s  */
#define TRIGGER_US  10
#define SETTLE_US  200000   /* 200 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in mm.
 * Returns >= 0 on success, -1 on timeout or error.
 */
static int measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 0) failed\n");
        return -1;
    }
    gpioDelay(SETTLE_US);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 0) failed\n");
        return -1;
    }

    /* Wait for echo rising edge */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    /* speed of sound ~343 m/s => 0.0343 mm/µs; round trip => /2 */
    return (int)((double)diff * 0.0343 / 2.0);
}

static void log_distance(int distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log, "%s, %d\n", timestamp, distance) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    fflush(g_log);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
