        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 0) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(SETTLE_US);

    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int distance = measure_distance();
        log_distance(distance);
        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

