#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_PIN      18
#define DISTANCE_THRESHOLD_CM 50
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_SOFT_RESET       0x0000
#define VL53L1X_SYSTEM_MODE      0x0001
#define VL53L1X_RANGE_START      0x0002
#define VL53L1X_RESULT_INT_STAT  0x0004
#define VL53L1X_RESULT_RANGE_STATUS 0x0006
#define VL53L1X_RESULT_DISTANCE  0x0008

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by a 16-bit value (big-endian). */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register address followed by 2 bytes (big-endian). */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char addr_buf[2];
    char data_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr_buf, 2) < 0)
        return -1;

    if (i2cReadDevice(handle, data_buf, 2) != 2)
        return -1;

    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write_reg16(handle, VL53L1X_SOFT_RESET, 0x0000) < 0) {
        fprintf(stderr, "Error: VL53L1X soft reset write failed.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Clear any pending interrupt */
    uint16_t int_stat = 0;
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_INT_STAT, &int_stat) < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status.\n");
        return -1;
    }

    /* Start continuous ranging */
    if (vl53l1x_write_reg16(handle, VL53L1X_RANGE_START, 0x0001) < 0) {
        fprintf(stderr, "Error: VL53L1X range start write failed.\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t range_status = 0;

    /* Check if new data is available */
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, &range_status) < 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }

    if ((range_status & 0x01) == 0) {
        /* No new data yet */
        return 1;
    }

    /* Read distance */
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_DISTANCE, distance_mm) < 0) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        return -1;
    }

    /* Clear interrupt */
    if (vl53l1x_write_reg16(handle, VL53L1X_RESULT_INT_STAT, 0x0001) < 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt.\n");
    }

    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d).\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", RELAY_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance_mm = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            int distance_cm = (int)(distance_mm / 10);
            printf("Distance: %d cm\n", distance_cm);

            if (distance_cm <= DISTANCE_THRESHOLD_CM) {
                gpioWrite(RELAY_PIN, 1);
            } else {
                gpioWrite(RELAY_PIN, 0);
            }
        } else if (rc < 0) {
            /* I2C error — ensure relay is off for safety */
            gpioWrite(RELAY_PIN, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

