        fprintf(stderr, "Error: VL53L1X soft reset write failed.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Clear any pending interrupt */
    uint16_t int_stat = 0;
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_INT_STAT, &int_stat) < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status.\n");
        return -1;
    }

    /* Start continuous ranging */
    if (vl53l1x_write_reg16(handle, VL53L1X_RANGE_START, 0x0001) < 0) {
        fprintf(stderr, "Error: VL53L1X range start write failed.\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t range_status = 0;

    /* Check if new data is available */
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, &range_status) < 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }

    if ((range_status & 0x01) == 0) {
        /* No new data yet */
        return 1;
    }

    /* Read distance */
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_DISTANCE, distance_mm) < 0) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        return -1;
    }

    /* Clear interrupt */
    if (vl53l1x_write_reg16(handle, VL53L1X_RESULT_INT_STAT, 0x0001) < 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt.\n");
    }

    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d).\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", RELAY_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance_mm = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            int distance_cm = (int)(distance_mm / 10);
            printf("Distance: %d cm\n", distance_cm);

            if (distance_cm <= DISTANCE_THRESHOLD_CM) {
                gpioWrite(RELAY_PIN, 1);
            } else {
                gpioWrite(RELAY_PIN, 0);
            }
        } else if (rc < 0) {
            /* I2C error — ensure relay is off for safety */
            gpioWrite(RELAY_PIN, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

