#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Wake up the MPU-6050 (clear sleep bit in PWR_MGMT_1) */
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "MPU-6050 not responding at address 0x%02X. Check wiring and power.\n", MPU6050_ADDR);
        goto cleanup;
    }

    /* Allow oscillator to stabilize after wake-up */
    usleep(100000);

    printf("MPU-6050 Gyroscope Reader\n");
    printf("Reading angular velocity (x, y, z) every 100 ms...\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        uint8_t buf[6];
        int16_t gyro_x, gyro_y, gyro_z;

        if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
            usleep(100000);
            continue;
        }

        gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
        gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
        gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Gyroscope: X = %6d, Y = %6d, Z = %6d\n", gyro_x, gyro_y, gyro_z);
        fflush(stdout);

        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

