#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define POLL_INTERVAL_SEC 60
#define CYCLE_DURATION_SEC 86400
#define RELAY_ON_TIME_SEC 5

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(int idx, int value) {
    if (gpiod_line_set_value(lines[idx], value) < 0) {
        fprintf(stderr, "Error setting GPIO%u: %s\n", relay_pins[idx], strerror(errno));
        return -1;
    }
    return 0;
}

static int water_plant(int idx) {
    if (set_relay(idx, 0) < 0) return -1;
    time_t start = time(NULL);
    if (start == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    for (int i = 0; i < RELAY_ON_TIME_SEC && running; i++) {
        sleep(1);
    }
    if (set_relay(idx, 1) < 0) return -1;
    if (running) {
        time_t end = time(NULL);
        if (end == (time_t)-1) {
            fprintf(stderr, "time() failed: %s\n", strerror(errno));
            return -1;
        }
        double elapsed = difftime(end, start);
        if (elapsed < RELAY_ON_TIME_SEC) {
            fprintf(stderr, "Watering time exceeded for plant %d\n", idx + 1);
            return -1;
        }
    }
    return 0;
}

static int log_cycle_start(void) {
    FILE *fp = fopen("watering_log.txt", "w");
    if (!fp) {
        fprintf(stderr, "Error opening watering_log.txt: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    struct tm *tm = localtime(&t);
    if (!tm) {
        fprintf(stderr, "localtime() failed\n");
        fclose(fp);
        return -1;
    }
    char buf[64];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s\n", buf) < 0) {
        fprintf(stderr, "Error writing to watering_log.txt: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing watering_log.txt: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO%u: %s\n", relay_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(lines[i], "plant-watering", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO%u as output: %s\n", relay_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    if (log_cycle_start() < 0) {
        cleanup();
        return 1;
    }

    time_t next_cycle = time(NULL);
    if (next_cycle == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        next_cycle += CYCLE_DURATION_SEC;
        if (next_cycle < time(NULL)) {
            next_cycle = time(NULL);
        }
        for (int i = 0; i < NUM_RELAYS && running; i++) {
            if (water_plant(i) < 0) {
                fprintf(stderr, "Error watering plant %d\n", i + 1);
            }
        }
    }

    cleanup();
    return 0;
}

