#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_GYRO_YOUT_H  0x45
#define MPU6050_GYRO_ZOUT_H  0x47

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 17

/* Angular velocity threshold (degrees/second) */
#define ANGULAR_VELOCITY_THRESHOLD 250.0f

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Sampling period (microseconds) — 20 Hz */
#define SAMPLE_PERIOD_US 50000

/* Structure to hold gyroscope data */
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

/* Circular buffer structure */
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* Global variables */
static int i2c_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int init_i2c(void);
static int read_gyro_data(gyro_data_t *data);
static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
static void check_threshold(gyro_data_t data);
static void signal_handler(int signal);
static void cleanup(void);

/* Initialize the circular buffer */
static void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

/* Initialize I2C communication with the MPU-6050 */
static int init_i2c(void) {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* Read raw gyroscope data from the MPU-6050 */
static int read_gyro_data(gyro_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    int16_t x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t z = (int16_t)((buffer[4] << 8) | buffer[5]);

    data->x = (float)x;
    data->y = (float)y;
    data->z = (float)z;

    clock_gettime(CLOCK_REALTIME, &data->timestamp);

    return 0;
}

/* Add data to the circular buffer */
static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

/* Check if the angular velocity exceeds the threshold */
static void check_threshold(gyro_data_t data) {
    if (fabsf(data.x) > ANGULAR_VELOCITY_THRESHOLD ||
        fabsf(data.y) > ANGULAR_VELOCITY_THRESHOLD ||
        fabsf(data.z) > ANGULAR_VELOCITY_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Initialize circular buffer */
    init_circular_buffer(&gyro_buffer);

    /* Set up signal handling */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gyro_data_t gyro_data;
    int reinit_count = 0;

    /* Main loop */
    while (program_running) {
        if (read_gyro_data(&gyro_data) == 0) {
            add_to_buffer(&gyro_buffer, gyro_data);
            check_threshold(gyro_data);
        } else {
            fprintf(stderr, "Error reading gyro data. Attempting re-initialization...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            if (init_i2c() != 0) {
                reinit_count++;
                if (reinit_count >= 3) {
                    fprintf(stderr, "Failed to re-initialize I2C after 3 attempts. Exiting.\n");
                    program_running = 0;
                }
            } else {
                reinit_count = 0;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup and exit */
    cleanup();
    return 0;
}

