#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define CS_LINE_OFFSET 8
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define LOG_FILE "gyro_log.txt"
#define READ_INTERVAL_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int spi_fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_gyro_data(int spi_fd, struct gpiod_line *cs_line,
                         int16_t *x_rate, int16_t *y_rate, int16_t *z_rate) {
    uint8_t tx[6] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx[6] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
            usleep(1000);
            continue;
        }

        if (spi_transfer(spi_fd, tx, rx, sizeof(tx)) < 0) {
            fprintf(stderr, "SPI transfer failed (attempt %d): %s\n",
                    attempt + 1, strerror(errno));
            gpiod_line_set_value(cs_line, 1);
            usleep(1000);
            continue;
        }

        if (gpiod_line_set_value(cs_line, 1) < 0) {
            fprintf(stderr, "Failed to deassert CS line: %s\n", strerror(errno));
            usleep(1000);
            continue;
        }

        *x_rate = (int16_t)((rx[0] << 8) | rx[1]);
        *y_rate = (int16_t)((rx[2] << 8) | rx[3]);
        *z_rate = (int16_t)((rx[4] << 8) | rx[5]);
        return 0;
    }

    fprintf(stderr, "Failed to read gyro data after %d attempts.\n", MAX_RETRIES);
    return -1;
}

static int log_data(FILE *fp, const char *timestamp,
                    int16_t x_rate, int16_t y_rate, int16_t z_rate) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    int spi_fd = -1;
    FILE *fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        goto cleanup_gpio;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup_gpio;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup_gpio;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup_spi;
    }

    printf("Starting MPU-9250 gyroscope logging to %s...\n", LOG_FILE);

    while (running) {
        int16_t x_rate, y_rate, z_rate;
        struct timespec ts;
        char timestamp[40];

        if (read_gyro_data(spi_fd, cs_line, &x_rate, &y_rate, &z_rate) == 0) {
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                struct tm tm_info;
                localtime_r(&ts.tv_sec, &tm_info);
