#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define GYRO_THRESHOLD 200.0f
#define WARNING_LED_PIN 17
#define BUFFER_SIZE 64
#define SAMPLE_INTERVAL_US 10000

#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

static gyro_data_t buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(int handle, uint8_t reg_high, uint8_t reg_low, uint16_t *value) {
    char tx[2] = { (char)reg_high, (char)reg_low };
    char rx[2] = {0};
    if (spiXfer(handle, tx, rx, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

static int read_gyro_data(int handle, float *x, float *y, float *z) {
    uint16_t raw_x, raw_y, raw_z;
    if (spi_read_register(handle, GYRO_XOUT_H, GYRO_XOUT_L, &raw_x) != 0) return -1;
    if (spi_read_register(handle, GYRO_YOUT_H, GYRO_YOUT_L, &raw_y) != 0) return -1;
    if (spi_read_register(handle, GYRO_ZOUT_H, GYRO_ZOUT_L, &raw_z) != 0) return -1;

    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;
    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    buffer[buffer_index].timestamp = clock();
    buffer[buffer_index].x = x;
    buffer[buffer_index].y = y;
    buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        struct tm *tm_info = localtime(&buffer[idx].timestamp.tv_sec);
        char time_str[32];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s.%09ld,%.2f,%.2f,%.2f\n", time_str, buffer[idx].timestamp.tv_nsec, buffer[idx].x, buffer[idx].y, buffer[idx].z);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(WARNING_LED_PIN, PI_OUTPUT);
    gpioWrite(WARNING_LED_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("MPU-6050 SPI monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float x, y, z;
        if (read_gyro_data(spi_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "SPI read error\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        add_to_buffer(x, y, z);

        if (x > GYRO_THRESHOLD || x < -GYRO_THRESHOLD ||
            y > GYRO_THRESHOLD || y < -GYRO_THRESHOLD ||
            z > GYRO_THRESHOLD || z < -GYRO_THRESHOLD) {
            gpioWrite(WARNING_LED_PIN, 1);
            gpioDelay(500000);
            gpioWrite(WARNING_LED_PIN, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(WARNING_LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    print_buffer();
    printf("Program terminated.\n");
    return 0;
}

