#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43

/* Sensitivity scale factors (±2g, ±250 deg/s) */
#define ACCEL_SCALE 16384.0f
#define GYRO_SCALE  131.0f

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 21

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 45.0f

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 100000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int  init_mpu6050(void);
static int  read_accel_data(int16_t *ax, int16_t *ay, int16_t *az);
static int  read_gyro_data(int16_t *gx, int16_t *gy, int16_t *gz);
static void calculate_tilt(int16_t ax, int16_t ay, int16_t az,
                           int16_t gx, int16_t gy, int16_t gz,
                           float *roll, float *pitch);
static void log_data(float roll, float pitch);
static void control_led(float roll, float pitch);
static void signal_handler(int sig);

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts OFF */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Initialize MPU-6050 */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for SIGINT (Ctrl+C) */
    signal(SIGINT, signal_handler);

    int16_t ax, ay, az, gx, gy, gz;
    float roll, pitch;

    /* Main loop */
    while (!terminate) {
        if (read_accel_data(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Warning: accelerometer read failed\n");
        } else if (read_gyro_data(&gx, &gy, &gz) != 0) {
            fprintf(stderr, "Warning: gyroscope read failed\n");
        } else {
            calculate_tilt(ax, ay, az, gx, gy, gz, &roll, &pitch);
            log_data(roll, pitch);
            control_led(roll, pitch);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

/* Initialize MPU-6050: wake up, set range to +/-2g */
static int init_mpu6050(void)
{
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Set accelerometer range to +/-2g (AFS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x08) < 0) {
        fprintf(stderr, "Error: failed to set accelerometer range\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* Read accelerometer data (6 bytes starting at ACCEL_XOUT_H) */
static int read_accel_data(int16_t *ax, int16_t *ay, int16_t *az)
{
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, MPU6050_ACCEL_XOUT_H, buf, 6) != 6) {
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Read gyroscope data (6 bytes starting at GYRO_XOUT_H) */
static int read_gyro_data(int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6) != 6) {
        return -1;
    }
    *gx = (int16_t)((buf[0] << 8) | buf[1]);
    *gy = (int16_t)((buf[2] << 8) | buf[3]);
    *gz = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Calculate roll and pitch from accelerometer data */
static void calculate_tilt(int16_t ax, int16_t ay, int16_t az,
                           int16_t gx, int16_t gy, int16_t gz,
                           float *roll, float *pitch)
{
    /* Convert raw to g's and degrees/s */
    float ax_g = (float)ax / ACCEL_SCALE;
    float ay_g = (float)ay / ACCEL_SCALE;
    float az_g = (float)az / ACCEL_SCALE;
    float gx_dps = (float)gx / GYRO_SCALE;
    float gy_dps = (float)gy / GYRO_SCALE;
    float gz_dps = (float)gz / GYRO_SCALE;

    /* Roll: tilt around X axis */
    *roll = atan2f(ay_g, az_g) * 180.0f / (float)M_PI;

    /* Pitch: tilt around Y axis */
    *pitch = atan2f(-ax_g, sqrtf(ay_g * ay_g + az_g * az_g)) * 180.0f / (float)M_PI;
}

/* Log data to CSV file */
static void log_data(float roll, float pitch)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open tilt_log.txt for appending\n");
        return;
    }
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);
}

/* Control LED based on tilt */
static void control_led(float roll, float pitch)
{
    bool tilt_detected = (fabsf(roll) > TILT_THRESHOLD) ||
                         (fabsf(pitch) > TILT_THRESHOLD);
    gpioWrite(LED_PIN, tilt_detected ? 1 : 0);
}

/* Signal handler for SIGINT */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

