#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXRS290 Register Addresses */
#define ADXRS290_REG_XGYRO_OUT 0x00
#define ADXRS290_REG_YGYRO_OUT 0x02
#define ADXRS290_REG_TEMP_OUT  0x04
#define ADXRS290_REG_DIAG_STAT 0x06
#define ADXRS290_REG_CTRL      0x08

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0

/* Sampling */
#define SAMPLE_DELAY_US 10000  /* 10 ms -> ~100 Hz */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a 16-bit register from the ADXRS290 via SPI.
   Returns 0 on success, -1 on failure. */
static int read_register(uint8_t reg, int16_t *value) {
    char tx[3] = { (char)(reg | 0x80), 0x00, 0x00 };
    char rx[3] = { 0, 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = (int16_t)(((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[2]);
    return 0;
}

/* Write a 16-bit register to the ADXRS290 via SPI.
   Returns 0 on success, -1 on failure. */
static int write_register(uint8_t reg, uint16_t value) {
    char tx[3] = { (char)(reg & 0x7F), (char)((value >> 8) & 0xFF), (char)(value & 0xFF) };
    char rx[3] = { 0, 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* Initialize the ADXRS290: set full-scale range to +/-250 dps,
   enable both axes, and verify the device is present by reading
   the temperature register. */
static int initialize_gyro(void) {
    /* Set full-scale range to +/-250 dps (FS = 0x00) */
    if (write_register(ADXRS290_REG_CTRL, 0x0000) != 0) {
        fprintf(stderr, "Failed to set full-scale range\n");
        return -1;
    }

    /* Enable X and Y axes (bits 0 and 1 of CTRL register) */
    if (write_register(ADXRS290_REG_CTRL, 0x0003) != 0) {
        fprintf(stderr, "Failed to enable X/Y axes\n");
        return -1;
    }

    /* Verify device presence by reading TEMP_OUT register */
    int16_t temp;
    if (read_register(ADXRS290_REG_TEMP_OUT, &temp) != 0) {
        fprintf(stderr, "Gyroscope not responding on SPI\n");
        return -1;
    }

    printf("ADXRS290 initialized successfully (temp=%d mdeg/s)\n", temp);
    return 0;
}

/* Log a sample to the CSV file */
static int log_data(FILE *f, struct timespec ts, int16_t x, int16_t y) {
    if (fprintf(f, "%ld.%06ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, x, y) < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }
    if (fflush(f) != 0) {
        fprintf(stderr, "Error flushing CSV file\n");
        return -1;
    }
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 (CE0 on GPIO8) at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the gyroscope */
    if (initialize_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file for appending */
    fp = fopen("gyro_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening gyro_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler\n");
    }

    printf("Logging gyro data to gyro_data.csv (Ctrl+C to stop)...\n");

    /* Main sampling loop */
    while (running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            fprintf(stderr, "clock_gettime failed\n");
            break;
        }

        int16_t x_rate, y_rate;

        if (read_register(ADXRS290_REG_XGYRO_OUT, &x_rate) != 0 ||
            read_register(ADXRS290_REG_YGYRO_OUT, &y_rate) != 0) {
            fprintf(stderr, "Error reading gyro data, attempting re-initialization...\n");
            spiClose(spi_handle);
            spi_handle = -1;
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
            if (spi_handle < 0) {
                fprintf(stderr, "SPI re-open failed: %d\n", spi_handle);
                break;
            }
            if (initialize_gyro() != 0) {
                fprintf(stderr, "Gyro re-initialization failed, exiting\n");
                break;
            }
            continue;
        }

        if (log_data(fp, ts, x_rate, y_rate) != 0) {
            fprintf(stderr, "Error logging data, exiting\n");
            break;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

