#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17
#define ALERT_DURATION_MS 2000
#define ALERT_INTERVAL_MS 500
#define DEBOUNCE_MS 50
#define LOG_FILE "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (level == 1) {
        static uint32_t last_tick[2] = {0, 0};
        uint32_t now = gpioTick();
        if (now - last_tick[gpio - SENSOR_1_PIN] > DEBOUNCE_MS * 1000) {
            last_tick[gpio - SENSOR_1_PIN] = now;
            if (gpioWrite(ALERT_PIN, 1) != 0) {
                fprintf(stderr, "Failed to set alert pin HIGH\n");
            }
            time_t rawtime = time(NULL);
            struct tm *timeinfo = localtime(&rawtime);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            if (log_file) {
                fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
                fflush(log_file);
            }
            printf("%s - Seismic event detected!\n", timestamp);
            gpioDelay(ALERT_DURATION_MS * 1000);
            if (gpioWrite(ALERT_PIN, 0) != 0) {
                fprintf(stderr, "Failed to set alert pin LOW\n");
            }
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize alert pin LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_1_PIN, sensor_callback) != 0 ||
        gpioSetAlertFunc(SENSOR_2_PIN, sensor_callback) != 0) {
        fprintf(stderr, "Failed to set alert functions\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
