#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXRS290 Register Addresses */
#define ADXRS290_REG_XGYRO_OUT 0x00
#define ADXRS290_REG_TEMP_OUT  0x01

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0: CPOL=0, CPHA=0 */

/* GPIO Configuration */
#define LED_PIN 17

/* Threshold and buffer configuration */
#define THRESHOLD_DEG_PER_SEC 20.0
#define BUFFER_SIZE 100

/* Data structure for gyroscope readings */
typedef struct {
    struct timespec timestamp;
    double x_rate;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t circular_buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_count = 0;

/* SPI handle */
static int spi_handle = -1;

/* Flag to signal program termination */
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int spi_init(void);
static int spi_read_register(uint8_t reg, uint16_t *value);
static int read_gyro_data(double *x_rate);
static void add_to_buffer(struct timespec ts, double x_rate);
static void check_threshold(double x_rate);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Initialize the SPI interface.
 * Returns 0 on success, -1 on failure.
 */
static int spi_init(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n",
                SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit register from the ADXRS290.
 * The MSB of the register address (bit 7) must be set to 1 for a read.
 * Returns 0 on success, -1 on failure.
 */
static int spi_read_register(uint8_t reg, uint16_t *value) {
    char tx_buf[3];
    char rx_buf[3];

    /* Build the SPI message: [reg | 0x80] [0x00] [0x00] */
    tx_buf[0] = (char)(reg | 0x80);
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error during SPI transfer: %s\n",
                pigpio_error(result));
        return -1;
    }

    /* The first byte received is the register address echoed back */
    uint8_t echo = (uint8_t)rx_buf[1];
    if (echo != (reg | 0x80)) {
        fprintf(stderr, "SPI echo mismatch: expected 0x%02X, got 0x%02X\n",
                reg | 0x80, echo);
        return -1;
    }

    /* The second and third bytes are the data payload (little-endian) */
    *value = (uint16_t)(((uint8_t)rx_buf[2] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

/*
 * Read the X-axis angular rate from the ADXRS290.
 * Returns 0 on success, -1 on failure.
 */
static int read_gyro_data(double *x_rate) {
    uint16_t raw_x;
    if (spi_read_register(ADXRS290_REG_XGYRO_OUT, &raw_x) != 0) {
        return -1;
    }

    /*
     * Convert raw LSBs to degrees per second.
     * The ADXRS290 outputs 16-bit data at 100 Hz.
     * Sensitivity is 0.0000625 deg/s/LSB (12-bit effective range).
     */
    *x_rate = (double)raw_x * 0.0000625;
    return 0;
}

/*
 * Add a reading to the circular buffer.
 */
static void add_to_buffer(struct timespec ts, double x_rate) {
    circular_buffer[buffer_head].timestamp = ts;
    circular_buffer[buffer_head].x_rate = x_rate;

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

/*
 * Check if the X-axis angular rate exceeds the threshold.
 */
static void check_threshold(double x_rate) {
    if (x_rate > THRESHOLD_DEG_PER_SEC) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/*
 * Cleanup resources before exiting.
 */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Initialize SPI */
    if (spi_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        struct timespec ts;
        double x_rate;

        if (read_gyro_data(&x_rate) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_to_buffer(ts, x_rate);
            check_threshold(x_rate);
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        /* Sleep for 10 milliseconds */
        gpioDelay(10000);
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

