#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27
#define PWM_FREQ 100
#define PWM_RANGE 255
#define MIN_BRIGHTNESS 0
#define MAX_BRIGHTNESS 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_lamp_brightness(int pin, int brightness) {
    if (brightness < MIN_BRIGHTNESS || brightness > MAX_BRIGHTNESS) {
        fprintf(stderr, "Error: brightness %d out of range [%d, %d]\n",
                brightness, MIN_BRIGHTNESS, MAX_BRIGHTNESS);
        return -1;
    }
    if (gpioPWM(pin, brightness) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void turn_off_lamps(void) {
    int pins[3] = {LAMP1_PIN, LAMP2_PIN, LAMP3_PIN};
    for (int i = 0; i < 3; i++) {
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Warning: gpioPWM off failed on pin %d\n", pins[i]);
        }
    }
}

static void cleanup(void) {
    turn_off_lamps();
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_seconds>\n", argv[0]);
        fprintf(stderr, "  total_seconds: fade duration in seconds (1-3600)\n");
        return EXIT_FAILURE;
    }

    char *endptr;
    long total_seconds = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || total_seconds < 1 || total_seconds > 3600) {
        fprintf(stderr, "Error: invalid duration '%s'. Must be an integer between 1 and 3600.\n", argv[1]);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[3] = {LAMP1_PIN, LAMP2_PIN, LAMP3_PIN};
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed on pin %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed on pin %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (set_lamp_brightness(pins[i], MAX_BRIGHTNESS) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sunset simulator started. Total duration: %ld seconds.\n", total_seconds);
    printf("Fading lamps sequentially. Press Ctrl+C to exit early.\n");

    int current_lamp = 0;
    int elapsed = 0;

    while (running && elapsed < total_seconds) {
        int brightness = MAX_BRIGHTNESS;
        if (set_lamp_brightness(pins[current_lamp], brightness) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        printf("Lamp %d (pin %d): fading to %d%% (brightness %d)\n",
               current_lamp + 1, pins[current_lamp], brightness, brightness);

        for (int i = 0; i < PWM_RANGE && running; i++) {
            brightness -= 1;
            if (brightness < 0) brightness = 0;
            if (set_lamp_brightness(pins[current_lamp], brightness) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            time_sleep(1.0 / PWM_FREQ);
        }

        current_lamp = (current_lamp + 1) % 3;
        elapsed = (int)(1.0 / PWM_FREQ);
    }

    printf("\nSunset simulation complete.\n");
    cleanup();
    return EXIT_SUCCESS;
}

