#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5C
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define POLL_DELAY_US 10000

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_ELE0_T_THRESH 0x41
#define MPR121_ELE0_R_THRESH 0x42

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void log_error(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s (errno: %d - %s)\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message, errno, strerror(errno));
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d", reg, value, rc);
        log_error(msg);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_ELE0_T_THRESH, 0x0F) < 0) return -1;
    if (mpr121_write_reg(MPR121_ELE0_R_THRESH, 0x0A) < 0) return -1;
    if (mpr121_write_reg(MPR121_ECR, 0x8F) < 0) return -1;
    return 0;
}

static int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read failed: rc=%d", rc);
        log_error(msg);
        return -1;
    }
    *touch_status = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void toggle_relay(void) {
    int current_state = gpioRead(RELAY_GPIO);
    if (current_state < 0) {
        log_error("Failed to read relay GPIO state");
        return;
    }
    if (gpioWrite(RELAY_GPIO, !current_state) < 0) {
        log_error("Failed to write relay GPIO");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C open failed: handle=%d", i2c_handle);
        log_error(msg);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        log_error("MPR121 initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set relay GPIO mode");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t touch_status;
    bool relay_state = false;
    uint32_t last_touch_time = 0;

    while (running) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status & (1 << 0)) {
                uint32_t now = gpioTick();
                if (now - last_touch_time > DEBOUNCE_DELAY_MS * 1000) {
                    last_touch_time = now;
                    relay_state = !relay_state;
                    toggle_relay();
                    printf("Electrode 0 touched. Relay toggled to %s\n", relay_state ? "ON" : "OFF");
                }
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

