#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

// PID constants
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Control loop period in microseconds
#define LOOP_PERIOD_US 50000

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// PID state
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
void set_motor_speed(int motor_a_speed, int motor_b_speed);
double calculate_tilt_error(void);
double calculate_distance(void);
void obstacle_avoidance(void);
void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);

// Set motor speeds with clamping
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    if (motor_a_speed < -255) motor_a_speed = -255;
    if (motor_a_speed > 255) motor_a_speed = 255;
    if (motor_b_speed < -255) motor_b_speed = -255;
    if (motor_b_speed > 255) motor_b_speed = 255;

    gpioWrite(MOTOR_A_FORWARD, (motor_a_speed > 0) ? 1 : 0);
    gpioWrite(MOTOR_A_BACKWARD, (motor_a_speed < 0) ? 1 : 0);
    gpioWrite(MOTOR_A_ENABLE, 1);

    gpioWrite(MOTOR_B_FORWARD, (motor_b_speed > 0) ? 1 : 0);
    gpioWrite(MOTOR_B_BACKWARD, (motor_b_speed < 0) ? 1 : 0);
    gpioWrite(MOTOR_B_ENABLE, 1);

    gpioPWM(MOTOR_A_ENABLE, abs(motor_a_speed));
    gpioPWM(MOTOR_B_ENABLE, abs(motor_b_speed));
}

// Calculate tilt error (simulated)
double calculate_tilt_error(void) {
    return (double)rand() / RAND_MAX * 20.0 - 10.0;
}

// Calculate distance (simulated)
double calculate_distance(void) {
    return 2.0 + (double)rand() / RAND_MAX * 398.0;
}

// Obstacle avoidance: reverse both motors at 50% speed
void obstacle_avoidance(void) {
    set_motor_speed(-128, -128);
}

// Log data to file
void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    // Initialize PWM range to 255
    gpioSetPWMrange(MOTOR_A_ENABLE, 255);
    gpioSetPWMrange(MOTOR_B_ENABLE, 255);

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Seed random number generator
    srand(time(NULL));

    // Main control loop
    while (running) {
        // Calculate tilt error and distance
        double tilt_error = calculate_tilt_error();
        double distance = calculate_distance();

        // PID control
        double error = tilt_error;
        double derivative = error - previous_error;
        integral += error;

        double output = KP * error + KI * integral + KD * derivative;

        // Motor speeds
        int motor_a_speed = (int)output;
        int motor_b_speed = (int)output;

        // Obstacle avoidance if distance is too close
        if (distance < 20.0) {
            obstacle_avoidance();
            motor_a_speed = 0;
            motor_b_speed = 0;
        } else {
            set_motor_speed(motor_a_speed, motor_b_speed);
        }

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Update previous error
        previous_error = error;

        // Wait for next control cycle
        gpioDelay(LOOP_PERIOD_US);
    }

    // Cleanup
    set_motor_speed(0, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

