        }

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Update previous error
        previous_error = error;

        // Wait for next control cycle
        gpioDelay(LOOP_PERIOD_US);
    }

    // Cleanup
    set_motor_speed(0, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

