#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms in microseconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed. "
                        "Ensure pigpiod is not running and you have root privileges.\n");
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input with pull-down */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts de-energized */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_touch_state = 0;

    printf("Monitoring TTP223 touch sensor on GPIO%d and relay on GPIO%d. "
           "Press Ctrl+C to exit.\n", TOUCH_SENSOR_PIN, RELAY_PIN);

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        /* Detect rising edge: transition from LOW to HIGH */
        if (touch_state == 1 && last_touch_state == 0) {
            /* Debounce: wait and re-read */
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirmed_state = gpioRead(TOUCH_SENSOR_PIN);
            if (confirmed_state < 0) {
                fprintf(stderr, "Error: failed to read GPIO%d during debounce.\n",
                        TOUCH_SENSOR_PIN);
                break;
            }
            if (confirmed_state == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: failed to write GPIO%d.\n", RELAY_PIN);
                    break;
                }
                printf("Touch detected! Relay toggled to state: %d\n", relay_state);
            }
        }

        last_touch_state = touch_state;
        gpioDelay(10000);  /* 10 ms poll interval */
    }

    /* Ensure relay is de-energized on exit */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

