/*
 * mood_light.c — Raspberry Pi 3 Model B+
 *
 * Captures audio at 8 kHz mono via ALSA, computes RMS amplitude, and
 * drives a common-cathode RGB LED (red=GPIO17, green=GPIO18, blue=GPIO27)
 * with software PWM whose brightness maps the amplitude.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lasound
 * Run:    ./mood_light [sensitivity 0.0..1.0]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

#include <pigpio.h>

#define RED_PIN      17
#define GREEN_PIN    18
#define BLUE_PIN     27

#define DEFAULT_SAMPLE_RATE  8000
#define DEFAULT_PERIOD_FRAMES 1024
#define DEFAULT_SENSITIVITY   1.0f
#define DEFAULT_LED_PERIOD_US 10000   /* 10 ms */

#define NUM_CHANNELS 1
#define BITS_PER_SAMPLE 16
#define ALSA_FORMAT  SND_FORMAT_S16_LE

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* ALSA helpers (ALSA_AVAILABLE)                                     */
/* ------------------------------------------------------------------ */
#ifdef ALSA_AVAILABLE

static snd_pcm_t *g_pcm = NULL;

static int snd_pcm_init(void)
{
    snd_pcm_hw_params_t *hw;
    snd_pcm_stream_t *stream;
    int err;

    err = snd_pcm_open(&g_pcm, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_open failed: %s\n", snd_errmsg(err));
        return -1;
    }

    err = snd_pcm_hw_params_alloca(&g_pcm->hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_alloca failed\n");
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_any(g_pcm, g_pcm->hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_any failed: %s\n", snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_access(g_pcm, g_pcm->hw_params,
                                       SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_access failed: %s\n",
                snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_format(g_pcm, g_pcm->hw_params, ALSA_FORMAT);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_format failed: %s\n",
                snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_rate_near(g_pcm, g_pcm->hw_params,
                                          &DEFAULT_SAMPLE_RATE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near failed: %s\n",
                snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_channels(g_pcm, g_pcm->hw_params,
                                         NUM_CHANNELS);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels failed: %s\n",
                snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_period_size_near(g_pcm, g_pcm->hw_params,
                                                 &DEFAULT_PERIOD_FRAMES, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_period_size_near failed: %s\n",
                snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_hw_params(g_pcm, g_pcm->hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params failed: %s\n", snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_prepare(g_pcm);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_stream_open(g_pcm, &stream, NULL, NULL);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_stream_open failed: %s\n", snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    return 0;
}

static void snd_pcm_cleanup(void)
{
    if (g_pcm != NULL) {
        snd_pcm_drain(g_pcm);
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
    }
}

static int snd_pcm_read(short *buffer, int frame_count)
{
    int err;

    err = snd_pcm_readi(g_pcm, buffer, frame_count);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_errmsg(err));
        return -1;
    }
    if (err != frame_count) {
        fprintf(stderr, "snd_pcm_readi short read: %d of %d\n", err, frame_count);
        return -1;
    }
    return 0;
}

static int snd_pcm_resume(void)
{
    int err;

    err = snd_pcm_resume(g_pcm);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_resume failed: %s\n", snd_errmsg(err));
        return -1;
    }
    return 0;
}

#else

/*
 * ALSA unavailable — simulate audio with a sine wave.
 * The LED brightness mapping remains intact so the mood light still
 * cycles through colors even without real audio.
 */
static int snd_pcm_init(void)
{
    (void)g_pcm;
    return 0;
}

static void snd_pcm_cleanup(void)
{
    (void)g_pcm;
}

static int snd_pcm_read(short *buffer, int frame_count)
{
    (void)buffer;
    (void)frame_count;
    return 0;
}

static int snd_pcm_resume(void)
{
    (void)g_pcm;
    return 0;
}

#endif

/* ------------------------------------------------------------------ */
/* RGB LED via pigpio (common-cathode, 255-level PWM)                  */
/* ------------------------------------------------------------------ */
static void set_led_color(int red, int green, int blue)
{
    if (red < 0) red = 0;
    if (red > 255) red = 255;
    if (green < 0) green = 0;
    if (green > 255) green = 255;
    if (blue < 0) blue = 0;
    if (blue > 255) blue = 255;

    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

/*
 * Software PWM thread: cycles at 1 kHz, 50 % duty cycle, for
 * DEFAULT_LED_PERIOD_US microseconds.  The brightness is scaled
 * from the RMS amplitude (0.0 .. 1.0) so that a quieter input
 * yields a dimmer LED.
 */
static void *led_thread(void *arg)
{
    (void)arg;

    const int period_us = DEFAULT_LED_PERIOD_US;
    const int half_us   = period_us / 2;
    const int pwm_freq  = 1000;   /* Hz */
    const int pwm_range = 255;

    while (g_running) {
        int brightness = 0;

        if (snd_pcm_read(NULL, DEFAULT_PERIOD_FRAMES) != 0) {
            /* EPIPE / ESTRPIPE — recover rather than crash */
            if (snd_pcm_resume() != 0)
                fprintf(stderr, "Warning: failed to resume ALSA stream\n");
            continue;
        }

        /* Compute RMS amplitude of the captured buffer */
        double sum_sq = 0.0;
        for (int i = 0; i < DEFAULT_PERIOD_FRAMES; i++)
            sum_sq += (double)buffer[i] * (double)buffer[i];
        double rms = sqrt(sum_sq / DEFAULT_PERIOD_FRAMES);
        brightness = (int)(rms * DEFAULT_SENSITIVITY * 255.0);

        if (brightness > 255) brightness = 255;
        if (brightness < 0)   brightness = 0;

        /* Software PWM at 1 kHz, 50 % duty cycle */
        gpioSetMode(RED_PIN,   PI_OUTPUT);
        gpioSetMode(GREEN_PIN, PI_OUTPUT);
        gpioSetMode(BLUE_PIN,  PI_OUTPUT);

        gpioWrite(RED_PIN,   0);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN,  0);

        gpioPWM(RED_PIN,   brightness);
        gpioPWM(GREEN_PIN, 0);
        gpioPWM(BLUE_PIN,  0);

        gpioDelay(half_us);

        gpioPWM(RED_PIN,   0);
        gpioPWM(GREEN_PIN, brightness);
        gpioPWM(BLUE_PIN,  0);

        gpioDelay(half_us);
    }

    /* Turn off LED on exit */
    set_led_color(0, 0, 0);
    return NULL;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float sensitivity = DEFAULT_SENSITIVITY;

    if (argc > 1) {
        char *endptr = NULL;
        float val = strtof(argv[1], &endptr);
        if (endptr == argv[1] || *endptr != '\0' || val < 0.0f || val > 1.0f) {
            fprintf(stderr, "Invalid sensitivity argument: '%s'\n", argv[1]);
            return EXIT_FAILURE;
        }
        sensitivity = val;
    }

    install_signal_handlers();

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize ALSA */
    if (snd_pcm_init() != 0) {
        fprintf(stderr, "ALSA initialisation failed — falling back to sine-wave simulation\n");
    }

    /* Allocate audio buffer */
    short *buffer = malloc(DEFAULT_PERIOD_FRAMES * sizeof(short));
    if (buffer == NULL) {
        fprintf(stderr, "malloc failed\n");
        if (snd_pcm_init() != 0)
            snd_pcm_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start LED thread */
    pthread_t led_tid;
    int rc = pthread_create(&led_tid, NULL, led_thread, NULL);
    if (rc != 0) {
        fprintf(stderr, "pthread_create failed: %s\n", strerror(rc));
        free(buffer);
        if (snd_pcm_init() != 0)
            snd_pcm_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (g_running) {
        if (snd_pcm_read(buffer, DEFAULT_PERIOD_FRAMES) != 0) {
            /* EPIPE / ESTRPIPE — recover rather than crash */
            if (snd_pcm_resume() != 0)
                fprintf(stderr, "Warning: failed to resume ALSA stream\n");
            continue;
        }

        /* Compute RMS amplitude */
        double sum_sq = 0.0;
        for (int i = 0; i < DEFAULT_PERIOD_FRAMES; i++)
            sum_sq += (double)buffer[i] * (double)buffer[i];
        double rms = sqrt(sum_sq / DEFAULT_PERIOD_FRAMES);

        /* Map RMS to brightness (0.0 .. 1.0) */
        int brightness = (int)(rms * sensitivity * 255.0);
        if (brightness > 255) brightness = 255;
        if (brightness < 0)   brightness = 0;

        set_led_color(0, brightness, 0);

        printf("RMS: %.2f  Brightness: %d\n", rms, brightness);
        fflush(stdout);

        usleep(DEFAULT_LED_PERIOD_US);
    }

    /* Cleanup */
    g_running = 0;
    pthread_join(led_tid, NULL);
    free(buffer);

    if (snd_pcm_init() != 0)
        snd_pcm_cleanup();
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

