    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels failed: %s\n",
                snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_period_size_near(g_pcm, g_pcm->hw_params,
                                                 &DEFAULT_PERIOD_FRAMES, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_period_size_near failed: %s\n",
                snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_hw_params(g_pcm, g_pcm->hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params failed: %s\n", snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_prepare(g_pcm);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_stream_open(g_pcm, &stream, NULL, NULL);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_stream_open failed: %s\n", snd_errmsg(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    return 0;
}

static void snd_pcm_cleanup(void)
{
    if (g_pcm != NULL) {
        snd_pcm_drain(g_pcm);
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
    }
}

static int snd_pcm_read(short *buffer, int frame_count)
{
    int err;

    err = snd_pcm_readi(g_pcm, buffer, frame_count);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_errmsg(err));
        return -1;
    }
    if (err != frame_count) {
        fprintf(stderr, "snd_pcm_readi short read: %d of %d\n", err, frame_count);
        return -1;
    }
    return 0;
}

