/* ------------------------------------------------------------------ */
/* RGB LED via pigpio (common-cathode, 255-level PWM)                  */
/* ------------------------------------------------------------------ */
static void set_led_color(int red, int green, int blue)
{
    if (red < 0) red = 0;
    if (red > 255) red = 255;
    if (green < 0) green = 0;
    if (green > 255) green = 255;
    if (blue < 0) blue = 0;
    if (blue > 255) blue = 255;

    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

/*
 * Software PWM thread: cycles at 1 kHz, 50 % duty cycle, for
 * DEFAULT_LED_PERIOD_US microseconds.  The brightness is scaled
 * from the RMS amplitude (0.0 .. 1.0) so that a quieter input
 * yields a dimmer LED.
 */
static void *led_thread(void *arg)
{
    (void)arg;

    const int period_us = DEFAULT_LED_PERIOD_US;
    const int half_us   = period_us / 2;
    const int pwm_freq  = 1000;   /* Hz */
    const int pwm_range = 255;

    while (g_running) {
        int brightness = 0;

        if (snd_pcm_read(NULL, DEFAULT_PERIOD_FRAMES) != 0) {
            /* EPIPE / ESTRPIPE — recover rather than crash */
            if (snd_pcm_resume() != 0)
                fprintf(stderr, "Warning: failed to resume ALSA stream\n");
            continue;
        }

        /* Compute RMS amplitude of the captured buffer */
        double sum_sq = 0.0;
        for (int i = 0; i < DEFAULT_PERIOD_FRAMES; i++)
            sum_sq += (double)buffer[i] * (double)buffer[i];
        double rms = sqrt(sum_sq / DEFAULT_PERIOD_FRAMES);
        brightness = (int)(rms * DEFAULT_SENSITIVITY * 255.0);

        if (brightness > 255) brightness = 255;
        if (brightness < 0)   brightness = 0;

        /* Software PWM at 1 kHz, 50 % duty cycle */
        gpioSetMode(RED_PIN,   PI_OUTPUT);
        gpioSetMode(GREEN_PIN, PI_OUTPUT);
        gpioSetMode(BLUE_PIN,  PI_OUTPUT);

        gpioWrite(RED_PIN,   0);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN,  0);

        gpioPWM(RED_PIN,   brightness);
        gpioPWM(GREEN_PIN, 0);
        gpioPWM(BLUE_PIN,  0);

        gpioDelay(half_us);

        gpioPWM(RED_PIN,   0);
        gpioPWM(GREEN_PIN, brightness);
        gpioPWM(BLUE_PIN,  0);

        gpioDelay(half_us);
    }

    /* Turn off LED on exit */
    set_led_color(0, 0, 0);
    return NULL;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float sensitivity = DEFAULT_SENSITIVITY;

    if (argc > 1) {
        char *endptr = NULL;
        float val = strtof(argv[1], &endptr);
        if (endptr == argv[1] || *endptr != '\0' || val < 0.0f || val > 1.0f) {
            fprintf(stderr, "Invalid sensitivity argument: '%s'\n", argv[1]);
            return EXIT_FAILURE;
        }
        sensitivity = val;
    }

    install_signal_handlers();

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize ALSA */
    if (snd_pcm_init() != 0) {
        fprintf(stderr, "ALSA initialisation failed — falling back to sine-wave simulation\n");
    }

    /* Allocate audio buffer */
    short *buffer = malloc(DEFAULT_PERIOD_FRAMES * sizeof(short));
    if (buffer == NULL) {
        fprintf(stderr, "malloc failed\n");
        if (snd_pcm_init() != 0)
            snd_pcm_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start LED thread */
    pthread_t led_tid;
    int rc = pthread_create(&led_tid, NULL, led_thread, NULL);
    if (rc != 0) {
        fprintf(stderr, "pthread_create failed: %s\n", strerror(rc));
        free(buffer);
        if (snd_pcm_init() != 0)
            snd_pcm_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (g_running) {
        if (snd_pcm_read(buffer, DEFAULT_PERIOD_FRAMES) != 0) {
            /* EPIPE / ESTRPIPE — recover rather than crash */
            if (snd_pcm_resume() != 0)
                fprintf(stderr, "Warning: failed to resume ALSA stream\n");
            continue;
        }

        /* Compute RMS amplitude */
        double sum_sq = 0.0;
        for (int i = 0; i < DEFAULT_PERIOD_FRAMES; i++)
            sum_sq += (double)buffer[i] * (double)buffer[i];
        double rms = sqrt(sum_sq / DEFAULT_PERIOD_FRAMES);

        /* Map RMS to brightness (0.0 .. 1.0) */
        int brightness = (int)(rms * sensitivity * 255.0);
        if (brightness > 255) brightness = 255;
        if (brightness < 0)   brightness = 0;

        set_led_color(0, brightness, 0);

        printf("RMS: %.2f  Brightness: %d\n", rms, brightness);
        fflush(stdout);

        usleep(DEFAULT_LED_PERIOD_US);
    }

    /* Cleanup */
    g_running = 0;
    pthread_join(led_tid, NULL);
    free(buffer);

    if (snd_pcm_init() != 0)
        snd_pcm_cleanup();
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

