#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x92
#define TCS34725_CDATAL  0x94
#define TCS34725_CDATAH  0x95
#define TCS34725_RDATAL  0x96
#define TCS34725_RDATAH  0x97
#define TCS34725_GDATAL  0x98
#define TCS34725_GDATAH  0x99
#define TCS34725_BDATAL  0x9A
#define TCS34725_BDATAH  0x9B

#define SAMPLE_INTERVAL_US 500000
#define INTEGRATION_TIME_MS 154

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", val, reg);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int r = i2cReadByteData(i2c_handle, reg);
    if (r < 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    *val = (uint8_t)r;
    return 0;
}

static int read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    int r = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (r < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X\n", reg);
        return -1;
    }
    if ((uint32_t)r != len) {
        fprintf(stderr, "Short read from register 0x%02X: got %d, expected %u\n", reg, r, len);
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    uint8_t id;
    if (read_reg(TCS34725_ID, &id) < 0) return -1;
    if (id != 0x44 && id != 0x45) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x44 or 0x45)\n", id);
        return -1;
    }

    if (write_reg(TCS34725_ENABLE, 0x00) < 0) return -1;
    if (write_reg(TCS34725_ATIME, INTEGRATION_TIME_MS) < 0) return -1;
    if (write_reg(TCS34725_ENABLE, 0x03) < 0) return -1;

    return 0;
}

static int read_color(uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t buf[8];
    if (read_block(TCS34725_CDATAL, buf, 8) < 0) return -1;

    *c = (uint16_t)buf[1] << 8 | buf[0];
    *r = (uint16_t)buf[3] << 8 | buf[2];
    *g = (uint16_t)buf[5] << 8 | buf[4];
    *b = (uint16_t)buf[7] << 8 | buf[6];
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", TCS34725_ADDRESS, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    fp = fopen("color_data.csv", "w");
    if (!fp) {
        fprintf(stderr, "Error opening color_data.csv\n");
        cleanup();
        return 1;
    }
    fprintf(fp, "Timestamp,C,R,G,B\n");

    uint16_t c, r, g, b;
    while (running) {
        if (read_color(&c, &r, &g, &b) == 0) {
            time_t now = time(NULL);
            fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b);
            fflush(fp);
        } else {
            fprintf(stderr, "Read failed; logging zeros\n");
            time_t now = time(NULL);
            fprintf(fp, "%ld,0,0,0,0\n", (long)now);
            fflush(fp);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

