#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define RELAY1 17
#define RELAY2 27
#define RELAY3 22
#define RELAY4 23

#define PWM_RANGE 100
#define PWM_FREQ 1000

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 3600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 86400

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

void set_relay_state(int relay_pin, int state) {
    gpioPWM(relay_pin, state);
}

void sunrise_phase() {
    printf("Sunrise phase starting...\n");
    for (int i = 0; i < SUNRISE_DURATION && program_running; i++) {
        for (int relay_pin = RELAY1; relay_pin <= RELAY4; relay_pin++) {
            int duty_cycle = (int)(((float)i / SUNRISE_DURATION) * PWM_RANGE);
            set_relay_state(relay_pin, duty_cycle);
        }
        gpioDelay(1000000 / PWM_FREQ);
    }
    printf("Sunrise phase complete.\n");
}

void daytime_phase() {
    printf("Daytime phase starting...\n");
    for (int i = 0; i < DAYTIME_DURATION && program_running; i++) {
        for (int relay_pin = RELAY1; relay_pin <= RELAY4; relay_pin++) {
            set_relay_state(relay_pin, PWM_RANGE);
        }
        gpioDelay(1000000 / PWM_FREQ);
    }
    printf("Daytime phase complete.\n");
}

void sunset_phase() {
    printf("Sunset phase starting...\n");
    for (int i = 0; i < SUNSET_DURATION && program_running; i++) {
        for (int relay_pin = RELAY1; relay_pin <= RELAY4; relay_pin++) {
            int duty_cycle = (int)(((float)i / SUNSET_DURATION) * PWM_RANGE);
            set_relay_state(relay_pin, duty_cycle);
        }
        gpioDelay(1000000 / PWM_FREQ);
    }
    printf("Sunset phase complete.\n");
}

void nighttime_phase() {
    printf("Nighttime phase starting...\n");
    for (int i = 0; i < NIGHTTIME_DURATION && program_running; i++) {
        for (int relay_pin = RELAY1; relay_pin <= RELAY4; relay_pin++) {
            set_relay_state(relay_pin, 0);
        }
        gpioDelay(1000000 / PWM_FREQ);
    }
    printf("Nighttime phase complete.\n");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(RELAY1, PI_OUTPUT);
    gpioSetMode(RELAY2, PI_OUTPUT);
    gpioSetMode(RELAY3, PI_OUTPUT);
    gpioSetMode(RELAY4, PI_OUTPUT);

    gpioSetPWMrange(RELAY1, PWM_RANGE);
    gpioSetPWMrange(RELAY2, PWM_RANGE);
    gpioSetPWMrange(RELAY3, PWM_RANGE);
    gpioSetPWMrange(RELAY4, PWM_RANGE);

    gpioSetPWMfrequency(RELAY1, PWM_FREQ);
    gpioSetPWMfrequency(RELAY2, PWM_FREQ);
    gpioSetPWMfrequency(RELAY3, PWM_FREQ);
    gpioSetPWMfrequency(RELAY4, PWM_FREQ);

    sunrise_phase();
    daytime_phase();
    sunset_phase();
    nighttime_phase();

    for (int relay_pin = RELAY1; relay_pin <= RELAY4; relay_pin++) {
        set_relay_state(relay_pin, 0);
    }

    gpioTerminate();
    return 0;
}

