#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_SEC 5
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos"
#define TIMESTAMP_FORMAT "%Y%m%d_%H%M%S"
#define TIMESTAMP_LEN 20

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, TIMESTAMP_FORMAT, timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_video(const char *timestamp) {
    char command[256];
    int ret;

    ret = snprintf(command, sizeof(command),
                   "raspivid -o %s/%s.h264 -t %d",
                   VIDEO_DIR, timestamp, VIDEO_DURATION_SEC);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: Command buffer too small.\n");
        return -1;
    }

    ret = system(command);
    if (ret == -1) {
        fprintf(stderr, "Error executing raspivid: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(ret) && WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(ret));
        return -1;
    }
    return 0;
}

int main(void) {
    int last_state = 1;
    uint32_t last_trigger_tick = 0;
    char timestamp[TIMESTAMP_LEN];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_PATH, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (running) {
        int current_state = gpioRead(SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", SENSOR_PIN);
            break;
        }

        uint32_t now = gpioTick();

        if (current_state == 0 && last_state == 1) {
            if (now - last_trigger_tick > DEBOUNCE_MS * 1000) {
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    printf("Motion detected at %s\n", timestamp);

                    if (capture_video(timestamp) != 0) {
                        fprintf(stderr, "Video capture failed for %s\n", timestamp);
                    } else {
                        printf("Video captured: %s.h264\n", timestamp);
                    }

                    if (log_motion_event(timestamp) != 0) {
                        fprintf(stderr, "Failed to log motion event.\n");
                    }
                } else {
                    fprintf(stderr, "Failed to generate timestamp.\n");
                }

                last_trigger_tick = now;
            }
        }

        last_state = current_state;
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

