static int read_gyro_data(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    if (i2c_read_reg16(fd, 0x43, &raw_x) < 0) return -1;
    if (i2c_read_reg16(fd, 0x45, &raw_y) < 0) return -1;
    if (i2c_read_reg16(fd, 0x47, &raw_z) < 0) return -1;
    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp = (long long)ts.tv_sec * 1000LL + (long long)ts.tv_nsec / 1000000LL;
    fprintf(fp, "%lld,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(fp);
}

