    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("gyro_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    float x, y, z;
    int retries = 3;
    while (running) {
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "I2C read error, attempting re-initialization...\n");
            if (init_mpu6050(i2c_fd) < 0) {
                fprintf(stderr, "Re-initialization failed, skipping sample\n");
            } else {
                retries--;
                if (retries <= 0) {
                    fprintf(stderr, "Max retries reached, skipping sample\n");
                }
            }
        }
        usleep(10000);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

