#include <unistd.h>
#include <string.h>

#define RELAY_1_PIN 4
#define RELAY_2_PIN 17
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22

#define DRIVER_INIT_FAILED 1
#define LOG_FILE_OPEN_FAILED 2
#define GPIO_INIT_FAILED 3
#define GPIO_WRITE_FAILED 4
#define GPIO_READ_FAILED 5

static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return GPIO_INIT_FAILED;
    }
    return 0;
}

static int set_relay_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", pin);
        return GPIO_WRITE_FAILED;
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return (rand() % 100) + 1;
}

static int determine_irrigation_state(int moisture_level) {
    return (moisture_level < 30) ? 1 : 0;
}

static void log_data(int moisture_level, int relay1_state, int relay2_state, int relay3_state, int relay4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
            timestamp, moisture_level,
            relay1_state ? "ON" : "OFF",
            relay2_state ? "ON" : "OFF",
            relay3_state ? "ON" : "OFF",
            relay4_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    set_relay_state(RELAY_1_PIN, 1);
    set_relay_state(RELAY_2_PIN, 1);
    set_relay_state(RELAY_3_PIN, 1);
    set_relay_state(RELAY_4_PIN, 1);

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    srand(time(NULL));

    if (initialize_gpio() != 0) {
        return DRIVER_INIT_FAILED;
    }

    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return LOG_FILE_OPEN_FAILED;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_pins[] = {RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN};
    for (int i = 0; i < 4; i++) {
        if (set_relay_state(relay_pins[i], 1) != 0) {
            cleanup();
            return GPIO_INIT_FAILED;
        }
    }

    while (program_running) {
        int moisture_level = read_moisture_sensor();
        int relay1_state = determine_irrigation_state(moisture_level);
        int relay2_state = determine_irrigation_state(moisture_level);
        int relay3_state = determine_irrigation_state(moisture_level);
        int relay4_state = determine_irrigation_state(moisture_level);

        if (set_relay_state(RELAY_1_PIN, relay1_state) != 0 ||
            set_relay_state(RELAY_2_PIN, relay2_state) != 0 ||
            set_relay_state(RELAY_3_PIN, relay3_state) != 0 ||
            set_relay_state(RELAY_4_PIN, relay4_state) != 0) {
            cleanup();
            return GPIO_WRITE_FAILED;
        }

        log_data(moisture_level, relay1_state, relay2_state, relay3_state, relay4_state);

        sleep(5);
    }

    cleanup();
    return 0;
}

