#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x32
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36
#define ADXL345_BW_RATE 0x2C
#define ADXL345_RANGE 0x28
#define ALARM_GPIO 27
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION_MS 500
#define POLL_INTERVAL_US 100000
#define ALARM_DURATION_US 5000000
#define I2C_BUS 1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read acceleration data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * 0.0039f;
    *y = (float)raw_y * 0.0039f;
    *z = (float)raw_z * 0.0039f;
    return 0;
}

static int detect_freefall(float x, float y, float z) {
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

static void trigger_alarm(int gpio) {
    gpioWrite(gpio, 1);
    gpioDelay(ALARM_DURATION_US);
    gpioWrite(gpio, 0);
}

static void log_freefall(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open freefall.log\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X\n", ADXL345_ADDRESS);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", ALARM_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(ALARM_GPIO, 0);

    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write to POWER_CTL register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(10000);

    if (i2cWriteByteData(i2c_handle, ADXL345_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error: Failed to write to BW_RATE register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, ADXL345_RANGE, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to write to RANGE register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(10000);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z;
    uint32_t freefall_start_tick = 0;
    int freefall_detected = 0;

    while (running) {
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                if (!freefall_detected) {
                    freefall_detected = 1;
                    freefall_start_tick = gpioTick();
                } else {
                    uint32_t elapsed = gpioTick() - freefall_start_tick;
                    if (elapsed >= FREEFALL_DURATION_MS * 1000) {
                        log_freefall(x, y, z);
                        trigger_alarm(ALARM_GPIO);
                        freefall_detected = 0;
                    }
                }
            } else {
                freefall_detected = 0;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(ALARM_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

