#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"

#define TRIGGER_PULSE_US  10
#define CYCLE_DELAY_US    200000
#define TIMEOUT_US        100000
#define MAX_PULSE_US      23200
#define MAX_DISTANCE_CM   4.0f

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static volatile uint32_t g_tick = 0;
static volatile uint32_t g_pulse_us = 0;
static volatile bool     g_echo_seen = false;
static volatile bool     g_new_reading = false;

static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_rising_edge(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)level;
    (void)tick;
    pthread_mutex_lock(&g_mutex);
    g_echo_seen = true;
    pthread_mutex_unlock(&g_mutex);
}

static void echo_falling_edge(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)level;
    (void)tick;
    pthread_mutex_lock(&g_mutex);
    if (g_echo_seen) {
        g_pulse_us = tick - g_tick;
        g_new_reading = true;
    }
    g_echo_seen = false;
    pthread_mutex_unlock(&g_mutex);
}

static void log_distance(float distance_cm)
{
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    pthread_mutex_lock(&g_mutex);
    if (g_new_reading) {
        fprintf(g_log_fp, "%lld,%.2f\n", timestamp_ns, distance_cm);
        fflush(g_log_fp);
        g_new_reading = false;
    }
    pthread_mutex_unlock(&g_mutex);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on ECHO_PIN %d.\n", ECHO_PIN);
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN %d low.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_falling_edge, NULL) != 0) {
        fprintf(stderr, "Error: failed to register falling-edge ISR on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_rising_edge, NULL) != 0) {
        fprintf(stderr, "Error: failed to register rising-edge ISR on ECHO_PIN %d.\n", ECHO_PIN);
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        trigger_sensor();

        uint32_t start_tick = g_tick;
        uint32_t elapsed = 0;

        while (g_running && elapsed < TIMEOUT_US) {
            gpioDelay(1000);
            elapsed += 1000;
        }

        if (!g_running) {
            break;
        }

        if (!g_new_reading) {
            fprintf(stderr, "Warning: no echo received within %d us.\n", TIMEOUT_US);
        } else if (g_pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: pulse width %u us exceeds maximum range (%.1f m).\n",
                    g_pulse_us, MAX_DISTANCE_CM);
        } else {
            float distance_cm = (float)g_pulse_us * 0.0343f / 2.0f;
            if (distance_cm > MAX_DISTANCE_CM) {
                fprintf(stderr, "Warning: distance %.2f cm exceeds maximum range (%.1f m).\n",
                        distance_cm, MAX_DISTANCE_CM);
            } else {
                log_distance(distance_cm);
                printf("Distance: %.2f cm\n", distance_cm);
            }
        }

        g_tick = start_tick;
    }

    printf("\nShutting down...\n");

    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    pthread_mutex_destroy(&g_mutex);
    gpioTerminate();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

