        if (rc == (int)len) return 0;
        fprintf(stderr, "I2C block read from reg 0x%02X failed (attempt %d): rc=%d\n", reg, attempt + 1, rc);
        gpioDelay(1000);
    }
    return -1;
}

static int init_lis3dh(int handle) {
    if (i2c_write_reg(handle, LIS3DH_CTRL_REG1_A, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg(handle, LIS3DH_CTRL_REG4_A, 0x08) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(handle, LIS3DH_OUT_X_L_A, buf, 6) != 0) return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * 0.000061f;
    *y = (float)raw_y * 0.000061f;
    *z = (float)raw_z * 0.000061f;
    return 0;
}

static bool detect_freefall(float x, float y, float z, float threshold) {
    float mag = sqrtf(x * x + y * y + z * z);
    return mag < threshold;
}

static bool detect_impact(float x, float y, float z, float threshold) {
    float mag = sqrtf(x * x + y * y + z * z);
    return mag > threshold;
}

static void activate_buzzer(int gpio, int duration_ms) {
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(gpio, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = FREEFALL_THRESHOLD_DEFAULT;
    float impact_threshold = IMPACT_THRESHOLD_DEFAULT;

    if (argc > 1) freefall_threshold = (float)atof(argv[1]);
    if (argc > 2) impact_threshold = (float)atof(argv[2]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, LIS3DH_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh(i2c_handle) != 0) {
        fprintf(stderr, "Error initializing LIS3DH sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Freefall threshold: %.2f g, Impact threshold: %.2f g\n", freefall_threshold, impact_threshold);

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (detect_freefall(x, y, z, freefall_threshold)) {
                printf("Freefall detected!\n");
            } else if (detect_impact(x, y, z, impact_threshold)) {
                printf("Impact detected!\n");
                activate_buzzer(BUZZER_GPIO, 1000);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

