#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

/* Motor 1 (X-axis) GPIO pins */
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

/* Motor 2 (Y-axis) GPIO pins */
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

#define STEP_DELAY_US 1000
#define SQUARE_SIDE_MM 50
#define STEPS_PER_REV 2048
#define STEP_DELAY_NS (STEP_DELAY_US * 1000)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int set_motor_pins(int motor, int in1, int in2, int in3, int in4) {
    int pins[4];
    if (motor == 1) {
        pins[0] = MOTOR1_IN1; pins[1] = MOTOR1_IN2; pins[2] = MOTOR1_IN3; pins[3] = MOTOR1_IN4;
    } else if (motor == 2) {
        pins[0] = MOTOR2_IN1; pins[1] = MOTOR2_IN2; pins[2] = MOTOR2_IN3; pins[3] = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Error: invalid motor number %d\n", motor);
        return -1;
    }
    for (int i = 0; i < 4; i++) {
        if (safe_set_mode(pins[i], gpioOUTPUT) < 0) return -1;
        if (safe_write(pins[i], (i < 2) ? 0 : 1) < 0) return -1;
    }
    return 0;
}

static int step_motor(int motor, int step) {
    int in1, in2, in3, in4;
    switch (step) {
        case 0: in1 = 1; in2 = 0; in3 = 0; in4 = 0; break;
        case 1: in1 = 1; in2 = 1; in3 = 0; in4 = 0; break;
        case 2: in1 = 0; in2 = 1; in3 = 1; in4 = 0; break;
        case 3: in1 = 0; in2 = 0; in3 = 1; in4 = 0; break;
        default:
            fprintf(stderr, "Error: invalid step %d for motor %d\n", step, motor);
            return -1;
    }
    if (set_motor_pins(motor, in1, in2, in3, in4) < 0) return -1;
    gpioDelay(STEP_DELAY_NS);
    return 0;
}

static int move_motor(int motor, int steps, int direction) {
    if (direction < 0) {
        steps = -steps;
    }
    for (int i = 0; i < steps; i++) {
        if (!g_running) return -1;
        if (step_motor(motor, (i * direction) % 4) < 0) return -1;
    }
    return 0;
}

static int move_square(int motor1, int motor2, int side_mm) {
    int steps_per_side = (int)(4 * (double)STEPS_PER_REV / (double)side_mm);
    if (move_motor(motor1, steps_per_side, 1) < 0) return -1;
    if (move_motor(motor2, steps_per_side, 1) < 0) return -1;
    if (move_motor(motor1, steps_per_side, -1) < 0) return -1;
    if (move_motor(motor2, steps_per_side, -1) < 0) return -1;
    return 0;
}

static void stop_motors(void) {
    int pins[4] = {MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4};
    for (int i = 0; i < 4; i++) {
        safe_write(pins[i], 0);
    }
    pins[0] = MOTOR2_IN1; pins[1] = MOTOR2_IN2; pins[2] = MOTOR2_IN3; pins[3] = MOTOR2_IN4;
    for (int i = 0; i < 4; i++) {
        safe_write(pins[i], 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(MOTOR1_IN1, gpioOUTPUT) < 0 ||
        safe_set_mode(MOTOR1_IN2, gpioOUTPUT) < 0 ||
        safe_set_mode(MOTOR1_IN3, gpioOUTPUT) < 0 ||
        safe_set_mode(MOTOR1_IN4, gpioOUTPUT) < 0 ||
        safe_set_mode(MOTOR2_IN1, gpioOUTPUT) < 0 ||
        safe_set_mode(MOTOR2_IN2, gpioOUTPUT) < 0 ||
        safe_set_mode(MOTOR2_IN3, gpioOUTPUT) < 0 ||
        safe_set_mode(MOTOR2_IN4, gpioOUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        stop_motors();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Moving square (%d mm) on Raspberry Pi 3 Model B+\n", SQUARE_SIDE_MM);
    while (g_running) {
        if (move_square(1, 2, SQUARE_SIDE_MM) < 0) {
            fprintf(stderr, "Error: motor movement failed\n");
            break;
        }
    }

    stop_motors();
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

