    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor configuration                                                 */
/* ------------------------------------------------------------------ */
static int configure_sensor(int handle)
{
    int who = i2cReadByteData(handle, LIS3DH_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who);
        return -1;
    }
    if (who != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LIS3DH_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_byte(handle, LIS3DH_CTRL1_XL, LIS3DH_CTRL1_XL_VAL) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (returns 0 on error, values set to 0)            */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (i2c_read_block(handle, LIS3DH_OUT_X_L, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* ±2g, 12-bit left-justified: sensitivity 4096 LSB/g */
    *x = (float)raw_x / 4096.0f;
    *y = (float)raw_y / 4096.0f;
    *z = (float)raw_z / 4096.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log acceleration event                                             */
/* ------------------------------------------------------------------ */
static void log_event(float x, float y, float z)
{
    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (!fp) {
        perror("fopen(/var/log/high_acceleration.log)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X=%.3f, Y=%.3f, Z=%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z);
    } else {
        fprintf(fp, "(timestamp error), X=%.3f, Y=%.3f, Z=%.3f\n", x, y, z);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int i2c_address = LIS3DH_ADDR_DEFAULT;
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:h")) != -1) {
        switch (opt) {
        case 'a':
            i2c_address = (int)strtol(optarg, NULL, 16);
            if (i2c_address < 0x03 || i2c_address > 0x77) {
                fprintf(stderr, "Invalid I2C address 0x%02X (must be 0x03-0x77)\n",
                        i2c_address);
                return EXIT_FAILURE;
            }
            break;
        case 't':
            threshold = strtof(optarg, NULL);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Threshold must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 'h':
        default:
            fprintf(stderr, "Usage: %s [-a i2c_addr] [-t threshold_g]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (non-hardware environment?)\n");
        return EXIT_SUCCESS;
    }

    /* Open I2C bus 1 (default for Raspberry Pi 5) */
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(1, 0x%02X) failed: %d\n", i2c_address, i2c_handle);
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    /* Configure sensor */
    if (configure_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    printf("Monitoring acceleration (threshold %.2f g, I2C 0x%02X)...\n",
           threshold, i2c_address);

    /* Main loop */
    while (!terminate) {
        float x, y, z;

        if (read_acceleration(i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error — continuing\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
            log_event(x, y, z);
            printf("High acceleration logged: X=%.3f Y=%.3f Z=%.3f\n", x, y, z);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

