#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdbool.h>

#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

#define BUFFER_SIZE 5
#define POLL_DELAY_US 10000
#define ALERT_DURATION_S 2

typedef struct {
    int left;
    int center;
    int right;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer sensor_buffer;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_buffer(CircularBuffer *cb, int left, int center, int right) {
    cb->data[cb->head].left = left;
    cb->data[cb->head].center = center;
    cb->data[cb->head].right = right;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void check_line_absent(int left, int center, int right) {
    if (center == 1) {
        printf("No line detected for 5 consecutive readings!\n");
        gpioWrite(ALERT_PIN, 1);
        sleep(ALERT_DURATION_S);
        gpioWrite(ALERT_PIN, 0);
    }
}

static void move_forward(void) {
    printf("Moving forward\n");
}

static void turn_left(void) {
    printf("Turning left\n");
}

static void turn_right(void) {
    printf("Turning right\n");
}

static void stop_robot(void) {
    printf("Stopping\n");
}

static void control_robot(int left, int center, int right) {
    if (center == 0) {
        move_forward();
    } else if (left == 0) {
        turn_left();
    } else if (right == 0) {
        turn_right();
    } else {
        stop_robot();
    }
}

static void cleanup(void) {
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(ALERT_PIN, 0);

    init_circular_buffer(&sensor_buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Line follower started. Press Ctrl+C to exit.\n");

    while (running) {
        int left = gpioRead(LEFT_SENSOR_PIN);
        int center = gpioRead(CENTER_SENSOR_PIN);
        int right = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error reading sensor pins\n");
            break;
        }

        add_to_buffer(&sensor_buffer, left, center, right);
        check_line_absent(left, center, right);
        control_robot(left, center, right);

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

