#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7210_ADDR 0x15
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0
#define LOG_FILE "magnetic_events.txt"
#define POLL_TIMEOUT_MS 50
#define SAMPLE_INTERVAL_US 100000

#define SI7210_REG_X_MSB 0x00
#define SI7210_REG_X_LSB 0x01
#define SI7210_REG_Y_MSB 0x02
#define SI7210_REG_Y_LSB 0x03
#define SI7210_REG_Z_MSB 0x04
#define SI7210_REG_Z_LSB 0x05
#define SI7210_REG_STATUS 0x06
#define SI7210_REG_CONFIG 0x07

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, msg);
    } else {
        fprintf(fp, "[timestamp error]: %s\n", msg);
    }
    fclose(fp);
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        log_event("I2C read error");
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        log_event("I2C write error");
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, float *x, float *y, float *z) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;
    uint16_t x_raw, y_raw, z_raw;

    if (read_register(handle, SI7210_REG_X_MSB, &x_msb) < 0) return -1;
    if (read_register(handle, SI7210_REG_X_LSB, &x_lsb) < 0) return -1;
    if (read_register(handle, SI7210_REG_Y_MSB, &y_msb) < 0) return -1;
    if (read_register(handle, SI7210_REG_Y_LSB, &y_lsb) < 0) return -1;
    if (read_register(handle, SI7210_REG_Z_MSB, &z_msb) < 0) return -1;
    if (read_register(handle, SI7210_REG_Z_LSB, &z_lsb) < 0) return -1;

    x_raw = ((uint16_t)x_msb << 8) | x_lsb;
    y_raw = ((uint16_t)y_msb << 8) | y_lsb;
    z_raw = ((uint16_t)z_msb << 8) | z_lsb;

    *x = (float)x_raw * 0.001f;
    *y = (float)y_raw * 0.001f;
    *z = (float)z_raw * 0.001f;
    return 0;
}

static int control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        log_event("Failed to write relay GPIO");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    control_relay(RELAY_GPIO, 0);
    gpioTerminate();
    log_event("Program terminated");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting relay GPIO mode\n");
        cleanup();
        return 1;
    }
    control_relay(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    log_event("Program started");

    while (!terminate) {
        float x, y, z;
        if (read_sensor_data(i2c_handle, &x, &y, &z) < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int relay_state = (x > THRESHOLD_MT) ? 1 : 0;
        if (control_relay(RELAY_GPIO, relay_state) < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "X=%.3f mT, Y=%.3f mT, Z=%.3f mT, Relay=%s",
                 x, y, z, relay_state ? "ON" : "OFF");
        log_event(msg);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

