#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define PORT 5000
#define LOG_FILE "relay_log.txt"
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int server_fd = -1;

static void log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int init_socket(void) {
    int fd;
    struct sockaddr_in address;
    int opt = 1;

    if ((fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(fd);
        return -1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(fd);
        return -1;
    }

    if (listen(fd, 3) < 0) {
        perror("listen failed");
        close(fd);
        return -1;
    }

    return fd;
}

static void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;
    char command[BUFFER_SIZE];

    memset(buffer, 0, sizeof(buffer));
    memset(command, 0, sizeof(command));

    while ((bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        strtrim(buffer);

        if (strncmp(buffer, "on", 2) == 0 || strncmp(buffer, "ON", 2) == 0) {
            if (gpioWrite(RELAY_GPIO, 1) == 0) {
                log_event("Relay activated");
            } else {
                log_event("Error activating relay");
            }
        } else if (strncmp(buffer, "off", 3) == 0 || strncmp(buffer, "OFF", 3) == 0) {
            if (gpioWrite(RELAY_GPIO, 0) == 0) {
                log_event("Relay deactivated");
            } else {
                log_event("Error deactivating relay");
            }
        } else {
            log_event("Invalid command received");
        }
    }

    if (bytes_received == 0) {
        log_event("Client disconnected");
    } else if (bytes_received < 0) {
        perror("recv failed");
    }

    close(client_socket);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    server_fd = init_socket();
    if (server_fd < 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);
    log_event("Server started");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);

        if (client_socket < 0) {
            if (running && errno != EINTR) {
                perror("accept failed");
                log_event("Error accepting connection");
            }
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        char log_message[BUFFER_SIZE];
        snprintf(log_message, sizeof(log_message), "Connection from %s", client_ip);
        log_event(log_message);

        handle_client(client_socket);
    }

    log_event("Server shutting down");
    cleanup();
    return 0;
}

