#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x22
#define SENSOR2_ADDR 0x23
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0f
#define POLL_DELAY_US 100000
#define LOG_FILE "flow_log.txt"

/* SLF3S-1300F: start continuous measurement command (two bytes) */
static const uint8_t CMD_START_MEAS[2] = {0x36, 0x00};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-8 polynomial 0x31, init 0x00, no final XOR (Sensirion convention) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t buf[3];
    int rc;

    rc = i2cWriteDevice(handle, (char *)CMD_START_MEAS, 2);
    if (rc < 0) {
        fprintf(stderr, "Error writing start-measurement command: %s\n", pigpio_error(rc));
        return -1;
    }

    /* Small delay so the sensor can process the command */
    gpioDelay(2000);

    rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc < 0) {
        fprintf(stderr, "Error reading flow data: %s\n", pigpio_error(rc));
        return -1;
    }
    if (rc != 3) {
        fprintf(stderr, "Short read: got %d bytes, expected 3\n", rc);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / 100.0f;
    return 0;
}

static void log_flow_data(float f1, float f2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000, f1, f2);
    fflush(fp);
    fclose(fp);
}

int main(void) {
    int handle1 = -1, handle2 = -1;
    int rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    rc = gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    if (rc < 0) {
        fprintf(stderr, "Failed to set relay GPIO %d as output: %s\n", RELAY_GPIO, pigpio_error(rc));
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1 (0x%02X): %s\n", SENSOR1_ADDR, pigpio_error(handle1));
        goto cleanup;
    }

    handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2 (0x%02X): %s\n", SENSOR2_ADDR, pigpio_error(handle2));
        goto cleanup;
    }

    while (running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = (read_flow_rate(handle1, &f1) == 0);
        int ok2 = (read_flow_rate(handle2, &f2) == 0);

        if (!ok1 || !ok2) {
            fprintf(stderr, "Sensor read error; skipping cycle\n");
        } else {
            log_flow_data(f1, f2);
            int relay_on = (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD);
            gpioWrite(RELAY_GPIO, relay_on ? 1 : 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    gpioWrite(RELAY_GPIO, 0);
    if (handle1 >= 0) i2cClose(handle1);
    if (handle2 >= 0) i2cClose(handle2);
    gpioTerminate();
    return 0;
}

