#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define MOTOR_RUN_TIME_US 5000000  /* 5 seconds in microseconds */
#define POLL_INTERVAL_US  200000   /* 200 ms */
#define DEBOUNCE_DRY_MS   3000     /* 3 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int motor_stop(void)
{
    if (gpioWrite(MOTOR_ENABLE_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set ENA low (stop motor)");
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 low (stop motor)");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low (stop motor)");
        return -1;
    }
    syslog(LOG_INFO, "Motor stopped");
    return 0;
}

static int motor_start(void)
{
    if (gpioWrite(MOTOR_ENABLE_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set ENA high (start motor)");
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high (start motor)");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 high (start motor)");
        return -1;
    }
    syslog(LOG_INFO, "Motor started");
    return 0;
}

static int motor_run_for(unsigned int duration_us)
{
    if (motor_start() < 0)
        return -1;

    /*
     * gpioDelay is a busy-wait that blocks pigpio; we use usleep so
     * the loop is interruptible by signals and the motor is stopped
     * promptly.
     */
    unsigned int elapsed = 0;
    while (elapsed < duration_us && g_running) {
        unsigned int step = (duration_us - elapsed < POLL_INTERVAL_US)
                             ? (duration_us - elapsed)
                             : POLL_INTERVAL_US;
        usleep(step);
        elapsed += step;
    }

    if (motor_stop() < 0)
        return -1;
    return 0;
}

