#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define POLL_DELAY_US  10000
#define DEBOUNCE_US    200000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_gpio_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "gpioWrite(pin=%u, level=%u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "gpioSetMode(pin=%u, mode=%u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_pull(unsigned pin, unsigned pud)
{
    if (gpioSetPullUpDown(pin, pud) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(pin=%u, pud=%u) failed\n", pin, pud);
        return -1;
    }
    return 0;
}

static int send_servo_pulse(unsigned pin, unsigned pulse_us)
{
    if (safe_gpio_write(pin, 1) < 0) return -1;
    gpioDelay(pulse_us);
    if (safe_gpio_write(pin, 0) < 0) return -1;
    return 0;
}

static int lock_door(void)
{
    printf("Locking door...\n");
    fflush(stdout);
    if (send_servo_pulse(SERVO_PIN, LOCK_PULSE_US) < 0)
        return -1;
    printf("Door locked.\n");
    fflush(stdout);
    return 0;
}

static int unlock_door(void)
{
    printf("Unlocking door...\n");
    fflush(stdout);
    if (send_servo_pulse(SERVO_PIN, UNLOCK_PULSE_US) < 0)
        return -1;
    printf("Door unlocked.\n");
    fflush(stdout);
    return 0;
}

static void cleanup(void)
{
    printf("Cleaning up and stopping servo...\n");
    fflush(stdout);
    if (send_servo_pulse(SERVO_PIN, 0) < 0)
        fprintf(stderr, "Warning: failed to stop servo during cleanup\n");
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_gpio_set_pull(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        safe_gpio_set_pull(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_gpio_set_mode(SERVO_PIN, PI_OUTPUT) < 0 ||
        safe_gpio_set_mode(LOCK_BUTTON, PI_INPUT) < 0 ||
        safe_gpio_set_mode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_lock_state = 0;
    int last_unlock_state = 0;

    while (g_running) {
        int lock_pressed = (gpioRead(LOCK_BUTTON) == 0);
        int unlock_pressed = (gpioRead(UNLOCK_BUTTON) == 0);

        if (lock_pressed && !last_lock_state) {
            if (lock_door() == 0)
                last_lock_state = 1;
        }

        if (unlock_pressed && !last_unlock_state) {
            if (unlock_door() == 0)
                last_unlock_state = 1;
        }

        if (lock_pressed) last_lock_state = 1;
        if (unlock_pressed) last_unlock_state = 1;

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

