#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define LOG_FILE "security_log.txt"
#define FLOOD_DURATION_SEC 60
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event_type, const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s: %s\n", timestamp, event_type, message) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin mode\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        cleanup();
        return 1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay pin state\n");
        cleanup();
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    int last_state = 0;

    while (running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "Failed to read PIR sensor\n");
            break;
        }

        if (pir_state == 1 && last_state == 0) {
            printf("Motion detected!\n");

            if (gpioWrite(RELAY_PIN, 1) != 0) {
                fprintf(stderr, "Failed to activate relay\n");
                break;
            }

            if (log_event("Motion Detected", "Floodlight activated") != 0) {
                fprintf(stderr, "Failed to log motion detection event\n");
                break;
            }

            time_t start_time = time(NULL);
            if (start_time == (time_t)-1) {
                fprintf(stderr, "time() failed: %s\n", strerror(errno));
                break;
            }

            for (int i = 0; i < FLOOD_DURATION_SEC && running; i++) {
                gpioDelay(POLL_INTERVAL_US);
            }

            time_t end_time = time(NULL);
            if (end_time == (time_t)-1) {
                fprintf(stderr, "time() failed: %s\n", strerror(errno));
                break;
            }

            if (gpioWrite(RELAY_PIN, 0) != 0) {
                fprintf(stderr, "Failed to deactivate relay\n");
                break;
            }

            if (log_event("Motion Detected", "Floodlight deactivated") != 0) {
                fprintf(stderr, "Failed to log motion detection event\n");
                break;
            }

            long duration_sec = difftime(end_time, start_time);
            if (duration_sec < 0) {
                fprintf(stderr, "Duration calculation error\n");
                break;
            }

            printf("Floodlight OFF after %ld seconds.\n", duration_sec);
        }

        last_state = pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

