#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <stdarg.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define PWM_FREQ 50
#define PWM_RANGE 1000
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_SAFE_ANGLE 90
#define LOG_FILE "security.log"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *format, ...) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    va_list args;
    va_start(args, format);
    vsyslog(LOG_INFO, format, args);
    va_end(args);

    if (log_file) {
        fprintf(log_file, "%s: ", timestamp);
        va_list args2;
        va_start(args2, format);
        vfprintf(log_file, format, args2);
        va_end(args2);
        fflush(log_file);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_UP);
    return 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_event("Invalid servo angle: %d", angle);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE + (int)((long)angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / 180);
    if (pulse_width < SERVO_MIN_PULSE) pulse_width = SERVO_MIN_PULSE;
    if (pulse_width > SERVO_MAX_PULSE) pulse_width = SERVO_MAX_PULSE;
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        log_event("gpioServo failed");
        return -1;
    }
    log_event("Servo angle set to %d", angle);
    return 0;
}

static int read_pir(void) {
    int value = gpioRead(PIR_PIN);
    if (value < 0) {
        log_event("gpioRead failed");
        return -1;
    }
    return value;
}

static int handle_client(int client_fd) {
    char buffer[1024];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n <= 0) {
        if (n < 0) log_event("recv failed: %s", strerror(errno));
        return 0;
    }
    buffer[n] = '\0';
    char *cmd = strtok(buffer, " \r\n");
    if (!cmd) {
        log_event("Empty command");
        return 0;
    }
    if (strcmp(cmd, "PIR") == 0) {
        int pir = read_pir();
        if (pir < 0) {
            log_event("Failed to read PIR sensor");
            return 0;
        }
        char response[64];
        snprintf(response, sizeof(response), "PIR:%d", pir);
        send(client_fd, response, strlen(response), 0);
        log_event("PIR command received, sent: %s", response);
        return 1;
    }
    char *arg = strtok(NULL, " \r\n");
    if (!arg) {
        log_event("Missing argument after API call");
        return 0;
    }
    int angle = atoi(arg);
    if (angle < 0 || angle > 180) {
        log_event("Invalid angle: %s", arg);
        return 0;
    }
    if (set_servo_angle(angle) < 0) {
        log_event("Failed to set servo angle");
        return 0;
    }
    log_event("API call: angle=%d", angle);
    return 1;
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_event("Starting security system");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_event("sigaction failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (init_gpio() < 0) {
        log_event("GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_event("Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_event("Socket creation failed: %s", strerror(errno));
        cleanup();
        closelog();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_event("setsockopt failed: %s", strerror(errno));
        cleanup();
        closelog();
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_event("Bind failed: %s", strerror(errno));
        cleanup();
        closelog();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_event("Listen failed: %s", strerror(errno));
        cleanup();
        closelog();
        return 1;
    }

    log_event("Listening on port %d", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            log_event("Accept failed: %s", strerror(errno));
            continue;
        }
        log_event("Client connected");
        handle_client(client_fd);
        close(client_fd);
        log_event("Client disconnected");
    }

    log_event("Shutting down");
    cleanup();
    closelog();
    return 0;
}

