#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define RELAY_PIN 23
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"
#define I2C_BUS 1
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_RESET 0x07
#define BH1750_MEASURE_CMD 0x10
#define BH1750_MEASURE_DELAY_US 180000
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(int handle) {
    if (i2cWriteByte(handle, BH1750_RESET) < 0) {
        fprintf(stderr, "Error: BH1750 reset failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int handle, float *lux_out) {
    if (i2cWriteByte(handle, BH1750_MEASURE_CMD) < 0) {
        fprintf(stderr, "Error: BH1750 measurement command failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(BH1750_MEASURE_DELAY_US);

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: BH1750 read failed: %s\n", strerror(errno));
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int log_data(FILE *fp, float lux) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (bh1750_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: BH1750 initialization failed. Sensor may be absent or bus error.\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set relay pin mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    gpioWrite(RELAY_PIN, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set signal handlers: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Grow light control started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        if (bh1750_read_lux(i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (log_data(log_file, lux) < 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }

            if (lux < LUX_THRESHOLD) {
                gpioWrite(RELAY_PIN, 1);
                printf("Grow light ON\n");
            } else {
                gpioWrite(RELAY_PIN, 0);
                printf("Grow light OFF\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read lux value. Retrying next cycle.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

