#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>

#define HX711_DOUT_PIN 23
#define HX711_SCK_PIN  24
#define SOLENOID_PIN   25

#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE     1.0f
#define DEFAULT_DURATION  200
#define POLL_INTERVAL_US  500000
#define TARE_SAMPLES      10
#define MAX_RETRIES       3
#define HX711_TIMEOUT_US  1000000

static volatile sig_atomic_t g_running = 1;
static float g_threshold = DEFAULT_THRESHOLD;
static float g_scale     = DEFAULT_SCALE;
static int   g_duration  = DEFAULT_DURATION;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_hx711(int *out_value) {
    int value = 0;
    int i;

    for (i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(HX711_DOUT_PIN)) value |= 1;
        if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
    }

    /* 25th pulse: select Channel A, Gain 128 */
    if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
    gpioDelay(1);

    /* Sign-extend 24-bit two's complement to 32-bit */
    if (value & 0x800000) value |= 0xFF000000;

    *out_value = value;
    return 0;
}

static int tare_hx711(int *tare_value) {
    int sum = 0;
    int valid = 0;

    for (int i = 0; i < TARE_SAMPLES; i++) {
        int v;
        if (read_hx711(&v) == 0) {
            sum += v;
            valid++;
        } else {
            syslog(LOG_ERR, "HX711 read failed during tare (sample %d)", i);
        }
        gpioDelay(10000);
    }

    if (valid == 0) {
        syslog(LOG_ERR, "HX711 tare failed: no valid readings after %d samples", TARE_SAMPLES);
        return -1;
    }
    *tare_value = sum / valid;
    syslog(LOG_INFO, "HX711 tare complete: %d", *tare_value);
    return 0;
}

static int read_weight(int *raw_value) {
    int sum = 0;
    int valid = 0;

    for (int i = 0; i < 5; i++) {
        if (read_hx711(raw_value) == 0) {
            sum += *raw_value;
            valid++;
        } else {
            syslog(LOG_ERR, "HX711 read failed (cycle %d)", i);
        }
        gpioDelay(10000);
    }

    if (valid == 0) {
        syslog(LOG_ERR, "Weight read failed: no valid readings after 5 cycles");
        return -1;
    }
    *raw_value = sum / valid;
    return 0;
}

static void activate_solenoid(int duration_ms) {
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH");
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW");
    }
}

static void cleanup(void) {
    gpioWrite(SOLENOID_PIN, 0);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioSetMode(HX711_SCK_PIN, PI_INPUT);
    gpioSetMode(SOLENOID_PIN, PI_INPUT);
    gpioTerminate();
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't': g_threshold = (int)atof(optarg); break;
            case 's': g_scale     = (float)atof(optarg); break;
            case 'd': g_duration  = (int)atof(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_grams] [-s scale_factor] [-d duration_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Weight monitoring started (threshold=%d g, scale=%.2f, duration=%d ms)",
           g_threshold, g_scale, g_duration);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DOUT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(HX711_SCK_PIN,  PI_OUTPUT) < 0 ||
        gpioSetMode(SOLENOID_PIN,  PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioWrite(HX711_SCK_PIN, 0);
    gpioWrite(SOLENOID_PIN, 0);

    int tare_value = 0;
    if (tare_hx711(&tare_value) != 0) {
        syslog(LOG_ERR, "HX711 tare failed; aborting");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring weight (threshold=%d g, scale=%.2f, duration=%d ms)",
           g_threshold, g_scale, g_duration);

    while (g_running) {
        int raw_value;
        if (read_weight(&raw_value) == 0) {
            float weight = (float)(raw_value - tare_value) * g_scale;
            syslog(LOG_INFO, "Raw=%d, Weight=%.2f g", raw_value, weight);

            if (weight > g_threshold) {
                syslog(LOG_INFO, "Threshold exceeded (%.2f g > %.2f g); activating solenoid",
                       weight, g_threshold);
                activate_solenoid(g_duration);
            }
        } else {
            syslog(LOG_ERR, "Weight read failed; retrying in 1 s");
        }

        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(POLL_INTERVAL_US);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    cleanup();
    return EXIT_SUCCESS;
}

