#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST       "localhost"
#define MQTT_PORT       1883
#define MQTT_CLIENT_ID  "relay_controller_1"
#define MQTT_TOPIC      "home/lights/control"
#define MQTT_QOS        0
#define MQTT_KEEPALIVE  60
#define GPIO_RELAY      17
#define LOOP_DELAY_US   100000
#define RETRY_DELAY_US  5000000

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg)
{
    syslog(LOG_ERR, "%s", msg);
}

static void log_info(const char *msg)
{
    syslog(LOG_INFO, "%s", msg);
}

static int set_relay(int state)
{
    if (gpioWrite(GPIO_RELAY, state) < 0) {
        log_error("gpioWrite failed for relay GPIO17");
        return -1;
    }
    return 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        log_info("MQTT connected to broker");
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC, MQTT_QOS) != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        } else {
            log_info("Subscribed to topic");
        }
    } else {
        char buf[256];
        snprintf(buf, sizeof(buf), "MQTT connect failed: %s", mosquitto_strerror(result));
        log_error(buf);
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc)
{
    (void)m;
    (void)userdata;
    if (rc != 0) {
        char buf[256];
        snprintf(buf, sizeof(buf), "MQTT disconnected with error code %d", rc);
        log_error(buf);
    } else {
        log_info("MQTT disconnected");
    }
}

static void on_message(struct mosquitto *m, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0) {
        char payload[32];
        int len = message->payloadlen < (int)sizeof(payload) - 1
                 ? message->payloadlen
                 : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';

        if (strcmp(payload, "ON") == 0) {
            if (set_relay(1) == 0) {
                log_info("Relay turned ON");
            }
        } else if (strcmp(payload, "OFF") == 0) {
            if (set_relay(0) == 0) {
                log_info("Relay turned OFF");
            }
        } else {
            log_error("Invalid payload received");
        }
    } else {
        log_error("Empty payload received");
    }
}

static void on_error(struct mosquitto *m, void *userdata, int rc)
{
    (void)m;
    (void)userdata;
    char buf[256];
    snprintf(buf, sizeof(buf), "MQTT error: %s", mosquitto_strerror(rc));
    log_error(buf);
}

static void cleanup(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
    closelog();
}

int main(void)
{
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO17 as output");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (set_relay(0) != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_info("GPIO17 initialized as output, relay OFF");

    mosquitto_lib_init();
    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        log_error("Failed to create MQTT client");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);
    mosquitto_error_callback_set(g_mosq, on_error);

    int rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        cleanup();
        return EXIT_FAILURE;
    }

    log_info("MQTT client connected to broker");

    while (g_running) {
        rc = mosquitto_loop(g_mosq, LOOP_DELAY_US, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT loop error");
            if (g_mosq) {
                mosquitto_destroy(g_mosq);
                g_mosq = NULL;
            }
            mosquitto_lib_cleanup();
            gpioTerminate();
            closelog();
            sleep(RETRY_DELAY_US / 1000000);
            continue;
        }
        if (!g_running) break;
    }

    log_info("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

