#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define PWM_FREQUENCY 50
#define PULSE_WIDTH_MIN 500
#define PULSE_WIDTH_MAX 2500
#define HOLD_TIME_US 3000000
#define PERIOD_US (1000000 / PWM_FREQUENCY)

int init_gpio(void);
void set_servo_pulse(int pin, int pulse_width);
void stop_servos(void);
void cleanup(void);

int main(void) {
    if (init_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return EXIT_FAILURE;
    }

    int pulse_widths[] = {1000, 1500, 2000, 500, 2500};
    int num_servos = (int)(sizeof(pulse_widths) / sizeof(pulse_widths[0]));

    for (int i = 0; i < num_servos; i++) {
        set_servo_pulse(SERVO1_PIN + i, pulse_widths[i]);
        usleep(HOLD_TIME_US);
    }

    stop_servos();
    cleanup();
    return EXIT_SUCCESS;
}

int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    return 0;
}

void set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < PULSE_WIDTH_MIN || pulse_width > PULSE_WIDTH_MAX) {
        fprintf(stderr, "Error: Pulse width %d out of range for pin %d.\n", pulse_width, pin);
        return;
    }
    gpioSetMode(pin, PI_OUTPUT);
    gpioSetPWMfrequency(pin, PWM_FREQUENCY);
    gpioSetPWMrange(pin, 1000);
    gpioPWM(pin, pulse_width);
}

void stop_servos(void) {
    for (int i = 0; i < 5; i++) {
        gpioPWM(SERVO1_PIN + i, 0);
    }
}

void cleanup(void) {
    gpioTerminate();
}

