#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM_PIN  17
#define MOTOR_A_DIR_PIN  18
#define MOTOR_B_PWM_PIN  22
#define MOTOR_B_DIR_PIN  23

#define ENCODER_A_PHASE_A 4
#define ENCODER_A_PHASE_B 5
#define ENCODER_B_PHASE_A 6
#define ENCODER_B_PHASE_B 12

/* ---- Tuning parameters ---- */
#define TARGET_RPM 50.0
#define KP 10.0
#define KI 0.1
#define PWM_FREQUENCY 10000  /* Hz */
#define PWM_RANGE 255
#define STALL_TIMEOUT_SEC 2.0
#define LOOP_PERIOD_US 100000  /* 100 ms */
#define TICKS_PER_REV 64.0

/* ---- Shared state ---- */
static volatile int32_t encoder_a_ticks = 0;
static volatile int32_t encoder_b_ticks = 0;
static volatile double motor_a_integral = 0.0;
static volatile double motor_b_integral = 0.0;
static volatile bool motor_a_running = true;
static volatile bool motor_b_running = true;
static volatile bool encoder_a_stalled = false;
static volatile bool encoder_b_stalled = false;

/* ---- Prototypes ---- */
static void motor_a_forward(void);
static void motor_a_backward(void);
static void motor_b_forward(void);
static void motor_b_backward(void);
static void motor_stop(void);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static double calculate_rpm(int32_t ticks, double elapsed_seconds);
static void pi_control(double target_rpm, double *integral, double kp, double ki, double *prev_error);
static void signal_handler(int sig);
static int initialize_gpio(void);
static void cleanup(void);

/* ---- Motor primitives ---- */
static void motor_a_forward(void) {
    gpioWrite(MOTOR_A_DIR_PIN, 1);
    gpioPWM(MOTOR_A_PWM_PIN, PWM_RANGE);
}

static void motor_a_backward(void) {
    gpioWrite(MOTOR_A_DIR_PIN, 0);
    gpioPWM(MOTOR_A_PWM_PIN, PWM_RANGE);
}

static void motor_b_forward(void) {
    gpioWrite(MOTOR_B_DIR_PIN, 1);
    gpioPWM(MOTOR_B_PWM_PIN, PWM_RANGE);
}

static void motor_b_backward(void) {
    gpioWrite(MOTOR_B_DIR_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, PWM_RANGE);
}

static void motor_stop(void) {
    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, 0);
    gpioWrite(MOTOR_A_DIR_PIN, 0);
    gpioWrite(MOTOR_B_DIR_PIN, 0);
}

/* ---- Encoder ISRs ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    if (level == 1) {
        encoder_a_ticks++;
    }
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    if (level == 1) {
        encoder_b_ticks++;
    }
}

/* ---- RPM calculation ---- */
static double calculate_rpm(int32_t ticks, double elapsed_seconds) {
    if (elapsed_seconds <= 0.0) {
        return 0.0;
    }
    double revolutions = (double)ticks / TICKS_PER_REV;
    return (revolutions / elapsed_seconds) * 60.0;
}

/* ---- PI controller ---- */
static void pi_control(double target_rpm, double *integral, double kp, double ki, double *prev_error) {
    double current_rpm = calculate_rpm(encoder_a_ticks, (double)gpioTick() / 1000000.0);
    double error = target_rpm - current_rpm;
    *prev_error = error;
    double new_integral = *integral + error;
    double output = kp * error + ki * new_integral;
    if (output < 0.0) {
        output = 0.0;
    } else if (output > PWM_RANGE) {
        output = PWM_RANGE;
    }
    gpioPWM(MOTOR_A_PWM_PIN, (int)output);
    *integral = new_integral;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    motor_a_running = false;
    motor_b_running = false;
}

/* ---- GPIO initialization ---- */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Motor A */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM pin mode\n");
        return -1;
    }
    if (gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set direction pin mode\n");
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return -1;
    }
    motor_stop();

    /* Motor B */
    if (gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM pin mode\n");
        return -1;
    }
    if (gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set direction pin mode\n");
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return -1;
    }
    motor_stop();

    /* Encoder A */
    if (gpioSetMode(ENCODER_A_PHASE_A, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set encoder A phase A mode\n");
        return -1;
    }
    if (gpioSetMode(ENCODER_A_PHASE_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set encoder A phase B mode\n");
        return -1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_A, RISING_EDGE, 0, encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set encoder A ISR\n");
        return -1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_B, RISING_EDGE, 0, encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set encoder A ISR\n");
        return -1;
    }

    /* Encoder B */
    if (gpioSetMode(ENCODER_B_PHASE_A, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set encoder B phase A mode\n");
        return -1;
    }
    if (gpioSetMode(ENCODER_B_PHASE_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set encoder B phase B mode\n");
        return -1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_A, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set encoder B ISR\n");
        return -1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_B, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set encoder B ISR\n");
        return -1;
    }

    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    motor_stop();
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    printf("Motor control started. Target RPM: %.1f\n", TARGET_RPM);

    double motor_a_integral = 0.0;
    double motor_b_integral = 0.0;
    double prev_error_a = 0.0;
    double prev_error_b = 0.0;
    double prev_target_rpm = TARGET_RPM;
    double elapsed_time = 0.0;
    uint32_t last_loop_tick = gpioTick();

    while (motor_a_running || motor_b_running) {
        uint32_t current_loop_tick = gpioTick();
        uint32_t loop_duration = current_loop_tick - last_loop_tick;
        last_loop_tick = current_loop_tick;

        if (loop_duration > 0) {
            elapsed_time += (double)loop_duration / 1000000000.0;
        }

        if (encoder_a_ticks == 0) {
            encoder_a_stalled = true;
        } else {
            encoder_a_stalled = false;
        }
        if (encoder_b_ticks == 0) {
            encoder_b_stalled = true;
        } else {
            encoder_b_stalled = false;
        }

        if (encoder_a_stalled || encoder_b_stalled) {
            if (encoder_a_stalled && !encoder_a_stalled_warned) {
                fprintf(stderr, "WARNING: Encoder A stalled (0 ticks for %.1f s)\n", STALL_TIMEOUT_SEC);
                encoder_a_stalled_warned = true;
            }
            if (encoder_b_stalled && !encoder_b_stalled_warned) {
                fprintf(stderr, "WARNING: Encoder B stalled (0 ticks for %.1f s)\n", STALL_TIMEOUT_SEC);
                encoder_b_stalled_warned = true;
            }
        }

        if (motor_a_running) {
            pi_control(prev_target_rpm, &motor_a_integral, KP, KI, &prev_error_a);
        }
        if (motor_b_running) {
            pi_control(prev_target_rpm, &motor_b_integral, KP, KI, &prev_error_b);
        }

        printf("Motor A: RPM = %.2f, PWM = %d | Motor B: RPM = %.2f, PWM = %d\n",
               calculate_rpm(encoder_a_ticks, elapsed_time),
               gpioPWM(MOTOR_A_PWM_PIN),
               calculate_rpm(encoder_b_ticks, elapsed_time),
               gpioPWM(MOTOR_B_PWM_PIN));

        gpioDelay(LOOP_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

