#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_LED 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define POLL_INTERVAL_SEC 5
#define BH1750_WAIT_MS 180
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(int handle) {
    if (i2cWriteByte(handle, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to set BH1750 continuous high-res mode.\n");
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int handle, int *lux_out) {
    char buf[2];
    if (i2cWriteByte(handle, 0x14) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement.\n");
        return -1;
    }
    gpioDelay(BH1750_WAIT_MS * 1000);
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read BH1750 data.\n");
        return -1;
    }
    *lux_out = (buf[0] << 8) | buf[1];
    return 0;
}

static void log_data(int lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", BH1750_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bh1750_init(i2c_handle) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    int lux;

    while (running) {
        if (bh1750_read_lux(i2c_handle, &lux) == 0) {
            log_data(lux, relay_state);

            if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
                if (gpioWrite(GPIO_LED, 1) == 0) {
                    relay_state = 1;
                    printf("Dusk detected. Activating LED.\n");
                }
            } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1) {
                if (gpioWrite(GPIO_LED, 0) == 0) {
                    relay_state = 0;
                    printf("Dawn detected. Deactivating LED.\n");
                }
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed. Ensuring relay is off.\n");
            gpioWrite(GPIO_LED, 0);
            relay_state = 0;
            log_data(-1, 0);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

