#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define FLOW_THRESHOLD 5.0
#define FLOW_HYSTERESIS 4.5
#define LOG_FILE "water_flow.log"
#define DEBOUNCE_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(log_file);
    }
}

static void flow_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio;
    (void)tick;
    (void)user;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        static int pulse_count = 0;
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static double calculate_flow_rate(int pulse_count, int interval_seconds) {
    if (interval_seconds <= 0) return 0.0;
    return (double)pulse_count / (double)interval_seconds * 60.0;
}

static void control_solenoid(double flow_rate) {
    static int solenoid_state = 1;
    int new_state = solenoid_state;

    if (flow_rate > FLOW_THRESHOLD) {
        new_state = 0;
    } else if (flow_rate < FLOW_HYSTERESIS) {
        new_state = 1;
    }

    if (new_state != solenoid_state) {
        if (gpioWrite(SOLENOID_PIN, new_state) == 0) {
            solenoid_state = new_state;
            char msg[128];
            snprintf(msg, sizeof(msg), "Solenoid state changed to %s",
                     solenoid_state ? "OPEN" : "CLOSED");
            log_message(msg);
        } else {
            log_message("ERROR: Failed to write solenoid pin");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on flow sensor pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set solenoid initial state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        pthread_mutex_destroy(&pulse_mutex);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_US, flow_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        pthread_mutex_destroy(&pulse_mutex);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Water flow monitoring started");

    while (running) {
        sleep(1);
        int pulse_count;
        pthread_mutex_lock(&pulse_mutex);
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double flow_rate = calculate_flow_rate(pulse_count, 1);
        control_solenoid(flow_rate);

        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f LPM", flow_rate);
        log_message(msg);
    }

    log_message("Shutting down water flow monitoring");
    gpioWrite(SOLENOID_PIN, 1);
    pthread_mutex_destroy(&pulse_mutex);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

