#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <json-c/json.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 12345
#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define DEFAULT_CALIBRATION_FACTOR 1000.0
#define DEFAULT_SERVO_PULSE_WIDTH 1000
#define DEFAULT_SERVO_PULSE_WIDTH_MIN 1000
#define DEFAULT_SERVO_PULSE_WIDTH_MAX 2000
#define DEFAULT_TARGET_WEIGHT 100.0
#define DEFAULT_WEIGHT_UNIT "grams"
#define DEFAULT_API_CALL_INTERVAL 1
#define HX711_TIMEOUT_ATTEMPTS 1000
#define HX711_TIMEOUT_US 1000
#define SERVO_SETTLE_US 1000000
#define DISPENSE_DELAY_US 1000000
#define MAX_BUFFER_SIZE 1024

typedef struct {
    double calibration_factor;
    int servo_pulse_width;
} Config;

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static Config config;
static json_object *log_entry = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, Config *cfg) {
    cfg->calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    cfg->servo_pulse_width = DEFAULT_SERVO_PULSE_WIDTH;

    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: could not open config file '%s': %s. Using defaults.\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *name = strtok(line, "=\n");
        char *value = strtok(NULL, "=\n");
        if (!name || !value) continue;
        if (strcmp(name, "calibration_factor") == 0) {
            cfg->calibration_factor = atof(value);
        } else if (strcmp(name, "servo_pulse_width") == 0) {
            cfg->servo_pulse_width = atoi(value);
        }
    }
    fclose(fp);

    if (cfg->calibration_factor <= 0.0) {
        fprintf(stderr, "Warning: calibration_factor must be positive. Using default.\n");
        cfg->calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    }
    if (cfg->servo_pulse_width < DEFAULT_SERVO_PULSE_WIDTH_MIN || cfg->servo_pulse_width > DEFAULT_SERVO_PULSE_WIDTH_MAX) {
        fprintf(stderr, "Warning: servo pulse width %d out of range [%d, %d]. Using default.\n", cfg->servo_pulse_width, DEFAULT_SERVO_PULSE_WIDTH_MIN, DEFAULT_SERVO_PULSE_WIDTH_MAX);
        cfg->servo_pulse_width = DEFAULT_SERVO_PULSE_WIDTH;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50);
    gpioSetPWMrange(SERVO_PIN, 20000);
    return 0;
}

static int init_server(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }
    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(fd);
        return -1;
    }
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(SERVER_PORT);
    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }
    if (listen(fd, 3) < 0) {
        perror("listen");
        close(fd);
        return -1;
    }
    return fd;
}

static int init_api_call(void) {
    (void)config.calibration_factor;
    (void)config.servo_pulse_width;
    return 0;
}

static int read_hx711(long *raw_value) {
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
    gpioDelay(1);
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > HX711_TIMEOUT_ATTEMPTS) {
            fprintf(stderr, "Error: HX711 data pin stuck HIGH (sensor absent or not ready).\n");
            return -1;
        }
    }
    long value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        value = (value << 1) | (gpioRead(HX711_DATA_PIN) & 1);
        if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
    }
    if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
    gpioDelay(1);
    if (value & 0x800000) value |= 0xFF000000;
    *raw_value = value;
    return 0;
}

static double calibrate_weight(long raw_value) {
    return (double)raw_value / config.calibration_factor;
}

static int set_servo_pulse_width(int pulse_width) {
    if (pulse_width < 0 || pulse_width > 20000) {
        fprintf(stderr, "Error: servo pulse width %d out of range [0, 20000].\n", pulse_width);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse width %d.\n", pulse_width);
        return -1;
    }
    return 0;
}

static int dispensing_loop(void) {
    char buffer[MAX_BUFFER_SIZE];
    ssize_t bytes_received;
    while (running) {
        bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            double target_weight = strtod(buffer, NULL);
            if (target_weight <= 0.0) {
                const char *err = "Error: target weight must be positive.\n";
                send(client_fd, err, strlen(err), 0);
                continue;
            }
            int actual_pulse_width = (int)(DEFAULT_SERVO_PULSE_WIDTH_MIN + (target_weight / DEFAULT_TARGET_WEIGHT) * (DEFAULT_SERVO_PULSE_WIDTH_MAX - DEFAULT_SERVO_PULSE_WIDTH_MIN));
            if (actual_pulse_width < DEFAULT_SERVO_PULSE_WIDTH_MIN) actual_pulse_width = DEFAULT_SERVO_PULSE_WIDTH_MIN;
            if (actual_pulse_width > DEFAULT_SERVO_PULSE_WIDTH_MAX) actual_pulse_width = DEFAULT_SERVO_PULSE_WIDTH_MAX;
            if (set_servo_pulse_width(actual_pulse_width) < 0) {
                const char *err = "Error: failed to set servo pulse width.\n";
                send(client_fd, err, strlen(err), 0);
                continue;
            }
            if (init_api_call() < 0) {
                const char *err = "Error: API call initialization failed.\n";
                send(client_fd, err, strlen(err), 0);
                continue;
            }
            printf("Dispensing target weight: %.2f g\n", target_weight);
            gpioDelay(DISPENSE_DELAY_US);
            long raw_value = 0;
            if (read_hx711(&raw_value) < 0) {
                const char *err = "Error: HX711 read failed.\n";
                send(client_fd, err, strlen(err), 0);
                continue;
            }
            double actual_weight = calibrate_weight(raw_value);
            printf("Actual weight: %.2f g\n", actual_weight);
            char response[MAX_BUFFER_SIZE];
            snprintf(response, sizeof(response), "Actual weight: %.2f g\n", actual_weight);
            send(client_fd, response, strlen(response), 0);
            if (log_entry) {
                json_object_object_add(log_entry, "target_weight", json_integer(target_weight));
                json_object_object_add(log_entry, "actual_weight", json_integer((int)actual_weight));
                char *json_str = json_object_to_json_string_pretty(log_entry);
                if (json_str) {
                    fprintf(log_file, "%s\n", json_str);
                    fflush(log_file);
                    free(json_str);
                }
            }
        } else if (bytes_received == 0) {
            printf("Client disconnected.\n");
            break;
        } else {
            if (errno != EINTR) perror("recv");
            break;
        }
    }
    return 0;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    if (log_entry) {
        json_object_free(log_entry);
        log_entry = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (read_config(CONFIG_FILE, &config) < 0) {
        fprintf(stderr, "Using default configuration.\n");
    }

    if (init_gpio() < 0) {
        return 1;
    }

    server_fd = init_server();
    if (server_fd < 0) {
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in client_addr = {0};
    socklen_t client_len = sizeof(client_addr);
    client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
    if (client_fd < 0) {
        perror("accept");
        cleanup();
        return 1;
    }

    printf("Server listening on %s:%d\n", SERVER_IP, SERVER_PORT);

    while (running) {
        if (read_hx711(&config.calibration_factor) < 0) {
            const char *err = "Error: HX711 initialization failed.\n";
            send(client_fd, err, strlen(err), 0);
            continue;
        }
        printf("HX711 calibration factor: %lf\n", config.calibration_factor);
        if (dispensing_loop() < 0) break;
    }

    cleanup();
    return 0;
}

