            snprintf(response, sizeof(response), "Actual weight: %.2f g\n", actual_weight);
            send(client_fd, response, strlen(response), 0);
            if (log_entry) {
                json_object_object_add(log_entry, "target_weight", json_integer(target_weight));
                json_object_object_add(log_entry, "actual_weight", json_integer((int)actual_weight));
                char *json_str = json_object_to_json_string_pretty(log_entry);
                if (json_str) {
                    fprintf(log_file, "%s\n", json_str);
                    fflush(log_file);
                    free(json_str);
                }
            }
        } else if (bytes_received == 0) {
            printf("Client disconnected.\n");
            break;
        } else {
            if (errno != EINTR) perror("recv");
            break;
        }
    }
    return 0;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    if (log_entry) {
        json_object_free(log_entry);
        log_entry = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (read_config(CONFIG_FILE, &config) < 0) {
        fprintf(stderr, "Using default configuration.\n");
    }

    if (init_gpio() < 0) {
        return 1;
    }

    server_fd = init_server();
    if (server_fd < 0) {
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in client_addr = {0};
    socklen_t client_len = sizeof(client_addr);
    client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
    if (client_fd < 0) {
        perror("accept");
        cleanup();
        return 1;
    }

    printf("Server listening on %s:%d\n", SERVER_IP, SERVER_PORT);

    while (running) {
        if (read_hx711(&config.calibration_factor) < 0) {
            const char *err = "Error: HX711 initialization failed.\n";
            send(client_fd, err, strlen(err), 0);
            continue;
        }
        printf("HX711 calibration factor: %lf\n", config.calibration_factor);
        if (dispensing_loop() < 0) break;
    }

    cleanup();
    return 0;
}

