#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define SERVO_FREQ 50
#define SERVO_RANGE 20000
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_START_ANGLE 90
#define ANGLE_STEP 10
#define PULSE_STEP (SERVO_RANGE / 1000)

static volatile sig_atomic_t running = 1;
static struct termios orig_termios;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int restore_terminal(void) {
    if (tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios) != 0) {
        perror("restore_terminal: tcsetattr");
        return -1;
    }
    return 0;
}

static int set_terminal_raw(void) {
    struct termios raw;
    memset(&raw, 0, sizeof(raw));
    if (tcgetattr(STDIN_FILENO, &orig_termios) != 0) {
        perror("set_terminal_raw: tcgetattr");
        return -1;
    }
    if (tcgetattr(STDIN_FILENO, &raw) != 0) {
        perror("set_terminal_raw: tcgetattr");
        return -1;
    }
    raw.c_lflag &= ~(ICANON | ECHO);
    raw.c_cc[VMIN] = 0;
    raw.c_cc[VTIME] = 1;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) != 0) {
        perror("set_terminal_raw: tcsetattr");
        return -1;
    }
    return 0;
}

static int angle_to_pulse(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return (angle * SERVO_RANGE) / 180;
}

static int pulse_to_angle(int pulse) {
    if (pulse < SERVO_MIN_PULSE) pulse = SERVO_MIN_PULSE;
    if (pulse > SERVO_MAX_PULSE) pulse = SERVO_MAX_PULSE;
    return (pulse * 180) / SERVO_RANGE;
}

static int set_servo_angle(int angle) {
    int pulse = angle_to_pulse(angle);
    if (gpioServo(SERVO_PIN, pulse) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d\n", pulse);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(SERVO_PIN, SERVO_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_terminal_raw() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (restore_terminal() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_angle(SERVO_START_ANGLE) != 0) {
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int current_angle = SERVO_START_ANGLE;
    int last_key = -1;

    while (running) {
        char c = getchar();
        if (c == EOF) {
            restore_terminal();
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (c == 'q' || c == 'Q') {
            break;
        }

        if (c == '+' || c == '=') {
            current_angle += ANGLE_STEP;
        } else if (c == '-' || c == '_') {
            current_angle -= ANGLE_STEP;
        } else if (c == '0' || c == '1' || c == '2' || c == '3' || c == '4' || c == '5' || c == '6' || c == '7' || c == '8' || c == '9') {
            current_angle = c - '0';
        }

        if (current_angle < 0) current_angle = 0;
        if (current_angle > 180) current_angle = 180;

        int pulse = angle_to_pulse(current_angle);
        if (set_servo_angle(current_angle) != 0) {
            restore_terminal();
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Angle: %3d°  Pulse: %4d µs\n", current_angle, pulse);
        fflush(stdout);

        last_key = c;
        usleep(50000);
    }

    if (set_servo_angle(0) != 0) {
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    restore_terminal();
    gpioTerminate();
    return EXIT_SUCCESS;
}

