    int current_state = gpioRead(RELAY_PIN);
    if (current_state < 0) {
        fprintf(stderr, "pigpio read error on relay pin\n");
        return;
    }
    if (gpioWrite(RELAY_PIN, !current_state) != 0) {
        fprintf(stderr, "pigpio write error on relay pin\n");
    }
}

