            cleanup_gpio();
            return 1;
        }

        if (touch_value == 1 && !was_touching) {
            was_touching = 1;
            touch_start_time = time(NULL);
        }

        if (touch_value == 1) {
            if (touch_start_time == 0) {
                touch_start_time = time(NULL);
            } else if (difftime(time(NULL), touch_start_time) > MAX_TOUCH_TIME_SEC) {
                if (relay_state == 1) {
                    toggle_relay();
                    relay_state = 0;
                }
            }
        } else {
            was_touching = 0;
            if (relay_state == 1) {
                toggle_relay();
                relay_state = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup_gpio();
    return 0;
}

