#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_RANGE          255
#define PWM_FREQUENCY      1000
#define SAMPLE_INTERVAL_US 100000
#define FLOW_SENSOR_PULSES_PER_LITER 100.0

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void flow_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user;
    static uint32_t last_tick = 0;
    uint32_t diff;
    if (last_tick == 0) {
        last_tick = tick;
        return;
    }
    diff = tick - last_tick;
    last_tick = tick;
    static int first_call = 1;
    if (first_call) {
        first_call = 0;
        return;
    }
    static double total_pulses = 0.0;
    total_pulses += (double)diff / 1000000.0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM pin mode\n");
        return -1;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set enable pin mode\n");
        return -1;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        return -1;
    }

    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return -1;
    }
    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return -1;
    }

    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Failed to enable valve\n");
        return -1;
    }
    if (gpioPWM(VALVE_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set initial PWM duty cycle\n");
        return -1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor\n");
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(VALVE_PWM_PIN, 0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

static double calculate_flow_rate(double pulses, double time_sec) {
    if (time_sec <= 0.0) return 0.0;
    return (double)pulses / FLOW_SENSOR_PULSES_PER_LITER / time_sec;
}

static int set_valve_position(double flow_rate, double target_flow_rate, double Kp) {
    double error = target_flow_rate - flow_rate;
    double duty_cycle = Kp * error;
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(VALVE_PWM_PIN, (int)duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static void log_data(double flow_rate, int valve_position) {
    if (g_log_file == NULL) return;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(g_log_file, "%s.%03ld,%.2f,%d\n", timestamp, ts.tv_nsec / 1000000, flow_rate, valve_position);
    fflush(g_log_file);
}

int main(int argc, char *argv[]) {
    double target_flow_rate = 0.0;
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s -t target_flow_rate_L_per_min\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (target_flow_rate <= 0.0) {
        fprintf(stderr, "Target flow rate must be a positive number\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen("flow_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    long file_size = ftell(g_log_file);
    if (file_size == 0) {
        fprintf(g_log_file, "timestamp_ms,flow_rate,valve_position\n");
        fflush(g_log_file);
    }

    double pulses = 0.0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (g_running) {
        struct timespec sleep_time = {0, SAMPLE_INTERVAL_US * 1000};
        nanosleep(&sleep_time, NULL);

        clock_gettime(CLOCK_REALTIME, &current_time);
        double elapsed_sec = (current_time.tv_sec - start_time.tv_sec) +
                             (current_time.tv_nsec - start_time.tv_nsec) / 1e9;
        double new_pulses = (double)(total_pulses - pulses) / elapsed_sec;
        pulses = total_pulses;

        double flow_rate = calculate_flow_rate(new_pulses, elapsed_sec);
        int valve_position = (int)flow_rate;
        if (valve_position < 0) valve_position = 0;
        if (valve_position > PWM_RANGE) valve_position = PWM_RANGE;

        if (set_valve_position(flow_rate, target_flow_rate, 1.0) != 0) {
            fprintf(stderr, "Error setting valve position\n");
        }

        log_data(flow_rate, valve_position);
    }

    cleanup_gpio();
    if (g_log_file != NULL) {
        fclose(g_log_file);
    }
    return EXIT_SUCCESS;
}

