            gpioDelay(100000);
            continue;
        }

        if (button_state == 0 && last_button_state == 1) {
            button_pressed = 1;
            gpioDelay(DEBOUNCE_DELAY_US);
            button_state = gpioRead(BUTTON_PIN);
            if (button_state == 0) {
                button_pressed = 1;
            } else {
                button_pressed = 0;
            }
        }
        last_button_state = button_state;

        if (button_pressed) {
            if (read_rfid_tag(rfid_tag) == 0) {
                if (verify_tag(rfid_tag) == 0) {
