#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PWM_FREQUENCY 100
#define PWM_RANGE 255
#define SAMPLE_TIME_US 100000
#define TARGET_SPEED 60.0
#define KP 1.0
#define KI 0.1
#define KD 0.5

static volatile int running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void stop_motors(void) {
    gpioPWM(MOTOR1_ENA, 0);
    gpioPWM(MOTOR1_IN1, 0);
    gpioPWM(MOTOR1_IN2, 0);
    gpioPWM(MOTOR2_ENB, 0);
    gpioPWM(MOTOR2_IN3, 0);
    gpioPWM(MOTOR2_IN4, 0);
}

static void cleanup(void) {
    stop_motors();
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void log_data(double motor1_speed, double motor2_speed,
                     double motor1_p, double motor1_i, double motor1_d,
                     double motor2_p, double motor2_i, double motor2_d,
                     double motor1_pid, double motor2_pid) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, motor1_speed, motor2_speed, motor1_p, motor1_i, motor1_d,
            motor2_p, motor2_i, motor2_d, motor1_pid, motor2_pid);
    fflush(log_file);
}

static void *encoder1_thread(void *arg) {
    (void)arg;
    int encoder1_count = 0;
    int last_a1 = 0, last_b1 = 0;

    while (running) {
        int a1 = gpioRead(ENCODER1_A);
        int b1 = gpioRead(ENCODER1_B);

        if (a1 < 0 || b1 < 0) {
            fprintf(stderr, "Error reading encoder A/B pins\n");
            gpioDelay(1000);
            continue;
        }

        if (a1 != last_a1) {
            if (b1 == 0) {
                encoder1_count++;
            } else {
                encoder1_count--;
            }
        }
        last_a1 = a1;
        last_b1 = b1;

        pthread_mutex_lock(&encoder1_mutex);
        encoder1_count = encoder1_count & 0xFFFF;
        double speed = (double)encoder1_count * 60.0 / 1024.0;
        pthread_mutex_unlock(&encoder1_mutex);

        gpioDelay(1000);
    }
    return NULL;
}

static void *encoder2_thread(void *arg) {
    (void)arg;
    int encoder2_count = 0;
    int last_a2 = 0, last_b2 = 0;

    while (running) {
        int a2 = gpioRead(ENCODER2_A);
        int b2 = gpioRead(ENCODER2_B);

        if (a2 < 0 || b2 < 0) {
            fprintf(stderr, "Error reading encoder A/B pins\n");
            gpioDelay(1000);
            continue;
        }

        if (a2 != last_a2) {
            if (b2 == 0) {
                encoder2_count++;
            } else {
                encoder2_count--;
            }
        }
        last_a2 = a2;
        last_b2 = b2;

        pthread_mutex_lock(&encoder2_mutex);
        encoder2_count = encoder2_count & 0xFFFF;
        double speed = (double)encoder2_count * 60.0 / 1024.0;
        pthread_mutex_unlock(&encoder2_mutex);

        gpioDelay(1000);
    }
    return NULL;
}

static double pid_control(double setpoint, double actual_value,
                          double kp, double ki, double kd,
                          double *integral, double *previous_error) {
    double error = setpoint - actual_value;
    *integral += error * SAMPLE_TIME_US / 1000000.0;
    if (*integral > 10000.0) *integral = 10000.0;
    if (*integral < -10000.0) *integral = -10000.0;
    double derivative = (error - *previous_error) / SAMPLE_TIME_US;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;
    return output;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Motor1_Speed_RPM,Motor2_Speed_RPM,Motor1_P,Motor1_I,Motor1_D,Motor2_P,Motor2_I,Motor2_D,Motor1_PID,Motor2_PID\n");

    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);

    gpioSetAlertFuncEx(ENCODER1_A, encoder1_callback, NULL);
    gpioSetAlertFuncEx(ENCODER1_B, encoder1_callback, NULL);
    gpioSetAlertFuncEx(ENCODER2_A, encoder2_callback, NULL);
    gpioSetAlertFuncEx(ENCODER2_B, encoder2_callback, NULL);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    pthread_t encoder1_thread_id, encoder2_thread_id;
    if (pthread_create(&encoder1_thread_id, NULL, encoder1_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder1 thread\n");
        cleanup();
        return 1;
    }
    if (pthread_create(&encoder2_thread_id, NULL, encoder2_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder2 thread\n");
        running = 0;
        pthread_join(encoder1_thread_id, NULL);
        cleanup();
        return 1;
    }

    double motor1_p = 0.0, motor1_i = 0.0, motor1_d = 0.0;
    double motor2_p = 0.0, motor2_i = 0.0, motor2_d = 0.0;
    double motor1_pid = 0.0, motor2_pid = 0.0;

    while (running) {
        double motor1_speed = 0.0, motor2_speed = 0.0;
        int encoder1_count = 0, encoder2_count = 0;

        pthread_mutex_lock(&encoder1_mutex);
        encoder1_count = encoder1_count & 0xFFFF;
        motor1_speed = (double)encoder1_count * 60.0 / 1024.0;
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        encoder2_count = encoder2_count & 0xFFFF;
        motor2_speed = (double)encoder2_count * 60.0 / 1024.0;
        pthread_mutex_unlock(&encoder2_mutex);

        motor1_pid = pid_control(TARGET_SPEED, motor1_speed, KP, KI, KD, &motor1_i, &motor1_p);
        motor2_pid = pid_control(TARGET_SPEED, motor2_speed, KP, KI, KD, &motor2_i, &motor2_p);

        if (motor1_pid > 100.0) motor1_pid = 100.0;
        if (motor1_pid < -100.0) motor1_pid = -100.0;
        if (motor2_pid > 100.0) motor2_pid = 100.0;
        if (motor2_pid < -100.0) motor2_pid = -100.0;

        if (motor1_pid > 0) {
            gpioPWM(MOTOR1_ENA, PWM_RANGE);
            gpioPWM(MOTOR1_IN1, PWM_RANGE);
            gpioPWM(MOTOR1_IN2, 0);
        } else if (motor1_pid < 0) {
            gpioPWM(MOTOR1_ENA, 0);
            gpioPWM(MOTOR1_IN1, 0);
            gpioPWM(MOTOR1_IN2, PWM_RANGE);
        } else {
            gpioPWM(MOTOR1_ENA, 0);
            gpioPWM(MOTOR1_IN1, 0);
            gpioPWM(MOTOR1_IN2, 0);
        }

        if (motor2_pid > 0) {
            gpioPWM(MOTOR2_ENB, PWM_RANGE);
            gpioPWM(MOTOR2_IN3, PWM_RANGE);
            gpioPWM(MOTOR2_IN4, 0);
        } else if (motor2_pid < 0) {
            gpioPWM(MOTOR2_ENB, 0);
            gpioPWM(MOTOR2_IN3, 0);
            gpioPWM(MOTOR2_IN4, PWM_RANGE);
        } else {
            gpioPWM(MOTOR2_ENB, 0);
            gpioPWM(MOTOR2_IN3, 0);
            gpioPWM(MOTOR2_IN4, 0);
        }

        log_data(motor1_speed, motor2_speed, motor1_p, motor1_i, motor1_d,
                 motor2_p, motor2_i, motor2_d, motor1_pid, motor2_pid);

        gpioDelay(SAMPLE_TIME_US);
    }

    running = 0;
    stop_motors();
    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);
    cleanup();
    return 0;
}

