#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5C
#define RELAY_GPIO 17
#define I2C_BUS 1
#define LOG_FILE "relay_log.txt"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_ECR 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg8(fd, MPR121_ECR, 0x00) < 0) return -1; // Soft reset
    usleep(10000);

    if (i2c_write_reg8(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_MHDF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDF, 0x05) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLF, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDT, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLT, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLT, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg8(fd, MPR121_E0TTH + i * 2, 0x0F) < 0) return -1;
        if (i2c_write_reg8(fd, MPR121_E0RTH + i * 2, 0x0A) < 0) return -1;
    }

    if (i2c_write_reg8(fd, MPR121_ECR, 0x0C) < 0) return -1; // Enable 12 electrodes, run mode
    usleep(10000);
    return 0;
}

static int read_touch_status(int fd, uint16_t *status) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L + 1, &hi) < 0) return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Relay State: %s\n", timestamp, state ? "ON" : "OFF");
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    uint16_t touch_status;
    int relay_state = 0;

    while (running) {
        if (read_touch_status(i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status\n");
            break;
        }

        int touched = (touch_status & 0x0FFF) != 0;
        if (touched && !relay_state) {
            gpioWrite(RELAY_GPIO, 1);
            relay_state = 1;
            log_relay_state(relay_state);
        } else if (!touched && relay_state) {
            gpioWrite(RELAY_GPIO, 0);
            relay_state = 0;
            log_relay_state(relay_state);
        }

        usleep(50000);
    }

    gpioWrite(RELAY_GPIO, 0);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

