#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define VALVE_1_GPIO 17
#define VALVE_2_GPIO 18
#define VALVE_1_DURATION_MS 500
#define VALVE_2_DURATION_MS 1000
#define VALVE_1_PAUSE_MS 5000
#define VALVE_2_PAUSE_MS 10000
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (log_file == NULL) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_valve(int gpio, int duration_ms) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", gpio);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", gpio);
        return -1;
    }

    return 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(VALVE_1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(VALVE_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_2_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(VALVE_1_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d LOW\n", VALVE_1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(VALVE_2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d LOW\n", VALVE_2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioWrite(VALVE_1_GPIO, 0);
    gpioWrite(VALVE_2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
