    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", gpio);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(gpio, 0) != 0) {
