#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define UNLOCK_DURATION_MS 500
#define POLL_INTERVAL_MS 50
#define RATE_LIMIT_MS 2000
#define LOG_FILE "door_events.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(log_file, "[timestamp_error] %s\n", event_type);
    } else {
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        char time_buf[32];
        strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(log_file, "[%s.%03ld] %s\n", time_buf, ts.tv_nsec / 1000000, event_type);
    }
    fflush(log_file);
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set relay HIGH\n");
        return;
    }
    log_event("Door Unlocked");
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set relay LOW\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set PIR pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on PIR pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay to LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }

    int last_pir_state = 0;
    uint32_t last_event_tick = 0;

    printf("Monitoring PIR sensor on GPIO %d, relay on GPIO %d. Press Ctrl+C to exit.\n", PIR_PIN, RELAY_PIN);

    while (running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "Error: failed to read PIR sensor\n");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            uint32_t now = gpioTick();
            if (now - last_event_tick >= RATE_LIMIT_MS * 1000) {
                log_event("Motion Detected");
                unlock_door();
                last_event_tick = now;
            }
        }
        last_pir_state = pir_state;
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

