#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"

#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET 0.0

#define WEIGHT_THRESHOLD 10.0
#define NUM_CALIBRATION_READINGS 100
#define READ_INTERVAL_MS 500
#define HX711_TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;

static double scale_factor = DEFAULT_SCALE_FACTOR;
static double offset = DEFAULT_OFFSET;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open calibration file '%s'. Using defaults.\n", CALIBRATION_FILE);
        return 0;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Warning: Could not read calibration data from '%s'. Using defaults.\n", CALIBRATION_FILE);
        fclose(fp);
        return 0;
    }
    fclose(fp);

    double s = strtod(line, NULL);
    if (s == 0.0) {
        fprintf(stderr, "Warning: Invalid scale factor in calibration file. Using default.\n");
        return 0;
    }
    scale_factor = s;

    if (!fgets(line, sizeof(line), fp)) {
        fclose(fp);
        return 0;
    }
    fclose(fp);

    double o = strtod(line, NULL);
    if (o == 0.0) {
        fprintf(stderr, "Warning: Invalid offset in calibration file. Using default.\n");
        return 0;
    }
    offset = o;

    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp) {
        fprintf(fp, "%.6f %.6f\n", scale_factor, offset);
        fclose(fp);
    } else {
        fprintf(stderr, "Warning: Could not save calibration data to '%s'.\n", CALIBRATION_FILE);
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set HX711 data pin mode.\n");
        return -1;
    }
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set HX711 clock pin mode.\n");
        return -1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin mode.\n");
        return -1;
    }

    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialize solenoid pin state.\n");
        return -1;
    }

    return 0;
}

static long read_hx711(void) {
    long value = 0;
    int timeout = 0;

    while (gpioRead(HX711_CLOCK_PIN) == 1) {
        if (timeout++ > HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 timeout waiting for clock low.\n");
            return -1;
        }
        gpioDelay(1);
    }

    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) {
            fprintf(stderr, "Error: Failed to write HX711 clock high.\n");
            return -1;
        }
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) {
            fprintf(stderr, "Error: Failed to write HX711 clock low.\n");
            return -1;
        }
        gpioDelay(1);
    }

    if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to write HX711 clock high for 25th pulse.\n");
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to write HX711 clock low for 25th pulse.\n");
        return -1;
    }
    gpioDelay(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

static double calibrate_hx711(void) {
    double sum = 0.0;
    int valid_readings = 0;

    printf("Starting calibration. Remove all weight from the load cell.\n");
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        long raw = read_hx711();
        if (raw == -1) {
            fprintf(stderr, "Error: Failed to read HX711 during calibration.\n");
            return -1.0;
        }
        sum += raw;
        valid_readings++;
        gpioDelay(10000);
    }

    if (valid_readings == 0) {
        fprintf(stderr, "Error: No valid readings during calibration.\n");
        return -1.0;
    }

    offset = sum / valid_readings;
    printf("Calibration complete. Offset: %.2f\n", offset);
    return offset;
}

static double calculate_weight(long raw_value) {
    return (raw_value - offset) / scale_factor;
}

static void log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file '%s'.\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
}

static void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        if (gpioWrite(SOLENOID_PIN, 1) < 0) {
            fprintf(stderr, "Error: Failed to engage solenoid.\n");
        } else {
            printf("Weight %.2f kg exceeds threshold %.2f kg. Solenoid engaged.\n", weight, WEIGHT_THRESHOLD);
        }
    } else {
        if (gpioWrite(SOLENOID_PIN, 0) < 0) {
            fprintf(stderr, "Error: Failed to disengage solenoid.\n");
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    if (read_calibration_data() < 0) {
        fprintf(stderr, "Using default calibration values.\n");
    }

    if (calibrate_hx711() < 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        gpioWrite(SOLENOID_PIN, 0);
        gpioTerminate();
        return 1;
    }

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        long raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read HX711. Skipping iteration.\n");
            gpioDelay(READ_INTERVAL_MS * 1000);
            continue;
        }

        double weight = calculate_weight(raw_value);
        log_weight(weight);
        control_solenoid(weight);

        gpioDelay(READ_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return 0;
}

