#include <unistd.h>
#include <syslog.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 50000
#define MOTOR_RUN_TIME_SEC 5
#define MOTOR_PWM_FREQ 1000
#define MOTOR_PWM_RANGE 255
#define MOTOR_PWM_DUTY 150
#define CHECK_INTERVAL_SEC 60
#define POST_CLOSE_DELAY_SEC 60

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpioRead(RAIN_SENSOR_PIN);
        if (val < 0) {
            syslog(LOG_ERR, "gpioRead failed on pin %d", RAIN_SENSOR_PIN);
            return -1;
        }
        if (val == 0) {
            low_count++;
        }
        if (i < DEBOUNCE_SAMPLES - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }
    return (low_count >= 3) ? 1 : 0;
}

static int control_motor(int direction) {
    if (direction != 0 && direction != 1) {
        syslog(LOG_ERR, "Invalid motor direction: %d", direction);
        return -1;
    }

    if (gpioWrite(MOTOR_IN1_PIN, direction) < 0) {
        syslog(LOG_ERR, "gpioWrite failed on IN1 pin %d", MOTOR_IN1_PIN);
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, !direction) < 0) {
        syslog(LOG_ERR, "gpioWrite failed on IN2 pin %d", MOTOR_IN2_PIN);
        return -1;
    }

    if (gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTY) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on PWM pin %d", MOTOR_PWM_PIN);
        return -1;
    }

    return 0;
}

static void stop_motor(void) {
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    stop_motor();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        fprintf(stderr, "pigpio initialisation failed\n");
        closelog();
        return EXIT_FAILURE;
    }

    log_file = fopen("/var/log/window_control.log", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor pin modes");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Window control system started");
    log_event("System started");

    while (running) {
        int rain = read_rain_sensor();
        if (rain < 0) {
            log_event("Error reading rain sensor");
            sleep(1);
            continue;
        }

        if (rain) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Rain detected, closing window");
            syslog(LOG_INFO, "%s", msg);
            log_event(msg);

            if (control_motor(1) < 0) {
                log_event("Error starting motor");
            } else {
                for (int i = 0; i < MOTOR_RUN_TIME_SEC * 10 && running; i++) {
                    gpioDelay(100000);
                }
                stop_motor();
                log_event("Motor stopped");
            }

            for (int i = 0; i < POST_CLOSE_DELAY_SEC * 10 && running; i++) {
                gpioDelay(100000);
            }
        }

        for (int i = 0; i < CHECK_INTERVAL_SEC * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    log_event("System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

