#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define LOCK_DURATION 5
#define LOG_FILE "stock_events.txt"
#define READ_TIMEOUT_US 1000000
#define READ_RETRIES 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int hx711_read(int *raw_value) {
    int retries = READ_RETRIES;
    while (retries > 0) {
        if (gpioSetMode(HX711_DT_PIN, PI_INPUT) != 0) {
            log_event("Error: Failed to set DT pin mode.");
            return -1;
        }
        if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) != 0) {
            log_event("Error: Failed to set SCK pin mode.");
            return -1;
        }
        if (gpioWrite(HX711_SCK_PIN, 0) != 0) {
            log_event("Error: Failed to write SCK low.");
            return -1;
        }
        int timeout = 0;
        while (gpioRead(HX711_DT_PIN) == 0 && timeout < READ_TIMEOUT_US) {
            gpioDelay(100);
            timeout += 100;
        }
        if (timeout >= READ_TIMEOUT_US) {
            log_event("Error: HX711 timeout waiting for data ready.");
            return -1;
        }
        long value = 0;
        for (int i = 0; i < 24; i++) {
            if (gpioWrite(HX711_SCK_PIN, 1) != 0) {
                log_event("Error: Failed to write SCK high.");
                return -1;
            }
            gpioDelay(1);
            value = (value << 1) | gpioRead(HX711_DT_PIN);
            if (gpioWrite(HX711_SCK_PIN, 0) != 0) {
                log_event("Error: Failed to write SCK low.");
                return -1;
            }
            gpioDelay(1);
        }
        if (gpioWrite(HX711_SCK_PIN, 1) != 0) {
            log_event("Error: Failed to write SCK high for 25th pulse.");
            return -1;
        }
        gpioDelay(1);
        if (gpioWrite(HX711_SCK_PIN, 0) != 0) {
            log_event("Error: Failed to write SCK low for 25th pulse.");
            return -1;
        }
        gpioDelay(1);
        if (value & 0x800000) {
            value |= ~0xffffff;
        }
        *raw_value = (int)value;
        return 0;
    }
    log_event("Error: HX711 read failed after retries.");
    return -1;
}

static double convert_to_grams(int raw_value) {
    return (double)raw_value / 1000.0;
}

static int activate_solenoid(int duration_seconds) {
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        log_event("Error: Failed to set solenoid pin mode.");
        return -1;
    }
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        log_event("Error: Failed to activate solenoid.");
        return -1;
    }
    gpioDelay(duration_seconds * 1000000);
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        log_event("Error: Failed to deactivate solenoid.");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    log_event("Program started.");
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        int raw_value;
        if (hx711_read(&raw_value) == 0) {
            double weight = convert_to_grams(raw_value);
            char message[128];
            snprintf(message, sizeof(message), "Weight: %.2f g", weight);
            log_event(message);
            if (weight < WEIGHT_THRESHOLD) {
                log_event("Weight below threshold. Activating solenoid lock.");
                if (activate_solenoid(LOCK_DURATION) != 0) {
                    log_event("Error: Solenoid activation failed.");
                }
            }
        } else {
            log_event("Error: Failed to read weight.");
        }
        gpioDelay(1000000);
    }
    log_event("Program shutting down.");
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        log_event("Warning: Failed to deactivate solenoid during shutdown.");
    }
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

