#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0
#define SAMPLE_DELAY_US 100000
#define HX711_TIMEOUT_US 100000
#define SOLENOID_HOLD_US 5000000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t solenoid_active = 0;
static FILE *log_file = NULL;
static FILE *calib_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hx711_read(int *out) {
    int data = 0;
    int timeout = 0;

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;

    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (++timeout > HX711_TIMEOUT_US) return -1;
        gpioDelay(1);
    }

    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        data = data << 1;
        if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
        if (gpioRead(HX711_DATA_PIN)) data |= 1;
    }

    if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
    gpioDelay(1);

    if (data & 0x800000) data |= 0xFF000000;
    *out = data;
    return 0;
}

static double hx711_to_weight(int raw, double cal) {
    return (double)raw / cal;
}

static int save_calibration(double cal) {
    calib_file = fopen(CALIBRATION_FILE, "w");
    if (!calib_file) return -1;
    fprintf(calib_file, "%.6f\n", cal);
    fclose(calib_file);
    calib_file = NULL;
    return 0;
}

static int load_calibration(double *cal) {
    calib_file = fopen(CALIBRATION_FILE, "r");
    if (!calib_file) return -1;
    if (fscanf(calib_file, "%lf", cal) != 1) {
        fclose(calib_file);
        calib_file = NULL;
        return -1;
    }
    fclose(calib_file);
    calib_file = NULL;
    return 0;
}

static int log_security_event(double weight) {
    if (!log_file) return -1;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
