    }

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int raw;
        if (hx711_read(&raw) != 0) {
            fprintf(stderr, "HX711 read timeout or error.\n");
            gpioDelay(SAMPLE_DELAY_US);
