#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read the KY-022 IR obstacle sensor.
 * The module is active-low: a LOW reading (0) means an obstacle is detected.
 * Returns 0 or 1 on success, -1 on error.
 */
static int read_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error reading sensor on GPIO%d: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/*
 * Toggle the relay state and log the event.
 * Returns 0 on success, -1 on error.
 */
static int toggle_relay(int pin) {
    int current = gpioRead(pin);
    if (current < 0) {
        fprintf(stderr, "Error reading relay state on GPIO%d: %s\n",
                pin, pigpio_error(current));
        return -1;
    }

    int new_state = (current == 0) ? 1 : 0;

    if (gpioWrite(pin, new_state) < 0) {
        fprintf(stderr, "Error writing to relay on GPIO%d: %s\n",
                pin, pigpio_error(new_state));
        return -1;
    }

    /* Build an ISO 8601 timestamp */
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    /* Append the event to the log file */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    const char *state_str = new_state ? "ON" : "OFF";
    if (fprintf(fp, "%s - Relay state changed to %s\n", timestamp, state_str) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pin as input */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %s\n",
                SENSOR_PIN, pigpio_error(SENSOR_PIN));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %s\n",
                RELAY_PIN, pigpio_error(RELAY_PIN));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise relay to OFF: %s\n",
                pigpio_error(RELAY_PIN));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-022 sensor on GPIO%d and relay on GPIO%d.\n",
           SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_relay_state = gpioRead(RELAY_PIN);
    if (last_relay_state < 0) {
        fprintf(stderr, "Failed to read initial relay state: %s\n",
                pigpio_error(RELAY_PIN));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int sensor_value = read_sensor(SENSOR_PIN);
        if (sensor_value < 0) {
            /* Sensor read error — wait and retry */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-022 is active-low: obstacle detected when sensor reads LOW */
        if (sensor_value == 0 && last_relay_state == 0) {
            /* No change — ignore */
        } else if (sensor_value == 0 && last_relay_state == 1) {
            /* Obstacle detected — toggle relay */
            if (toggle_relay(RELAY_PIN) < 0) {
                fprintf(stderr, "Relay toggle failed; continuing.\n");
            }
        } else if (sensor_value == 1 && last_relay_state == 0) {
            /* No obstacle — toggle relay */
            if (toggle_relay(RELAY_PIN) < 0) {
                fprintf(stderr, "Relay toggle failed; continuing.\n");
            }
        } else if (sensor_value == 1 && last_relay_state == 1) {
            /* No change — ignore */
        } else {
            fprintf(stderr, "Unexpected sensor reading: %d\n", sensor_value);
        }

        last_relay_state = gpioRead(RELAY_PIN);
        if (last_relay_state < 0) {
            fprintf(stderr, "Failed to read relay state: %s\n",
                    pigpio_error(RELAY_PIN));
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown: turn relay OFF and release pigpio resources */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

