#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define MIN_DURATION 1
#define MAX_DURATION 3600
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_watering_duration(const char *filename, int *duration_out) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening configuration file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading configuration file '%s': %s\n", filename, ferror(fp) ? strerror(errno) : "unexpected EOF");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *start = strstr(line, "duration=");
    if (!start) {
        fprintf(stderr, "Configuration file '%s' does not contain 'duration=<seconds>'\n", filename);
        return -1;
    }

    errno = 0;
    char *endptr = NULL;
    long val = strtol(start + 8, &endptr, 10);
    if (errno != 0 || endptr == start + 8 || *endptr != '\0') {
        fprintf(stderr, "Invalid duration format in configuration file '%s'\n", filename);
        return -1;
    }

    if (val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Duration %ld out of range [%d, %d].\n", val, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration_out = (int)val;
    return 0;
}

static int control_valve(int gpio, int duration_seconds) {
    if (gpioWrite(gpio, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d low (valve off): %s\n", GPIO_PIN, strerror(errno));
        return -1;
    }
    printf("Valve OFF\n");

    time_t start = time(NULL);
    if (start == (time_t)-1) {
        fprintf(stderr, "Error getting start time: %s\n", strerror(errno));
        return -1;
    }

    while (g_running && (time(NULL) - start) < duration_seconds) {
        time_t remaining = (time_t)(duration_seconds - (time(NULL) - start));
        if (remaining <= 0) break;
        struct timespec ts = { .tv_sec = remaining, .tv_nsec = 0 };
        nanosleep(&ts, NULL);
    }

    if (!g_running) {
        fprintf(stderr, "Interrupted by signal during watering.\n");
        return -1;
    }

    if (gpioWrite(gpio, 1) < 0) {
        fprintf(stderr, "Error setting GPIO %d high (valve on): %s\n", GPIO_PIN, strerror(errno));
        return -1;
    }
    printf("Valve ON\n");

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(GPIO_PIN, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d low initially: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    int duration = 0;
    if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Failed to read watering duration from configuration file.\n");
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        return 1;
    }

    printf("Watering duration: %d seconds\n", duration);

    if (control_valve(GPIO_PIN, duration) != 0) {
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        return 1;
    }

    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    return 0;
}

