#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define MOTOR_LEFT_PIN 22
#define MOTOR_RIGHT_PIN 23
#define MOTOR_PWM_FREQ 1000
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return val;
}

static void set_motor_speed(int left_pin, int right_pin, int left_speed, int right_speed) {
    if (gpioPWM(left_pin, left_speed) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", left_pin, strerror(errno));
    }
    if (gpioPWM(right_pin, right_speed) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", right_pin, strerror(errno));
    }
}

static void log_data(FILE *fp, int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Left: %d, Middle: %d, Right: %d, Left Speed: %d, Right Speed: %d\n",
            timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(fp);
}

static void cleanup(void) {
    set_motor_speed(MOTOR_LEFT_PIN, MOTOR_RIGHT_PIN, 0, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int left_sensor, middle_sensor, right_sensor;
    int left_speed, right_speed;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting sensor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_LEFT_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting motor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_LEFT_PIN, MOTOR_PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR_RIGHT_PIN, MOTOR_PWM_FREQ) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_LEFT_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_RIGHT_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        left_sensor = read_sensor(LEFT_SENSOR_PIN);
        middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        if (left_sensor < 0 || middle_sensor < 0 || right_sensor < 0) {
            fprintf(stderr, "Sensor read error, stopping motors\n");
            set_motor_speed(MOTOR_LEFT_PIN, MOTOR_RIGHT_PIN, 0, 0);
            break;
        }

        if (left_sensor == 0 && middle_sensor == 0) {
            left_speed = 150;
            right_speed = 150;
        } else if (left_sensor == 0 && middle_sensor != 0 && right_sensor != 0) {
            left_speed = 150;
            right_speed = 0;
        } else if (middle_sensor == 0 && right_sensor == 0) {
            left_speed = 0;
            right_speed = 150;
        } else {
            left_speed = 0;
            right_speed = 0;
        }

        set_motor_speed(MOTOR_LEFT_PIN, MOTOR_RIGHT_PIN, left_speed, right_speed);
        log_data(log_file, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

