            set_motor_speed(MOTOR_LEFT_PIN, MOTOR_RIGHT_PIN, 0, 0);
            break;
        }

        if (left_sensor == 0 && middle_sensor == 0) {
            left_speed = 150;
            right_speed = 150;
        } else if (left_sensor == 0 && middle_sensor != 0 && right_sensor != 0) {
            left_speed = 150;
            right_speed = 0;
        } else if (middle_sensor == 0 && right_sensor == 0) {
            left_speed = 0;
            right_speed = 150;
        } else {
            left_speed = 0;
            right_speed = 0;
        }

        set_motor_speed(MOTOR_LEFT_PIN, MOTOR_RIGHT_PIN, left_speed, right_speed);
        log_data(log_file, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

