#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"
#define MEASUREMENT_DELAY_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fclose(fp);
}

static int read_lux(int handle, int *lux_out) {
    char cmd = 0x10;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        log_event("I2C write error: failed to send measurement command");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        log_event("I2C read error: failed to read lux data");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (int)(raw / 1.2);
    return 0;
}

static void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay set to %s", state ? "ON" : "OFF");
    log_event(msg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    log_event("Program started");
    int relay_state = 0;
    while (running) {
        int lux;
        if (read_lux(i2c_handle, &lux) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Lux: %d", lux);
            log_event(msg);
            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
            }
        } else {
            log_event("Sensor read failed");
        }
        gpioDelay(500000);
    }
    log_event("Program terminated");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    return 0;
}

