#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_SAFE_PULSE_WIDTH 2000
#define DEBOUNCE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width %d out of range [%d, %d]\n",
                pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set button pins as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: Failed to set pull-up resistors on button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    int lock_state = 0;
    int unlock_state = 0;

    while (running) {
        int lock_pressed = (gpioRead(LOCK_BUTTON_PIN) == 0);
        int unlock_pressed = (gpioRead(UNLOCK_BUTTON_PIN) == 0);

        if (lock_pressed && !lock_state) {
            if (set_servo_pulse(SERVO_PIN, SERVO_SAFE_PULSE_WIDTH) == 0) {
                lock_state = 1;
                printf("Door locked.\n");
            }
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        if (unlock_pressed && !unlock_state) {
            if (set_servo_pulse(SERVO_PIN, SERVO_SAFE_PULSE_WIDTH) == 0) {
                unlock_state = 1;
                printf("Door unlocked.\n");
            }
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

