        fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int safe_set_pull(int pin, unsigned pull) {
    if (gpioSetPullUpDown(pin, pull) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int safe_set_timer(int pin, int interval_ms) {
    if (gpioSetTimerFuncEx(pin, interval_ms, NULL, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void motor_off(int pin) {
    safe_write(pin, 0);
}

static void cleanup(void) {
    motor_off(MOTOR1_PIN);
    motor_off(MOTOR2_PIN);
    gpioTerminate();
}

