    if (safe_set_mode(MOTOR1_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_set_pull(MOTOR1_PIN, PI_PUD_OFF) < 0 ||
        safe_set_pull(MOTOR2_PIN, PI_PUD_OFF) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_write(MOTOR1_PIN, 0) < 0 || safe_write(MOTOR2_PIN, 0) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_set_timer(MOTOR1_PIN, MOTOR1_ON_MS) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (safe_set_timer(MOTOR2_PIN, MOTOR2_ON_MS) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

