#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/gpio.h>
#include <linux/gpiochip.h>
#include <sys/ioctl.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO    27
#define ZMQ_PORT          5555
#define ZMQ_TOPIC         "SOUND_ALERTS"
#define POLL_INTERVAL_US  10000
#define ALARM_DURATION_S  1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int gpio_export(unsigned int offset) {
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%u", offset);
    if (len < 0 || len >= (int)sizeof(buf)) return -1;
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) return -1;
    if (write(fd, buf, (size_t)len) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(unsigned int offset) {
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%u", offset);
    if (len < 0 || len >= (int)sizeof(buf)) return -1;
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) return -1;
    if (write(fd, buf, (size_t)len) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(unsigned int offset, const char *dir) {
    char path[64];
    int len = snprintf(path, sizeof(path), "/sys/class/gpio/gpio%u/direction", offset);
    if (len < 0 || len >= (int)sizeof(path)) return -1;
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    if (write(fd, dir, 4) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(unsigned int offset, int value) {
    char path[64];
    int len = snprintf(path, sizeof(path), "/sys/class/gpio/gpio%u/value", offset);
    if (len < 0 || len >= (int)sizeof(path)) return -1;
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    char val = (value == 1) ? '1' : '0';
    if (write(fd, &val, 1) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_bias(unsigned int offset, const char *bias) {
    char path[64];
    int len = snprintf(path, sizeof(path), "/sys/class/gpio/gpio%u/bias", offset);
    if (len < 0 || len >= (int)sizeof(path)) return -1;
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    if (write(fd, bias, 4) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int zmq_init(void) {
    zmq_context_t *ctx = zmq_ctx_new();
    if (!ctx) {
        perror("zmq_ctx_new");
        return -1;
    }

    int lsock = zmq_socket(ctx, ZMQ_REQ);
    if (lsock < 0) {
        perror("zmq_socket(req)");
        zmq_ctx_destroy(ctx);
        return -1;
    }

    int rsock = zmq_socket(ctx, ZMQ_SUB);
    if (rsock < 0) {
