#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <jansson.h>

#define IR_GPIO 17
#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define PULSE_BUFFER_SIZE 100

#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_RPT_SPACE 2250
#define NEC_TOLERANCE 100
#define NEC_MIN_PULSES 32

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_times[PULSE_BUFFER_SIZE];
static volatile int pulse_count = 0;
static volatile uint32_t last_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_alert_cb(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) {
        uint32_t diff = tick - last_tick;
        last_tick = tick;

        if (pulse_count < PULSE_BUFFER_SIZE) {
            pulse_times[pulse_count++] = diff;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow");
            pulse_count = 0;
        }
    }
}

static int decode_nec(const uint32_t *times, int count, uint32_t *command) {
    if (count < NEC_MIN_PULSES) {
        syslog(LOG_ERR, "NEC frame too short: %d pulses", count);
        return -1;
    }

    if (times[0] < NEC_HDR_MARK - NEC_TOLERANCE || times[0] > NEC_HDR_MARK + NEC_TOLERANCE) {
        syslog(LOG_ERR, "Invalid header mark: %u us", times[0]);
        return -1;
    }

    uint32_t addr = 0, inv_addr = 0;
    for (int i = 0; i < 16; i++) {
        int idx = 1 + i * 2;
        if (idx + 1 >= count) {
            syslog(LOG_ERR, "Incomplete frame: missing %d pulses", 16 - i);
            return -1;
        }
        uint32_t mark = times[idx];
        uint32_t space = times[idx + 1];

        if (mark < NEC_BIT_MARK - NEC_TOLERANCE || mark > NEC_BIT_MARK + NEC_TOLERANCE) {
            syslog(LOG_ERR, "Invalid bit mark: %u us", mark);
            return -1;
        }

        if (space > NEC_ONE_SPACE - NEC_TOLERANCE && space < NEC_ONE_SPACE + NEC_TOLERANCE) {
            addr |= (1u << i);
        } else if (space > NEC_ZERO_SPACE - NEC_TOLERANCE && space < NEC_ZERO_SPACE + NEC_TOLERANCE) {
            continue;
        } else {
            syslog(LOG_ERR, "Invalid space: %u us", space);
            return -1;
        }
    }

    for (int i = 0; i < 16; i++) {
        int idx = 17 + i * 2;
        if (idx + 1 >= count) {
            syslog(LOG_ERR, "Incomplete frame: missing %d pulses", 16 - i);
            return -1;
        }
        uint32_t mark = times[idx];
        uint32_t space = times[idx + 1];

        if (mark < NEC_BIT_MARK - NEC_TOLERANCE || mark > NEC_BIT_MARK + NEC_TOLERANCE) {
            syslog(LOG_ERR, "Invalid bit mark: %u us", mark);
            return -1;
        }

        if (space > NEC_ONE_SPACE - NEC_TOLERANCE && space < NEC_ONE_SPACE + NEC_TOLERANCE) {
            inv_addr |= (1u << i);
        } else if (space > NEC_ZERO_SPACE - NEC_TOLERANCE && space < NEC_ZERO_SPACE + NEC_TOLERANCE) {
            continue;
        } else {
            syslog(LOG_ERR, "Invalid space: %u us", space);
            return -1;
        }
    }

    if ((addr ^ inv_addr) != 0xFFFF) {
        syslog(LOG_ERR, "NEC checksum mismatch: addr=0x%08X inv=0x%08X", addr, inv_addr);
        return -1;
    }

    *command = addr;
    return 0;
}

static int publish_mqtt(const char *topic, const char *payload) {
    int rc = mqtt_connect(NULL, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (rc != PI_MQTT_CONNECT_OK) {
        syslog(LOG_ERR, "MQTT connect failed: %d", rc);
        return -1;
    }

    rc = mqtt_subscribe(NULL, topic, 0);
    if (rc != PI_MQTT_SUBSCRIBE_OK) {
        syslog(LOG_ERR, "MQTT subscribe failed: %d", rc);
        mqtt_disconnect(NULL);
        return -1;
    }

    rc = mqtt_loop(1000);
    if (rc != PI_MQTT_OK) {
        syslog(LOG_ERR, "MQTT loop failed: %d", rc);
        mqtt_disconnect(NULL);
        return -1;
    }

    mqtt_disconnect(NULL);
    return 0;
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting IR decoder on GPIO%d", IR_GPIO);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_WARNING, "Failed to set pull-up on GPIO%d", IR_GPIO);
    }

    if (gpioSetAlertFunc(IR_GPIO, ir_alert_cb) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO%d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "IR decoder ready. Waiting for signals...");

    while (running) {
        gpioDelay(100000);

        if (pulse_count >= NEC_MIN_PULSES) {
            uint32_t command = 0;
            if (decode_nec(pulse_times, pulse_count, &command) == 0) {
                char json_str[128];
                json_t *root = json_object();
                if (root) {
                    json_object_set_new(root, "command", json_integer(command));
                    json_serialize_ex(root, JSON_INDENT(4), json_str, sizeof(json_str));
                    json_decref(root);
                } else {
                    syslog(LOG_ERR, "JSON serialization failed");
                }

                if (publish_mqtt(MQTT_TOPIC, json_str) != 0) {
                    syslog(LOG_ERR, "MQTT publish failed");
                } else {
                    syslog(LOG_INFO, "Decoded command: %s", json_str);
                }
            }
            pulse_count = 0;
        }
    }

    syslog(LOG_INFO, "Shutting down IR decoder");
    gpioSetAlertFunc(IR_GPIO, NULL);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

