#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define MULTICAST_ADDR  "239.255.255.250"
#define MULTICAST_PORT  5005
#define NUM_SENSORS     4
#define CONV_TIME_MS    180
#define LOOP_DELAY_MS   1000

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/*
 * Read lux from a BH1750FVI sensor.
 * Returns 0 on success and stores lux in *out_lux; returns -1 on error.
 */
static int read_bh1750(int fd, int sensor_id, float *out_lux)
{
    uint8_t cmd = 0x10; /* Power ON + Continuous High-Resolution mode */
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "BH1750 %d: write failed: %s\n", sensor_id, strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete (max ~120 ms for H-Resolution mode) */
    usleep(CONV_TIME_MS * 1000);

    /* Read 2 bytes: MSB first, then LSB */
    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "BH1750 %d: read failed (got %zd bytes): %s\n",
                sensor_id, r, r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out_lux = (float)raw / 1.2f;
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(" I2C_DEVICE ")");
        return EXIT_FAILURE;
    }

    /* Set the slave address for the first sensor */
    if (ioctl(i2c_fd, I2C_SLAVE, 0x24) < 0) {
        perror("ioctl(I2C_SLAVE 0x24)");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open the UDP socket for multicast */
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (connect(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("connect");
        close(sockfd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("BH1750 Multicast Sender started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float lux_values[NUM_SENSORS];
        int error_count = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int fd = i2c_fd;
            if (ioctl(fd, I2C_SLAVE, 0x24 + i) < 0) {
                perror("ioctl(I2C_SLAVE 0x24 + i)");
                lux_values[i] = NAN;
                continue;
            }

            float lux;
            if (read_bh1750(fd, i + 1, &lux) == 0) {
                lux_values[i] = lux;
            } else {
                lux_values[i] = NAN;
                error_count++;
            }
        }

        if (error_count > 0) {
            fprintf(stderr, "Warning: %d sensor read errors this cycle.\n", error_count);
        }

        char buffer[256];
        int n = snprintf(buffer, sizeof(buffer),
                         "%d,%.2f;%d,%.2f;%d,%.2f;%d,%.2f",
                         1, lux_values[0],
                         2, lux_values[1],
                         3, lux_values[2],
                         4, lux_values[3]);
        if (n < 0 || (size_t)n >= sizeof(buffer)) {
            fprintf(stderr, "snprintf buffer overflow\n");
        } else {
            if (sendto(sockfd, buffer, (size_t)n, 0,
                        (struct sockaddr *)&addr, sizeof(addr)) < 0) {
                perror("sendto");
            }
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    /* Clean shutdown */
    close(sockfd);
    close(i2c_fd);
    printf("\nTerminated cleanly.\n");
    return EXIT_SUCCESS;
}

