#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "airflow_log.txt"
#define RETRY_COUNT    3
#define RETRY_DELAY_MS 100
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_zero_length(int fd)
{
    /*
     * Issue a zero-length I2C write to generate a start condition.
     * This is a best-effort; the sensor may not respond immediately.
     */
    if (write(fd, NULL, 0) < 0) {
        if (errno == ENXIO) {
            return -1; /* No sensor present */
        }
        return -2; /* Other write error */
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == ENXIO) {
            return -1; /* No sensor present */
        }
        return -2; /* Other read error */
    }
    if ((size_t)n != len) {
        return -3; /* Short read */
    }
    return 0;
}

static int read_airflow_rate(int fd, float *airflow_rate)
{
    uint8_t buf[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2c_write_zero_length(fd) == 0) {
            if (i2c_read_bytes(fd, buf, sizeof(buf)) == 0) {
                /*
                 * AWM7300V: 14-bit flow data in the first two bytes.
                 * Bits [15:2] of the first byte are the upper 12 bits,
                 * bits [7:0] of the second byte are the lower 2 bits.
                 */
                uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
                raw >>= 2; /* Right-align the 14-bit value */

                /*
                 * Conversion: raw * 0.0000625 = SLPM
                 * Per datasheet: 0.0000625 * 2^14 = 0.0000625 * 16384 = 1.0 SLPM
                 */
                *airflow_rate = (float)raw * 0.0000625f;
                return 0;
            }
        }
        retries--;
        if (retries > 0) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static int log_airflow_rate(FILE *fp, float airflow_rate)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        return -1;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", timestamp, airflow_rate) < 0) {
        return -1;
    }

    if (fflush(fp) != 0) {
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x00) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float airflow_rate;

        if (read_airflow_rate(g_i2c_fd, &airflow_rate) == 0) {
            if (log_airflow_rate(g_log_fp, airflow_rate) != 0) {
                fprintf(stderr, "Error writing to log file.\n");
            }
        } else {
            fprintf(stderr, "Error reading airflow rate.\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    printf("\nCleaning up...\n");

    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

