        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float airflow_rate;

        if (read_airflow_rate(g_i2c_fd, &airflow_rate) == 0) {
            if (log_airflow_rate(g_log_fp, airflow_rate) != 0) {
                fprintf(stderr, "Error writing to log file.\n");
            }
        } else {
            fprintf(stderr, "Error reading airflow rate.\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    printf("\nCleaning up...\n");

    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

