#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define AS7341_ADDR 0x39
#define AS7341_ID_REG 0x00
#define AS7341_ID_VAL 0x39
#define AS7341_ENABLE_REG 0x01
#define AS7341_ENABLE_PON 0x01
#define AS7341_CFG6_REG 0x06
#define AS7341_CFG6_SMUX 0x00
#define AS7341_CFG7_REG 0x07
#define AS7341_CFG7_ATIME 0x00
#define AS7341_CFG8_REG 0x08
#define AS7341_CFG8_WTIME 0x00
#define AS7341_DATA_REG 0x01
#define AS7341_DATA_LEN 24
#define LOG_FILE "spectral_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int as7341_init(int fd) {
    uint16_t id;
    if (i2c_read_reg16(fd, AS7341_ID_REG, &id) < 0) {
        fprintf(stderr, "Error: Failed to read AS7341 ID register.\n");
        return -1;
    }
    if (id != AS7341_ID_VAL) {
        fprintf(stderr, "Error: AS7341 not found (ID=0x%04X, expected 0x%04X).\n", id, AS7341_ID_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, AS7341_ENABLE_REG, AS7341_ENABLE_PON) < 0) {
        fprintf(stderr, "Error: Failed to power on AS7341.\n");
        return -1;
    }
    usleep(10000);
    if (i2c_write_reg8(fd, AS7341_CFG6_REG, AS7341_CFG6_SMUX) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG7_REG, AS7341_CFG7_ATIME) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG8_REG, AS7341_CFG8_WTIME) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_ENABLE_REG, AS7341_ENABLE_PON | 0x02) < 0) return -1;
    return 0;
}

static int read_spectral_data(int fd, uint16_t data[10]) {
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg16(fd, AS7341_DATA_REG + (i * 2), &data[i]) < 0) {
            fprintf(stderr, "Error: Failed to read spectral channel %d.\n", i);
            return -1;
        }
    }
    return 0;
}

static float calculate_lux(const uint16_t data[10]) {
    float f1 = (float)data[0];
    float f2 = (float)data[1];
    float f3 = (float)data[2];
    float f4 = (float)data[3];
    float f5 = (float)data[4];
    float f6 = (float)data[5];
    float f7 = (float)data[6];
    float f8 = (float)data[7];
    float c = (float)data[8];
    float nir = (float)data[9];
    float lux = 0.0;
    lux += f1 * 0.0001;
    lux += f2 * 0.0001;
    lux += f3 * 0.0001;
    lux += f4 * 0.0001;
    lux += f5 * 0.0001;
    lux += f6 * 0.0001;
    lux += f7 * 0.0001;
    lux += f8 * 0.0001;
    lux += c * 0.0001;
    lux += nir * 0.0001;
    return lux;
}

static int log_data(FILE *fp, float lux, const uint16_t data[10]) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%u,%u,%u,%u,%u,%u,%u,%u,%u\n",
            timestamp, lux, data[0], data[1], data[2], data[3], data[4],
            data[5], data[6], data[7], data[8], data[9]);
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }
    if (as7341_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: AS7341 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        close(i2c_fd);
        return 1;
    }
    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,Lux,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR\n");
        fflush(log_fp);
    }
    uint16_t spectral_data[10];
    while (running) {
        if (read_spectral_data(i2c_fd, spectral_data) < 0) {
            fprintf(stderr, "Error: Spectral read failed, retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        float lux = calculate_lux(spectral_data);
        if (log_data(log_fp, lux, spectral_data) < 0) {
            fprintf(stderr, "Error: Failed to write to log file.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

