#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define D7S_I2C_ADDR 0x14
#define D7S_REG_X_AXIS 0x01
#define D7S_REG_Y_AXIS 0x03
#define D7S_REG_Z_AXIS 0x05
#define D7S_REG_STATUS 0x07
#define D7S_REG_TEMP 0x09
#define D7S_REG_DIAG 0x0B
#define D7S_REG_RESET 0x0D
#define D7S_RESET_CMD 0x80
#define D7S_RESET_DELAY_MS 10
#define D7S_STATUS_DATA_READY 0x01
#define D7S_STATUS_ERROR 0x02
#define D7S_STATUS_OVERFLOW 0x04
#define D7S_STATUS_FAULT 0x08
#define D7S_STATUS_TEMP_FAULT 0x10
#define D7S_STATUS_DIAG_FAULT 0x20
#define D7S_SCALE_FACTOR 0.000244140625f
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define DEFAULT_I2C_BUS "/dev/i2c-1"
#define DEFAULT_OUTPUT_FILE "seismic_data.csv"
#define DEFAULT_INTERVAL 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static FILE *error_log_file = NULL;
static char *output_filename = DEFAULT_OUTPUT_FILE;
static int i2c_address = D7S_I2C_ADDR;
static int sampling_interval = DEFAULT_INTERVAL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (error_log_file) {
        fprintf(error_log_file, "%s: %s\n", timestamp, message);
        fflush(error_log_file);
    }
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, unsigned char reg, int *value) {
    unsigned char buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (int)((buf[0] << 8) | buf[1]);
    return 0;
}

static int d7s_reset(int fd) {
    if (i2c_write_byte(fd, D7S_REG_RESET, D7S_RESET_CMD) < 0) {
        return -1;
    }
    usleep(D7S_RESET_DELAY_MS * 1000);
    return 0;
}

static int d7s_init(int fd) {
    if (d7s_reset(fd) < 0) {
        return -1;
    }
    unsigned char status;
    int retries = 0;
    do {
        if (i2c_read_byte(fd, D7S_REG_STATUS, &status) < 0) {
            return -1;
        }
        if ((status & D7S_STATUS_DATA_READY) == 0) {
            usleep(10000);
        } else {
            break;
        }
        retries++;
    } while (retries < 10);
    if (retries >= 10) {
        return -1;
    }
    return 0;
}

static int d7s_read_axis(int fd, unsigned char reg, float *x_g, float *y_g, float *z_g) {
    int raw_x, raw_y, raw_z;
    if (i2c_read_word(fd, reg, &raw_x) < 0) return -1;
    if (i2c_read_word(fd, reg + 2, &raw_y) < 0) return -1;
    if (i2c_read_word(fd, reg + 4, &raw_z) < 0) return -1;
    *x_g = (float)raw_x * D7S_SCALE_FACTOR;
    *y_g = (float)raw_y * D7S_SCALE_FACTOR;
    *z_g = (float)raw_z * D7S_SCALE_FACTOR;
    return 0;
}

static int d7s_check_status(int fd, unsigned char *status) {
    if (i2c_read_byte(fd, D7S_REG_STATUS, status) < 0) {
        return -1;
    }
    if (*status & D7S_STATUS_DATA_READY) {
        return 0;
    }
    if (*status & D7S_STATUS_ERROR) {
        return -2;
    }
    if (*status & D7S_STATUS_OVERFLOW) {
        return -3;
    }
    if (*status & D7S_STATUS_FAULT) {
        return -4;
    }
    if (*status & D7S_STATUS_TEMP_FAULT) {
        return -5;
    }
    if (*status & D7S_STATUS_DIAG_FAULT) {
        return -6;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    if (error_log_file) {
        fflush(error_log_file);
        fclose(error_log_file);
        error_log_file = NULL;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = atoi(optarg);
                if (sampling_interval <= 0) {
                    sampling_interval = 1;
                }
                break;
            case 'f':
                output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval_seconds] [-f output_file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    error_log_file = fopen("seismic_error.log", "a");
    if (!error_log_file) {
        perror("fopen seismic_error.log");
        return EXIT_FAILURE;
    }

    csv_file = fopen(output_filename, "a");
    if (!csv_file) {
        perror("fopen output_file");
        fclose(error_log_file);
        return EXIT_FAILURE;
    }

    i2c_fd = open(DEFAULT_I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    if (d7s_init(i2c_fd) < 0) {
        log_error("D7S initialization failed (sensor absent or bus error)");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "D7S initialized. Logging to %s every %d seconds. Press Ctrl+C to stop.\n", output_filename, sampling_interval);

    while (running) {
        unsigned char status;
        int status_code = d7s_check_status(i2c_fd, &status);
        if (status_code < 0) {
            if (status_code == -2) {
                log_error("D7S reported data-ready error");
            } else if (status_code == -3) {
                log_error("D7S reported overflow error");
            } else if (status_code == -4) {
                log_error("D7S reported fault error");
            } else if (status_code == -5) {
                log_error("D7S reported temperature fault");
            } else if (status_code == -6) {
                log_error("D7S reported diagnostic fault");
            } else {
                log_error("D7S status check failed");
            }
            sleep(sampling_interval);
            continue;
        }

        if ((status & D7S_STATUS_DATA_READY) == 0) {
            sleep(sampling_interval);
            continue;
        }

        float x_g, y_g, z_g;
        if (d7s_read_axis(i2c_fd, D7S_REG_X_AXIS, &x_g, &y_g, &z_g) < 0) {
            log_error("Failed to read X axis");
        } else if (d7s_read_axis(i2c_fd, D7S_REG_Y_AXIS, &x_g, &y_g, &z_g) < 0) {
            log_error("Failed to read Y axis");
        } else if (d7s_read_axis(i2c_fd, D7S_REG_Z_AXIS, &x_g, &y_g, &z_g) < 0) {
            log_error("Failed to read Z axis");
        } else {
            time_t now = time(NULL);
