#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_light_level(int fd, float *lux_out) {
    uint8_t cmd = BH1750_CONT_HIGH_RES_MODE;
    uint8_t buf[2];

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error: I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(180000);

    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: I2C read failed (got %zd bytes): %s\n", n, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

int main(void) {
    int i2c_fd = -1;
    int sock_fd = -1;
    struct sockaddr_in addr;
    struct in_addr multicast_addr;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd < 0) {
        perror("Failed to create socket");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (setsockopt(sock_fd, IPPROTO_IP, IP_MULTICAST_TTL, &addr.sin_addr.s_addr, sizeof(addr.sin_addr.s_addr)) < 0) {
        perror("Failed to set multicast TTL");
        close(sock_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float lux;
        if (read_light_level(i2c_fd, &lux) == 0) {
            char message[64];
            int len = snprintf(message, sizeof(message), "%.2f", lux);
            if (len > 0) {
                if (sendto(sock_fd, message, (size_t)len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
                    perror("Failed to send UDP multicast");
                }
            }
        } else {
            fprintf(stderr, "Failed to read light level, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (sock_fd >= 0) close(sock_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return EXIT_SUCCESS;
}

