#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define UART_PORT "/dev/ttyS0"
#define BAUD_RATE B921600
#define CSV_FILE "radar_data.csv"
#define READ_BUF_SIZE 4096
#define FRAME_BUF_SIZE 8192
#define MAGIC_WORD_LEN 8
#define TLV_HEADER_LEN 8
#define MAX_OBJECTS 100

/* AWR1642 TLV types */
#define TLV_TYPE_DETECTED_POINTS 1
#define TLV_TYPE_RANGE_PROFILE 2

/* Magic word: 0x02040608 0x0A0C0E10 (little-endian 8-byte sequence) */
static const uint8_t MAGIC_WORD[MAGIC_WORD_LEN] = {0x02,0x04,0x06,0x08,0x0A,0x0C,0x0E,0x10};

/* TLV header: type (4 bytes) + length (4 bytes) */
static const uint8_t TLV_HEADER[TLV_HEADER_LEN] = {0x01,0x02,0x03,0x04};

typedef struct {
    uint32_t timestamp_sec;
    uint32_t timestamp_nsec;
    int16_t range_idx;
    int16_t velocity_idx;
    int16_t peak_val;
    int16_t x;
    int16_t y;
    int16_t z;
} __attribute__((packed)) detected_point_t;

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;
static FILE *g_csv_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *port, speed_t baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) { perror("open UART"); return -1; }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) { perror("tcgetattr"); close(fd); return -1; }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1; /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) { perror("tcsetattr"); close(fd); return -1; }
    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) { if (errno == EINTR) continue; perror("read"); return -1; }
        if (n == 0) { fprintf(stderr, "UART EOF\n"); return -1; }
        total += (size_t)n;
    }
    return 0;
}

static int find_magic_word(const uint8_t *buf, size_t len) {
    for (size_t i = 0; i <= len - MAGIC_WORD_LEN; i++) {
        if (memcmp(buf + i, MAGIC_WORD, MAGIC_WORD_LEN) == 0) return (int)i;
    }
    return -1;
}

static int process_frame(const uint8_t *frame, size_t frame_len) {
    if (frame_len < MAGIC_WORD_LEN) { fprintf(stderr, "Frame too short\n"); return -1; }

    if (memcmp(frame, MAGIC_WORD, MAGIC_WORD_LEN) != 0) {
        fprintf(stderr, "Magic word mismatch\n");
        return -1;
    }

    size_t offset = MAGIC_WORD_LEN;
    int objects_written = 0;

    while (offset + TLV_HEADER_LEN <= frame_len) {
        uint32_t tlv_type = *(uint32_t *)(frame + offset);
        uint32_t tlv_len  = *(uint32_t *)(frame + offset + 4);
        offset += TLV_HEADER_LEN;

        if (offset + tlv_len > frame_len) {
            fprintf(stderr, "TLV length exceeds frame\n");
            break;
        }

        if (tlv_type == TLV_TYPE_DETECTED_POINTS) {
            size_t num_points = tlv_len / sizeof(detected_point_t);
            if (num_points > MAX_OBJECTS) num_points = MAX_OBJECTS;

            for (size_t i = 0; i < num_points; i++) {
                detected_point_t pt;
                memcpy(&pt, frame + offset + i * sizeof(pt), sizeof(pt));

                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                fprintf(g_csv_fp, "%ld.%09ld,%d,%.3f,%.3f\n",
                        (long)ts.tv_sec, ts.tv_nsec,
                        (int)pt.range_idx,
                        (double)pt.velocity_idx * 0.0343,
                        (double)pt.range_idx * 0.0343);
                objects_written++;
            }
        }

        offset += tlv_len;
    }

    if (objects_written > 0) {
        fflush(g_csv_fp);
    }
    return objects_written;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_uart_fd = init_uart(UART_PORT, BAUD_RATE);
    if (g_uart_fd < 0) return 1;

    g_csv_fp = fopen(CSV_FILE, "a");
    if (!g_csv_fp) { perror("fopen CSV"); close(g_uart_fd); return 1; }

    fprintf(g_csv_fp, "timestamp,object_index,range_m,velocity_mps\n");
    fflush(g_csv_fp);

    uint8_t read_buf[READ_BUF_SIZE];
    uint8_t frame_buf[FRAME_BUF_SIZE];
    size_t frame_len = 0;

    while (g_running) {
        ssize_t n = read(g_uart_fd, read_buf, sizeof(read_buf));
        if (n < 0) { if (errno == EINTR) continue; perror("read"); break; }
        if (n == 0) { fprintf(stderr, "UART EOF\n"); break; }

        for (ssize_t i = 0; i < n; i++) {
            if (frame_len < FRAME_BUF_SIZE) {
                frame_buf[frame_len++] = read_buf[i];
            } else {
                fprintf(stderr, "Frame buffer overflow, resyncing\n");
                frame_len = 0;
            }
        }

        int magic_pos = find_magic_word(frame_buf, frame_len);
        if (magic_pos < 0) {
            if (frame_len >= MAGIC_WORD_LEN) {
                memmove(frame_buf, frame_buf + frame_len - MAGIC_WORD_LEN, MAGIC_WORD_LEN);
                frame_len = MAGIC_WORD_LEN;
            }
            continue;
        }

        if (magic_pos > 0) {
            memmove(frame_buf, frame_buf + magic_pos, frame_len - magic_pos);
            frame_len -= magic_pos;
        }

        if (frame_len < MAGIC_WORD_LEN) {
            continue;
        }

        int objects = process_frame(frame_buf, frame_len);
        if (objects < 0) {
            fprintf(stderr, "Frame processing error\n");
        }
    }

    if (g_csv_fp) { fflush(g_csv_fp); fclose(g_csv_fp); g_csv_fp = NULL; }
    if (g_uart_fd >= 0) { close(g_uart_fd); g_uart_fd = -1; }
    return 0;
}

