#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE   B115200
#define LINE_BUF_SZ 256
#define POLL_TIMEOUT_SEC 2
#define READ_TIMEOUT_SEC 0.5

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void parse_range_data(const char *data)
{
    char *endptr = NULL;
    double range = strtod(data, &endptr);
    if (endptr == data) {
        fprintf(stderr, "Error: invalid range data '%s'\n", data);
        return;
    }

    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    char time_str[32];
    if (strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    printf("Timestamp: %s, Range: %.2f meters\n", time_str, range);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0) {
        return EXIT_FAILURE;
    }

    char line_buf[LINE_BUF_SZ];
    size_t line_len = 0;
    char read_buf[256];

    printf("Starting range detection on %s at 115200 8N1...\n", UART_DEVICE);
    fflush(stdout);

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval tv;
        tv.tv_sec = POLL_TIMEOUT_SEC;
        tv.tv_usec = 0;

        int sel = select(g_uart_fd + 1, &readfds, NULL, NULL, &tv);

        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error from select: %s\n", strerror(errno));
            break;
        }

        if (sel == 0) {
            continue;
        }

        ssize_t n = read(g_uart_fd, read_buf, sizeof(read_buf));
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error from read: %s\n", strerror(errno));
            break;
        }

        if (n == 0) {
            continue;
        }

        for (ssize_t i = 0; i < n && g_running; i++) {
            char c = read_buf[i];

            if (c == '\n') {
                line_buf[line_len] = '\0';

                if (line_len > 0) {
                    char *ts_ptr = NULL;
                    double range = strtod(line_buf, &ts_ptr);
                    if (ts_ptr != NULL && line_len > 0) {
                        parse_range_data(line_buf);
                    }
                }

                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SZ - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Warning: line buffer overflow, discarding\n");
                    line_len = 0;
                }
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

