#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        serClose(uart_fd);
        uart_fd = -1;
    }
    gpioTerminate();
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", LEFT_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", MIDDLE_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", RIGHT_SENSOR_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", LEFT_SENSOR_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", MIDDLE_SENSOR_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", RIGHT_SENSOR_PIN);
        return -1;
    }

    return 0;
}

static int init_uart(void) {
    uart_fd = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_fd < 0) {
        fprintf(stderr, "Error: failed to open UART %s: %d\n", UART_DEVICE, uart_fd);
        return -1;
    }
    return 0;
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
    fflush(stdout);
}

static void check_emergency_stop(int left, int middle, int right) {
    if (left == 0 && middle == 0 && right == 0) {
        const char *msg = "EMERGENCY STOP!\n";
        size_t len = strlen(msg);
        int written = serWrite(uart_fd, (char *)msg, len);
        if (written < 0) {
            fprintf(stderr, "Error: failed to write to UART: %d\n", written);
        } else if (written != len) {
            fprintf(stderr, "Error: partial UART write: %d of %zu bytes\n", written, len);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_uart() < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Monitoring KY-033 sensor. Press Ctrl+C to exit.\n");

    while (running) {
        int left = gpioRead(LEFT_SENSOR_PIN);
        int middle = gpioRead(MIDDLE_SENSOR_PIN);
        int right = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error: GPIO read failed\n");
            break;
        }

        log_sensor_data(left, middle, right);
        check_emergency_stop(left, middle, right);

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}
